// Généré par docs/tools/build-docs-index.mjs : ne pas modifier à la main.
window.SEARCH_INDEX = [{"url":"api.html","page":"API","title":"API","text":"Tout ce que les paquets de Super exportent, paquet par paquet. Chaque entrée renvoie vers la page qui l'explique."},{"url":"api.html#super-core","page":"API","title":"@super-ts/core","text":"Exports : SuperContract , SuperStore , CommandFailure , et des types."},{"url":"api.html#api-contract","page":"API","title":"SuperContract","text":"export type CounterTypes = { state: CounterState; commands?: { increment(input: { id: string }): Outcome<{ count: number }, 'unknown' | 'storage'>; load(): void }; events?: { emptied: void }; }; export class CounterContract extends SuperContract<CounterTypes> { constructor() { super({ name: 'counter' }); // le nom, unique dans l'app : la clé du store } count(s: CounterState, id: string) { // un sélecteur : une méthode, l'état en premier paramètre return s.counts[id] ?? 0; } } Une commande a au plus un paramètre, le body, et déclare void ou Outcome<Résultat, Raisons> . Les sélecteurs sont mémoïsés ; pending est fourni par Super et ne peut pas être déclaré. Voir Contrats et Sélecteurs ."},{"url":"api.html#api-superstore","page":"API","title":"SuperStore","text":"type Deps = { cart: StoreOfContract<'cart'>; orderClient: OrderClient }; export class CheckoutStore extends SuperStore<CheckoutContract> implements Commands<CheckoutStore> { constructor({ cart, orderClient }: Deps) { super({ contract: 'checkout', initialState: { lastOrder: null } }); // StoreOptions } async placeOrder({ address }: { address: string }) { … } // une méthode publique par commande #helper() { … } // code partagé : méthode #privée } CheckoutStore.create({ cart, orderClient }) // le handle (StoreHandle), jamais l'instance Outil protégé Rôle this.get() L'état courant, figé. this.set(patch | fn) Merge superficiel ; notification regroupée par microtask. this.selectors.x(…) Les sélecteurs du contrat sur l'état courant, plus pending(…) . this.emit(nom, payload?) Émet un événement déclaré par le contrat. this.send(nom, body?) Envoie une commande de ce store, suivie par Super. this.fail(raison) Fait échouer la commande en cours avec une raison déclarée. Ne revient pas. this.signal Avorté par dispose() . L'état n'est ni lisible ni modifiable dans le constructeur. Commands<Self> vérifie que chaque commande du contrat a une méthode aux paramètres identiques, qui ne renvoie que le résultat déclaré, et qu'aucune méthode publique n'est hors contrat. StoreHandle Signature contract Le contrat implémenté ( contract.name ). state() Readonly<S> selectors Les sélecteurs du contrat sur l'état courant, plus pending(…) : cart.selectors.count() . send(nom, body?) Promise<void> , rejetée avec une CommandFailure ( reason ) si la commande échoue pending(commande?, body?) boolean on(nom, écouteur, { signal }?) Retourne la fonction de désabonnement. subscribe(écouteur, { signal }?) Retourne la fonction de désabonnement. dispose() void ; les send suivants sont rejetés. Voir Stores ."},{"url":"api.html#api-outcome","page":"API","title":"Outcome et cycle de vie","text":"commands: { increment(input: { id: string }): Outcome<{ count: number }, 'unknown' | 'storage'> } 'increment:done' // { input, result } 'increment:failed' // { input, reason: 'unknown' | 'storage' | 'error', error: Error | null } pending('increment', { id }) // sur les sélecteurs : this.counter.selectors.pending(…), this.selectors.pending(…), store.pending(…) new CommandFailure(command, reason, input) // l'erreur de la promesse de send pour un échec déclaré Voir Le cycle de vie d'une commande ."},{"url":"api.html#api-types-core","page":"API","title":"Types","text":"ContractTypes La forme de ce que déclare un contrat : { state; commands?; events? } . Contracts , ContractName Le dictionnaire nom → classe de contrat, rempli par src/@core/contracts.d.ts (généré), et ses clés. StoreOfContract<'nom'> Le type du handle d'un store par le nom de son contrat, par exemple pour une dépendance entre stores. ContractStore<K> Le handle d'un store, par la classe de son contrat. ContractState , ContractCommands , ContractEvents , ContractSelectors , ContractInput Extraient une partie d'une classe de contrat. BoundContractSelectors , BoundSelectors , PendingReader Les sélecteurs, état déjà fourni, et pending . Commands<Self> , StoreOptions La vérification des commandes d'un store, et ce que reçoit super(…) dans son constructeur. Outcome<R, F> , ResultOf , FailureOf , InputOf , UnexpectedFailure L'issue déclarée d'une commande et ses parties ; 'error' , la raison d'une exception. CommandMap , Events , CommandEvents , AllEvents Commandes, événements, et événements de cycle de vie ( nom:done , nom:failed ). StoreHandle , AnyStore , StatePatch , PayloadArgs , ListenOptions , Unsubscribe Le handle d'un store et les types de ses méthodes. Handlers<C> , CommandTools Des handlers de commandes, qui reçoivent le body puis { fail } (les commands d'un fakeStore )."},{"url":"api.html#super-dom","page":"API","title":"@super-ts/dom","text":"Exports : SuperElement , html , nothing , repeat , createApp , CONTEXT_REQUEST , defineRouter , params , query , createRouter , RouterOutlet , redirect , et des types."},{"url":"api.html#api-fichiers-super","page":"API","title":"Un composant .super","text":"Un composant s'écrit dans un fichier .super : un module TypeScript dont les méthodes de classe émettent des éléments. Il exporte une classe qui étend SuperElement , comme n'importe quel module : l'API ci-dessous ne change pas. Son seul import de @super-ts/dom est en général SuperElement (et RouterOutlet pour une mise en page). import { SuperElement } from '@super-ts/dom'; /** Affiché par le router quand aucune route ne correspond. */ export class NotFoundScreen extends SuperElement { @tag = 'not-found-screen'; @title = 'Page introuvable'; @selector path = this.router.current.path; render() { <main class=\"screen\"> <h1>Page introuvable</h1> <p>Rien à l’adresse <code>{this.path.value}</code>.</p> <button type=\"button\" on:click={() => this.router.send('navigate', { to: 'examples' })}>Retour aux exemples</button> </main> } } Un import sans extension trouve le .super : import { NotFoundScreen } from '@components/not-found' charge not-found/index.super , depuis un .super comme depuis un .ts ( routes.ts , main.ts , un test), avec les types. Une méthode qui émet des éléments ( render , renderError , une méthode #privée ) ne renvoie rien : return; s'arrête en gardant ce qui est émis, return x; ne compile pas. Les déclarations s'écrivent dans la classe , sans générique : @tag , @prop , @emit , @title , et pour la préparation @contract , @selector , @state , @form , @ref , @on (voir Déclarations du composant et Préparer ). Un composant écrit dans un .ts garde static tag , le générique SuperElement<{ props; emits }> et les méthodes ( this.contract(…) , this.selector(…) …). Un module sans template (contrat, store, domaine, routes, main.ts , test) reste un .ts . Voir Templates pour la syntaxe, et Outillage pour la vérification des types et l'éditeur."},{"url":"api.html#api-superelement","page":"API","title":"SuperElement","text":"export class CounterCard extends SuperElement { // pas de générique dans un .super @tag = 'counter-card'; // obligatoire, en minuscules avec un tiret @title = () => `Compteur ${this.count.value}`; // facultatif : une chaîne, ou une fonction suivie @prop counterId: string; // obligatoire, lue par this.counterId @prop compact?: boolean; // facultative @prop tone: 'neutral' | 'danger' = 'neutral'; // facultative, avec une valeur par défaut @emit answered: { confirmed: boolean }; // émis par this.emit('answered', …) ; void sans payload @contract counter; // ContractView : selectors, send, on @selector count = () => this.counter.selectors.count(this.counterId); // Selection : .value @state local = { message: null as string | null }; // LocalState : get(), set() @form edit = { initial, submit }; // FormHandle : voir Formulaires @ref input: HTMLInputElement; // ElementRef : <input ref={this.input} />, .value @on('counter', 'reset:done') // écouteur : payload typé par l'événement onReset({ input }) { … } protected override mounted() { … } protected override unmounted() { … } render() { <main>…</main> } // émet ses éléments, sans return override renderError(error: Error) { <p>{error.message}</p> } // facultatif } // Dans le render d'un parent (.super) : props et événements vérifiés contre @prop et @emit <CounterCard counterId=\"cafes\" on:answered={this.onAnswered} /> // Hors template (main.ts, tests) : renvoie l'élément CounterCard.create(props?, { on? }) CounterCard.eventName('answered') // nom DOM d'un événement émis, pour un écouteur posé à la main Membre Rôle @tag = 'x-y'; Le nom du custom element : obligatoire (sauf classe abstract ), une chaîne en minuscules avec un tiret. Remplace static tag dans un .super . @prop nom: T; Une prop : obligatoire ( nom: T ), facultative ( nom?: T ) ou avec une valeur par défaut calculée une fois par instance ( nom: T = valeur ). Pas de nom de propriété des éléments HTML ( id , title …) ; page est réservé. Voir Déclarations du composant . @emit nom: T; Un événement émis vers le parent ( void s'il ne transporte rien). @title = …; Le titre de la page tant que le composant est monté : une chaîne, ou une fonction suivie (recalculée après chaque rendu). Voir Le titre de la page . this.nom Une prop déclarée, lisible dès les champs, toujours à sa valeur courante. Une copie faite à la construction ne suit pas les changements : lire dans render ou selector pour une valeur à jour. this.props Toutes les props, en lecture seule, en un objet. Dans un .super , on lit chaque prop par this.nom . @contract nom; , @contract nom = 'contrat'; La vue du store fourni pour ce contrat, lue par this.nom : selectors , send (sans attente), on . Une fois par contrat, tous les contrats sauf le router. Forme .ts : this.contract(nom) . Voir Lire un store . this.router La vue du router de l'app, sans déclaration et lisible partout ( render compris) : la route active current ( name() , path() , params.x() , query.x() ), une route précise at(nom) , commandes navigate , visit , back , et href . Voir Le router dans un composant . this.page.title = … Pose le titre de la page ( TitleValue : une chaîne ou une fonction suivie) tant que le composant est monté. Dans un champ ou le constructeur, repris à chaque montage (ce que fait @title ) ; une fois monté, remplace le titre du composant jusqu'au démontage. En écriture seulement ; interdit pendant render . Le dernier composant monté qui pose un titre l'emporte. @selector nom = lecture; { value } : la valeur d'un sélecteur, telle quelle ; le composant ne se re-rend que si elle change. Sur une valeur de route ( @selector id = this.router.current.params.id; ), aussi isValid() . Forme .ts : this.selector(lecture) . @state nom = initial; { get(), set(patch) } . Forme .ts : this.state(initial) . Voir État local . @form nom = options; Un formulaire. Forme .ts : this.form(options) . Voir Formulaires . @ref nom: T; Une référence vers un élément du template, posée par ref={this.nom} (refusée si la balise n'est pas un T ) ; .value vaut undefined tant que l'élément n'est pas rendu. Forme .ts : this.ref<T>() . @on('contrat', 'événement') méthode(payload) { … } Un écouteur sur une méthode, appelée à chaque événement tant que le composant est monté ; le paramètre est typé par l'événement. Pas besoin de @contract ; 'router' écoute le router. Forme .ts : this.contract('contrat').on('événement', …) dans le constructeur. Voir Les écouteurs . this.emit(nom, payload?) Événement déclaré par @emit , vers le parent, écouté par on:nom={…} sur la balise (ou { on: { nom } } avec create ). this.signal Avorté au démontage. mounted() , unmounted() Après le premier rendu, à chaque montage ; au démontage. render() Émet le HTML du composant, à chaque rendu. render() {} ne rend rien. renderError(error) Facultatif : émet ses éléments à la place de render si render ou un descendant plante. Voir Gérer les erreurs . @contract , @selector , @state , @form , @ref et @on se déclarent dans le corps de la classe ; dans un .ts , leurs méthodes s'appellent dans un champ ou le constructeur, jamais pendant render , et lèvent une erreur sinon ; this.page.title ne se pose pas non plus pendant render . Voir Composants et Parents et enfants ."},{"url":"api.html#api-form","page":"API","title":"Formulaires","text":"@form order = { initial, // les valeurs, qui donnent les types rules?: { champ: (valeur, valeurs) => true | 'message' }, validate?: (valeurs) => ({ champ: 'message' }), scrollToError?: boolean, // true par défaut : focus sur la première erreur checks?: { champ: { command, toInput, accept, delay? } }, submit: { to: this.checkout, command: 'placeOrder', toInput: (valeurs) => input }, failures?: { fields: { raison: { champ: 'message' } }, form: { raison: 'message', error?: 'message' } }, }; // → bind() · field(nom, valeur?) · error(nom) · formError() · submitting() · checking(nom) // values() · set(nom, valeur) · list(nom) · submit() · reset() // list(nom) → items() (key, index, value, field, error) · add(ligne) · remove(ligne | index) submit.to est une vue déclarée par @contract avant le formulaire ( this.contract(…) dans un .ts ). Voir Formulaires ."},{"url":"api.html#api-templates","page":"API","title":"Templates","text":"Un template s'écrit dans les méthodes d'un fichier .super : // texte brut et interpolation <p class=\"total\">Total : {formatPrice(total)}</p> // attribut calculé (null le retire), attribut booléen, écouteur <a href={url} aria-current={active ? 'page' : null}>Panier</a> <button disabled={busy} on:click={this.save}>Enregistrer</button> // propriété DOM, référence, directive d'élément (formulaires) <input prop:value={draft} ref={this.input} /> <form {order.bind()}>…</form> // afficher ou non, liste (à clés ou non), choix sans cascade if (cond) { … } else { … } for (const x of xs; key x.id) { … } switch (s) { case 'a': … default: … } // composant enfant : props et événements typés <ConfirmDialog question=\"Vider le panier ?\" on:answered={this.onAnswered} /> html , nothing et repeat (lit-html) restent exportés pour du code qui n'est pas un composant ; ils ne servent plus à écrire un composant. Voir Templates , et Et html, nothing, repeat ? ."},{"url":"api.html#api-createapp","page":"API","title":"createApp","text":"createApp({ root, stores?, router?, onError? }) // App : { root, mount(element), dispose() } onError: (error, { tag, phase, caughtBy }) => void // phase : setup · render · renderError · event · listener · mount CONTEXT_REQUEST // nom de l'événement DOM par lequel un composant demande un store Voir Brancher l'application et Gérer les erreurs ."},{"url":"api.html#api-router","page":"API","title":"Router","text":"export const Router = defineRouter({ examples: '/', counters: '/counters?sort&tag[]', // chaîne : valeurs texte, tag[] : liste counter: { path: '/counters/:id', params: params<{ id: number }>({ id: Number }) }, // objet : valeurs typées search: { path: '/search', query: query<{ page: number; q?: string }>({ page: { type: Number, default: 1 }, q: String }) }, }) .guards(({ read }) => ({ // facultatif, avant les écrans checkout: () => !read('cart').isEmpty() || { to: 'shop' }, counter: ({ params }) => params.id.isValid() || { to: 'counters' }, // la route, comme at() la donne })) .screens(() => ({ // toujours le dernier appel examples: ExamplesScreen, // un écran : aucune prop obligatoire counters: CounterListScreen, counter: CounterScreen, search: SearchScreen, form: redirect({ to: 'profile' }), // redirection à la place d'un écran '*': NotFoundScreen, // facultatif : aucun chemin ne correspond '!': ErrorScreen, // facultatif : un écran a planté, reçoit { error, path } })); const router = createRouter(Router, { mode?: 'browser' | 'memory', initialPath?, title? }); // RouterHandle // title?: { default?, suffix? } : default sans titre posé, suffix ajouté au titre posé createRouter(Router, { title: { default: 'Super · exemples', suffix: ' · Super' } }) Router.href('counter', { params: { id: 42 } }) // '/counters/42', hors composant Router.paths // les routes déclarées // dans un composant : this.router, sans déclaration this.router.current.name() // 'counter' | … | null ; aussi path() this.router.current.params.id() // dans l'écran de `counter` : number | undefined this.router.current.query.sort() // chaque valeur se passe aussi à @selector this.router.current.params.id.isValid() // l'URL portait-elle une valeur conforme ? this.router.at('counter').params.id() // une route précise ; lève une erreur si une autre est active this.router.href('counters', { query: { sort: 'label' } }) // '/counters?sort=label', sans abonner le composant this.router.send('navigate', { to: 'counter', params: { id: 42 }, query: { … } }) // aussi visit(path), back() @on('router', 'navigated') onNavigated({ from, to }) { … } // un écouteur ; dans un .ts : this.router.on('navigated', …) <RouterOutlet /> // dans un render : affiche l'écran actif // le handle (tests, main.ts) router.state() // { path, name, params, query, invalid, screen, errorScreen } Le titre se règle dans les options de createRouter , pas dans defineRouter (dont les clés sont des routes). Sans default , le titre d'origine du document revient. Voir Router et Le titre de la page ."},{"url":"api.html#api-types-dom","page":"API","title":"Types","text":"ElementTypes , PropsIn , EmitsIn , RouteIn , PropsOf , EventsOf Ce que déclare un composant ( { props?, emits?, route? } , tiré par le compilateur .super des @prop , des @emit et de la route d'un écran), et les props et événements d'une classe ou d'une instance. ElementClass , Screen , ChildOptions Une classe de composant, un écran du router, les options { on } de create . ContractView , RouterView , ViewOf , ElementSelectors , StoreContractName , AppRouterView Ce que donnent @contract ( this.contract(nom) ) et this.router . Selection , RouteSelection , Selected , SelectorValue , Unselected Ce que donne @selector (avec isValid() pour une valeur de route), et la marque qui réserve selector aux valeurs de sélecteurs. LocalState , ElementRef Ce que donnent @state et @ref ( this.state et this.ref dans un .ts ). Page , TitleValue , TitleOptions this.page (son title , en écriture seulement), la valeur d'un titre ( string | (() => string) ), et le réglage { default?, suffix? } de l'option title de createRouter . Children Des éléments passés à un composant : le type d'une prop remplie par les enfants écrits entre ses balises ( content ), par un emplacement <:nom> ou par une méthode qui émet des éléments (voir Templates ). FormOptions , FormHandle , FormRules , FieldRule , FieldCheck , FormFailures , FormList , FormListItem , FieldName , ListName , FieldOption Les formulaires. App , AppOptions , ErrorInfo , ErrorDetail , ErrorPhase createApp et les erreurs de composants. RouterDefinition , RouterHandle , RouterOptions , RouteState , RouterCommands , RouterEvents La déclaration, le handle et le contrat du router. AppRouterContract , AppRouterContractOf , AppRouteNames Le contrat du router vu d'un composant, typé par les routes de l'app (inscrit sous 'router' dans contracts.d.ts ), et les noms de ces routes. RouteTable , RouteDeclaration , PathParams , QueryParams , ParamsOf , QueryOf Les routes déclarées (chaîne ou objet), et le type de leurs paramètres et de leur query. ParamsSpec , QuerySpec , ParamsDescription , QueryDescription Les descriptions écrites avec params<T>({…}) et query<T>({…}) , vérifiées contre T . CurrentRoute , RouteAt , RouteValue La route active ( this.router.current ), une route précise ( this.router.at(nom) , un guard), et une de leurs valeurs, avec isValid() . ScreenRoutes , RouteOfTag Le lien entre le tag d'un écran et sa route, généré par le plugin Vite dans contracts.d.ts , et la route d'un composant d'après son tag. RouteInput , HrefArgs , NavigateTargetOf Le typage des liens et des navigations : { params, query } . ScreensDeclaration , ScreensFor , ErrorScreen , Redirect , GuardsFor , GuardResult , GuardTools Les écrans, redirections et guards."},{"url":"api.html#super-testing","page":"API","title":"@super-ts/testing","text":"mount(Classe, { props?, stores?, router?, on?, onError? }) // Promise<Mounted> : { container, element, setProps, unmount } cleanup() // démonte tout (dans un afterEach) flush() // laisse passer les rendus en attente record(store, 'événement') // Recorder : { calls, last, stop } fakeStore('nom', { state, commands? }) // FakeStore : handle + { sent, setState, emit } FakeCommands<'nom'> // le type des commands d'un faux store SentCommand // une entrée de sent : { name, args } Voir Tester ."},{"url":"api.html#super-ui","page":"API","title":"@super-ts/ui","text":"Importer le paquet charge sa feuille de styles. Tous les composants acceptent une prop class . Export Rôle Field , Select , Checkbox , RadioGroup , fieldOf(form, 'nom') Les champs reliés à un @form . Types : FieldRef , Choice . CommandButton , commandOf(vue, 'commande', entrée) Un bouton qui envoie une commande, désactivé pendant qu'elle est en cours. Type : CommandRef . RouteLink Un lien vers une route, aria-current=\"page\" sur la page affichée. Toasts , createToasts() , ToastQueue Une file de messages et son affichage. Types : Toast , ToastOptions , ToastTone . ErrorPanel Une erreur présentée, pour un renderError ou l'écran '!' . Dialog , Modal , ConfirmDialog Les fenêtres modales. Types : CloseOn , CloseReason . Menu , Tabs , Disclosure , Tooltip , Popover , Combobox Les primitives accessibles. Types : MenuItem , Tab . Button , Badge , Spinner , Skeleton , EmptyState L'affichage. Table , columns<Row>([…]) La table, statique ou branchée. Types : Column , Sort , TableRequest . Voir Kit d'interface ."},{"url":"api.html#super-vite","page":"API","title":"@super-ts/vite","text":"superPlugin({ src: '/chemin/absolu/vers/src' }) // SuperPluginOptions ; règles d'architecture, alias @core/ et @components/, // génération de src/@core/contracts.d.ts, compilation des .super Les briques du plugin sont exportées aussi, pour un outillage maison : RULES , ALIASES Où s'importent SuperContract / SuperStore ( @core ) et SuperElement ( @components ) ; les alias @core et @components . checkModule , checkCoreImports , checkComponentImports (cheminRelatif, code) : le message d'erreur si le module enfreint une règle, null sinon. contractsIn , scanContracts , scanRouter Lisent les contrats d'un fichier ou de src/@core/ , et le router de l'app. contractsModule , contractsDeclaration Produisent le module qui inscrit les contrats, et le contenu de contracts.d.ts . hotModuleCode (code) : le code ajouté en dev à un module de composant pour le remplacement à chaud, null s'il ne déclare aucun composant. Le plugin compile aussi chaque .super en TypeScript, puis en JS, avec une source map vers le .super , et ajoute .super aux extensions résolues. Voir Architecture et Outillage ."},{"url":"api.html#super-lint","page":"API","title":"@super-ts/lint","text":"{ \"extends\": [\"@super-ts/lint/config.json\"] } // ordre des imports : @super-ts, puis @components / @core, puis le reste Voir L'ordre des imports ."},{"url":"application.html","page":"Brancher l'application","title":"Brancher l'application","text":"La racine de composition, main.ts , est le seul endroit qui choisit les adapters, crée les stores et le router, et les fournit aux composants."},{"url":"application.html#la-racine-de-composition","page":"Brancher l'application","title":"La racine de composition","text":"import './styles.css'; // références globales d'abord : les feuilles des composants passent après import './kit-theme.css'; // le thème de @super-ts/ui pour toute l'app import { createApp, createRouter } from '@super-ts/dom'; import { AppShell } from '@components/app-shell'; import { CartStore } from '@core/cart/store'; import { CatalogStore } from '@core/catalog/store'; import { CheckoutStore } from '@core/checkout/store'; import { CounterStore } from '@core/counter/store'; import { ErrorLogStore } from '@core/error-log/store'; import { ProfileStore } from '@core/profile/store'; import { createDummyJsonProductCatalog } from './adapters/dummyjson-product-catalog'; import { createFakeOrderClient } from './adapters/fake-order-client'; import { createFakeProfileClient } from './adapters/fake-profile-client'; import { createLocalStorageCounterRepository } from './adapters/local-storage-counter-repository'; import { createSavedCart } from './adapters/saved-cart'; import { Router } from './routes'; // Racine de composition (user-land) : on choisit ici les adapters et on assemble les stores. const counter = CounterStore.create({ counterRepository: createLocalStorageCounterRepository() }); const profile = ProfileStore.create({ profileClient: createFakeProfileClient() }); // serveur simulé, avec latence const savedCart = createSavedCart(); const cart = CartStore.create({ quantities: savedCart.load() }); // le panier d'avant le rechargement const checkout = CheckoutStore.create({ cart, orderClient: createFakeOrderClient() }); // un store qui dépend d'un autre const errorLog = ErrorLogStore.create(); const catalog = CatalogStore.create({ productCatalog: createDummyJsonProductCatalog() }); // l'API publique de test dummyjson.com // Le titre de l'onglet : celui que pose l'écran affiché (`@title`), suivi du nom de l'app. const router = createRouter(Router, { title: { default: 'Super · exemples', suffix: ' · Super' } }); // subscribe : le panier est enregistré à chaque changement, et survit au rechargement de la page. // Le store ne sait rien du stockage : c'est la racine de composition qui le branche. cart.subscribe((state) => savedCart.save(state.quantities)); createApp({ root: document.querySelector<HTMLElement>('#app')!, stores: [counter, profile, cart, checkout, errorLog, catalog], router, // Toute erreur de composant, rattrapée ou non : la console, et le journal affiché par l'exemple « Erreurs ». onError: (error, { tag, phase, caughtBy }) => { console.error(`[${tag}] ${phase}`, { caughtBy }, error); errorLog.send('record', { message: error.message, tag, phase, caughtBy }); }, }).mount(AppShell.create()); Créer les stores avec XStore.create(deps) : c'est ici qu'on choisit localStorage , une API HTTP ou une version en mémoire, et qu'on passe un store à celui qui en dépend ( checkout reçoit cart ). create renvoie le handle du store, jamais l'instance de la classe. Créer le router à partir du Router déclaré dans routes.ts , avec le cadre du titre de l'onglet ( title: { default, suffix } , voir Le titre de la page ). Créer l'application sur un élément racine, en lui fournissant stores et router. Monter le composant racine, créé par AppShell.create() . main.ts reste un fichier .ts : il n'a pas de template, il crée le composant par create() au lieu de l'écrire <AppShell /> . L'import @components/app-shell , sans extension, trouve app-shell/index.super . main.ts est du user-land : Super ne lui impose rien. Pas de conteneur d'injection, pas de configuration cachée : tout l'assemblage se lit dans ce fichier. Il peut aussi utiliser les handles directement, comme ici cart.subscribe , qui enregistre le panier dans le localStorage à chaque changement (par l'adapter adapters/saved-cart.ts ) : le panier relu au démarrage ( CartStore.create({ quantities: savedCart.load() }) ) survit ainsi au rechargement de la page. C'est un bon usage de subscribe : synchroniser l'état avec un système extérieur (stockage, analytics, autre onglet), hors de tout composant, sans que le store le sache. CartStore ne connaît pas le stockage, c'est la racine de composition qui le branche. Le compteur fait l'inverse : son store parle à un port, CounterRepository , parce que la persistance fait partie de son métier (chargement asynchrone, erreurs à afficher). Voir subscribe ."},{"url":"application.html#createapp","page":"Brancher l'application","title":"createApp","text":"Option Rôle root L'élément HTML sous lequel l'application vit. stores Les handles de store à fournir aux composants rendus sous root , chacun sous le nom de son contrat. router Le router créé par createRouter . Il est fourni sous le nom 'router' , les clics sur les liens internes deviennent des navigations, et ses guards lisent les stores de cette application. onError Reçoit toute erreur de composant rendu sous root , rattrapée ou non : (error, { tag, phase, caughtBy }) . Voir Gérer les erreurs . Retour Rôle mount(élément) Remplace le contenu de la racine par l'élément, et le retourne. dispose() Retire le fournisseur et l'interception des liens, puis vide la racine. root L'élément racine."},{"url":"application.html#comment-un-composant-trouve-son-store","page":"Brancher l'application","title":"Comment un composant trouve son store","text":"Un composant déclare @contract counter; . À son montage, il demande au DOM, en remontant depuis lui-même : « qui fournit un store pour le contrat counter ? ». L'application la plus proche qui en a un répond. Conséquences pratiques : Un composant fonctionne partout sous la racine , à n'importe quelle profondeur, sans qu'on lui passe le store en props. Le nom du contrat sert de clé : celui de super({ name: 'counter' }) dans @core/counter/contract.ts . Le composant n'importe ni le contrat ni le store ; le plugin Vite refuse deux contrats du même nom et génère @core/contracts.d.ts , qui type @contract counter (et this.contract('counter') dans un composant écrit en .ts ). Un composant monté sans store pour ce nom lève une erreur explicite (phase setup ) : « aucun store fourni pour le contrat \"counter\". Ajoute-le à createApp({ stores }) ou à mount(..., { stores }) »."},{"url":"application.html#applications-imbriquees","page":"Brancher l'application","title":"Plusieurs applications","text":"Dans l' exemple Widget : widgets/timer-widget.ts , @components/widget/index.super . Le minuteur vit dans une seconde application, imbriquée dans la première, avec son propre store. On peut créer plusieurs applications, et même les imbriquer : la plus proche du composant répond en premier. C'est utile pour un widget qui a ses propres stores au milieu d'une page. Dans l'exemple, une fonction user-land monte le minuteur sur l'élément qu'on lui donne, et renvoie de quoi tout libérer : import { createApp } from '@super-ts/dom'; import { TimerWidget } from '@components/widget/timer-widget'; import { TimerStore } from '@core/timer/store'; export function mountTimerWidget(root: HTMLElement): () => void { const timer = TimerStore.create(); const app = createApp({ root, stores: [timer] }); app.mount(TimerWidget.create()); return () => { app.dispose(); timer.dispose(); }; } L'écran /widget l'appelle sur un élément de son propre template, déclaré par @ref widgetSlot: HTMLElement; et posé avec ref={this.widgetSlot} , et libère le widget s'il est démonté pendant qu'il est ouvert : export class WidgetScreen extends SuperElement { @tag = 'widget-screen'; @title = 'Widget'; @state local = { open: false }; @ref widgetSlot: HTMLElement; #close: (() => void) | null = null; toggle = () => { if (this.#close) { this.#close(); this.#close = null; this.local.set({ open: false }); return; } this.#close = mountTimerWidget(this.widgetSlot.value!); this.local.set({ open: true }); }; protected override unmounted() { this.#close?.(); this.#close = null; } render() { <main class=\"screen\"> <h1>Widget</h1> {/* … */} <button type=\"button\" on:click={this.toggle}>{this.local.get().open ? 'Fermer le minuteur' : 'Ouvrir le minuteur'}</button> <div class=\"widget-slot\" ref={this.widgetSlot}></div> </main> } } Sous l'élément du widget, @contract timer trouve le store de la seconde application ; @contract counter remonterait jusqu'à la première. Le minuteur n'en sait rien : il demande un contrat par son nom, et l'application la plus proche qui le fournit répond. Un seul store par contrat dans une application Fournir deux stores pour le même contrat à la même application lève une erreur : « deux stores fournis pour le contrat \"counter\" »."},{"url":"application.html#charger-les-donnees-au-demarrage","page":"Brancher l'application","title":"Charger les données au démarrage","text":"Deux façons, selon où tu veux voir l'intention : // Dans le composant racine, au montage (choix de l'exemple) export class AppShell extends SuperElement { @tag = 'app-shell'; @contract counter; // … protected override mounted() { this.counter.send('load'); } } // Ou directement dans main.ts, sur le handle void counter.send('load');"},{"url":"architecture.html","page":"Architecture","title":"Architecture","text":"Super impose deux dossiers et quatre règles. Tout le reste de ton src est du user-land : Super ne le regarde pas."},{"url":"architecture.html#la-structure","page":"Architecture","title":"La structure","text":"src/ ├── @core/ IMPOSÉ PAR SUPER : contrats et stores │ ├── counter/ contract.ts, store.ts, store.test.ts │ └── contracts.d.ts généré par le plugin Vite (à committer) ├── @components/ IMPOSÉ PAR SUPER : composants (écrans compris) │ ├── counter/ index.super, index.css, index.test.ts, counter-controls.super │ ├── app-shell/ la coquille │ └── shared/ composants réutilisables ├── domain/ user-land (choix de ce projet) ├── ports/ user-land (choix de ce projet) ├── adapters/ user-land (choix de ce projet) ├── routes.ts user-land └── main.ts user-land Dans @core/ , la convention est un dossier par contrat : contract.ts , store.ts et son test. Dans @components/ , un dossier par écran , en kebab-case et sans suffixe ( shop/index.super exporte ShopScreen ), avec ses sous-composants en fichiers à plat ( counter/counter-controls.super ) ; les composants réutilisables vont dans shared/ . Un composant est un fichier .super (voir Templates ) ; ses tests, eux, restent des .ts . Les règles du plugin, elles, ne regardent que le premier niveau : un fichier est sous @core/ ou sous @components/ , ou ailleurs. src/@core/contracts.d.ts est généré par le plugin Vite : c'est le dictionnaire nom → classe de contrat (plus le router, sous 'router' ) qui permet d'écrire @contract counter; avec tous les types, et le lien entre chaque écran et sa route ( ScreenRoutes ). On le committe, on ne l'écrit jamais."},{"url":"architecture.html#le-prefixe-arobase","page":"Architecture","title":"Le préfixe @","text":"Le préfixe se lit d'un coup d'œil : un dossier préfixé appartient à Super , un dossier sans préfixe appartient à ton projet. Un dossier core/ ou components/ sans @ n'a rien de spécial : c'est un dossier user-land comme un autre, qui ne peut donc contenir ni store ni composant. Pourquoi @ et pas $ ? Dans un shell, $core est lu comme une variable : cd src/$core arrive silencieusement dans src/ . @ passe sans souci dans le shell, dans les imports relatifs et dans les URLs du serveur de dev. À ne pas confondre @super-ts/core est le paquet du framework. @core/counter/contract est un fichier de ton app, dans src/@core/ . L'un vient de node_modules , l'autre de ton src ."},{"url":"architecture.html#importer-depuis-core-et-components","page":"Architecture","title":"Importer depuis @core et @components","text":"Les deux dossiers Super s'importent par alias, depuis n'importe quel fichier, quelle que soit sa profondeur : import { AppShell } from '@components/app-shell'; import { CounterStore } from '@core/counter/store'; Plus de '../../@core/…' à recompter quand un fichier change de dossier. Les imports relatifs ( '../@core/counter/store' ) restent possibles, et les règles d'architecture s'appliquent aux deux écritures. Côté Vite et Vitest, rien à faire : le plugin superPlugin déclare ces alias lui-même, à partir du dossier src que tu lui donnes. Un import sans extension trouve aussi un .super : '@components/app-shell' mène à app-shell/index.super . Côté TypeScript , pour l'IDE et le typecheck, déclare les alias dans le tsconfig.json de ton app (aucun plugin ne peut les injecter dans TypeScript). Chaque alias a deux cibles : ton src , et les déclarations des .super , que l'outillage écrit dans .super/types/ (un dossier ignoré par git). rootDirs fusionne les arborescences (ton src , les déclarations, puis le TS virtuel de .super/virtual/ d'où elles tirent leurs types) : un .ts qui importe un composant .super , comme routes.ts , en voit les types, et « aller à la définition » ouvre le .super . { \"compilerOptions\": { \"paths\": { // … les paquets @super-ts/… \"@core/*\": [\"./src/@core/*\", \"./.super/types/src/@core/*\"], \"@components/*\": [\"./src/@components/*\", \"./.super/types/src/@components/*\"] }, \"rootDirs\": [\"./src\", \"./.super/types/src\", \"./.super/virtual/src\"] } } Qui écrit ce TS virtuel, et quand : voir Outillage ."},{"url":"architecture.html#ordre-des-imports","page":"Architecture","title":"L'ordre des imports","text":"Super fixe aussi l'ordre des imports, vérifié au lint : les paquets Super : @super-ts/… ; les dossiers Super : @components/… et @core/… ; tout le reste : modules Node ( node:… ), paquets npm, puis chemins relatifs. À l'intérieur de chaque groupe, l'ordre est alphabétique. import { createRouter } from '@super-ts/dom'; import { type FakeCommands, fakeStore, flush, mount } from '@super-ts/testing'; import type { CounterState } from '@core/counter/contract'; import { within } from '@testing-library/dom'; import userEvent from '@testing-library/user-event'; import { describe, expect, test } from 'vitest'; import { Router } from '../../routes'; import { CounterScreen } from '.'; On lit d'un coup d'œil ce qui vient du framework, ce qui vient des briques Super de l'app, et le reste. Les imports sans nom ( import './styles.css' ) ne sont jamais déplacés : ils servent de séparateurs, ce qui préserve l'ordre de chargement des feuilles de style."},{"url":"architecture.html#le-lint","page":"Architecture","title":"Le lint","text":"La règle est portée par Biome. Super fournit sa configuration, que ton projet étend dans son biome.json : { \"extends\": [\"@super-ts/lint/config.json\"] } npm run lint # vérifie l'ordre des imports et le formatage (lancé aussi par npm run check) npm run lint:fix # corrige les deux Dans ce dépôt, la configuration de Super est dans packages/lint/config.json . La configuration de Super ne touche qu'à l'ordre des imports : le formatage et les autres règles de lint restent au choix du projet. Le dépôt, lui, active le formateur de Biome (deux espaces, guillemets simples, 140 colonnes) et formate les .super avec les mêmes règles (voir Outillage ). Les autres dossiers n'ont pas d'alias Seuls les dossiers Super en ont. ports/ , adapters/ ou routes.ts s'importent en relatif ( '../routes' ), ou avec tes propres alias si tu en déclares."},{"url":"architecture.html#les-regles","page":"Architecture","title":"Les quatre règles","text":"Règle Ce qui est refusé Les contrats et les stores se définissent sous src/@core/ . Un module hors de @core/ qui importe SuperContract ou SuperStore depuis @super-ts/core . Les composants se définissent sous src/@components/ . Un module hors de @components/ ( .super ou .ts ) qui importe SuperElement depuis @super-ts/dom . Un composant n'importe de @core/ que des types. Un composant qui importe une valeur de @core/ : un store, une classe de contrat, une constante, une fonction, ou un import * as . Les contrats et les stores ne dépendent pas du DOM. Un module de @core/ qui importe quoi que ce soit de @super-ts/dom ( html , SuperElement , createApp …), sauf des types. La quatrième règle garde le cœur de l'app indépendant de l'affichage : un store se teste sans DOM, et pourrait servir à une autre interface. La troisième règle est la plus importante : elle garantit qu' un composant ne voit un store qu'à travers son contrat , qu'il demande par son nom ( @contract counter; ). Il lit par les sélecteurs, envoie des commandes, écoute des événements, et rien d'autre. C'est ce qui permet de le tester avec un faux store, et d'empêcher qu'une logique métier se glisse dans la vue."},{"url":"architecture.html#le-plugin-vite","page":"Architecture","title":"Le plugin Vite","text":"Le plugin @super-ts/vite compile les .super et fait respecter ces règles. Il se déclare dans vite.config.ts , et sert aussi à Vitest : import { superPlugin } from '@super-ts/vite'; import { fileURLToPath } from 'node:url'; import { defineConfig } from 'vite'; export default defineConfig({ plugins: [superPlugin({ src: fileURLToPath(new URL('./src', import.meta.url)) })], }); Le même plugin : compile chaque .super en TypeScript (des gabarits lit-html), puis en retire les types ; une erreur de compilation arrête le chargement du module, avec sa position dans le .super ; fournit une source map du JS final vers le .super : traces d'erreur et débogueur pointent la ligne et la colonne de la source (voir Source maps ) ; applique les règles d'architecture au code compilé : un .super est vérifié comme le serait un .ts ; en dev, réécrit le TS virtuel d'un .super à chaque transformation, pour que les .ts qui l'importent en voient les types à jour ; déclare les alias @core/ et @components/ , et ajoute .super aux extensions résolues (voir plus haut) ; lit les contrats de src/@core/ (les fichiers contract.ts , ou *.contract.ts , qui déclarent export class X extends SuperContract et se nomment par super({ name }) ), refuse deux contrats du même nom, et les inscrit pour que chaque store retrouve le sien par son nom ; repère le router de l'app ( export const Router = defineRouter(…) ) et l'ajoute sous 'router' ; lit ses .screens(…) pour relier le tag de chaque écran à sa route ( 'counter-screen': 'counter' ), qui type this.router.current dans l'écran ; écrit le tout dans src/@core/contracts.d.ts , au lancement puis à chaque fichier enregistré en dev ; en dev, rend les composants remplaçables à chaud (voir ci-dessous)."},{"url":"architecture.html#remplacement-a-chaud","page":"Architecture","title":"Remplacement à chaud des composants","text":"En dev, modifier un composant ne recharge pas la page : la nouvelle version remplace l'ancienne, et les éléments affichés gardent leur état (état local, saisie, état des stores) et se re-rendent avec le nouveau code. Les composants créés ensuite utilisent la nouvelle version, y compris par un parent qui n'a pas été modifié. Ce remplacement n'est sûr que si les champs du composant n'ont pas changé : les éléments affichés ont été construits avec les anciens. Super recharge donc la page entière quand la modification : ajoute, retire ou renomme un champ ou une déclaration de préparation ( @state extra = …; ) ; modifie un handler en champ fléché ( onAnswered = () => … ) ; touche un composant qui a des membres #privés , champs ou méthodes comme un #row() qui émet des éléments (ceux de l'ancienne classe ne sont pas ceux de la nouvelle). Modifier render , renderError , mounted ou une autre méthode se fait à chaud. Pour un .super , c'est son code compilé qui remplace l'ancien. Un fichier de @core/ (contrat, store) recharge toujours la page. Rien de tout ça n'existe en build : le code ajouté par le plugin n'est actif que sous vite en dev. Un module qui enfreint une règle n'est pas chargé : Vite refuse de le transformer et affiche l'erreur (overlay en dev, échec du build ou du test). [super] src/shared/badge.ts importe SuperElement depuis @super-ts/dom. Les composants ne se définissent que sous src/@components/ : ce module n'est pas chargé. [super] src/@components/counter-list/counter-list-item.super importe CounterContract depuis @core/counter/contract. Un composant n'importe de src/@core/ que des types : il parle aux stores par leur contrat (@contract cart;). Ce module n'est pas chargé."},{"url":"architecture.html#ce-que-le-plugin-ne-verifie-pas","page":"Architecture","title":"Ce que le plugin ne vérifie pas","text":"Les tests ( *.test.ts , *.test-d.ts ) : l'app ne les charge pas, ils peuvent importer un vrai store ou définir des doublures où ils veulent. Les imports de type ( import type { CounterState } from '@core/counter/contract' ) : ils disparaissent à la compilation, ils sont libres partout. Le user-land : domain/ , ports/ , adapters/ , routes.ts , main.ts importent ce qu'ils veulent. Le plugin lit le code comme du texte (pour un .super , le code compilé) : il reconnaît les imports nommés (y compris renommés avec as ), un contrat à sa déclaration export class X extends SuperContract et le router à export const Router = defineRouter(…) . Voir Limites ."},{"url":"architecture.html#le-user-land","page":"Architecture","title":"Le user-land","text":"Hors de @core/ et @components/ , tu organises comme tu veux. Dans l' app d'exemples : domain/ : les types et les règles métier ( Product , CartLine , le catalogue des compteurs, la page de produits demandée à une API), sans Super ni DOM. Les contrats s'en servent ; un composant peut en importer les types. ports/ : les interfaces dont les stores ont besoin (ici CounterRepository , ProfileClient , OrderClient , ProductCatalog ). C'est un choix inspiré de l'architecture hexagonale ; un autre projet pourrait mettre ces interfaces à côté du store, dans @core/ . adapters/ : les implémentations concrètes de ces ports ( localStorage , mémoire, un serveur simulé, l'API HTTP de dummyjson.com…). routes.ts : les routes et les écrans, déclarés dans un seul export, Router . Un composant y accède par this.router , qui construit aussi les liens ( this.router.href(…) ) ; Router.href sert au code hors composants. main.ts : la racine de composition, le seul endroit qui choisit les adapters et assemble le tout."},{"url":"architecture.html#qui-importe-quoi","page":"Architecture","title":"Qui importe quoi","text":"Depuis Peut importer @core/ (contrats, stores) Les autres contrats et stores, le domaine, les ports, @super-ts/core ; de @super-ts/dom , seulement des types. @components/ Les types de @core/ , les autres composants, le domaine et le reste du user-land, @super-ts/dom , et le kit @super-ts/ui . User-land Tout. Une seule règle de dépendance à retenir Un composant dépend du contrat d'un store, jamais de son implémentation."},{"url":"chantiers.html","page":"Chantiers et questions ouvertes","title":"Chantiers et questions ouvertes","text":"Ce qui manque à Super pour une vraie app, les suites mises de côté, et les questions encore en discussion. Rien de tout cela n'est décidé : c'est la liste d'où partira le prochain chantier. Ce que Super ne fait pas bien aujourd'hui est dans Limites ."},{"url":"chantiers.html#chantiers","page":"Chantiers et questions ouvertes","title":"Les chantiers qui manquent le plus","text":"Par ordre d'importance : ce sont les manques les plus visibles face aux autres frameworks."},{"url":"chantiers.html#chargement-a-la-demande","page":"Chantiers et questions ouvertes","title":"1. Chargement à la demande des écrans, et loaders","text":"Aujourd'hui, toute l'app part dans un seul bundle : le router importe tous ses écrans, aucun n'est chargé à la demande. Une app qui grossit le paie à chaque premier chargement. Des écrans chargés à la navigation : counter: () => import('@components/counter') dans .screens(…) , avec un état de chargement et une erreur de chargement rattrapée comme une erreur d'écran. Des loaders : un écran déclare les données à charger avant de s'afficher (une commande de store), pour ne pas afficher un écran vide puis le remplir. Le préchargement : le code et les données d'un écran chargés au survol ou au focus d'un lien qui y mène."},{"url":"chantiers.html#donnees-serveur","page":"Chantiers et questions ouvertes","title":"2. Une couche de données serveur au-dessus des commandes","text":"Les commandes d'un store parlent au serveur par ses ports, et leur issue revient par nom:done et nom:failed . Tout le reste s'écrit à la main dans chaque store, alors que les besoins sont toujours les mêmes (c'est ce que fait TanStack Query) : dédoublonner deux chargements identiques lancés en même temps ; servir la valeur déjà connue et la revalider en arrière-plan ; réessayer un chargement qui échoue ; invalider ce qu'une écriture rend périmé ; appliquer une écriture tout de suite (mise à jour optimiste), et revenir en arrière si elle échoue ; choisir quoi faire de deux commandes concurrentes (garder la dernière, les mettre en file)."},{"url":"chantiers.html#journal-des-commandes","page":"Chantiers et questions ouvertes","title":"3. Un journal des commandes pour le développement","text":"Chaque commande passe déjà par un EventTarget , avec son issue. Un panneau de développement pourrait les lister : la commande, ce qu'elle a reçu, sa durée, son résultat ou sa raison d'échec, et l'état du store avant et après. C'est peu de code pour beaucoup d'aide au débogage, et une première brique de devtools."},{"url":"chantiers.html#suites","page":"Chantiers et questions ouvertes","title":"Les suites laissées de côté","text":""},{"url":"chantiers.html#suites-router","page":"Chantiers et questions ouvertes","title":"Router","text":"Un raccourci pour changer une seule clé de la query (aujourd'hui, navigate avec ...query ). Des paramètres et une query décrits par un schéma Zod ou Valibot (Standard Schema), à la place des descriptions de Super. Renvoyer vers l'écran '*' quand un paramètre est invalide ( { invalid: 'not-found' } par paramètre). Restaurer le scroll et placer le focus après une navigation. Le reste du <head> par écran ( <meta> , description) : le titre existe déjà, par @title . Une valeur oubliée dans oneOf n'est pas signalée à la compilation."},{"url":"chantiers.html#suites-kit","page":"Chantiers et questions ouvertes","title":"Kit d'interface","text":"Quelques textes ne se changent pas encore par une prop : « Vérification… », « Chargement… » de Table et Combobox , la pagination, « Détails ». Le tri d'une table sur plusieurs colonnes. L'API popover native quand le navigateur l'a, avec le repli actuel sinon. fieldOf ne sert que dans le rendu du composant qui déclare le formulaire."},{"url":"chantiers.html#publication","page":"Chantiers et questions ouvertes","title":"Publication","text":"Publier les paquets @super-ts/* sur npm, une fois l'API stabilisée : aujourd'hui, ils sont résolus par alias depuis packages/*/src . Publier la grammaire Tree-sitter et l'extension Zed. Il faut pour cela un dépôt public pour chacune, une licence, des textes en anglais, un serveur de langage publié sur npm (en un seul fichier) que l'extension installe, et une demande d'ajout au registre des extensions de Zed."},{"url":"chantiers.html#questions-ouvertes","page":"Chantiers et questions ouvertes","title":"Questions ouvertes","text":"Les dépendances entre contrats. Déclarer qu'un store écoute un autre store, pour rendre le graphe lisible et détecter les cycles. Overlays globaux (toast, confirmation demandée depuis n'importe quel écran) : rester en user-land avec un store dédié qui pilote un composant monté dans le shell, ou devenir un concept Super. Guard de sortie. Empêcher de quitter un écran (modifications non enregistrées), porté par l'écran plutôt que par la route."},{"url":"composants.html","page":"Composants : une classe et son render","title":"Composants : une classe et son render","text":"Un composant est un custom element typé, écrit comme une classe qui étend SuperElement . Ses déclarations et ses champs préparent l'instance une fois ; render() affiche à chaque rendu."},{"url":"composants.html#definir-un-composant","page":"Composants : une classe et son render","title":"Définir un composant","text":"Un composant vit dans un fichier .super sous src/@components/ , par exemple src/@components/shop/index.super . C'est un module TypeScript ordinaire, à une différence près : dans ses méthodes, le HTML s'écrit directement, en éléments placés comme des instructions (voir Templates ). Un import sans extension le trouve : @components/shop désigne shop/index.super . import { SuperElement } from '@super-ts/dom'; import type { CounterChange, CounterFailure } from '../../domain/counter'; import { CounterControls } from './counter-controls'; import './index.css'; const DONE: Record<CounterChange, string> = { increment: 'Incrémenté', decrement: 'Décrémenté', reset: 'Remis à zéro', }; // L'écran choisit le texte de chaque raison d'échec (le compilateur signale une raison oubliée). const FAILED: Record<CounterFailure | 'error', string> = { unknown: 'Ce compteur n’existe pas.', 'below-min': 'Le compteur est déjà à zéro.', storage: 'Impossible d’enregistrer : le stockage est indisponible.', error: 'Une erreur inattendue est survenue.', }; /** Écran de la route `/counters/:id` : il lit `id` dans sa route. */ export class CounterScreen extends SuperElement { @tag = 'counter-screen'; // Suivi : renommer le compteur change aussi le titre de l'onglet. @title = () => this.label.value ?? 'Compteur introuvable'; // Le paramètre de la route, lu à l'appel : `this.counterId()`. counterId = this.router.current.params.id; // Ne lit que ce qui concerne le compteur affiché : les autres compteurs ne re-rendent pas l'écran. @contract counter; @selector label = () => this.counter.selectors.label(this.counterId()); @selector count = () => this.counter.selectors.count(this.counterId()); @selector canDecrement = () => this.counter.selectors.canDecrement(this.counterId()); // Un chargement ou une écriture en cours : on attend avant d'en relancer une. @selector busy = () => this.counter.selectors.pending(); @state local = { message: null as string | null }; // L'écran envoie une commande et laisse filer ; Super publie l'issue de chacune. @on('counter', 'increment:done') onIncremented({ input, result }) { this.#done('increment', input.id, result.count); } @on('counter', 'decrement:done') onDecremented({ input, result }) { this.#done('decrement', input.id, result.count); } @on('counter', 'reset:done') onReset({ input, result }) { this.#done('reset', input.id, result.count); } @on('counter', 'increment:failed') onIncrementFailed({ input, reason }) { this.#failed(input.id, reason); } @on('counter', 'decrement:failed') onDecrementFailed({ input, reason }) { this.#failed(input.id, reason); } @on('counter', 'reset:failed') onResetFailed({ input, reason }) { this.#failed(input.id, reason); } // Seules les issues du compteur affiché deviennent un message. #done(change: CounterChange, id: string, count: number) { if (id === this.counterId()) this.local.set({ message: `${DONE[change]} : ${count}` }); } #failed(id: string, reason: CounterFailure | 'error') { if (id === this.counterId()) this.local.set({ message: FAILED[reason] }); } run = (command: CounterChange) => this.counter.send(command, { id: this.counterId() }); #back() { <a class=\"back-link\" href={this.router.href('counters')}>← Tous les compteurs</a> } render() { const label = this.label.value; if (label === null) { <main class=\"screen\">{this.#back()}<h1>Compteur introuvable</h1><p>Aucun compteur « {this.counterId()} ».</p></main> return; } const count = this.count.value; const busy = this.busy.value; <main class=\"screen counter-screen\"> {this.#back()} <h1>{label}</h1> <CounterControls count={count} canDecrement={this.canDecrement.value && !busy} canIncrement={!busy} on:increment={() => this.run('increment')} on:decrement={() => this.run('decrement')} /> <button type=\"button\" class=\"counter-reset\" disabled={count === 0 || busy} on:click={() => this.run('reset')}>Remettre à zéro</button> <p class=\"counter-message\" role=\"status\">{this.local.get().message}</p> </main> } } Une classe de composant se compose de quatre éléments : Élément Rôle extends SuperElement La classe de base, sans générique dans un .super : le compilateur tire les types du composant de ses déclarations. Les déclarations @tag (le nom du custom element, obligatoire, avec un tiret), puis selon les besoins @prop pour les props reçues, @emit pour les événements émis vers le parent, @title pour le titre de la page. Voir Déclarations du composant . Un écran ne reçoit pas de props du router : il lit sa route par this.router.current , typé d'après sa route sans rien déclarer (voir L'écran et sa route ). La préparation Les contrats ( @contract ), les valeurs lues ( @selector ), l'état local ( @state ), le formulaire ( @form ), les références ( @ref ), les écouteurs ( @on sur une méthode), et les actions en champs. Voir Préparer . render() Le HTML du composant, obligatoire, écrit en éléments dans le corps de la méthode, sans return . Une méthode facultative renderError(error) le remplace si le composant ou un descendant plante (voir Gérer les erreurs ). Le composant n'importe rien de @core/ , sauf des types : il parle aux stores par @contract nom; (et au router par this.router ), et le plugin Vite le vérifie."},{"url":"composants.html#declarations","page":"Composants : une classe et son render","title":"Déclarations du composant","text":"Ce qui décrit le composant vu de l'extérieur s'écrit en tête du corps de sa classe : son tag, ses props, ses événements, et le titre de la page tant qu'il est monté. Pas de générique sur SuperElement , pas de type Props au-dessus de la classe : le compilateur tire les types du composant de ces lignes, et les vérifie à chaque balise qui l'utilise. Ce que le composant prépare une fois (contrats, lectures, état, formulaire, références, écouteurs) se déclare de la même façon : voir Préparer . export class ConfirmDialog extends SuperElement { @tag = 'confirm-dialog'; @title = 'Confirmation'; @prop question: string; @prop tone: 'neutral' | 'danger' = 'neutral'; @prop note?: string; @emit answered: { confirmed: boolean }; render() { <p>{this.question}</p> <button on:click={() => this.emit('answered', { confirmed: true })}>Confirmer</button> } } Déclaration Sens @tag = 'x-y'; Le nom du custom element. Obligatoire (sauf classe abstract ), une chaîne en minuscules avec un tiret. Unique dans l'app : un second composant avec le même tag lève une erreur à son premier create . @prop nom: T; Une prop obligatoire, lue par this.nom . @prop nom?: T; Une prop facultative ( T | undefined ). @prop nom: T = valeur; Une prop facultative avec une valeur par défaut, calculée une fois par instance. @emit nom: T; Un événement, émis par this.emit('nom', payload) ( void s'il ne transporte rien). @title = …; Le titre de la page tant que le composant est monté : une chaîne, ou une fonction suivie. Voir Le titre de la page ."},{"url":"composants.html#declarer-les-props","page":"Composants : une classe et son render","title":"Les props","text":"Une prop se lit par son nom, this.question , partout dans la classe et dès les champs. La lecture donne toujours la valeur courante, et un changement de prop re-rend le composant. this.props existe toujours (toutes les props, en lecture seule), mais on écrit this.nom . Le détail des trois formes est dans Parents et enfants . Le contenu écrit entre les balises remplit la prop content . Elle se déclare comme les autres ( @prop content: Children; ) et se lit par this.content . Voir Composer : des enfants . Les noms des propriétés natives sont refusés. Le composant est un élément du DOM : une prop ne peut pas s'appeler id , title , hidden , slot … L'erreur de type le dit : « « title » est déjà une propriété des éléments HTML : choisis un autre nom ». Dans la démo, title est devenu heading ( KitPage , Card ) et id est devenu counterId ( CounterListItem ). Un paramètre de route id se lit de même dans un champ nommé autrement : counterId = this.router.current.params.id; . page est réservé : c'est this.page , qui porte le titre de la page."},{"url":"composants.html#declarer-les-evenements","page":"Composants : une classe et son render","title":"Les événements","text":"@emit nom: T; déclare un événement et ce qu'il transporte ( void s'il ne transporte rien). Le composant l'émet par this.emit('nom', payload) , le parent l'écoute par on:nom={…} sur la balise. Voir emit chez l'enfant, on chez le parent ."},{"url":"composants.html#erreurs-de-declaration","page":"Composants : une classe et son render","title":"Ce que le compilateur refuse","text":"Un tag manquant, écrit static tag = … (une correction rapide le réécrit en @tag ), ou qui n'est pas une chaîne en minuscules avec un tiret. Un générique écrit à la main : « Dans un .super , les props et les événements se déclarent dans la classe : @prop nom: Type; et @emit nom: Type; ». Une déclaration en double, une prop sans type, un ? avec une valeur par défaut, un @emit avec une valeur, une déclaration hors d'un composant. Un composant écrit dans un fichier .ts ( RouterOutlet , les composants de @super-ts/ui , les tests du framework) n'a pas ces déclarations : il garde static tag et le générique, et lit ses props par this.props . Il prépare aussi par des méthodes ( this.contract(…) , this.selector(…) , this.state(…) , this.form(…) , this.ref<T>() , .on(…) dans le constructeur). type Props = { question: string }; type Emits = { answered: { confirmed: boolean } }; export class ConfirmDialog extends SuperElement<{ props: Props; emits: Emits }> { static tag = 'confirm-dialog'; // … }"},{"url":"composants.html#declarations-de-preparation","page":"Composants : une classe et son render","title":"Préparer : stores, lectures, état, formulaire, références, écouteurs","text":"Ce que le composant prépare une fois, à sa construction, se déclare aussi dans le corps de sa classe : les contrats qu'il lit, ses valeurs lues, son état local, son formulaire, ses références et ses écouteurs. La plupart des composants n'ont donc plus de constructeur. export class ProfileScreen extends SuperElement { @tag = 'profile-screen'; @contract profile; @contract shop = 'catalog'; // un autre nom de champ que celui du contrat @selector saving = () => this.profile.selectors.pending('save'); @state local = { saved: null as string | null }; @form edit = { initial: { name: '' }, submit: { to: this.profile, command: 'save' } }; @ref nameInput: HTMLInputElement; @on('profile', 'save:done') onSaved({ result }) { this.local.set({ saved: result.id }); } render() { <form {this.edit.bind()}> <input ref={this.nameInput} {this.edit.field('name')} /> <button type=\"submit\" disabled={this.saving.value}>Enregistrer</button> </form> } } Dans un .super Avant, et toujours dans un .ts Se lit par @contract cart; cart = this.contract('cart'); this.cart.selectors.x() , this.cart.send(…) @contract shop = 'catalog'; shop = this.contract('catalog'); idem, sous le nom this.shop @selector lines = this.cart.selectors.lines; lines = this.selector(this.cart.selectors.lines); this.lines.value @selector count = () => …; count = this.selector(() => …); this.count.value @state local = { … }; local = this.state({ … }); this.local.get() , this.local.set(…) @form edit = { … }; edit = this.form({ … }); this.edit.bind() , this.edit.field('name') … @ref input: HTMLInputElement; input = this.ref<HTMLInputElement>(); ref={this.input} , puis this.input.value @on('profile', 'save:done') onSaved(p) { … } this.profile.on('save:done', (p) => …) dans le constructeur la méthode, appelée à chaque événement tant que le composant est monté Seule la déclaration change : la lecture reste la même ( this.lines.value , this.local.get() , this.edit.bind() , this.input.value , this.cart.send(…) ). Pas de type sur @contract , @selector , @state , @form : il vient de la valeur. Pour l'élargir, on écrit as dans la valeur ( null as string | null ). @ref , à l'inverse, déclare le type de son élément et n'a pas de valeur. La valeur de @contract x = '…' est une chaîne écrite telle quelle , le nom du contrat : @contract log = 'error-log'; lit le contrat error-log sous le nom this.log . L'ordre compte , comme pour des champs : un @selector ou un @form qui lit this.cart vient après @contract cart ."},{"url":"composants.html#declarer-un-ecouteur","page":"Composants : une classe et son render","title":"Les écouteurs : @on","text":"Un écouteur se déclare sur une méthode : @on('contrat', 'événement') au-dessus d'elle, et la méthode est appelée à chaque événement tant que le composant est monté. Plus besoin de constructeur pour poser un écouteur. @on n'exige pas de @contract : il ouvre lui-même l'accès au contrat. Un composant qui ne fait qu'écouter profile n'a pas besoin de @contract profile; . Le paramètre de la méthode est typé par l'événement : pour save:done , { input, result } ; pour save:failed , { input, reason } . Pas besoin de l'annoter. @on('router', 'navigated') écoute le router , comme this.router.on('navigated', …) . Le nom de l'événement est une chaîne écrite telle quelle , sans gabarit ( `${change}:done` ) : une méthode par événement. Dans la démo, CounterScreen déclare onIncremented , onDecremented , onReset , onIncrementFailed …, qui appellent toutes #done ou #failed (voir l'extrait en tête de page )."},{"url":"composants.html#formulaire-et-balise-form","page":"Composants : une classe et son render","title":"Pourquoi @form et pas un composant <Form>","text":"Un formulaire est de l'état du composant : ses valeurs, ses erreurs, ses vérifications, sa soumission, lus partout dans le template ( this.edit.field('name') , this.edit.values() , le bouton « Enregistrement… »). La balise, elle, existe déjà : c'est le <form> natif, relié par <form {this.edit.bind()}> . Un <Form> cacherait cet état et ferait perdre le typage des champs. <Table> , lui, est un composant parce qu'il ne fait qu'afficher."},{"url":"composants.html#erreurs-de-preparation","page":"Composants : une classe et son render","title":"Les erreurs de préparation","text":"Un contrat déclaré deux fois : « Le contrat cart est déjà déclaré par @contract cart ». @contract router : « Le router se lit par this.router , sans @contract ». Un type sur @contract , @selector , @state ou @form : « Pas de type sur @selector : il vient de la valeur ». Les anciennes formes, dans un .super : local = this.state({ … }) donne « Dans un .super , this.state(…) se déclare par @state : @state local = …; », avec une correction rapide qui réécrit la ligne (de même pour this.contract , this.selector , this.form et this.ref ). Un this.x.on(…) dans le constructeur : « Dans un .super , un écouteur se déclare sur une méthode : @on('x', 'événement') onEvent(payload) { … } ». Pas de correction automatique : la méthode est à écrire. Hors d'un composant, rien ne change : un store qui écoute un autre store garde cart.on('add:done', …) dans son constructeur, main.ts garde cart.subscribe(…) , et le handle d'un store, dans un test, garde counter.on('increment:done', …) ."},{"url":"composants.html#declarations-dans-l-editeur","page":"Composants : une classe et son render","title":"Dans l'éditeur","text":"Un @ tapé dans le corps d'un composant propose tag , title , prop , emit , contract , selector , state , form , ref et on , avec un gabarit à compléter ; @t ne propose plus que tag et title , et un @tag ou un @title déjà écrit n'est plus proposé. Le survol de chaque déclaration affiche sa documentation. Après @contract , l'éditeur propose les contrats de l'app que le composant ne déclare pas encore. Dans @contract x = '…' et @on('…', '…') , l'éditeur complète les noms des contrats de l'app, puis ceux des événements du contrat choisi. @prop et @emit sont du TypeScript valide (des champs décorés) ; @tag = … et @title = … ne le sont pas, mais le formateur et la grammaire Tree-sitter de Zed les connaissent (voir Outillage )."},{"url":"composants.html#les-deux-phases","page":"Composants : une classe et son render","title":"Préparer, puis rendre","text":"Déclarations et champs render() Quand Une fois, à la création de l'instance. Au montage, puis à chaque changement de props, d'état local ou de valeur lue dans un store. Rôle Préparer : déclarer les contrats lus, les valeurs réactives, l'état local, le formulaire, les références, les écouteurs, les actions. Décrire le HTML à partir des valeurs courantes. S'écrit avec @contract , @selector , @state , @form , @ref , @on , @title (dans un .ts : this.contract , this.selector , this.state , this.form , this.ref , on d'un contrat, this.page.title ). Les champs préparés : .value , get() , les sélecteurs, les props ( this.nom ). Produit Rien. Les éléments qu'il émet, ou rien du tout ( render() {} ). La préparation est bloquée pendant le rendu. Dans un .super , elle ne s'écrit que par des déclarations, en dehors de render . Les méthodes qu'elles appellent ( contract , state , selector , ref et form , écrites telles quelles dans un .ts ) lèvent une erreur si elles sont appelées pendant render : on ne peut pas résoudre un store ou créer un état à chaque rendu. L'écouteur on d'un contrat est permis dans un gestionnaire ou dans mounted , mais lève une erreur pendant un rendu ; this.page.title de même (voir Le titre de la page ). L'erreur passe par le renderError du composant, comme toute erreur de rendu. Les props sont lisibles dès les déclarations et les champs : Super les dépose avant de construire l'instance. Une valeur copiée à ce moment-là ( @state local = { draft: this.text }; , les valeurs initiales d'un formulaire d'édition) ne suit pas les changements suivants : pour une valeur toujours à jour, lis la prop ( this.text ) dans render , dans la fonction d'un selector ou dans un écouteur, comme les méthodes @on de CounterScreen , qui appellent this.counterId() quand l'événement arrive et lisent donc la route du moment."},{"url":"composants.html#preparation-ou-render","page":"Composants : une classe et son render","title":"Où mettre quoi : préparation ou render ?","text":"La question à se poser : est-ce que ça doit exister une seule fois pour l'instance, ou est-ce que ça se recalcule à partir des valeurs du moment ? Ligne Où Pourquoi @tag , @prop , @emit déclaration Ce que le composant est vu de l'extérieur : en tête de la classe, une fois pour toutes. @title = () => … déclaration Le titre se pose une fois ; la fonction, elle, est recalculée après chaque rendu. @contract counter; déclaration Résoudre un store est un branchement, fait une fois. Pendant un rendu, il lève une erreur. @selector count = …; déclaration Déclare ce que le composant lit. La valeur, elle, est recalculée à chaque lecture de .value . @state local = { message: null }; déclaration L'état local doit survivre aux rendus. Recréé à chaque rendu, il repartirait de zéro. @form edit = { … }; , @ref input: HTMLInputElement; déclaration Un formulaire et une référence sont de l'état de l'instance : créés une fois, lus à chaque rendu. @on('counter', 'increment:done') onIncremented(…) { … } méthode décorée Un écouteur se pose une fois, et vit tant que le composant est monté. Pas de constructeur. run = (command) => … champ fléché Une action stable, créée une fois, avec this lié. this.count.value render Les valeurs changent : on les lit au moment du rendu. if (label === null) render Une décision d'affichage dépend de la valeur actuelle. La branche émet ses éléments, puis return; arrête le rendu : ce qui est déjà émis est gardé. <main>…</main> render Les éléments sont l'affichage lui-même. #back() { <a …>…</a> } méthode Un morceau de HTML réutilisé s'écrit dans une méthode qui émet ses éléments, appelée par {this.#back()} dans render . En résumé : la préparation porte les verbes déclarer, s'abonner, écouter, préparer ; render porte les verbes lire, décider, afficher . render doit pouvoir être appelé dix fois de suite sans conséquence. L'erreur classique : lire une valeur dans un champ Un champ s'initialise à la création de l'instance : les props sont lisibles, mais le store n'est pas encore résolu, et une valeur lue à ce moment-là ne suivrait pas les changements. // ✗ lève une erreur : le contrat ne se lit qu'une fois le composant monté count = this.counter.selectors.count(this.counterId); // ✓ déclare la lecture, lis la valeur dans render @selector count = () => this.counter.selectors.count(this.counterId); render() { <output>{this.count.value}</output> }"},{"url":"composants.html#un-composant-sans-store","page":"Composants : une classe et son render","title":"Un composant sans store","text":"Un composant de présentation, qui affiche ses props et émet des événements, n'a besoin que de render : /** Composant de présentation pur : il ne connaît aucun store. */ export class CounterControls extends SuperElement { @tag = 'counter-controls'; @prop count: number; @prop canDecrement: boolean; @prop canIncrement: boolean; @emit increment: void; @emit decrement: void; render() { <div class=\"counter-controls\" role=\"group\" aria-label=\"Compteur\"> <button type=\"button\" aria-label=\"Décrémenter\" disabled={!this.canDecrement} on:click={() => this.emit('decrement')}>−</button> <output class=\"counter-value\" aria-label=\"Valeur du compteur\">{this.count}</output> <button type=\"button\" aria-label=\"Incrémenter\" disabled={!this.canIncrement} on:click={() => this.emit('increment')}>+</button> </div> } } Il ne connaît aucun store : il reste réutilisable et se teste seul."},{"url":"composants.html#un-composant-pour-un-effet-de-bord","page":"Composants : une classe et son render","title":"Un composant pour un effet de bord","text":"Dans l' exemple Widget : timer-shortcuts.super . Un raccourci clavier sur window , nettoyé par signal . Certains composants existent surtout pour ce qu'ils font au montage, pas pour ce qu'ils affichent. Tout ce qu'ils posent avec this.signal , ou par un écouteur @on , est nettoyé au démontage. import { SuperElement } from '@super-ts/dom'; /** Un raccourci clavier posé sur window au montage, retiré par `signal` au démontage. */ export class TimerShortcuts extends SuperElement { @tag = 'timer-shortcuts'; @contract timer; protected override mounted() { window.addEventListener( 'keydown', (event) => { const typing = event.target instanceof HTMLInputElement || event.target instanceof HTMLTextAreaElement; if (event.code !== 'Space' || typing) return; event.preventDefault(); this.timer.send('toggle'); }, { signal: this.signal }, ); } render() { <p class=\"shortcut\">Barre d'espace : démarrer ou mettre en pause.</p> } } Cas typiques : lancer une commande au montage, écouter un événement pour déclencher une action ailleurs (analytics, son, focus), poser un écouteur sur window . Un composant qui n'affiche rien garde un render vide : render() {} (voir Ne rien rendre )."},{"url":"composants.html#les-outils-d-un-composant","page":"Composants : une classe et son render","title":"Les outils d'un composant","text":"Tout passe par this . Ce que la classe déclare, ce qu'elle utilise (les outils de préparation sont protégés : seule la classe y a accès), et ce que Super appelle sur la classe elle-même. Membre Où Rôle Ce que la classe déclare @tag = 'x-y'; en tête de la classe Le nom du custom element, obligatoire, avec un tiret ( 'counter-screen' ). Vérifié au premier create . Voir Déclarations du composant . @prop nom: T; en tête de la classe Une prop reçue du parent : obligatoire, facultative ( nom?: T ) ou avec une valeur par défaut ( nom: T = valeur ). @emit nom: T; en tête de la classe Un événement émis vers le parent ( void s'il ne transporte rien). @title = …; en tête de la classe Le titre de la page tant que le composant est monté : une chaîne, ou une fonction suivie. Voir Le titre de la page . @contract nom; , @contract nom = 'contrat'; dans la classe Le store fourni pour ce contrat, vu à travers ses sélecteurs, send et on . Tous les contrats sauf le router. Dans un .ts : this.contract(nom) . Voir Lire un store . @selector nom = …; dans la classe Une valeur lue d'un sélecteur, lue par .value dans render ; le composant ne se re-rend que si elle change. Dans un .ts : this.selector(lecture) . Voir Lire un store . @state nom = { … }; dans la classe L'état local, lu par get() , changé par set(…) . Dans un .ts : this.state(initial) . Voir État local . @form nom = { … }; dans la classe Un formulaire : champs liés, règles, vérifications, soumission par une commande. Dans un .ts : this.form(options) . Voir Formulaires . @ref nom: T; dans la classe Une référence vers un élément du template : <input ref={this.input} /> , puis this.input.value une fois monté. Le compilateur refuse la référence si T n'est pas le type de la balise (voir Références ). Dans un .ts : this.ref<T>() . @on('contrat', 'événement') méthode(payload) { … } sur une méthode Un écouteur, appelé à chaque événement tant que le composant est monté, sans @contract nécessaire ; 'router' écoute le router. Dans un .ts : .on(…) dans le constructeur. Voir Les écouteurs . render() méthode obligatoire Décrit le HTML, à chaque rendu. Ne peut ni lire un nouveau contrat ni créer d'état. renderError(error) méthode facultative Affiché à la place de render si render , un descendant, ou la résolution d'un store au montage plante. S'il plante lui-même, l'erreur remonte au parent. Voir Gérer les erreurs . mounted() , unmounted() méthodes facultatives Appelées après le premier rendu de chaque montage, et au démontage. Ce que la classe utilise this.nom partout, dès les champs Une prop déclarée par @prop , toujours à sa valeur courante. Un changement de prop re-rend le composant ; une copie faite à la construction ne le suit pas. this.props les donne toutes, en lecture seule. this.emit(nom, payload?) partout Émet un événement déclaré par @emit , vers le parent. Voir Parents et enfants . this.router partout Le router de l'app, sans déclaration : ses sélecteurs, send , on et href . Voir Le router dans un composant . this.page.title = … partout sauf render Pose le titre de la page tant que le composant est monté, comme @title : une chaîne, ou une fonction suivie. En écriture seulement. Voir Le titre de la page . this.signal une fois monté AbortSignal avorté au démontage, pour les écouteurs posés hors de Super ( window.addEventListener(…, { signal: this.signal }) ). Inutile pour les stores : les écouteurs @on se nettoient seuls. this partout L'élément lui-même, pour les cas que l'API ne couvre pas (focus, mesures). Sur la classe <Classe prop={…} on:nom={…} /> template Monte l'enfant à cet emplacement (même instance d'un rendu à l'autre). Les props sont vérifiées contre ses @prop , les écouteurs contre ses @emit . Voir Parents et enfants . Classe.create(props?, { on }?) hors template Renvoie l'élément, pour le montage initial, le router ou un test. Les props et les écouteurs sont typés de la même façon. Classe.eventName(nom) hors template Le nom DOM d'un événement émis ( 'confirm-dialog:answered' ), pour un écouteur posé à la main. Un champ ou une prop ne peut pas porter le nom d'une propriété native d' HTMLElement ( slot , title , hidden , id …) : le composant est un élément du DOM, et ce nom est déjà pris. page est réservé de même, pour this.page . Ne surcharge pas non plus connectedCallback ni disconnectedCallback : Super lève une erreur au premier create . Utilise mounted et unmounted ."},{"url":"composants.html#mounted-et-unmounted","page":"Composants : une classe et son render","title":"mounted et unmounted","text":"Dans l' exemple Widget : timer-widget.super . Un intervalle démarré au montage, arrêté au démontage. import { RouterOutlet, SuperElement } from '@super-ts/dom'; import { RouteLink } from '@super-ts/ui'; import './index.css'; /** Mise en page commune : la navigation entre les exemples, puis l'écran de la route active. */ export class AppShell extends SuperElement { @tag = 'app-shell'; @contract counter; protected override mounted() { this.counter.send('load'); } render() { // Chaque lien se marque lui-même `aria-current=\"page\"` sur la page affichée ; `activeFor` // étend une section à ses autres routes (la liste des compteurs et un compteur). <header class=\"app-header\"> <nav aria-label=\"Exemples\"> <RouteLink to={{ to: 'examples' }}> Exemples </RouteLink> <RouteLink to={{ to: 'counters' }} activeFor={['counter']}> Compteurs </RouteLink> <RouteLink to={{ to: 'profile' }}> Formulaire </RouteLink> <RouteLink to={{ to: 'shop' }} activeFor={['checkout']}> Boutique </RouteLink> <RouteLink to={{ to: 'errors' }}> Erreurs </RouteLink> <RouteLink to={{ to: 'widget' }}> Widget </RouteLink> <RouteLink to={{ to: 'composition' }}> Composition </RouteLink> <RouteLink to={{ to: 'kit' }}> Kit </RouteLink> </nav> </header> <RouterOutlet /> } } Le shell ne lit rien du store des compteurs : il ne se re-rend jamais pour lui. Il s'en sert seulement pour charger les compteurs une fois, au montage. Utilise mounted quand tu as besoin du DOM déjà rendu (mesurer, donner le focus) ou pour lancer une action au montage. Ce qui doit s'arrêter au démontage s'arrête dans unmounted : #interval: ReturnType<typeof setInterval> | undefined; // L'intervalle vit entre le montage et le démontage du widget. protected override mounted() { this.#interval = setInterval(() => this.timer.send('tick'), 1000); } protected override unmounted() { clearInterval(this.#interval); }"},{"url":"composants.html#cycle-de-vie","page":"Composants : une classe et son render","title":"Cycle de vie","text":"Création : la balise du parent (ou create ) dépose les props, puis construit l'instance (déclarations et champs, dans leur ordre, puis constructeur s'il y en a un), qui les lit déjà. Montage : l'élément entre dans le DOM. Super résout les contrats déclarés, branche les écouteurs @on , fait le premier render , pose son titre s'il en déclare un, puis appelle mounted . Rendus : à chaque changement de props, d'état local ou de valeur lue dans un store. Plusieurs changements dans la même tâche ne donnent qu'un rendu. Déplacement : un élément déplacé dans le DOM (par exemple par une boucle for avec key ) n'est pas redémarré : il garde son état. Démontage : un vrai retrait du DOM avorte signal , désabonne le composant de ses stores (lectures et écouteurs @on ), retire son titre, puis appelle unmounted . S'il est réinséré plus tard, la même instance se remonte : ses contrats sont résolus de nouveau, ses écouteurs @on rebranchés, son titre reposé, et mounted rappelé. Son état local est conservé."},{"url":"composants.html#titre-de-la-page","page":"Composants : une classe et son render","title":"Le titre de la page","text":"Le titre de l'onglet ( document.title ) appartient aux composants montés : un composant le pose par @title , et le retire en se démontant. Personne n'écrit document.title à la main."},{"url":"composants.html#titre-fixe-ou-suivi","page":"Composants : une classe et son render","title":"Un titre fixe ou suivi","text":"Une chaîne donne un titre fixe, posé au montage et retiré au démontage : @title = 'Widget'; . Une fonction donne un titre suivi : elle est recalculée après chaque rendu, avec les mêmes lectures que render . Le titre de la boutique change donc avec le panier : export class ShopScreen extends SuperElement { @tag = 'shop-screen'; // Suivi : le titre de l'onglet change avec le panier, comme le rendu. @title = () => { const count = this.cart.selectors.count(); return count > 0 ? `Boutique (${count} au panier)` : 'Boutique'; }; @contract cart; // … } Le calcul est libre (une condition, un formatage), contrairement à la fonction d'un @selector . Dans l'écran d'un compteur, @title = () => this.label.value ?? 'Compteur introuvable'; suit le nom du compteur : le renommer change aussi le titre de l'onglet."},{"url":"composants.html#this-page-title","page":"Composants : une classe et son render","title":"this.page.title","text":"@title est un raccourci : this.page.title = … fait la même chose en impératif, avec une chaîne ou une fonction. Ce qui change, c'est le moment où on l'écrit. Posé dans Effet Un champ ou le constructeur, dans un .ts (ce que fait @title ) Le titre du composant, repris à chaque montage. mounted , un gestionnaire Remplace le titre du composant jusqu'à son démontage. render Interdit : lève une erreur. onSaved = () => { this.page.title = 'Profil enregistré'; };"},{"url":"composants.html#la-pile-des-titres","page":"Composants : une classe et son render","title":"La pile des titres","text":"Plusieurs composants montés peuvent poser un titre en même temps. Le dernier monté l'emporte ; ceux en dessous continuent de suivre leurs données sans s'afficher ; quand il se démonte, le titre précédent revient. N'importe quel composant peut poser un titre, pas seulement un écran : dans la démo, KitPage , la mise en page commune du kit, donne leur titre à toutes les pages du kit avec @title = () => this.heading; . Le déroulé, pour la boutique et un dialogue de confirmation qui déclarerait @title = 'Confirmation'; , avec le réglage de la démo ( suffix: ' · Super' , default: 'Super · exemples' ) : Moment Titres posés (du plus ancien au plus récent) Titre de l'onglet La boutique se monte, panier vide Boutique Boutique · Super Un produit ajouté au panier Boutique (1 au panier) Boutique (1 au panier) · Super « Vider le panier » ouvre le dialogue Boutique (1 au panier) , Confirmation Confirmation · Super « Confirmer » : le panier se vide, le dialogue se démonte Boutique Boutique · Super Navigation vers un écran sans titre aucun Super · exemples À l'avant-dernière ligne, la boutique a suivi le panier vidé pendant que le dialogue était au-dessus : son titre est déjà à jour quand il revient."},{"url":"composants.html#titre-ce-qui-est-interdit","page":"Composants : une classe et son render","title":"Ce qui est interdit","text":"Poser le titre pendant render : this.page.title lève une erreur (« ne se pose pas pendant render »). Lire le titre : this.page.title se pose, il ne se lit pas ; le lire lève une erreur. Une prop nommée title : c'est une propriété des éléments HTML (la démo l'appelle heading ). page est réservé."},{"url":"composants.html#titre-par-defaut-et-suffixe","page":"Composants : une classe et son render","title":"Titre par défaut et suffixe","text":"Le router règle ce qui entoure les titres posés, dans les options de createRouter (pas dans defineRouter , dont les clés sont des routes) : const router = createRouter(Router, { title: { default: 'Super · exemples', suffix: ' · Super' } }); default s'affiche quand aucun composant ne pose de titre ; suffix est ajouté au titre posé. Sans default , c'est le titre d'origine du document qui revient. Voir Le titre de la page dans la page du router."},{"url":"composants.html#creer-un-element-hors-template","page":"Composants : une classe et son render","title":"Créer un élément hors template","text":"Dans un fichier .super , <CounterControls count={count} … /> monte l'enfant à cet emplacement (voir Parents et enfants ) ; l'outillage le traduit en CounterControls.create(props, { on }) . Hors template, pour le montage initial ou un test, on appelle ce create(props?, { on }?) directement : il renvoie l'élément. createApp({ root, stores, router }).mount(AppShell.create()); Un composant ne s'écrit pas par son tag : <counter-screen> tapé dans un template ou dans index.html n'est pas supporté. Il passe toujours par sa classe, en balise ( <CounterControls count={count} … /> ) ou par create ."},{"url":"contrats.html","page":"Contrats","title":"Contrats","text":"Un contrat décrit un store vu de l'extérieur : ce qu'on peut lire, ce qu'on peut lui demander, ce qu'il annonce. C'est la seule chose qu'un composant connaît d'un store."},{"url":"contrats.html#declarer-un-contrat","page":"Contrats","title":"Déclarer un contrat","text":"import { type Outcome, SuperContract } from '@super-ts/core'; import { COUNTERS, MIN_COUNT } from '../../domain/counter'; export type CounterState = { counts: Readonly<Record<string, number>>; loadErrorMessage: string | null; }; export type CounterTypes = { state: CounterState; commands: { load(): void; increment(input: { id: string }): Outcome<{ count: number }, 'unknown' | 'storage'>; decrement(input: { id: string }): Outcome<{ count: number }, 'unknown' | 'below-min' | 'storage'>; reset(input: { id: string }): Outcome<{ count: number }, 'unknown' | 'storage'>; }; }; export class CounterContract extends SuperContract<CounterTypes> { constructor() { super({ name: 'counter' }); } count(s: CounterState, id: string) { return s.counts[id] ?? 0; } canDecrement(s: CounterState, id: string) { return (s.counts[id] ?? 0) > MIN_COUNT; } // … } Un contrat tient en trois morceaux : Un type ( CounterTypes ) qui décrit son état, ses commandes et ses événements, pour le compilateur. Une classe qui étend SuperContract<CounterTypes> et se nomme dans son constructeur : super({ name: 'counter' }) . Ce nom est la clé du contrat dans toute l'app : un composant déclare @contract counter; , un store déclare super({ contract: 'counter', … }) . Des méthodes , facultatives : chacune est un sélecteur, une lecture autorisée de l'état (voir Sélecteurs ). Un contrat vit dans src/@core/<nom>/contract.ts , un dossier par contrat, à côté de son store. Le plugin Vite lit ces fichiers et génère src/@core/contracts.d.ts , le dictionnaire nom → classe qui type @contract counter; , @on('counter', …) et StoreOfContract<'counter'> . Ce fichier se committe, mais ne s'écrit jamais à la main."},{"url":"contrats.html#les-trois-cles","page":"Contrats","title":"Les trois clés : state, commands, events","text":"Clé Requise Ce qu'elle décrit Si on l'omet state oui L'interface de l'état que le store garde en mémoire. Un objet. Ne compile pas. commands non Ce qu'on peut demander au store : nom(body): void . Le store n'accepte aucune commande. events non Ce que le store annonce : nom: payload . Le store n'émet rien. Ce contrat minimal est valide : export class ClockContract extends SuperContract<{ state: { now: number } }> { constructor() { super({ name: 'clock' }); } }"},{"url":"contrats.html#state","page":"Contrats","title":"state : l'interface de l'état","text":"state est le type de ce que le store garde en mémoire. Il fixe la forme de l' initialState passé au constructeur du store, ce que le store lit avec this.get() et modifie avec this.set() , et le premier paramètre des sélecteurs. Les composants ne voient jamais cette interface : ils lisent à travers les sélecteurs."},{"url":"contrats.html#commands","page":"Contrats","title":"commands : les demandes","text":"Une commande est une demande adressée au store. Elle prend au plus un paramètre , le body (un objet, plus lisible et extensible que plusieurs arguments), et rien ne revient à celui qui l'envoie . En pratique, une commande modifie souvent l'état, mais pas forcément. La règle qui compte est dans l'autre sens : seul le store modifie son état. commands: { load(): void; // sans body : send('load') increment(input: { id: string }): Outcome<{ count: number }, 'unknown' | 'storage'>; } Une commande déclare l'un ou l'autre : void : elle n'a pas d'issue particulière à publier (en dehors d'un échec inattendu). Outcome<Résultat, Raisons> : ce que produit son succès (publié dans increment:done ), et la liste fermée de ses raisons d'échec (publiées dans increment:failed ). Voir Déclarer l'issue . Rien ne revient à l'appelant Une réponse directe, ou plusieurs paramètres, ne compilent pas : // @ts-expect-error une commande ne renvoie pas de donnée class Async extends SuperContract<{ state: {}; commands: { add(): Promise<number> } }> {} // @ts-expect-error deux paramètres : une commande n'a qu'un body class Bad extends SuperContract<{ state: {}; commands: { add(a: number, b: number): void } }> {} C'est un choix de conception : le composant envoie et laisse filer, et Super publie l'issue à tous ceux qui l'écoutent. void suffit même si la méthode du store est async ."},{"url":"contrats.html#events","page":"Contrats","title":"events : les annonces","text":"Dans l' exemple Boutique : cart/contract.ts . Chaque commande a déjà ses événements, publiés par Super : increment:done et increment:failed . La clé events sert aux autres faits que le store annonce, ceux qui ne sont pas l'issue d'une seule commande. Un événement associe un nom à son payload. Seul le store émet (avec this.emit ) ; tout le monde peut écouter : composants, autres stores, tests. // Un événement écrit à la main : un fait qui n'est pas l'issue d'une seule commande. // Le panier devient vide après `clear`, ou après le `remove` du dernier article. events: { emptied: void; // this.emit('emptied'), sans payload }; Un événement avec payload s'écrit synced: { at: number } et s'émet par this.emit('synced', { at: Date.now() }) ."},{"url":"contrats.html#ce-qu-un-contrat-n-est-pas","page":"Contrats","title":"Ce qu'un contrat n'est pas","text":"Pas une implémentation. Il ne dit pas comment les commandes sont traitées : c'est le rôle du store . Pas une instance. Un contrat ne porte aucun état. Il peut exister plusieurs stores pour le même contrat (un par test, par exemple). Pas les dépendances du store. Le CounterRepository n'apparaît pas dans le contrat : c'est un détail d'implémentation, déclaré par le constructeur du store. À l'exécution, Super ne lit d'un contrat que son nom et ses méthodes (les sélecteurs). Les types state , commands et events n'existent que pour le compilateur."},{"url":"contrats.html#qui-utilise-le-contrat","page":"Contrats","title":"Qui utilise le contrat","text":"Qui Pour quoi Le store class CounterStore extends SuperStore<CounterContract> implements Commands<CounterStore> : le compilateur exige une méthode par commande et vérifie les événements émis. Les composants @contract counter; pour lire par les sélecteurs et envoyer, @on('counter', …) pour écouter (voir les déclarations ). createApp Retrouve le bon store pour un composant : le nom du contrat sert de clé. Le plugin Vite Lit les contrats de src/@core/ , génère contracts.d.ts , refuse deux contrats du même nom. Les tests fakeStore('counter', …) pour un composant ; store.selectors.count('cafes') sur le handle d'un vrai store."},{"url":"contrats.html#pieges","page":"Contrats","title":"Pièges","text":"Une clé mal orthographiée est refusée command au lieu de commands (ou event au lieu de events ) ne compile pas : l'erreur apparaît sur super({ name }) , avec la clé en cause et les clés attendues (« clé inconnue dans les types du contrat : command (attendu : state, commands, events) »). Le nom s'écrit en toutes lettres Le plugin lit super({ name: 'counter' }) dans le source : le nom doit être une chaîne littérale. Deux contrats du même nom sont refusés, et 'router' est réservé au router de l'app. L'état des sélecteurs s'annote à la main TypeScript n'infère pas les paramètres d'une méthode : écris count(s: CounterState, id: string) . Ce premier paramètre est vérifié à la déclaration du store ( SuperStore<CounterContract> ) : un type qui n'accepte pas l'état du contrat ne compile pas."},{"url":"demarrer.html","page":"Démarrer","title":"Démarrer","text":"Installer le dépôt, lancer l'exemple, puis écrire une fonctionnalité complète de bout en bout."},{"url":"demarrer.html#installer","page":"Démarrer","title":"Installer","text":"Super n'est pas encore publié sur npm. On travaille dans le dépôt, qui contient les paquets et une app d'exemple. npm install npm run dev # l'app d'exemple sur http://localhost:5173 npm test # les tests (Vitest, happy-dom) npm run typecheck # super-tsc : les types des .ts et des .super, tests de types *.test-d.ts compris npm run lint # Biome (ordre des imports, formatage) et formatage des .super npm run format # formate tout : Biome pour les .ts, le formateur des .super pour les .super npm run check # lint, typecheck, tests, puis index de la doc Les paquets @super-ts/core , @super-ts/dom , @super-ts/testing , @super-ts/ui et @super-ts/vite sont résolus par des alias déclarés dans les tsconfig.json et vite.config.ts . Dans l'app, les dossiers Super s'importent eux aussi par alias, depuis n'importe quel fichier : '@core/counter/contract' , '@components/app-shell' (voir Architecture ). Les composants s'écrivent dans des fichiers .super : le plugin Vite les compile, et npm run typecheck les vérifie. Pour avoir les erreurs et la complétion dans ton éditeur, branche le serveur de langage des .super (voir Outillage )."},{"url":"demarrer.html#l-app-d-exemple","page":"Démarrer","title":"L'app d'exemple","text":"examples/demo est une seule app, qui regroupe les exemples de Super. npm run dev la lance sur http://localhost:5173 ; sa page d'accueil mène à chaque exemple : Compteurs ( /counters ) : une liste de compteurs, une page de détail par compteur avec des boutons + et −, une persistance dans le localStorage . Formulaire de profil ( /profile ) : tous les types de champs, des règles, une vérification asynchrone, une liste dynamique, et un serveur simulé (latence, adresse prise, panne réseau). Boutique ( /shop ) : un store qui dépend d'un autre, un événement écrit à la main, un dialogue de confirmation, un guard. Erreurs ( /errors ) : chaque niveau de gestion des erreurs, provoqué pour de vrai, avec le journal de onError . Widget ( /widget ) : une seconde application dans la page, un mounted avec nettoyage par signal , un raccourci clavier. Kit ( /kit ) : un sommaire et une page par famille de composants de @super-ts/ui , branchés sur les stores de la démo, dont une table branchée sur une vraie API et une page de thème. Presque tous les extraits de cette doc en viennent : quand un extrait est tiré de l'exemple, un lien mène au fichier complet. La page Exemples détaille ce que montre chaque fichier. examples/demo/src/ ├── @core/ imposé par Super : un dossier par contrat │ ├── counter/ contract.ts, store.ts, store.test.ts │ ├── profile/, cart/, checkout/, error-log/, timer/, catalog/ │ └── contracts.d.ts généré par le plugin Vite : le dictionnaire des contrats ├── @components/ imposé par Super : un dossier par écran │ ├── app-shell/ la coquille : navigation et RouterOutlet │ ├── counter/ index.super (CounterScreen), counter-controls.super, leurs .css et tests │ ├── counter-list/, profile/, shop/, checkout/, errors/, widget/, composition/, kit/ │ ├── examples/, not-found/, error/ │ └── shared/ composants réutilisables (confirm-dialog.super) ├── domain/ user-land : types et règles métier, ni Super ni DOM ├── ports/ user-land : interfaces dont dépendent les stores ├── adapters/ user-land : localStorage, mémoire, serveur simulé, API HTTP ├── widgets/ user-land : une seconde app montée dans la page ├── routes.ts user-land : chemins et écrans, d'où sort le Router typé └── main.ts user-land : racine de composition"},{"url":"demarrer.html#ta-premiere-fonctionnalite","page":"Démarrer","title":"Ta première fonctionnalité : un bouton de thème","text":"On va ajouter un bouton qui bascule entre mode clair et mode sombre. C'est volontairement simple, mais ça passe par toutes les étapes : contrat, store, composant, branchement et test."},{"url":"demarrer.html#etape-1-le-contrat","page":"Démarrer","title":"Étape 1 : le contrat","text":"Le contrat décrit ce que le store sait faire, sans dire comment. C'est une classe, dans son propre dossier sous src/@core/ , qui se nomme dans son constructeur : c'est par ce nom qu'on la demandera. import { SuperContract } from '@super-ts/core'; export type ThemeMode = 'light' | 'dark'; export type ThemeState = { mode: ThemeMode }; export type ThemeTypes = { state: ThemeState; // ce que le store garde en mémoire commands: { toggle(): void }; // ce qu'on peut lui demander events: { changed: { mode: ThemeMode } }; // ce qu'il annonce }; export class ThemeContract extends SuperContract<ThemeTypes> { constructor() { super({ name: 'theme' }); } // Ce qu'on peut lire : un sélecteur est une méthode qui reçoit l'état. isDark(s: ThemeState) { return s.mode === 'dark'; } } Le plugin Vite repère le contrat et l'inscrit dans src/@core/contracts.d.ts , un fichier généré (à committer, jamais à écrire à la main). C'est ce qui fait connaître 'theme' au compilateur partout dans l'app. Voir Contrats et Sélecteurs ."},{"url":"demarrer.html#etape-2-le-store","page":"Démarrer","title":"Étape 2 : le store","text":"Le store implémente le contrat : un état de départ, et une méthode par commande. import { type Commands, SuperStore } from '@super-ts/core'; import type { ThemeContract } from './contract'; export class ThemeStore extends SuperStore<ThemeContract> implements Commands<ThemeStore> { constructor() { super({ contract: 'theme', initialState: { mode: 'light' } }); } toggle() { const mode = this.selectors.isDark() ? 'light' : 'dark'; this.set({ mode }); this.emit('changed', { mode }); } } implements Commands<ThemeStore> fait vérifier les méthodes par le compilateur : une commande oubliée, un paramètre différent du contrat ou une méthode publique hors contrat ne compilent pas. Ce constructeur ne prend rien : le store se crée avec ThemeStore.create() . Voir Stores ."},{"url":"demarrer.html#etape-3-le-composant","page":"Démarrer","title":"Étape 3 : le composant","text":"Le composant demande le store par le nom de son contrat, lit un sélecteur et envoie la commande au clic. Il est réutilisable : il va dans src/@components/shared/ , dans un fichier .super . import { SuperElement } from '@super-ts/dom'; export class ThemeToggle extends SuperElement { @tag = 'theme-toggle'; // Une fois, à la construction : le store, et ce qu'on en lit. @contract theme; @selector isDark = this.theme.selectors.isDark; // À chaque rendu : on affiche à partir des valeurs courantes. render() { <button type=\"button\" on:click={() => this.theme.send('toggle')}> {this.isDark.value ? 'Passer en mode clair' : 'Passer en mode sombre'} </button> } } render() ne renvoie rien : le bouton est écrit comme une instruction, on:click pose l'écouteur et {…} affiche une valeur (voir Templates ). Le composant n'importe rien de src/@core/ : @contract theme; suffit, et le compilateur connaît les sélecteurs et les commandes du contrat. Voir Composants et Lire un store ."},{"url":"demarrer.html#etape-4-le-branchement","page":"Démarrer","title":"Étape 4 : le branchement","text":"La racine de composition, main.ts , crée les stores et les fournit à l'app. Le composant peut alors être utilisé n'importe où sous la racine, par exemple dans l'en-tête de la coquille : <ThemeToggle /> , après import { ThemeToggle } from '@components/shared/theme-toggle' . const counter = CounterStore.create({ counterRepository: createLocalStorageCounterRepository() }); const theme = ThemeStore.create(); const router = createRouter(Router); createApp({ root: document.querySelector<HTMLElement>('#app')!, stores: [counter, theme], router }) .mount(AppShell.create()); L'app retrouve chaque store par le nom de son contrat : un composant qui demande 'theme' reçoit celui-ci. Voir Brancher l'application ."},{"url":"demarrer.html#etape-5-le-test","page":"Démarrer","title":"Étape 5 : le test","text":"import { flush, mount } from '@super-ts/testing'; import { ThemeStore } from '@core/theme/store'; import { within } from '@testing-library/dom'; import userEvent from '@testing-library/user-event'; import { expect, test } from 'vitest'; import { ThemeToggle } from './theme-toggle'; test('le bouton bascule le thème', async () => { const theme = ThemeStore.create(); const { container } = await mount(ThemeToggle, { stores: [theme] }); await userEvent.click(within(container).getByRole('button')); await flush(); expect(theme.selectors.isDark()).toBe(true); expect(container.textContent).toContain('Passer en mode clair'); }); Le test reste un .ts : il importe le composant .super sans extension et le monte avec mount . Un test peut importer un store : le plugin ne vérifie pas les fichiers *.test.ts . Pour tester le composant seul, remplace le vrai store par fakeStore('theme', { state: { mode: 'dark' } }) . Voir Tester ."},{"url":"demarrer.html#et-ensuite","page":"Démarrer","title":"Et ensuite","text":"Persister le thème : ajoute un port ThemeStorage et un adapter localStorage (voir Ports et adapters ). Comprendre le trajet complet d'une action : Commandes et événements . Ajouter des pages : Router ."},{"url":"erreurs.html","page":"Gérer les erreurs","title":"Gérer les erreurs","text":"Quand un composant plante, Super peut afficher un rendu de repli à la place de la partie cassée, et signaler l'erreur à un endroit unique. Trois niveaux, du plus local au plus global : le renderError d'un composant, l'écran '!' du router, et onError dans l'application."},{"url":"erreurs.html#sans-frontiere","page":"Gérer les erreurs","title":"Sans rien déclarer","text":"Chaque cas de cette page se provoque dans l' exemple Erreurs ( npm run dev , puis /errors ) : errors/index.super et ses blocs, main.ts . Son journal affiche ce que reçoit onError . Exemple : l'écran d'un compteur appelle label.toUpperCase() alors que label vaut null . Sans frontière d'erreur, l'écran reste vide (ou figé sur son dernier affichage si l'erreur survient plus tard), l'erreur part dans la console, et le reste de la page continue de fonctionner. L'utilisateur voit une zone blanche, sans explication."},{"url":"erreurs.html#render-error","page":"Gérer les erreurs","title":"Le renderError d'un composant","text":"renderError(error) est une méthode facultative, à côté de render . Elle s'affiche à la place de render quand le composant, ou l'un de ses descendants, plante. Elle s'écrit comme render : elle émet ses éléments, sans return . import { SuperElement } from '@super-ts/dom'; /** 1. Un bloc qui plante au rendu quand on le casse : son propre renderError remplace seulement sa zone. */ export class FragileCard extends SuperElement { @tag = 'fragile-card'; @prop broken: boolean; render() { if (this.broken) throw new Error('le bloc a lu une donnée absente'); <p class=\"ok\">Ce bloc s'affiche normalement.</p> } override renderError(error: Error) { <p class=\"fallback\">Ce bloc a planté ({error.message}) : son renderError le remplace, le reste de la page continue.</p> } } Il reçoit l'erreur , toujours un Error : une valeur levée qui n'en est pas un est convertie. Il a accès aux props ( this.broken ) et aux champs du composant, comme render . Il rattrape les erreurs des descendants : si un enfant plante, au rendu comme dans son constructeur, le parent entier passe à son renderError . Il rattrape un store introuvable au montage (phase setup ) : l'instance existe, il peut afficher un remplacement. S'il lit lui-même ce store, il plante à son tour et l'erreur remonte. Il ne rattrape pas l'erreur de son propre constructeur : si le constructeur (ou un champ) plante, l'instance n'existe pas. L'erreur (phase setup ) remonte au renderError d'un ancêtre. Une fois en renderError , le composant y reste jusqu'à son démontage. Il continue de se re-rendre si ses props changent. Un écran est remonté à chaque navigation, ce qui le remet à zéro. Pour remettre à zéro un bloc, on le recrée : l'exemple Erreurs place ses blocs dans for (const _round of [round]; key _round) , et « Recommencer » incrémente round , ce qui change la clé et recrée les composants (voir Listes ). S'il plante lui-même , l'erreur remonte au parent suivant : pas de boucle. /** 2. (suite) Le parent de BrokenChild : son renderError rattrape l'erreur de l'enfant. */ export class GuardedPanel extends SuperElement { @tag = 'guarded-panel'; @prop withChild: boolean; render() { <p class=\"ok\">Panneau parent.</p> if (this.withChild) { <BrokenChild /> } } override renderError(error: Error) { <p class=\"fallback\">Le parent a rattrapé l'erreur de son enfant ({error.message}).</p> } } BrokenChild , écrit <BrokenChild /> dans le render du panneau, lève une erreur dans son constructeur. Elle est signalée au nom de l'enfant ( tag: 'broken-child' , phase: 'setup' ) et rattrapée par GuardedPanel ( caughtBy: 'guarded-panel' ). Pourquoi une méthode à part, et pas une erreur passée à render Si c'est render qui a planté, le rappeler risquerait de replanter au même endroit. renderError est un second rendu, écrit pour ne dépendre que de l'erreur et du strict nécessaire."},{"url":"erreurs.html#ou-mettre-un-render-error","page":"Gérer les erreurs","title":"Où mettre un renderError","text":"Sur un écran , pour un message adapté à la page (« Impossible d'afficher ce compteur »). Sur une partie autonome d'un écran (un graphique, un widget), pour que le reste de l'écran reste utilisable. Sur le shell ( AppShell ), pour couvrir les erreurs hors de l'écran actif, comme dans l'en-tête. Pas besoin d'en mettre partout : l'écran '!' sert de filet par défaut pour tous les écrans."},{"url":"erreurs.html#l-ecran-d-erreur","page":"Gérer les erreurs","title":"L'écran '!' du router","text":"Si l'erreur d'un écran remonte jusqu'au RouterOutlet sans avoir été rattrapée, l'outlet affiche l'écran '!' à la place de l'écran actif. Le shell et la navigation restent utilisables. .screens(() => ({ examples: ExamplesScreen, // … errors: ErrorsScreen, widget: WidgetScreen, composition: CompositionScreen, // … '*': NotFoundScreen, '!': ErrorScreen, })); import { SuperElement } from '@super-ts/dom'; /** Écran '!' : affiché par le router quand un écran plante sans être rattrapé. */ export class ErrorScreen extends SuperElement { @tag = 'error-screen'; @title = 'Erreur'; @prop error: Error; @prop path: string; render() { <main class=\"screen\"> <h1>Cette page a rencontré un problème</h1> <p>{this.error.message}</p> <button type=\"button\" on:click={() => this.router.send('navigate', { to: 'examples' })}>Retour aux exemples</button> </main> } } L'écran '!' reçoit l'erreur et le chemin en props : c'est le seul écran qui reçoit des props du router. Le compilateur exige que ses props soient { error: Error; path: string } : @prop error: Error; et @prop path: string; . Toute navigation le referme et remonte un écran neuf : aller sur une autre page puis revenir, ou simplement recliquer sur le lien de la page en erreur. Si l'écran plante encore, l'écran '!' réapparaît. S'il plante lui-même, l'erreur continue de remonter. /** 3. Un bloc dont le renderError plante aussi : l'erreur remonte jusqu'à l'écran '!' du router. */ export class DoubleFailure extends SuperElement { @tag = 'double-failure'; @prop armed: boolean; render() { if (this.armed) throw new Error('rendu cassé'); <p class=\"ok\">Prêt.</p> } override renderError(): unknown { throw new Error('le renderError a planté lui aussi'); } }"},{"url":"erreurs.html#onerror","page":"Gérer les erreurs","title":"Signaler : onError","text":"onError , dans createApp , reçoit toute erreur de composant rendu sous la racine, qu'elle ait été rattrapée ou non. C'est l'endroit unique pour journaliser ou prévenir un outil de suivi. createApp({ root: document.querySelector<HTMLElement>('#app')!, stores: [counter, profile, cart, checkout, errorLog, catalog], router, // Toute erreur de composant, rattrapée ou non : la console, et le journal affiché par l'exemple « Erreurs ». onError: (error, { tag, phase, caughtBy }) => { console.error(`[${tag}] ${phase}`, { caughtBy }, error); errorLog.send('record', { message: error.message, tag, phase, caughtBy }); }, }).mount(AppShell.create()); En production, on y branche plutôt un outil de suivi : export function reportToMonitoring(error: Error, context: { tag: string; phase: string; caughtBy: string | null }) { if (import.meta.env.DEV) console.error(`[${context.tag}] ${context.phase}`, error, context); else navigator.sendBeacon('/api/errors', JSON.stringify({ message: error.message, stack: error.stack, ...context })); } reportToMonitoring est une fonction de ton projet : Super l'appelle par onError , il ne l'implémente pas. Information Contenu error L'erreur, toujours un Error . tag Le composant qui a planté ( 'fragile-card' ). phase 'setup' (constructeur, ou store introuvable au montage), 'render' ou 'renderError' : l'affichage était cassé. 'event' , 'listener' ou 'mount' : une action a échoué (voir plus bas). caughtBy Ce qui l'a rattrapée : le tag d'un composant avec renderError , 'super-router-outlet' pour l'écran '!' , ou null . Sans onError , une erreur rattrapée part dans la console, et une erreur non rattrapée est levée. Avec des applications imbriquées, c'est la plus proche du composant qui signale, une seule fois."},{"url":"erreurs.html#qui-rattrape-quoi","page":"Gérer les erreurs","title":"Qui rattrape quoi","text":"Une erreur remonte l'arbre des composants depuis celui qui a planté. Le premier qui sait la traiter la garde : le composant qui a planté, s'il a un renderError (sauf pour l'erreur de son propre constructeur) ; sinon son parent, puis le parent du parent, jusqu'au premier qui a un renderError ; sinon, si elle atteint le RouterOutlet , l'écran '!' ; sinon personne : le composant reste vide. Dans tous les cas, onError est appelé une fois. Les blocs de l'exemple Erreurs couvrent chaque ligne : Ce qui plante Ce qui s'affiche FragileCard au rendu, avec son propre renderError Son renderError , à la place du bloc seulement. caughtBy: 'fragile-card' . BrokenChild dans son constructeur, sous GuardedPanel (avec renderError ) Le renderError de GuardedPanel , à la place de tout le panneau. tag: 'broken-child' , phase: 'setup' , caughtBy: 'guarded-panel' . DoubleFailure au rendu, puis son renderError L'erreur continue jusqu'au RouterOutlet : écran '!' à la place de l'écran Erreurs. La navigation reste utilisable. Un écran sans renderError ( CounterListScreen ) L'écran '!' , à la place de la liste des compteurs. L'en-tête dans AppShell , sans renderError Rien n'est rattrapé : l'en-tête reste vide, onError est appelé. Un renderError sur AppShell couvre ce cas."},{"url":"erreurs.html#erreurs-d-action","page":"Gérer les erreurs","title":"Les erreurs d'action : on:événement, on, mounted","text":"Une erreur dans un gestionnaire d'événement du template, dans un écouteur on d'un contrat, ou dans mounted / unmounted est elle aussi signalée à onError , avec le composant d'où elle vient. Rien à écrire : Super enveloppe ces fonctions lui-même."},{"url":"erreurs.html#4-un-clic-qui-plante","page":"Gérer les erreurs","title":"4. Un clic qui plante","text":"L'affichage ne change pas : l'erreur est seulement signalée (phase event ). { throw new Error('le gestionnaire de clic a planté'); }}>Clic qui plante Une erreur dans… phase À l'écran un gestionnaire on:click={…} (synchrone ou asynchrone) 'event' Rien ne change. un écouteur @on('counter', '…') ( this.counter.on(…) dans un .ts ) 'listener' Rien ne change. mounted() ou unmounted() 'mount' Rien ne change. Le composant ne bascule pas sur son renderError : quand une action échoue, l'affichage est en général toujours juste. Remplacer l'écran entier pour un clic raté serait disproportionné. L'erreur est seulement signalée (dans la console sans onError ), et caughtBy vaut null ."},{"url":"erreurs.html#ce-qui-n-est-pas-couvert","page":"Gérer les erreurs","title":"Ce qui n'est pas couvert","text":"Le code que Super ne voit pas passer : un setTimeout , ou la fonction d'un window.addEventListener posé à la main dans mounted . Une erreur à cet endroit part dans la console. unmounted d'un composant retiré du DOM : l'erreur ne peut plus remonter à l'application. Elle part dans la console. Un gestionnaire construit hors d'un composant , dans un gabarit html créé au chargement d'un module .ts par exemple : il n'est rattaché à aucun composant. Le constructeur d'un composant créé hors template ( AppShell.create() dans main.ts ) : l'erreur est levée à l'appel de create , comme pour tout code. Les erreurs des stores : elles ne passent pas par là. Un store rattrape ses erreurs et les publie par son état ou un événement (voir Stores : les erreurs ). Les erreurs de configuration levées par Super lui-même (deux stores pour un contrat, route inconnue dans href , static tag manquant dans un composant .ts ) : ce sont des erreurs de programmation, à corriger."},{"url":"erreurs.html#tester-les-erreurs","page":"Gérer les erreurs","title":"Tester les erreurs","text":"mount accepte aussi onError : const onError = vi.fn(); const { container } = await mount(FragileCard, { props: { broken: true }, onError }); expect(container.textContent).toContain('Ce bloc a planté (le bloc a lu une donnée absente)'); expect(onError).toHaveBeenCalledWith(expect.any(Error), { tag: 'fragile-card', phase: 'render', caughtBy: 'fragile-card' });"},{"url":"etat-local.html","page":"État local","title":"État local","text":"L'état local appartient à une instance de composant : privé, créé avec elle, perdu avec elle. Il sert aux données d'interface ; les données de l'app vivent dans un store."},{"url":"etat-local.html#creer-un-etat-local","page":"État local","title":"Créer un état local","text":"export class StatusLine extends SuperElement { @tag = 'status-line'; @state local = { message: null as string | null }; render() { <p role=\"status\">{this.local.get().message}</p> } } Écriture Rôle @state local = initial; Déclare l'état dans le corps de la classe, qui se lit ensuite par this.local (voir les déclarations ). La valeur initiale est copiée. Dans un composant écrit en .ts , l'équivalent est local = this.state(initial) , dans un champ ou le constructeur uniquement (pendant render , il lève une erreur). get() La valeur courante, figée. À appeler dans render pour refléter le dernier changement. set(patch) Fusionne le patch (un niveau), puis re-rend le composant. Accepte un objet partiel ou une fonction (courant) => patch . this.local.set({ message: 'Incrémenté : 3' }); this.local.set((current) => ({ clicks: current.clicks + 1 })); Plusieurs set d'affilée ne donnent qu'un seul rendu."},{"url":"etat-local.html#le-type-et-null-as","page":"État local","title":"Le type, et null as string | null","text":"@state ne porte pas de type : il vient de la valeur initiale (écrire @state local: … = … est une erreur). @state local = { message: null }; donnerait un champ de type null , et this.local.set({ message: 'ok' }) ne compilerait pas. On élargit donc avec as les champs qui changeront de type : @state local = { message: null as string | null, open: false, selectedId: null as string | null };"},{"url":"etat-local.html#local-ou-store","page":"État local","title":"État local ou store ?","text":"Dans l'état local Dans un store Un message de confirmation affiché sous des boutons Les valeurs des compteurs Un panneau ouvert ou fermé, un onglet actif Un « chargement en cours » que plusieurs composants affichent Une saisie en cours, avant validation Les données validées et persistées La question d'un dialogue ouvert Une erreur de chargement à montrer sur plusieurs écrans Les questions à se poser : Un autre composant en a-t-il besoin ? Si oui, store. Doit-elle survivre à la navigation ? Si oui, store. L'état local disparaît avec l'écran : en revenant sur « Cafés », le message de la visite précédente n'est plus là, et c'est ce qu'on veut. Est-ce une donnée de l'app ou un détail d'affichage ? Donnée de l'app : store."},{"url":"etat-local.html#un-evenement-transforme-en-etat-local","page":"État local","title":"Un événement transformé en état local","text":"L'issue d'une commande est ponctuelle : pour l'afficher, l'écran la recopie dans son état local. C'est le cas du message « Incrémenté : 3 », dans une méthode @on de l'écran d'un compteur : counterId = this.router.current.params.id; @contract counter; // … @state local = { message: null as string | null }; // L'écran envoie une commande et laisse filer ; Super publie l'issue de chacune. @on('counter', 'increment:done') onIncremented({ input, result }) { this.#done('increment', input.id, result.count); } // … // Seules les issues du compteur affiché deviennent un message. #done(change: CounterChange, id: string, count: number) { if (id === this.counterId()) this.local.set({ message: `${DONE[change]} : ${count}` }); } La méthode lit le paramètre de la route ( this.counterId() ) quand l'événement arrive : elle voit ainsi la valeur à jour, et non celle du moment où le composant a été créé."},{"url":"etat-local.html#caracteristiques","page":"État local","title":"Ce qu'il faut savoir","text":"Privé : seul ce composant le lit et l'écrit. Ni le store, ni le parent, ni les autres composants n'y ont accès. Par instance : deux écrans montés en même temps ont chacun le leur. Lié à l'instance : il naît avec le composant et disparaît avec lui. Un élément déplacé par une boucle for avec key le garde ; un composant que le parent cesse de rendre puis rend de nouveau est une nouvelle instance, avec un état neuf. Réactif : set re-rend le composant, comme un changement de store. C'est l'équivalent du useState de React, regroupé dans un seul objet."},{"url":"exemples.html","page":"Exemples","title":"Exemples","text":"Les exemples de Super vivent dans une seule app, examples/demo . Sa page d'accueil mène à chacun : compteurs, formulaire, boutique, erreurs, widget, composition, kit d'interface. Cette page dit quel fichier montre quel concept."},{"url":"exemples.html#lancer-l-app","page":"Exemples","title":"Lancer l'app","text":"npm install npm run dev # http://localhost:5173 : la liste des exemples Pour suivre les liens « Voir le fichier » de cette doc vers le code, ouvre la doc avec npm run docs (elle sert alors tout le dépôt), ou ouvre directement docs/index.html dans un navigateur."},{"url":"exemples.html#ce-qui-est-commun","page":"Exemples","title":"Ce qui est commun aux exemples","text":"L'app suit l'organisation de Super : un dossier par contrat sous src/@core/ ( contract.ts , store.ts , store.test.ts ), un dossier par écran sous src/@components/ ( index.super , sa feuille index.css , son test index.test.ts , et ses sous-composants à plat à côté), les composants réutilisables dans @components/shared/ , et le métier dans src/domain/ . Le reste ( ports/ , adapters/ , routes.ts , main.ts , widgets/ ) est du user-land. Les composants sont des fichiers .super (voir Templates ) ; tout le reste, tests compris, est en .ts . Fichier Ce qu'il montre Voir src/main.ts La racine de composition : les adapters choisis (dont celui du catalogue, sur dummyjson.com), les stores créés par XStore.create(deps) , le router (avec le titre de l'onglet par défaut et son suffixe, createRouter(Router, { title: { default, suffix } }) ), createApp et onError . Elle charge aussi styles.css puis kit-theme.css . Brancher l'application src/routes.ts Le router : routes nommées, un écran par route, des queries décrites et typées ( query<CountersQuery>({ sort: … }) pour la liste des compteurs, query<KitTableQuery>({ sort, order, page }) pour la table branchée du kit), une redirection ( /form ), un guard, les écrans '*' et '!' . Router src/@core/contracts.d.ts Le dictionnaire nom → contrat (et 'router' ), généré par le plugin Vite : il type @contract et @on ( this.contract('…') dans un .ts ), fakeStore('…') et StoreOfContract<'…'> . Committé, jamais écrit à la main. Le plugin Vite src/domain/ Les types et règles métier ( Product , CartLine , le catalogue des compteurs…), sans Super ni DOM, importés par les contrats, les stores et les écrans. Le user-land @components/app-shell/index.super La coquille : navigation par des RouteLink du kit, qui posent aria-current eux-mêmes ( activeFor pour une section), <RouterOutlet /> , un mounted() qui charge les compteurs. RouteLink , Charger les données au démarrage @components/examples/index.super Un écran sans store ni état : seulement des liens construits par this.router.href(…) . Liens @components/not-found/index.super L'écran '*' , qui lit le chemin par this.router.current.path et envoie navigate au router. Le router dans un composant @components/error/index.super L'écran '!' , qui reçoit l'erreur et le chemin en props. L'écran '!' src/styles.css et les .css des composants Les styles globaux (dont color-scheme: light dark : l'app suit le thème du système), puis une feuille par composant ( index.css de chaque écran) imbriquée sous son tag. Styles d'un composant src/app.test.ts L'app entière testée : vrais stores, adapters, router en mémoire. Tester l'app entière tsconfig.json Les alias @core/ et @components/ pour TypeScript. Importer depuis @core"},{"url":"exemples.html#compteurs","page":"Exemples","title":"Exemple : les compteurs","text":"/counters liste des compteurs (cafés, pompes, livres lus) ; /counters/:id affiche un compteur avec des boutons + et −. Les valeurs sont enregistrées dans le localStorage . Fichier Ce qu'il montre Voir @core/counter/contract.ts Un contrat : CounterContract extends SuperContract , état, commandes avec Outcome et raisons d'échec, sélecteurs écrits en méthodes (catalogue compris). Contrats , Sélecteurs @core/counter/store.ts Un store : CounterStore extends SuperStore implements Commands , une dépendance vers un port, this.selectors , this.fail(raison) , résultat retourné, erreur de chargement gardée dans l'état. Stores , Commandes et événements domain/counter.ts Le métier des compteurs : catalogue, minimum, noms des changements et des raisons d'échec. Le user-land ports/counter-repository.ts Un port, en user-land. Ports et adapters adapters/local-storage-counter-repository.ts Un adapter localStorage , avec validation des données lues. Les adapters adapters/in-memory-counter-repository.ts Un adapter en mémoire, pour les tests. Tester un store @components/counter-list/index.super CounterListScreen : des @selector sur les sélecteurs, pending('load') , une erreur de chargement avec bouton « Réessayer », une boucle for avec key , un tri lu dans la query par this.router.current.query.sort ( ?sort=label ), qui ne remonte pas l'écran. Lire un store , Query @components/counter-list/counter-list-item.super Un composant par ligne, qui lit la valeur de son compteur : seule la ligne qui change se re-rend. Sa prop s'appelle counterId ( @prop counterId: string; ) : id est une propriété des éléments HTML. Lire un store @components/counter/index.super CounterScreen , un écran complet : le paramètre id lu par this.router.current.params.id dans le champ counterId , un titre d'onglet suivi ( @title = () => this.label.value ?? 'Compteur introuvable'; , qui change quand le compteur est renommé), @contract , @selector qui dépend de la route, pending() , une méthode @on par événement :done et :failed , état local ( @state ), message par raison d'échec. Composants , État local @components/counter/counter-controls.super Un sous-composant de présentation : props déclarées par @prop , événements par @emit et émis par this.emit , sans store. Parents et enfants @core/counter/store.test.ts Un store testé sans DOM : record , store.selectors , raisons d'échec. Tester un store @components/counter/index.test.ts Un écran testé avec fakeStore('counter', …) , qui émet les issues. Faux store @components/counter/counter-controls.test.ts Un composant de présentation testé seul. Tester un composant @components/counter-list/index.test.ts La liste montée par RouterOutlet avec un faux store : tri par query sans remonter l'écran. Query"},{"url":"exemples.html#formulaire","page":"Exemples","title":"Exemple : le formulaire de profil","text":"/profile est un formulaire avec chaque type de champ. Il est soumis à un serveur simulé par un adapter, avec de la latence. Pour voir chaque cas : taken@example.com est une adresse déjà prise, une adresse contenant offline provoque une panne réseau, une image de plus de 1 Mo est refusée. Fichier Ce qu'il montre Voir @core/profile/contract.ts Un store sans état : deux commandes, la soumission ( save ) et la vérification ( checkEmail ), avec leurs raisons d'échec. Leur cycle de vie suffit au formulaire. La soumission @core/profile/store.ts Un store qui traduit les réponses du serveur en issue de commande ( return this.fail(…) ). Déclarer l'issue domain/profile.ts Ce que le serveur enregistre : ProfileInput , sans Super ni DOM. Le user-land ports/profile-client.ts Le port du serveur. Ports et adapters adapters/fake-profile-client.ts Un adapter asynchrone qui simule un serveur : latence, refus, panne. Les adapters @components/profile/index.super ProfileScreen : un formulaire déclaré par @form , tous les types de champs, règles, validate , checks , liste dynamique, failures , reset . Formulaires @components/profile/index.test.ts Le formulaire testé au clavier : erreurs des règles, vérification, erreurs du serveur, liste, remise à zéro. Tester un formulaire @core/profile/store.test.ts et adapters/fake-profile-client.test.ts Le store et l'adapter testés seuls. Tester"},{"url":"exemples.html#boutique","page":"Exemples","title":"Exemple : la boutique","text":"/shop affiche un catalogue et un panier ; /shop/checkout passe la commande auprès d'un serveur simulé. Une adresse contenant refus fait refuser le paiement, offline simule une panne. Fichier Ce qu'il montre Voir domain/shop.ts Le métier de la boutique : Product , CartLine , Order , le catalogue et le calcul des lignes. Le user-land @core/cart/contract.ts Un événement écrit à la main ( emptied ), des sélecteurs qui calculent lignes et total à partir du métier. Événements écrits à la main @core/cart/store.ts Un store sans dépendance qui émet son événement au bon moment ( this.emit('emptied') ). Stores @core/checkout/contract.ts Une commande dont l'issue porte un résultat ( Outcome<Order, …> ) et trois raisons d'échec. Contrats @core/checkout/store.ts Un store qui dépend d'un autre, typé par StoreOfContract<'cart'> : il lit le panier par ses sélecteurs, lui envoie clear , écoute ses événements. Un store qui dépend d'un autre ports/order-client.ts Le port du serveur de commandes. Ports et adapters adapters/fake-order-client.ts Un serveur simulé : latence, paiement refusé, panne. Les adapters @components/shared/confirm-dialog.super Un composant réutilisable : un dialogue rendu ou non par son parent, qui répond par un événement. Un dialogue @components/shop/index.super ShopScreen : le catalogue et le panier, l'écoute de emptied , le dialogue de confirmation écouté par un champ fléché, et un titre d'onglet suivi qui compte les articles du panier ( @title = () => … : « Boutique (3 au panier) »). Parents et enfants , Le titre de la page @components/checkout/index.super CheckoutScreen : un écran protégé par un guard, un petit formulaire soumis à un store qui dépend d'un autre. Guards routes.ts Le guard de la commande, read('cart').isEmpty() , déclaré avant les écrans. Guards adapters/saved-cart.ts Le panier enregistré dans le localStorage : load() relit les quantités (en ignorant des données invalides), save(quantities) les écrit. Les adapters main.ts subscribe : le panier est créé avec les quantités enregistrées ( CartStore.create({ quantities: savedCart.load() }) ), puis enregistré à chaque changement ( cart.subscribe((state) => savedCart.save(state.quantities)) ) : il survit au rechargement de la page. Le store ne sait rien du stockage, c'est la racine de composition qui le branche. subscribe @core/checkout/store.test.ts Le store de commande testé avec un vrai panier, y compris après son dispose() . Tester un store @components/shop/index.test.ts La boutique testée : lignes et total, dialogue de confirmation (annuler, confirmer). Tester"},{"url":"exemples.html#erreurs","page":"Exemples","title":"Exemple : les erreurs","text":"/errors propose un bouton par cas. Chacun provoque une vraie erreur ; le journal en bas de l'écran montre ce que reçoit onError : le composant, la phase, et ce qui l'a rattrapée. Fichier Ce qu'il montre Voir @components/errors/index.super ErrorsScreen : un bouton par cas, un clic qui plante (phase event ), et le journal lu dans le store error-log . Qui rattrape quoi @components/errors/fragile-card.super Un renderError qui remplace le rendu de son propre composant. Gérer les erreurs @components/errors/guarded-panel.super Un parent dont le renderError rattrape l'erreur de constructeur de son enfant, broken-child.super . Qui rattrape quoi @components/errors/double-failure.super Un renderError qui plante à son tour : l'erreur remonte jusqu'à l'écran '!' . L'écran '!' @core/error-log/store.ts Le journal des erreurs, alimenté par onError . onError main.ts onError qui écrit dans la console et dans le journal. onError app.test.ts Chaque cas testé dans l'app entière, jusqu'à l'écran '!' . Tester les erreurs"},{"url":"exemples.html#widget","page":"Exemples","title":"Exemple : le widget","text":"/widget ouvre et ferme un minuteur qui vit dans une seconde application, avec son propre store. La barre d'espace le démarre ou le met en pause. Fichier Ce qu'il montre Voir widgets/timer-widget.ts Une seconde createApp sur son propre élément, puis dispose() de l'application et du store. Plusieurs applications @core/timer/store.ts Le store du minuteur, fourni seulement à la seconde application. Stores @components/widget/timer-widget.super Un mounted() qui démarre un intervalle, un unmounted() qui l'arrête. Cycle de vie @components/widget/timer-shortcuts.super Un raccourci clavier posé sur window au montage, retiré par this.signal au démontage. Cycle de vie @components/widget/index.super WidgetScreen : un @ref vers l'élément du widget, qu'il ouvre et ferme, et libère dans unmounted() si on quitte la page. Plusieurs applications @components/widget/index.test.ts Le widget testé : minuteur, raccourci clavier, libération. Tester"},{"url":"exemples.html#composition","page":"Exemples","title":"Exemple : la composition","text":"/composition montre des composants qui reçoivent du contenu de leur parent, et les deux façons de remplir un emplacement nommé : un emplacement <:actions> écrit entre les balises, ou une méthode #actions(note) qui émet des éléments. Fichier Ce qu'il montre Voir @components/composition/card.super Card : @prop heading: string; (pas title , déjà une propriété des éléments HTML), @prop content: Children; (le contenu écrit entre ses balises) et @prop actions?: Children; , placées par {this.content} et {this.actions} . Des enfants @components/composition/tabs.super Tabs : une liste d'emplacements ( panels: Children[] ), et l'onglet ouvert en état local. Emplacements nommés @components/composition/index.super CompositionScreen : une carte à enfants, une carte remplie par <:actions> , des cartes en boucle remplies par #actions(note) , des onglets remplis par des méthodes. Les boutons du contenu modifient l'état de l'écran. Composer @components/composition/index.test.ts L'écran testé : enfants, emplacement, méthode dans une boucle, onglets. Tester"},{"url":"exemples.html#kit","page":"Exemples","title":"Exemple : le kit d'interface","text":"/kit est le sommaire du kit : une page par famille de composants de @super-ts/ui , branchée sur les stores de la démo. Chaque page partage la même mise en page ( KitPage : un lien « ← Le kit », un titre, une présentation, le contenu), et a sa propre route : Page Route Ce qu'elle montre Formulaires et commandes /kit/forms Le formulaire est soumis au store du profil ( taken@example.com est une adresse déjà prise), et le bouton de commande remet vraiment le compteur des cafés à zéro. Fenêtres /kit/windows Un dialogue, une modale et une confirmation, rendus selon l'état local. Primitives /kit/primitives Un menu, un popover, une info-bulle, des onglets, un contenu repliable, un combobox à valeurs en dur, et un combobox qui cherche ses suggestions dans l'API dummyjson.com. Affichage /kit/display Les variantes de bouton, les badges, les spinners, un squelette, un état vide et un panneau d'erreur. Table /kit/table Une table statique sur les compteurs, et une table branchée sur l'API publique de test dummyjson.com, dont le tri et la page vivent dans l'URL. Thème /kit/theme Les manières de surcharger le style du kit, chacune à côté de son effet : toute l'app, une zone, le thème sombre forcé dans une zone, une instance, une règle ordinaire, une table dense. La table branchée suit les ports et adapters de la démo : le store du catalogue ne connaît que le port ProductCatalog ; main.ts lui donne l'adapter sur dummyjson.com, les tests un adapter en mémoire qui trie, pagine et cherche comme le serveur. Le store ignore une réponse dépassée par une demande plus récente : trier deux fois de suite ne peut pas afficher la page du premier tri. La page « Thème » affiche le code qu'elle applique : chaque fichier CSS y est importé deux fois, une fois pour être appliqué, une fois en texte par le suffixe Vite ?raw ( import ZONE_CSS from './theme-zone.css?raw' ), affiché dans un <pre> . Le code montré ne peut donc pas s'écarter du code appliqué. Fichier Ce qu'il montre Voir @components/kit/index.super KitScreen : le sommaire, des RouteLink vers les six pages. RouteLink @components/kit/kit-page.super KitPage : la mise en page commune, qui reçoit son titre par la prop heading et le contenu de la page en enfants. Ce n'est pas un écran, mais il donne leur titre d'onglet à toutes les pages du kit ( @title = () => this.heading; ). Composer , Le titre de la page @components/kit/kit.css La mise en page des pages, écrite par l'app : le kit n'en fournit pas. Ce que le kit apporte @components/kit/forms.super Field , Select , RadioGroup et Checkbox reliés à un @form par fieldOf ; un CommandButton préparé par commandOf ; des Toasts alimentés par les issues des commandes, écoutées par @on . Les champs , CommandButton , Toasts @components/kit/windows.super Dialog , Modal et ConfirmDialog rendus selon l'état local. Les fenêtres @components/kit/primitives.super Menu , Popover , Tooltip , des Tabs dont les panneaux sont des méthodes, Disclosure , un Combobox à valeurs en dur et un autre branché sur la recherche du catalogue. Les primitives @components/kit/display.super Les variantes de Button , Badge , Spinner , Skeleton , EmptyState , ErrorPanel . L'affichage @components/kit/table.super Une Table statique ; une Table branchée dont le tri et la page sont lus dans la query ( @selector sort = this.router.current.query.sort; …), changés par navigate sur on:sort et on:page , et chargés sur on:request par this.catalog.send('load', …) ; le chargement par pending('load') , un message d'erreur et un bouton « Réessayer ». La table branchée @components/kit/theme.super Chaque surcharge appliquée et affichée par ?raw , avec ses fichiers theme-zone.css , theme-dark.css , theme-instance.css , theme-rule.css et theme-compact.css . Surcharger le thème , Clair et sombre src/kit-theme.css Le thème du kit pour toute la démo : quelques variables --super-* sur :root , chargées par main.ts . Surcharger le thème src/domain/catalog.ts Product , les colonnes triables ( PRODUCT_SORTS ), la page demandée ( ProductQuery ) et la page reçue ( ProductPage ). Le user-land src/ports/product-catalog.ts Le port ProductCatalog : list(query) renvoie une page de produits triée côté serveur. Ports et adapters src/adapters/dummyjson-product-catalog.ts L'adapter sur l'API publique de test dummyjson.com : pagination ( limit , skip ) et tri ( sortBy , order ) faits par le serveur. Son test lui donne un faux fetch . Ports et adapters src/adapters/in-memory-product-catalog.ts L'adapter en mémoire des tests : il trie et pagine comme le serveur, et garde les demandes reçues ( queries ). Tester @core/catalog/store.ts CatalogStore et son contrat ( contract.ts ) : la commande load , qui échoue en 'network' avec un message, et ignore une réponse dépassée par une demande plus récente. Son test le vérifie. Stores @components/app-shell/index.super La navigation par RouteLink . RouteLink @components/kit/index.test.ts Chaque page testée au clavier et à la souris : le sommaire, validation et soumission, modale fermée par Échap, menu, choix dans le combobox, tri de la table statique, table branchée pilotée par l'URL (sur l'adapter en mémoire), CSS affiché par la page « Thème ». Tester un écran qui utilise le kit"},{"url":"faq.html","page":"Questions fréquentes","title":"Questions fréquentes","text":"Les questions qu'on se pose en découvrant Super, avec une réponse courte et un lien vers le détail."},{"url":"faq.html#faq-architecture","page":"Questions fréquentes","title":"Architecture","text":""},{"url":"faq.html#pourquoi-le-prefixe-arobase","page":"Questions fréquentes","title":"Pourquoi les dossiers s'appellent @core et @components ?","text":"Le préfixe @ marque ce qui appartient à Super : un dossier préfixé suit les règles de Super, un dossier sans préfixe est à toi. $ a été écarté parce qu'un shell le lit comme une variable ( cd src/$core arrive dans src/ ). Détails ."},{"url":"faq.html#imports-par-alias","page":"Questions fréquentes","title":"Comment importer depuis @core sans compter les « ../ » ?","text":"Par alias : import { CounterStore } from '@core/counter/store' dans main.ts ou un test, import type { CounterState } from '@core/counter/contract' depuis un composant. Le plugin Vite les déclare tout seul ; pour TypeScript, déclare-les dans le paths de ton tsconfig.json , chacun avec une seconde cible vers le TS virtuel des .super . Détails ."},{"url":"faq.html#mon-module-n-est-pas-charge","page":"Questions fréquentes","title":"Vite affiche « ce module n'est pas chargé ». Pourquoi ?","text":"Le plugin d'architecture a refusé le module : un contrat, un store ou un composant défini hors de son dossier, un composant qui importe autre chose que des types depuis @core/ , ou un module de @core/ qui importe @super-ts/dom . Le message dit quel nom pose problème. Déplace le fichier, passe par @contract …; , ou ajoute un sélecteur au contrat. Les quatre règles ."},{"url":"faq.html#comment-un-composant-trouve-son-store","page":"Questions fréquentes","title":"Comment un composant trouve-t-il son store sans l'importer ?","text":"Par le nom de son contrat : @contract counter; . Le plugin Vite écrit le dictionnaire des contrats dans src/@core/contracts.d.ts , ce qui donne au compilateur les sélecteurs, les commandes et les événements de chacun. Au montage, l'application la plus proche fournit le store de ce nom. Détails ."},{"url":"faq.html#pourquoi-un-composant-ne-peut-pas-importer-une-fonction-de-core","page":"Questions fréquentes","title":"Pourquoi un composant ne peut-il pas importer une fonction de @core ?","text":"Pour qu'il ne voie un store qu'à travers son contrat. Une fonction utilitaire ( countOf , findCounter ) ou une constante ( MIN_COUNT , le catalogue) devient un sélecteur du contrat : le composant y accède par this.counter.selectors . Une règle métier sans lien avec un store peut aussi vivre dans domain/ , en user-land. Quoi mettre dans un sélecteur ."},{"url":"faq.html#ou-mettre-un-repository","page":"Questions fréquentes","title":"Où mettre un repository, un client HTTP, un port ?","text":"En user-land, où tu veux. L' app d'exemples utilise ports/ pour les interfaces et adapters/ pour les implémentations, mais Super ne connaît pas ces dossiers. Ports et adapters ."},{"url":"faq.html#lit-remplacable","page":"Questions fréquentes","title":"Peut-on remplacer lit-html par un autre moteur de templates ?","text":"Non. lit-html est une dépendance assumée de Super, mais cachée : tu écris tes composants en .super , que le plugin Vite compile en gabarits lit-html, sans jamais importer lit. Templates ."},{"url":"faq.html#pourquoi-des-fichiers-super","page":"Questions fréquentes","title":"Pourquoi un composant est-il un fichier .super et pas un .ts ?","text":"Pour que son template soit vérifié comme le reste du code : une balise inconnue, une prop manquante ou en trop, un événement que l'enfant n'émet pas, un objet affiché par erreur ne compilent pas. Un .super reste un module TypeScript : seules les méthodes qui contiennent des éléments et les déclarations du composant ( @tag , @prop , @emit , @title ) changent. Contrats, stores, routes et tests restent des .ts . Les fichiers .super ."},{"url":"faq.html#editeur-super","page":"Questions fréquentes","title":"Mon éditeur ne comprend pas les fichiers .super. Que faire ?","text":"Branche le serveur de langage des .super ( packages/lang-server ) : erreurs, complétion, survol, aller à la définition. En ligne de commande, npm run typecheck vérifie les .super avec le reste. Outillage ."},{"url":"faq.html#faq-stores","page":"Questions fréquentes","title":"Contrats et stores","text":""},{"url":"faq.html#state-commands-events-obligatoires","page":"Questions fréquentes","title":"state, commands et events sont-ils obligatoires ?","text":"state oui ; commands et events non. Attention : une clé mal orthographiée n'est pas signalée. Les trois clés ."},{"url":"faq.html#commands-mutent-le-state","page":"Questions fréquentes","title":"Les commandes sont-elles les actions qui modifient l'état ?","text":"Souvent, mais pas forcément : une commande peut aussi seulement appeler un adapter et émettre un événement. La règle qui compte : seul le store modifie son état, un composant envoie une commande. commands ."},{"url":"faq.html#pourquoi-une-commande-ne-renvoie-rien","page":"Questions fréquentes","title":"Pourquoi une commande ne renvoie-t-elle rien ?","text":"Pour que la vue n'attende jamais. Le store fait le travail asynchrone et publie le résultat par son état ou un événement, que tous les composants concernés voient. Pourquoi pas d'await ."},{"url":"faq.html#faq-en-cours","page":"Questions fréquentes","title":"Comment savoir qu'une commande est en cours, pour désactiver un bouton ?","text":"Avec @selector incrementing = () => this.counter.selectors.pending('increment', { id: this.counterId() }); : Super suit chaque commande, il n'y a aucun drapeau à gérer dans le store. pending ."},{"url":"faq.html#faq-issue","page":"Questions fréquentes","title":"Comment savoir qu'une commande a réussi ou échoué ?","text":"Super publie increment:done (avec le body et le résultat) et increment:failed (avec le body et la raison). Le contrat déclare l'un et l'autre avec Outcome<Résultat, Raisons> . Le cycle de vie ."},{"url":"faq.html#faq-return-fail","page":"Questions fréquentes","title":"Faut-il écrire return this.fail(…) ?","text":"Ce n'est pas obligatoire : this.fail est déclaré comme ne revenant jamais, et le type se resserre après un if (!result.ok) this.fail(result.reason) . Le return rend seulement la sortie visible à la lecture. Détails ."},{"url":"faq.html#faq-raisons","page":"Questions fréquentes","title":"À quoi servent les raisons comme 'unknown' | 'below-min' | 'storage' ?","text":"Ce sont les causes possibles d'échec, déclarées par le contrat. Le store échoue avec this.fail('below-min') , et le composant associe à chaque raison le message de son choix. Le compilateur vérifie les deux côtés. Les raisons d'échec ."},{"url":"faq.html#etat-ou-evenement","page":"Questions fréquentes","title":"Je publie le résultat par l'état ou par un événement ?","text":"Par l'état si c'est une donnée qui dure (une valeur, un « en cours », une erreur de chargement). Par un événement si c'est un fait ponctuel (« enregistré », « refusé »). Le tableau de décision ."},{"url":"faq.html#selecteurs-sur-le-contrat","page":"Questions fréquentes","title":"Pourquoi ne pas appeler les sélecteurs sur le contrat ?","text":"Un contrat n'a pas d'état : il peut exister plusieurs stores pour le même contrat. Les sélecteurs se lisent donc sur un store, déjà liés à son état : this.selectors.count(id) dans le store, this.counter.selectors.count(id) dans un composant, store.selectors.count(id) dans un test. Sélecteurs ."},{"url":"faq.html#selecteur-sans-parametre","page":"Questions fréquentes","title":"Pourquoi certains sélecteurs n'ont pas de paramètre ?","text":"Un sélecteur ne prend un paramètre que si la réponse en dépend. loadErrorMessage ne dépend que de l'état global, canDecrement dépend du compteur. Sans paramètre, il se passe tel quel : @selector loadError = this.counter.selectors.loadErrorMessage; . Détails ."},{"url":"faq.html#store-send-autre-store","page":"Questions fréquentes","title":"Un store peut-il envoyer une commande à un autre store ?","text":"Oui, s'il le reçoit en dépendance dans son constructeur : await this.#cart.send('clear') . Il peut attendre la fin du traitement, mais ne reçoit aucune donnée : il lit ensuite l'état de l'autre store ou écoute ses événements. Exemple complet ."},{"url":"faq.html#deux-stores-meme-contrat","page":"Questions fréquentes","title":"Peut-on avoir deux stores pour le même contrat ?","text":"Pas dans la même application (erreur « deux stores fournis »). Oui dans deux applications distinctes ou imbriquées, et bien sûr dans les tests, qui créent un store neuf à chaque cas. Plusieurs applications ."},{"url":"faq.html#faq-composants","page":"Questions fréquentes","title":"Composants","text":""},{"url":"faq.html#preparation-et-render","page":"Questions fréquentes","title":"Qu'est-ce qui se prépare dans les champs ? Quelle différence avec render ?","text":"Les déclarations du corps de la classe s'exécutent une fois, à la construction : elles demandent les stores ( @contract ), créent l'état local ( @state ), les lectures ( @selector ), les références ( @ref ) et les formulaires ( @form ), et posent les écouteurs ( @on ). render s'exécute à chaque rendu et écrit les éléments à afficher. Préparer, puis rendre ."},{"url":"faq.html#champ-ou-render","page":"Questions fréquentes","title":"Comment savoir si une ligne va dans un champ ou dans render ?","text":"Si ça doit exister une seule fois pour l'instance (store, état, lecture, écouteur, handler) : une déclaration ( @contract , @state , @selector , @on …) ou un champ. Si ça se recalcule à partir des valeurs du moment (lire .value , les props, décider, afficher) : render . Ces déclarations ne s'écrivent pas dans render ; dans un composant écrit en .ts , Super lève une erreur si tu appelles this.contract , this.state , this.selector ou on pendant le rendu. Le tableau ligne par ligne ."},{"url":"faq.html#au-montage","page":"Questions fréquentes","title":"Où lancer une commande au montage, ou poser un écouteur sur window ?","text":"Dans mounted() , appelé après le premier rendu, à chaque montage : la coquille de l'exemple y envoie this.counter.send('load') . Un écouteur sur window prend { signal: this.signal } , et disparaît au démontage. Exemples ."},{"url":"faq.html#props-dans-le-constructeur","page":"Questions fréquentes","title":"Puis-je lire une prop dans le constructeur ?","text":"Oui : Super dépose les props avant de construire le composant, elles sont lisibles dès les champs. Une valeur copiée à la construction (un état local, les valeurs initiales d'un formulaire) ne suit pas les changements suivants ; pour une valeur toujours à jour, lis la prop ( this.nom ) dans render ou dans la fonction d'un selector , recalculée à chaque rendu."},{"url":"faq.html#prop-nom-refuse","page":"Questions fréquentes","title":"Pourquoi ma prop ne peut-elle pas s'appeler title ou id ?","text":"Parce qu'un composant est un élément HTML, et qu'une prop se lit par this.nom : this.title , this.id ou this.hidden existent déjà. Le compilateur refuse @prop title: string; (« « title » est déjà une propriété des éléments HTML : choisis un autre nom ») ; choisis un nom qui dit ce que c'est ( heading , counterId ). Pour le titre de l'onglet, c'est @title , une déclaration du composant et pas une prop. Les noms déjà pris ."},{"url":"faq.html#mon-composant-ne-se-met-pas-a-jour","page":"Questions fréquentes","title":"Mon composant ne se met pas à jour. Pourquoi ?","text":"Tu as copié une valeur du store dans un champ ordinaire (dans mounted , par exemple) : elle est figée. Déclare un @selector et lis .value dans render . L'erreur classique . Ton selector ne lit pas la valeur que tu affiches : le composant ne se re-rend que si la valeur du sélecteur change. Tu lis l'état local avec une valeur copiée au lieu d'appeler this.local.get() dans render ."},{"url":"faq.html#la-vue-est-elle-prevenue","page":"Questions fréquentes","title":"Quand l'état du store change, la vue est-elle prévenue ?","text":"Oui. Un selector abonne le composant ; à chaque changement, Super recalcule la valeur et re-rend si elle a changé. Un sélecteur lu directement dans render abonne de la même façon : le composant ne se re-rend que si la valeur lue a changé. Rien à écrire de ton côté. Détails ."},{"url":"faq.html#composant-lit-etat-brut","page":"Questions fréquentes","title":"Un composant peut-il lire l'état brut du store ?","text":"Non. @contract counter; ne donne que les sélecteurs, send et on : jamais l'état brut, jamais l'instance du store. Détails ."},{"url":"faq.html#pourquoi-une-ligne-par-compteur","page":"Questions fréquentes","title":"Pourquoi la liste des compteurs a-t-elle un composant par ligne ?","text":"Une liste lue d'un bloc se re-rend en entier dès qu'une valeur change. Un composant par ligne ( counter-list-item.super ) lit sa propre valeur et ne se re-rend que pour elle. Ce qui compte comme un changement ."},{"url":"faq.html#null-as","page":"Questions fréquentes","title":"Pourquoi écrire null as string | null ?","text":"Le type de l'état local est déduit de la valeur initiale : @state local = { message: null as string | null }; . Sans le as , le champ serait de type null et ne pourrait jamais recevoir de texte. Détails ."},{"url":"faq.html#etat-local-ou-store-faq","page":"Questions fréquentes","title":"Ce message, je le mets dans l'état local ou dans le store ?","text":"Dans l'état local s'il ne concerne que ce composant et peut disparaître avec lui. Dans le store si un autre composant en a besoin ou s'il doit survivre à la navigation. Le tableau ."},{"url":"faq.html#faq-formulaires","page":"Questions fréquentes","title":"Formulaires","text":""},{"url":"faq.html#faq-form-champ","page":"Questions fréquentes","title":"Comment lier un champ de formulaire à une valeur ?","text":"Avec @form edit = { … }; dans la classe, puis <input {this.edit.field('email')} /> dans le template. Le type d'élément décide de la valeur : texte, nombre (ou null ), booléen, tableau, fichier. Tous les types de champs ."},{"url":"faq.html#faq-form-radio","page":"Questions fréquentes","title":"Comment gérer des boutons radio ou un groupe de cases à cocher ?","text":"Passe la valeur de chaque bouton ou case en second argument : field('plan', 'pro') , field('interests', 'sport') . Radios , cases à cocher ."},{"url":"faq.html#faq-form-zod","page":"Questions fréquentes","title":"Puis-je utiliser Zod ou une autre bibliothèque de validation ?","text":"Oui : une règle est une simple fonction qui renvoie true ou un message. Super n'impose rien. Les règles ."},{"url":"faq.html#faq-form-serveur","page":"Questions fréquentes","title":"Comment afficher une erreur du serveur sous le bon champ ?","text":"Rattache la raison d'échec de la commande à un champ dans failures.fields , ou au formulaire dans failures.form . Les erreurs du serveur ."},{"url":"faq.html#faq-form-async","page":"Questions fréquentes","title":"Comment vérifier une valeur côté serveur pendant la saisie ?","text":"Avec checks : une commande du store, déclenchée après une pause dans la frappe, dont les réponses périmées sont ignorées. Les vérifications asynchrones ."},{"url":"faq.html#pourquoi-form-pas-composant","page":"Questions fréquentes","title":"Pourquoi @form et pas un composant <Form> ?","text":"Parce qu'un formulaire est de l'état du composant : ses valeurs, ses erreurs, ses vérifications et sa soumission sont lus partout dans le template ( this.edit.field('name') , this.edit.values() , le bouton « Enregistrement… »). La balise existe déjà : c'est le <form> natif, relié par <form {this.edit.bind()}> . Un composant <Form> cacherait cet état et ferait perdre le typage des champs. <Table> est un autre cas : un composant d'affichage. Une déclaration plutôt qu'un composant ."},{"url":"faq.html#faq-form-liste","page":"Questions fréquentes","title":"Comment gérer un nombre variable de lignes (téléphones, adresses) ?","text":"Déclare un tableau d'objets dans initial , puis phones = this.edit.list('phones') dans un champ, avec item.key comme clé de la boucle : for (const item of this.phones.items(); key item.key) { … } . Les listes dynamiques ."},{"url":"faq.html#faq-evenements","page":"Questions fréquentes","title":"Événements et asynchrone","text":""},{"url":"faq.html#await-dans-un-composant","page":"Questions fréquentes","title":"Je peux écrire await this.counter.send(…) dans un composant ?","text":"Non : dans un composant, send renvoie void , il n'y a rien à attendre. Le résultat revient par l'état ou un événement. Commandes et événements ."},{"url":"faq.html#a-quoi-sert-signal","page":"Questions fréquentes","title":"À quoi sert signal ? Dois-je le passer à on ?","text":"this.signal est avorté à la fin de vie : au démontage pour un composant, au dispose() pour un store. Il sert uniquement aux écouteurs posés hors de Super, comme window.addEventListener('keydown', …, { signal: this.signal }) dans mounted . Entre Super et Super, jamais : les écouteurs déclarés par @on , comme ceux posés par un store sur un store reçu en dépendance, s'arrêtent tout seuls. Les outils d'un composant , un store qui dépend d'un autre ."},{"url":"faq.html#composant-emet-evenement-store","page":"Questions fréquentes","title":"Un composant peut-il émettre un événement de store, comme increment:done ?","text":"Non. La vue que donne @contract n'a pas d' emit . Le this.emit du composant émet ses propres événements, vers son parent, sur un autre canal. Qui peut émettre ."},{"url":"faq.html#pourquoi-on-dans-le-parent","page":"Questions fréquentes","title":"Pourquoi on apparaît dans le parent et pas dans l'enfant ?","text":"L'enfant émet ( this.emit('increment') ), le parent écoute ( <CounterControls … on:increment={…} /> ). L'enfant ne sait pas qui l'écoute, comme un bouton HTML ne sait pas qui écoute son click . emit et on ."},{"url":"faq.html#ouvrir-un-dialogue","page":"Questions fréquentes","title":"Comment ouvrir un dialogue et récupérer la réponse sans await ?","text":"Le parent ouvre le dialogue en lui passant une prop ( question ), le dialogue répond par un événement ( answered ). Le motif complet ."},{"url":"faq.html#erreur-dans-un-handler","page":"Questions fréquentes","title":"Que se passe-t-il si une commande du store lève une erreur ?","text":"La commande échoue avec la raison 'error' : Super publie nom:failed avec l'exception dans error , et l'exception part dans la console. Hors composant, la promesse de send est rejetée. Un échec prévu s'écrit plutôt this.fail('raison') , que la vue sait afficher. Les erreurs ."},{"url":"faq.html#faq-router","page":"Questions fréquentes","title":"Router","text":""},{"url":"faq.html#pas-de-declare-module","page":"Questions fréquentes","title":"Faut-il déclarer les routes globalement pour typer les liens ?","text":"Non. defineRouter renvoie un Router déjà typé par tes chemins, et le plugin Vite l'inscrit sous 'router' dans src/@core/contracts.d.ts . Un composant construit ses liens avec this.router.href('counter', { params: { id } }) ; Router.href sert au code hors composants. Déclarer les routes ."},{"url":"faq.html#faq-lire-un-parametre","page":"Questions fréquentes","title":"Comment un écran lit-il l'identifiant de l'URL ?","text":"Par this.router.current , pas par ses props : this.router.current.params.id() , ou @selector counterId = this.router.current.params.id; puis this.counterId.value (un champ ne peut pas s'appeler id : c'est une propriété des éléments HTML). La valeur est typée par la route de l'écran, sans rien déclarer : le plugin Vite relie chaque écran à sa route. Lire la route dans l'écran ."},{"url":"faq.html#faq-parametre-invalide","page":"Questions fréquentes","title":"Mon paramètre est un nombre : que se passe-t-il sur /counters/abc ?","text":"L'écran de la route s'affiche quand même, avec un id qui vaut undefined , et isValid() renvoie false . L'écran affiche un message, ou le guard de la route redirige : ({ params }) => params.id.isValid() || { to: 'counters' } . Une clé de query invalide, elle, prend simplement sa valeur par défaut. Une valeur invalide dans l'URL ."},{"url":"faq.html#faq-redirection-temporaire","page":"Questions fréquentes","title":"Comment faire pointer un chemin vers une autre page, en attendant ?","text":"Déclare redirect({ to: 'home' }) à la place de l'écran, dans .screens(…) . Les liens vers ce chemin restent justes, et le jour où la page existe, tu remplaces la redirection par l'écran. Redirections ."},{"url":"faq.html#faq-guard","page":"Questions fréquentes","title":"Comment protéger une page, par exemple réservée aux utilisateurs connectés ?","text":"Avec un guard, déclaré avant les écrans : .guards(({ read }) => ({ account: () => read('session').isLoggedIn() || { to: 'login' } })) . Il lit le store par le nom de son contrat, et le chemin refusé n'entre pas dans l'historique. Guards ."},{"url":"faq.html#pourquoi-screens-a-part","page":"Questions fréquentes","title":"Pourquoi les écrans sont-ils déclarés à part, dans .screens(...) ?","text":"Parce que le type des écrans dépend de Router ( this.router le lit dans contracts.d.ts ), et que Router contient les écrans. Avec les chemins posés à part dans defineRouter(...) , et .screens(...) en dernier appel, le compilateur type Router sans lire les écrans. Une forme qui mélangerait chemins et écrans dans un même objet ne pourrait pas être typée : le router retomberait en any . .screens(...) doit donc rester le dernier appel. Détails ."},{"url":"faq.html#pourquoi-une-fonction-dans-screens","page":"Questions fréquentes","title":"Pourquoi .screens(() => ({ … })) prend une fonction ?","text":"Pour éviter un cycle au chargement : routes.ts importe les écrans, et un module qu'un écran importe peut importer routes.ts à son tour (pour Router.href , par exemple). La fonction retarde la lecture des écrans à la création du router, par createRouter , quand tout est chargé. Détails ."},{"url":"faq.html#lien-pas-intercepte","page":"Questions fréquentes","title":"Un lien recharge la page au lieu de naviguer. Pourquoi ?","text":"Il est externe, relatif, a un target , un attribut download ou data-native , ou le clic utilisait une touche de modification. Ou bien il est rendu hors de la racine de l'application. L'interception des liens ."},{"url":"faq.html#etat-local-ecran-perdu","page":"Questions fréquentes","title":"Pourquoi l'état local de mon écran repart de zéro quand je change de page ?","text":"Chaque changement de chemin monte une nouvelle instance de l'écran, même pour la même route avec un autre paramètre. Une donnée qui doit survivre à la navigation va dans un store. RouterOutlet ."},{"url":"faq.html#faq-erreurs","page":"Questions fréquentes","title":"Erreurs","text":""},{"url":"faq.html#faq-composant-plante","page":"Questions fréquentes","title":"Un composant plante et laisse une zone blanche. Comment afficher autre chose ?","text":"Donne-lui une méthode renderError(error) , ou à un de ses ancêtres. Pour tous les écrans d'un coup, déclare l'écran '!' dans le router. Qui rattrape quoi ."},{"url":"faq.html#render-error-ou-ecran-erreur","page":"Questions fréquentes","title":"renderError ou écran '!' : lequel s'affiche ?","text":"Le plus proche du composant qui a planté : son propre renderError , puis celui d'un ancêtre, puis l'écran '!' s'il atteint le RouterOutlet . Une erreur de constructeur n'est rattrapée que par un ancêtre. Le tableau ."},{"url":"faq.html#faq-erreur-clic","page":"Questions fréquentes","title":"Une erreur dans un on:click ou un écouteur on est-elle rattrapée ?","text":"Elle est signalée à onError (phase 'event' , 'listener' , ou 'mount' pour mounted et unmounted ), mais l'affichage ne change pas : une action qui échoue ne casse pas l'écran. Les erreurs d'action ."},{"url":"faq.html#faq-sortir-ecran-erreur","page":"Questions fréquentes","title":"Comment revenir à la page après l'écran '!' ?","text":"Toute navigation le referme et remonte un écran neuf : un autre lien, ou un nouveau clic sur le lien de la page en erreur. L'écran '!' ."},{"url":"faq.html#faq-signaler-erreurs","page":"Questions fréquentes","title":"Comment envoyer les erreurs à un outil de suivi ?","text":"Avec onError dans createApp : il reçoit toute erreur de composant, rattrapée ou non, avec le composant, la phase et ce qui l'a rattrapée. onError ."},{"url":"faq.html#faq-tests","page":"Questions fréquentes","title":"Tests","text":""},{"url":"faq.html#test-d","page":"Questions fréquentes","title":"À quoi servent les fichiers *.test-d.ts, et pourquoi « -d » ?","text":"Ce sont des tests de types, vérifiés par npm run typecheck et jamais exécutés. Chaque // @ts-expect-error affirme qu'une ligne doit être refusée par le compilateur. Le « d » vient de .d.ts , c'est la convention de Vitest. Tests de types ."},{"url":"faq.html#tester-le-router-dans-l-app","page":"Questions fréquentes","title":"Dois-je tester le router ou les sélecteurs dans mon app ?","text":"Non : le fonctionnement de Super est testé dans les paquets. Ton app teste son propre comportement. Qui teste quoi ."},{"url":"faq.html#aucun-store-fourni","page":"Questions fréquentes","title":"Mon test échoue avec « aucun store fourni pour le contrat ».","text":"Passe le store, vrai ( CounterStore.create(…) ) ou faux ( fakeStore('counter', { state }) ), à mount(Composant, { stores: [counter] }) . Si le composant contient des liens ou lit le router, passe aussi router . mount ."},{"url":"faq.html#localstorage-clear","page":"Questions fréquentes","title":"« localStorage.clear is not a function » dans les tests.","text":"Node 25 expose un localStorage natif qui masque celui de happy-dom. Ajoute execArgv: ['--no-experimental-webstorage'] à la configuration de Vitest. Configuration ."},{"url":"flux.html","page":"Commandes et événements","title":"Commandes et événements","text":"La vue envoie et laisse filer. Le store fait le travail, attend ce qu'il doit attendre, puis réussit ou échoue. Super suit chaque commande de bout en bout : il sait quand elle est en cours, et publie son issue."},{"url":"flux.html#le-trajet-d-un-clic","page":"Commandes et événements","title":"Le trajet d'un clic","text":"Ce qui se passe quand on clique sur « + » dans l'écran d'un compteur : CounterControls émet increment vers son parent (événement de composant). CounterScreen envoie la commande : this.counter.send('increment', { id: 'cafes' }) . Il n'attend rien. Super note que increment est en cours : this.counter.selectors.pending() devient vrai, l'écran se re-rend avec les boutons désactivés. La méthode increment du store attend this.#repository.save(…) , met à jour counts et retourne { count: 3 } . Super note que la commande est finie (les boutons se réactivent) et publie increment:done avec { input: { id: 'cafes' }, result: { count: 3 } } . L'écran affiche la nouvelle valeur (elle a changé dans l'état) et « Incrémenté : 3 » (grâce à l'événement, reçu par sa méthode @on('counter', 'increment:done') )."},{"url":"flux.html#envoyer-une-commande","page":"Commandes et événements","title":"Envoyer une commande","text":"export class CounterScreen extends SuperElement { @tag = 'counter-screen'; counterId = this.router.current.params.id; @contract counter; run = (command: CounterChange) => this.counter.send(command, { id: this.counterId() }); // et on laisse filer } Dans un composant, send renvoie void . Il n'y a rien à attendre : écrire await this.counter.send(…) n'a pas de sens, et aucune donnée ne revient à l'appelant."},{"url":"flux.html#pourquoi-pas-d-await-dans-un-composant","page":"Commandes et événements","title":"Pourquoi pas d'await dans un composant","text":"Un seul endroit pour l'asynchrone. Les attentes et les erreurs vivent dans le store ; le suivi « en cours / réussi / échoué » est fait par Super. La vue reste une fonction de ce qu'elle lit. Pas de vue qui attend une réponse qui n'arrivera jamais. Si l'écran est démonté pendant la sauvegarde, rien ne casse : le store finit son travail et Super publie l'issue à qui l'écoute. Tout le monde voit l'issue. Une réponse ne profite qu'à l'appelant ; un événement profite à tous les composants concernés."},{"url":"flux.html#le-cycle-de-vie","page":"Commandes et événements","title":"Le cycle de vie d'une commande","text":"Chaque commande passe par trois moments, que Super suit sans que le store ait rien à écrire : Moment Ce que Super expose Côté composant En cours La méthode du store a commencé et n'a pas fini. this.counter.selectors.pending('increment') vaut true : re-rendu automatique. Réussie La méthode a fini sans erreur. Événement increment:done , avec le body ( input ) et le résultat ( result ). @on('counter', 'increment:done') onIncremented({ input, result }) { … } Échouée La méthode a appelé this.fail(raison) , ou levé une exception. Événement increment:failed , avec le body, la raison et l'erreur. @on('counter', 'increment:failed') onIncrementFailed({ input, reason }) { … } pending redevient faux avant que :done ou :failed soit émis : un écouteur voit déjà la commande comme terminée."},{"url":"flux.html#declarer-l-issue","page":"Commandes et événements","title":"Déclarer l'issue dans le contrat","text":"Une commande déclare ce que produit son succès et pourquoi elle peut échouer, avec Outcome<Résultat, Raisons> : commands: { load(): void; increment(input: { id: string }): Outcome<{ count: number }, 'unknown' | 'storage'>; decrement(input: { id: string }): Outcome<{ count: number }, 'unknown' | 'below-min' | 'storage'>; reset(input: { id: string }): Outcome<{ count: number }, 'unknown' | 'storage'>; }; Le résultat ( { count: number } ) est ce que Super publie dans increment:done . Il ne revient jamais à celui qui a envoyé la commande. Les raisons sont une liste fermée de codes, propres à ce contrat. Elles décrivent les refus prévus : 'unknown' pour un compteur hors catalogue, 'below-min' pour un compteur déjà à 0, 'storage' quand l'enregistrement échoue. Une commande sans Outcome ( load(): void ) a quand même son cycle de vie : load:done sans résultat, et load:failed pour une exception inattendue."},{"url":"flux.html#dans-le-store","page":"Commandes et événements","title":"Dans le store : retourner ou échouer","text":"increment({ id }: { id: string }) { return this.#write(id, this.selectors.count(id) + 1); } decrement({ id }: { id: string }) { if (this.selectors.find(id) && this.selectors.count(id) <= MIN_COUNT) this.fail('below-min'); return this.#write(id, this.selectors.count(id) - 1); } /** Le code commun aux trois écritures : une méthode privée, pas une commande. */ async #write(id: string, next: number) { if (!this.selectors.find(id)) this.fail('unknown'); // refus prévu, typé await this.#repository.save(id, next).catch(() => this.fail('storage')); this.set((s) => ({ counts: { ...s.counts, [id]: next } })); return { count: next }; // publié dans increment:done } Chaque commande du contrat est une méthode du store, qui reçoit le body. implements Commands<CounterStore> vérifie qu'aucune ne manque et que leurs paramètres sont exactement ceux du contrat. this.fail(raison) fait échouer la commande et ne revient pas. Seules les raisons déclarées par le contrat sont acceptées : this.fail('nope') ne compile pas. La méthode retourne le résultat déclaré. L'oublier, ou retourner autre chose, ne compile pas. Le code partagé s'écrit en méthode #privée : une méthode publique hors contrat est refusée par le compilateur. Plus de drapeau « en cours » à remettre à zéro dans un catch , ni d'événement d'issue à émettre : Super s'en charge."},{"url":"flux.html#return-fail","page":"Commandes et événements","title":"return this.fail(…) ou this.fail(…)","text":"this.fail est déclaré comme ne revenant jamais ( never ), et le compilateur en tient compte : après un this.fail(…) conditionnel, le type se resserre. Le store du profil l'écrit avec return , qui rend la sortie visible à la lecture : async save(input: ProfileInput) { const result = await this.#client.save(input).catch(() => this.fail('network')); if (!result.ok) return this.fail(result.reason); // ensuite, result.ok est vrai : result.id existe return { id: result.id }; } Les deux formes font exactement la même chose, à la compilation comme à l'exécution : this.fail interrompt la méthode dans tous les cas. return this.fail(…) se lit mieux quand la suite dépend de la condition, comme ici ; un simple this.fail(…) suffit pour une garde, comme if (!this.selectors.find(id)) this.fail('unknown') . Un appel à this.fail dans une fonction fléchée (le .catch(() => this.fail('network')) ci-dessus) fait aussi échouer la commande : l'exception remonte jusqu'à elle."},{"url":"flux.html#raisons-d-echec","page":"Commandes et événements","title":"Les raisons d'échec : des codes, pas des messages","text":"Le store dit ce qui s'est passé ; le composant choisit quoi afficher . Le texte, et donc la langue, reste dans la vue, et le compilateur signale une raison oubliée : const FAILED: Record<CounterFailure | 'error', string> = { unknown: 'Ce compteur n’existe pas.', 'below-min': 'Le compteur est déjà à zéro.', storage: 'Impossible d’enregistrer : le stockage est indisponible.', error: 'Une erreur inattendue est survenue.', }; Avec un code, le composant peut aussi réagir différemment selon le cas : proposer de libérer de l'espace pour 'storage' , ou ne rien afficher pour 'below-min' ."},{"url":"flux.html#echec-inattendu","page":"Commandes et événements","title":"L'échec inattendu : la raison 'error'","text":"Une exception que le store n'a pas prévue (un bug, un undefined.x ) fait aussi échouer la commande, avec la raison 'error' et l'exception dans error . L'interface ne reste donc jamais bloquée en « en cours ». Elle part aussi dans la console, alors qu'un échec déclaré, prévu, n'y apparaît pas."},{"url":"flux.html#en-cours","page":"Commandes et événements","title":"Savoir qu'une commande est en cours : pending","text":"@contract counter; @selector isLoading = () => this.counter.selectors.pending('load'); // une commande @selector isSaving = () => this.counter.selectors.pending('increment', { id: this.counterId() }); // pour ce body @selector isBusy = () => this.counter.selectors.pending(); // n'importe laquelle pending est fourni par Super avec les sélecteurs du contrat : lu dans un @selector (ou dans render ), il re-rend le composant quand une commande commence ou finit. Le body se filtre champ par champ : { id: 'cafes' } correspond à toute commande dont le body a id === 'cafes' . Si deux commandes identiques sont en cours, pending reste vrai jusqu'à la fin de la dernière. Dans le store, this.selectors.pending(…) donne la même information ; hors composant, store.pending(…) . pending est réservé : un contrat ne peut pas déclarer de sélecteur de ce nom."},{"url":"flux.html#ecouter-l-issue","page":"Commandes et événements","title":"Écouter l'issue","text":"counterId = this.router.current.params.id; @contract counter; @state local = { message: null as string | null }; // L'écran envoie une commande et laisse filer ; Super publie l'issue de chacune. @on('counter', 'increment:done') onIncremented({ input, result }) { this.#done('increment', input.id, result.count); } @on('counter', 'increment:failed') onIncrementFailed({ input, reason }) { this.#failed(input.id, reason); } // … de même pour decrement et reset // Seules les issues du compteur affiché deviennent un message. #done(change: CounterChange, id: string, count: number) { if (id === this.counterId()) this.local.set({ message: `${DONE[change]} : ${count}` }); } #failed(id: string, reason: CounterFailure | 'error') { if (id === this.counterId()) this.local.set({ message: FAILED[reason] }); } Une méthode par événement : @on('counter', 'increment:done') appelle la méthode à chaque issue, avec un paramètre typé par l'événement ( { input, result } ). Le nom de l'événement s'écrit tel quel, sans gabarit : pour plusieurs commandes, une méthode chacune, qui délèguent à une méthode privée. @on n'exige pas de @contract (voir les déclarations ). Le body est joint à l'issue ( input ) : l'écran de « Cafés » reconnaît ses propres commandes, sans que le store ait à recopier l' id . La route se lit dans la méthode ( this.counterId() ), au moment où l'issue arrive : elle voit la route à jour. Transforme l'issue en état local pour l'afficher : un événement ne dure pas, l'état local si (voir État local ). Rien à nettoyer : une méthode @on est appelée tant que le composant est monté, et plus après. Dans un composant écrit en .ts , l'équivalent est this.counter.on(…) dans un champ ou le constructeur ; on est interdit pendant render ."},{"url":"flux.html#recevoir-le-resultat","page":"Commandes et événements","title":"Une issue durable : l'état","text":"Un événement est ponctuel : un composant monté plus tard ne le voit pas. Ce qui doit durer va dans l'état. Par l'état Par l'issue d'une commande Nature Une donnée qui dure : une valeur, une erreur de chargement. Un fait ponctuel : « c'est enregistré », « c'est refusé ». Exemple counts , loadErrorMessage increment:done , increment:failed Côté composant Lu avec @selector x = () => this.counter.selectors.…; . Écouté avec @on('counter', '…') sur une méthode. Un composant monté plus tard Voit la valeur. Ne voit rien : l'événement est passé. Dans l'exemple des compteurs, une erreur de chargement doit rester affichée sur la liste, même si on y revient plus tard : le store la range dans loadErrorMessage plutôt que de faire échouer load . Un refus d'écriture, lui, n'a de sens que sur le moment : c'est l'issue de la commande."},{"url":"flux.html#evenements-ecrits-a-la-main","page":"Commandes et événements","title":"Les événements écrits à la main","text":"Dans l' exemple Boutique : @core/cart/contract.ts , @core/cart/store.ts , @components/shop/index.super . Le panier émet emptied quand il devient vide, que ce soit par clear ou par le dernier remove . Le cycle de vie couvre l'issue des commandes. Pour un fait qui n'est pas l'issue d'une commande (une synchronisation de fond terminée, une donnée arrivée d'un serveur), le contrat déclare ses propres événements, et le store les émet : // contrat events: { synced: { at: number } }; // store this.emit('synced', { at: Date.now() });"},{"url":"flux.html#qui-peut-emettre","page":"Commandes et événements","title":"Qui peut émettre, qui peut écouter","text":"Émettre un événement de store L'écouter Super Le cycle de vie des commandes ( :done , :failed ). Le store Ses événements déclarés, avec this.emit dans ses méthodes. Ceux des stores reçus en dépendance ( cart.on(…) dans son constructeur). Un composant Non. La vue que donne @contract n'a pas d' emit . Oui, avec @on('counter', '…') sur une méthode. Un test Oui, avec fakeStore(…).emit(…) , pour jouer le store. Oui, avec record(store, 'increment:done') . Le emit d'un composant n'est pas celui d'un store Un composant a aussi un this.emit , mais il émet les événements du composant vers son parent (ceux déclarés dans son type emits ). Le store et ses abonnés ne le voient jamais. C'est voulu : un composant ne peut pas annoncer une écriture qui n'a jamais eu lieu."},{"url":"flux.html#les-deux-sortes-d-evenements","page":"Commandes et événements","title":"Les deux sortes d'événements","text":"Événement de store Événement de composant Déclaré dans le contrat : Outcome d'une commande, ou events: { synced: … } le composant : @emit increment: void; Émis par Super (issue d'une commande) ou le store ( this.emit ) le composant : this.emit('increment') Écouté par tout ce qui a accès au store : @on('counter', 'increment:done') dans un composant, counter.on('increment:done', …) ailleurs le parent seulement : <CounterControls … on:increment={…} /> Sert à annoncer ce qui s'est passé dans le store signaler une interaction au parent Voir Parents et enfants pour les événements de composant."},{"url":"flux.html#les-commandes-dans-les-tests","page":"Commandes et événements","title":"Les commandes dans les tests","text":"Hors composant (tests, autres stores, racine de composition), send renvoie une promesse : elle se résout quand la commande a réussi, et se rejette quand elle échoue, avec une CommandFailure qui porte la raison. const failed = record(store, 'decrement:failed'); await expect(store.send('decrement', { id: 'cafes' })).rejects.toMatchObject({ reason: 'below-min' }); expect(failed.last).toEqual({ input: { id: 'cafes' }, reason: 'below-min', error: null });"},{"url":"formulaires.html","page":"Formulaires","title":"Formulaires","text":"@form relie des champs à des valeurs typées, applique tes règles, vérifie au besoin côté serveur pendant la saisie, et soumet par une commande de store. « En cours » et les erreurs du serveur viennent du cycle de vie de cette commande."},{"url":"formulaires.html#un-premier-formulaire","page":"Formulaires","title":"Un premier formulaire","text":"import { type Outcome, SuperContract } from '@super-ts/core'; export type AccountState = { userId: string | null }; export class AccountContract extends SuperContract<{ state: AccountState; commands: { register(input: { email: string; password: string }): Outcome<{ userId: string }, 'email-taken' | 'network'>; }; }> { constructor() { super({ name: 'account' }); } userId(s: AccountState) { return s.userId; } } import { SuperElement } from '@super-ts/dom'; export class SignupScreen extends SuperElement { @tag = 'signup-screen'; @title = 'Inscription'; @contract account; // le store qui recevra la commande @form signup = { initial: { email: '', password: '' }, rules: { email: (v) => /.+@.+\\..+/.test(v) || 'Adresse invalide', password: (v) => v.length >= 8 || '8 caractères minimum', }, submit: { to: this.account, command: 'register', toInput: (values) => values }, failures: { fields: { 'email-taken': { email: 'Adresse déjà utilisée' } }, form: { network: 'Connexion impossible, réessaie.' }, }, }; render() { const { signup } = this; <form {signup.bind()}> <label>E-mail <input type=\"email\" {signup.field('email')} /></label> <p class=\"error\">{signup.error('email')}</p> <label>Mot de passe <input type=\"password\" {signup.field('password')} /></label> <p class=\"error\">{signup.error('password')}</p> <p role=\"alert\">{signup.formError()}</p> <button disabled={signup.submitting()}>Créer mon compte</button> </form> } } @form signup = { … }; se déclare dans le corps de la classe, une fois, comme les autres déclarations de préparation . Le type des champs vient de la valeur : pas d'annotation sur @form . Dans un composant écrit en .ts , l'équivalent est signup = this.form({ … }) , qui lève une erreur s'il est appelé pendant render . Le formulaire est prêt dès la construction : render peut lire ses valeurs et ses erreurs au premier rendu. Il se branche sur le store au montage du composant, et s'en débranche au démontage. signup.bind() et signup.field('email') sont des directives d'élément : elles s'écrivent entre accolades dans la balise, <form {signup.bind()}> pour le formulaire, <input {signup.field('email')} /> pour un champ (voir Attributs ). disabled={signup.submitting()} pose l'attribut tant que la soumission est en cours, et le retire ensuite. @contract account; donne une vue du store sans rien en lire : le formulaire a ses propres valeurs. Il a seulement besoin du store pour envoyer register et suivre son issue. submit.to doit être une vue déclarée par @contract , avant le formulaire dans la classe : les déclarations s'initialisent dans l'ordre."},{"url":"formulaires.html#pourquoi-pas-un-composant-form","page":"Formulaires","title":"Pourquoi une déclaration et pas un composant <Form>","text":"Un formulaire est de l'état du composant : ses valeurs, ses erreurs, ses vérifications et sa soumission sont lus partout dans le template ( this.edit.field('name') , this.edit.values() , le bouton « Enregistrement… »). La balise, elle, existe déjà : c'est le <form> natif, relié par <form {this.edit.bind()}> . Un composant <Form> cacherait cet état derrière ses props et ferait perdre le typage des champs. <Table> est un autre cas : c'est un composant d'affichage."},{"url":"formulaires.html#les-valeurs-initiales","page":"Formulaires","title":"Les valeurs initiales donnent les types","text":"Le type de chaque champ est déduit de initial . Élargis ce qui changera de type : initial: { name: '', // string age: null as number | null, // nombre facultatif : null quand le champ est vide plan: 'free' as 'free' | 'pro' | 'team', // une union : seuls ces choix sont acceptés languages: [] as string[], // plusieurs valeurs avatar: null as File | null, // fichier phones: [{ label: 'mobile', number: '' }], // une liste de lignes (voir Listes dynamiques) }, Un tableau d'objets est une liste dynamique . Un tableau de valeurs simples ( string[] ) est un champ à plusieurs valeurs : liste à choix multiples ou groupe de cases à cocher."},{"url":"formulaires.html#lier-les-champs","page":"Formulaires","title":"Lier les champs : field","text":"field(nom) se place sur un <input> , un <select> ou un <textarea> . Il écrit la valeur dans le champ, écoute la saisie, et note le premier passage dans le champ. Il choisit tout seul la bonne propriété selon le type d'élément. Champ Écriture Valeur texte, e-mail, mot de passe, recherche, téléphone, URL <input type=\"email\" {f.field('email')} /> string zone de texte <textarea {f.field('bio')}></textarea> string date, heure, date et heure, mois, semaine, couleur <input type=\"date\" {f.field('birthdate')} /> string (format du navigateur : 1906-12-09 , #ff0000 ) nombre <input type=\"number\" {f.field('age')} /> number , ou null si le champ est vidé curseur <input type=\"range\" min=\"0\" max=\"100\" {f.field('volume')} /> number liste déroulante <select {f.field('country')}>…</select> string (la value de l'option) liste à choix multiples <select multiple {f.field('languages')}>…</select> string[] boutons radio <input type=\"radio\" {f.field('plan', 'pro')} /> la valeur du bouton coché case à cocher seule <input type=\"checkbox\" {f.field('newsletter')} /> boolean groupe de cases à cocher <input type=\"checkbox\" {f.field('interests', 'sport')} /> string[] des cases cochées fichier <input type=\"file\" {f.field('avatar')} /> File | null plusieurs fichiers <input type=\"file\" multiple {f.field('photos')} /> File[] Le kit d'interface fournit des champs déjà câblés ( Field , Select , Checkbox , RadioGroup ) : libellé, aide, erreur et attributs ARIA compris, reliés par fieldOf(edit, 'email') . Dans les extraits qui suivent, initial vient de la déclaration @form edit = { … }; , et les balises du corps de render() , où const { edit } = this; donne le formulaire."},{"url":"formulaires.html#champs-texte","page":"Formulaires","title":"Champs texte","text":"initial: { name: '', email: '', password: '', search: '', phone: '', website: '', bio: '' }, // dans render() <input {edit.field('name')} /> <input type=\"email\" {edit.field('email')} /> <input type=\"password\" {edit.field('password')} /> <input type=\"search\" {edit.field('search')} /> <input type=\"tel\" {edit.field('phone')} /> <input type=\"url\" {edit.field('website')} /> <textarea {edit.field('bio')}></textarea> La valeur suit chaque frappe ; le champ est noté « touché » quand on le quitte."},{"url":"formulaires.html#nombres-et-curseurs","page":"Formulaires","title":"Nombres et curseurs","text":"initial: { age: null as number | null, quantity: 1, volume: 50 }, // dans render() <input type=\"number\" {edit.field('age')} /> // null si vidé <input type=\"number\" min=\"1\" step=\"1\" {edit.field('quantity')} /> <input type=\"range\" min=\"0\" max=\"100\" {edit.field('volume')} /> Un champ nombre vidé donne null : déclare null as number | null pour un nombre facultatif. Les attributs min , max et step guident la saisie, mais ne remplacent pas une règle : le formulaire désactive la validation native du navigateur au profit de tes règles."},{"url":"formulaires.html#dates-et-couleurs","page":"Formulaires","title":"Dates, heures et couleurs","text":"initial: { birthdate: '', alarm: '', meeting: '', month: '', week: '', color: '#3b82f6' }, // dans render() <input type=\"date\" {edit.field('birthdate')} /> // '1906-12-09' <input type=\"time\" {edit.field('alarm')} /> // '07:30' <input type=\"datetime-local\" {edit.field('meeting')} /> // '2026-11-25T14:00' <input type=\"month\" {edit.field('month')} /> // '2026-11' <input type=\"week\" {edit.field('week')} /> // '2026-W48' <input type=\"color\" {edit.field('color')} /> // '#3b82f6' Ces champs donnent des chaînes, au format du navigateur. Convertis-les dans submit.toInput si la commande attend un autre format."},{"url":"formulaires.html#listes-deroulantes","page":"Formulaires","title":"Listes déroulantes","text":"initial: { country: 'FR', languages: [] as string[] }, // dans render() <select {edit.field('country')}> <option value=\"FR\">France</option> <option value=\"BE\">Belgique</option> </select> <select multiple {edit.field('languages')}> for (const l of LANGUAGES; key l.code) { <option value={l.code}>{l.label}</option> } </select> Les options peuvent venir d'un tableau, rendues par une boucle for à clé : la sélection est rétablie une fois les options en place."},{"url":"formulaires.html#boutons-radio","page":"Formulaires","title":"Boutons radio","text":"initial: { plan: 'free' as 'free' | 'pro' | 'team' }, // dans render() <label><input type=\"radio\" {edit.field('plan', 'free')} /> Gratuite</label> <label><input type=\"radio\" {edit.field('plan', 'pro')} /> Pro</label> <label><input type=\"radio\" {edit.field('plan', 'team')} /> Équipe</label> Chaque bouton reçoit sa valeur en second argument ; le formulaire coche celui qui correspond. La valeur est typée par l'union : field('plan', 'gold') ne compile pas. Pas besoin d'attribut name ni value ."},{"url":"formulaires.html#cases-a-cocher","page":"Formulaires","title":"Cases à cocher","text":"initial: { newsletter: false, interests: [] as string[] }, // dans render() <label><input type=\"checkbox\" {edit.field('newsletter')} /> Recevoir la newsletter</label> // boolean <label><input type=\"checkbox\" {edit.field('interests', 'sport')} /> Sport</label> // string[] <label><input type=\"checkbox\" {edit.field('interests', 'lecture')} /> Lecture</label> Sans second argument, la case vaut true ou false . Avec, elle ajoute ou retire sa valeur du tableau."},{"url":"formulaires.html#fichiers","page":"Formulaires","title":"Fichiers","text":"initial: { avatar: null as File | null, photos: [] as File[] }, // dans render() <input type=\"file\" accept=\"image/*\" {edit.field('avatar')} /> <input type=\"file\" multiple {edit.field('photos')} /> Un navigateur ne permet pas de pré-remplir un champ fichier : la valeur initiale est forcément vide, et reset() vide le champ."},{"url":"formulaires.html#champs-hors-formulaire","page":"Formulaires","title":"Les valeurs sans champ","text":"Une valeur n'a pas besoin d'un champ visible : un identifiant, une valeur calculée ou choisie par un composant maison se lisent avec values() et se modifient avec set(nom, valeur) . initial: { rating: 0 }, // dans render() <StarRating value={edit.values().rating} on:picked={(n) => edit.set('rating', n)} /> Les props sont lisibles quand le formulaire se construit, mais initial n'est lu qu'une fois : une valeur qui vient des props et peut changer (l'identifiant de la fiche éditée) n'y va pas. Ajoute-la dans submit.toInput , appelé à la soumission : toInput: (values) => ({ ...values, id: this.recordId }) , avec @prop recordId: string; (une prop ne peut pas s'appeler id , propriété native des éléments HTML)."},{"url":"formulaires.html#bind","page":"Formulaires","title":"La balise form : bind","text":"<form {edit.bind()}> soumet le formulaire au clic sur un bouton ou à la touche Entrée, sans recharger la page. Il désactive la validation native du navigateur (bulles d'erreur), remplacée par tes règles et tes messages. Sans <form> , appelle edit.submit() toi-même."},{"url":"formulaires.html#regles","page":"Formulaires","title":"Les règles","text":"Une règle reçoit la valeur du champ et toutes les valeurs, et renvoie true ou le message d'erreur : rules: { name: (v) => v.trim() !== '' || 'Nom obligatoire', age: (v) => v === null || (v >= 13 && v <= 120) || 'Entre 13 et 120 ans', languages: (v) => v.length > 0 || 'Choisis au moins une langue', avatar: (v) => v === null || v.size < 2_000_000 || 'Image de 2 Mo maximum', endDate: (v, values) => v >= values.startDate || 'La fin doit suivre le début', }, Super n'impose aucune bibliothèque de validation. Avec Zod, par exemple : const emailSchema = z.string().email(); rules: { email: (v) => emailSchema.safeParse(v).success || 'Adresse invalide', },"},{"url":"formulaires.html#validate","page":"Formulaires","title":"Les règles croisées : validate","text":"Quand une erreur dépend de plusieurs champs, validate reçoit toutes les valeurs et renvoie les erreurs par champ : validate: (values) => (values.password === values.confirm ? {} : { confirm: 'Les mots de passe diffèrent' }), // Avec un schéma Zod complet : validate: (values) => { const result = profileSchema.safeParse(values); if (result.success) return {}; return Object.fromEntries(result.error.issues.map((issue) => [issue.path[0], issue.message])); },"},{"url":"formulaires.html#quand-les-erreurs-s-affichent","page":"Formulaires","title":"Quand les erreurs s'affichent","text":"Une règle ou validate : après le premier passage dans le champ (on le quitte, ou on change une case, une liste, un fichier), ou après une tentative de soumission. Taper une adresse incomplète n'affiche rien tant qu'on est dans le champ. Une erreur du serveur ( failures.fields ) : tout de suite, et jusqu'à ce qu'on modifie ce champ. Une vérification asynchrone refusée : dès sa réponse. error('email') renvoie un seul message, dans cet ordre de priorité : serveur, règle du champ, validate , vérification asynchrone."},{"url":"formulaires.html#soumission","page":"Formulaires","title":"La soumission","text":"La soumission est une commande d'un store. submit dit laquelle, et toInput convertit les valeurs du formulaire en input de la commande : on retire ce qui ne sert qu'à l'écran (une confirmation de mot de passe), on convertit (une date vide en null ), on regroupe. Quand les valeurs ont déjà la bonne forme, toInput: (values) => values suffit. C'est ce même input qu'on retrouve dans save:done et save:failed . submit: { to: this.profile, // déclaré plus haut par @contract profile; command: 'save', toInput: ({ confirm, birthdate, ...values }) => ({ ...values, birthdate: birthdate || null }), }, Ce qui se passe à la soumission : Tous les champs sont marqués « touchés » : les erreurs des règles apparaissent. S'il reste une erreur (règle, validate ou vérification refusée), rien n'est envoyé, et le premier champ en erreur est centré à l'écran et reçoit le focus. Si une vérification asynchrone est en cours, la soumission l'attend, puis repart toute seule. Sinon, la commande part avec toInput(valeurs) . submitting() est vrai jusqu'à son issue. En cas d'échec, l'erreur s'affiche selon failures . En cas de succès, le formulaire efface ses erreurs et garde ses valeurs. Pour réagir au succès (naviguer, afficher une confirmation, vider le formulaire), écoute l'issue de la commande par une méthode @on : @contract profile; @form edit = { /* … */ submit: { to: this.profile, command: 'save', toInput: (values) => values } }; @on('profile', 'save:done') onSaved() { this.router.send('navigate', { to: 'home' }); } La méthode est appelée à chaque save:done tant que le composant est monté ; son paramètre est typé par l'événement ( { input, result } ). Soumettre avant le montage (appeler edit.submit() pendant la construction) lève une erreur : le formulaire ne parle au store qu'une fois branché."},{"url":"formulaires.html#aller-a-la-premiere-erreur","page":"Formulaires","title":"Aller à la première erreur","text":"Quand une soumission est bloquée, le formulaire centre à l'écran le premier champ en erreur, dans l'ordre de la page, et lui donne le focus. Même chose quand le serveur renvoie une erreur rattachée à un champ ( failures.fields ). Sur un long formulaire, l'utilisateur voit tout de suite ce qu'il doit corriger, peut le faire au clavier, et un lecteur d'écran annonce le champ. Pour un groupe de radios ou de cases, c'est la première case du groupe qui reçoit le focus. Une erreur rattachée au formulaire entier ( failures.form ) ne déplace rien : elle n'a pas de champ. Seuls les champs liés par field(…) sont retrouvés : une valeur sans champ visible ne déplace rien. Pour le désactiver : @form edit = { initial, rules, submit, scrollToError: false };"},{"url":"formulaires.html#erreurs-du-serveur","page":"Formulaires","title":"Les erreurs du serveur : failures","text":"Chaque raison d'échec déclarée par la commande est rattachée à un champ, ou au formulaire entier : // save(input: ProfileInput): Outcome<{ id: string }, 'email-taken' | 'avatar-too-large' | 'network' | 'rate-limited'> failures: { fields: { 'email-taken': { email: 'Adresse déjà utilisée' }, // sous le champ email 'avatar-too-large': { avatar: 'Image refusée par le serveur' }, }, form: { network: 'Connexion impossible, réessaie.', // dans formError() 'rate-limited': 'Trop de tentatives, réessaie dans une minute.', error: 'Un problème est survenu de notre côté.', // facultatif }, }, Clé Où s'affiche le message Quand il disparaît fields Sous le champ, avec error('email') . Une raison peut viser plusieurs champs. Quand on modifie ce champ. form Pour tout le formulaire, avec formError() . À la soumission suivante. Chaque raison déclarée apparaît une seule fois , dans fields ou dans form . Une raison oubliée, en double, inconnue du contrat, ou un champ inconnu dans fields ne compilent pas. form.error est facultatif. C'est le message d'une exception inattendue (un bug, une réponse illisible). Sans lui, formError() affiche « Une erreur inattendue est survenue. », pour que l'utilisateur ne reste jamais sans retour. L'exception part aussi dans onError . Une commande sans raison d'échec déclarée n'a pas besoin de failures ."},{"url":"formulaires.html#verifications-asynchrones","page":"Formulaires","title":"Les vérifications asynchrones : checks","text":"Une vérification pendant la saisie (« cette adresse est-elle libre ? ») est une commande du store de soumission. Le formulaire la déclenche et lit son issue : // checkEmail(input: { email: string }): Outcome<{ available: boolean }, 'network'> checks: { email: { command: 'checkEmail', toInput: (email) => ({ email }), accept: ({ available }) => available || 'Adresse déjà utilisée', delay: 400, }, }, // dans render() <input type=\"email\" {edit.field('email')} /> if (edit.checking('email')) { <small>Vérification…</small> } <p class=\"error\">{edit.error('email')}</p> Seulement si les règles du champ passent : inutile d'interroger le serveur pour \"abc\" . Après une pause dans la saisie de delay millisecondes (300 par défaut) : une seule requête pour une adresse tapée d'un trait. Les réponses périmées sont ignorées : si le champ a changé depuis, la réponse de l'ancienne valeur ne compte pas. checking('email') est vrai pendant la pause et pendant la requête. La soumission attend la fin des vérifications en cours. Une vérification qui échoue (réseau coupé) ne bloque pas : le serveur reste juge à la soumission, et la raison revient alors par failures . Les vérifications passent par le même store que la soumission : c'est ce qui permet au compilateur de typer toInput et accept selon la commande choisie."},{"url":"formulaires.html#listes-dynamiques","page":"Formulaires","title":"Listes dynamiques","text":"Pour un nombre de lignes qui change pendant la saisie (téléphones, adresses, lignes de facture), déclare un tableau d'objets : @contract profile; @form edit = { initial: { phones: [{ label: 'mobile', number: '' }] }, rules: { phones: { number: (v) => /^\\+?[0-9 ]{6,}$/.test(v) || 'Numéro invalide' }, // une règle par champ de ligne }, validate: (v) => (v.phones.length > 0 ? {} : { phones: 'Au moins un numéro' }), submit: { to: this.profile, command: 'savePhones', toInput: (v) => v }, }; phones = this.edit.list('phones'); render() { const { edit, phones } = this; for (const item of phones.items(); key item.key) { <div> <select {item.field('label')}><option>mobile</option><option>travail</option></select> <input type=\"tel\" {item.field('number')} /> <button type=\"button\" on:click={() => phones.remove(item)}>Retirer</button> <p class=\"error\">{item.error('number')}</p> </div> } <p class=\"error\">{edit.error('phones')}</p> <button type=\"button\" on:click={() => phones.add({ label: 'mobile', number: '' })}>Ajouter un numéro</button> } Membre Rôle list('phones') La liste, à déclarer dans un champ, après le formulaire ( phones = this.edit.list('phones') ). items() Les lignes, chacune avec key , index , value , field(nom) et error(nom) . add(ligne) Ajoute une ligne complète, typée par la liste. remove(ligne | index) Retire une ligne. Utilise item.key comme clé de la boucle ( for (const item of phones.items(); key item.key) ). Elle ne change pas quand on retire une autre ligne : la saisie et les erreurs restent sur la bonne ligne. L'index, lui, se décale."},{"url":"formulaires.html#lire-et-piloter","page":"Formulaires","title":"Lire et piloter le formulaire","text":"Membre Rôle bind() Sur <form> : soumission sans rechargement. field(nom, valeur?) Sur un champ. La valeur en second argument pour un radio ou une case d'un groupe. error(nom) Le message sous un champ, ou null . formError() Le message pour tout le formulaire, ou null . submitting() La soumission est en cours, ou attend des vérifications. checking(nom) Une vérification de ce champ est en cours. values() Les valeurs courantes. set(nom, valeur) Change une valeur, comme une saisie. list(nom) Une liste dynamique. submit() Soumet, comme le bouton (et amène à la première erreur s'il y en a). reset() Revient aux valeurs initiales, efface erreurs, champs touchés et vérifications."},{"url":"formulaires.html#exemple-complet","page":"Formulaires","title":"Exemple complet","text":"Ce formulaire tourne dans l'app d'exemples : npm run dev , puis la page /profile . Il utilise chaque type de champ, une règle croisée, une vérification asynchrone, une liste dynamique, et un serveur simulé par un adapter (latence, adresse déjà prise, image trop lourde, panne réseau). Voir aussi le store , le port , le type ProfileInput , l' adapter simulé et les tests de l'écran . import { type Outcome, SuperContract } from '@super-ts/core'; import type { ProfileInput } from '../../domain/profile'; // Ce store n'a pas d'état : il fait l'intermédiaire avec le serveur. Ses commandes et leur cycle de vie // (en cours, réussie, échouée) suffisent au formulaire. export class ProfileContract extends SuperContract<{ state: {}; commands: { // La soumission du formulaire : son issue alimente « en cours » et les erreurs du serveur. save(input: ProfileInput): Outcome<{ id: string }, 'email-taken' | 'avatar-too-large' | 'network'>; // La vérification asynchrone de l'adresse, pendant la saisie. checkEmail(input: { email: string }): Outcome<{ available: boolean }, 'network'>; }; }> { constructor() { super({ name: 'profile' }); } } import { SuperElement } from '@super-ts/dom'; import './index.css'; const COUNTRIES = [ { code: 'FR', label: 'France' }, { code: 'BE', label: 'Belgique' }, { code: 'CH', label: 'Suisse' }, { code: 'CA', label: 'Canada' }, ]; const LANGUAGES = [ { code: 'fr', label: 'Français' }, { code: 'en', label: 'Anglais' }, { code: 'es', label: 'Espagnol' }, ]; const INTERESTS = [ { value: 'sport', label: 'Sport' }, { value: 'lecture', label: 'Lecture' }, { value: 'musique', label: 'Musique' }, ]; /** Écran de la route `/profile` : un formulaire avec chaque type de champ, soumis à un serveur simulé. */ export class ProfileScreen extends SuperElement { @tag = 'profile-screen'; @title = 'Profil'; // Le store ne sert qu'à envoyer les commandes et suivre leur issue : on n'en lit rien. @contract profile; @state local = { saved: null as string | null }; @form edit = { // Les valeurs initiales donnent le type de chaque champ. initial: { name: '', email: '', password: '', confirm: '', age: null as number | null, website: '', bio: '', country: 'FR', languages: [] as string[], plan: 'free' as 'free' | 'pro' | 'team', newsletter: false, interests: [] as string[], birthdate: '', meetingTime: '', color: '#4f46e5', volume: 50, avatar: null as File | null, phones: [{ label: 'mobile', number: '' }], }, // Une règle par champ : `true`, ou le message d'erreur. rules: { name: (v) => v.trim() !== '' || 'Nom obligatoire', email: (v) => /.+@.+\\..+/.test(v) || 'Adresse invalide', password: (v) => v.length >= 8 || '8 caractères minimum', age: (v) => v === null || (v >= 13 && v <= 120) || 'Entre 13 et 120 ans', website: (v) => v === '' || /^https?:\\/\\/.+/.test(v) || 'Adresse commençant par http:// ou https://', bio: (v) => v.length <= 280 || '280 caractères maximum', languages: (v) => v.length > 0 || 'Choisis au moins une langue', avatar: (v) => v === null || v.type.startsWith('image/') || 'Choisis une image', phones: { number: (v) => /^\\+?[0-9 ]{6,}$/.test(v) || 'Numéro invalide' }, }, // Les règles qui croisent plusieurs champs. validate: (v) => ({ ...(v.password === v.confirm ? {} : { confirm: 'Les mots de passe diffèrent' }), ...(v.phones.length > 0 ? {} : { phones: 'Au moins un numéro' }), }), // La vérification asynchrone de l'adresse, pendant la saisie. checks: { email: { command: 'checkEmail', toInput: (email) => ({ email }), accept: ({ available }) => available || 'Adresse déjà utilisée', delay: 400, }, }, // La soumission est une commande : `confirm` ne sert qu'à l'écran, on le retire. submit: { to: this.profile, command: 'save', toInput: ({ confirm, ...values }) => values }, // Chaque raison d'échec de `save`, sur un champ ou sur le formulaire. failures: { fields: { 'email-taken': { email: 'Adresse déjà utilisée' }, 'avatar-too-large': { avatar: 'Image trop lourde (1 Mo maximum)' }, }, form: { network: 'Connexion impossible, réessaie.' }, }, }; phones = this.edit.list('phones'); @on('profile', 'save:done') onSaved({ result }) { this.local.set({ saved: result.id }); } render() { const { edit, phones, local } = this; <main class=\"screen\"> <h1>Formulaire de profil</h1> <p class=\"hint\"> Le serveur est simulé. Essaie <code>taken@example.com</code> (adresse déjà prise), une adresse contenant <code>offline</code> (panne réseau), ou une image de plus de 1 Mo. </p> <form {edit.bind()}> <fieldset> <legend>Identité</legend> <label>Nom <input {edit.field('name')} /></label> <p class=\"error\">{edit.error('name')}</p> <label>E-mail <input type=\"email\" {edit.field('email')} /></label> if (edit.checking('email')) { <small class=\"checking\">Vérification…</small> } <p class=\"error\">{edit.error('email')}</p> <label>Mot de passe <input type=\"password\" {edit.field('password')} /></label> <p class=\"error\">{edit.error('password')}</p> <label>Confirmation <input type=\"password\" {edit.field('confirm')} /></label> <p class=\"error\">{edit.error('confirm')}</p> <label>Âge <input type=\"number\" {edit.field('age')} /></label> <p class=\"error\">{edit.error('age')}</p> <label>Site web <input type=\"url\" {edit.field('website')} /></label> <p class=\"error\">{edit.error('website')}</p> <label>Présentation <textarea rows=\"3\" {edit.field('bio')}></textarea></label> <p class=\"error\">{edit.error('bio')}</p> </fieldset> <fieldset> <legend>Préférences</legend> <label> Pays <select {edit.field('country')}> for (const c of COUNTRIES; key c.code) { <option value={c.code}>{c.label}</option> } </select> </label> <label> Langues <select multiple {edit.field('languages')}> for (const l of LANGUAGES; key l.code) { <option value={l.code}>{l.label}</option> } </select> </label> <p class=\"error\">{edit.error('languages')}</p> <fieldset class=\"inline\"> <legend>Offre</legend> <label><input type=\"radio\" {edit.field('plan', 'free')} /> Gratuite</label> <label><input type=\"radio\" {edit.field('plan', 'pro')} /> Pro</label> <label><input type=\"radio\" {edit.field('plan', 'team')} /> Équipe</label> </fieldset> <label class=\"inline\"><input type=\"checkbox\" {edit.field('newsletter')} /> Recevoir la newsletter</label> <fieldset class=\"inline\"> <legend>Centres d'intérêt</legend> for (const i of INTERESTS; key i.value) { <label><input type=\"checkbox\" {edit.field('interests', i.value)} /> {i.label}</label> } </fieldset> </fieldset> <fieldset> <legend>Dates, couleur, volume, avatar</legend> <label>Date de naissance <input type=\"date\" {edit.field('birthdate')} /></label> <label>Heure de rendez-vous <input type=\"time\" {edit.field('meetingTime')} /></label> <label>Couleur préférée <input type=\"color\" {edit.field('color')} /></label> <label>Volume ({edit.values().volume}) <input type=\"range\" min=\"0\" max=\"100\" {edit.field('volume')} /></label> <label>Avatar <input type=\"file\" accept=\"image/*\" {edit.field('avatar')} /></label> <p class=\"error\">{edit.error('avatar')}</p> </fieldset> <fieldset> <legend>Téléphones</legend> for (const item of phones.items(); key item.key) { <div class=\"phone\"> <select aria-label=\"Type de numéro\" {item.field('label')}> <option value=\"mobile\">mobile</option><option value=\"travail\">travail</option><option value=\"domicile\">domicile</option> </select> <input type=\"tel\" aria-label=\"Numéro\" {item.field('number')} /> <button type=\"button\" on:click={() => phones.remove(item)}>Retirer</button> <p class=\"error\">{item.error('number')}</p> </div> } <p class=\"error\">{edit.error('phones')}</p> <button type=\"button\" on:click={() => phones.add({ label: 'mobile', number: '' })}>Ajouter un numéro</button> </fieldset> <p role=\"alert\" class=\"form-error\">{edit.formError()}</p> <p role=\"status\" class=\"saved\">{local.get().saved ? `Profil enregistré (n° ${local.get().saved}).` : ''}</p> <div class=\"actions\"> <button type=\"button\" on:click={() => (edit.reset(), local.set({ saved: null }))}>Tout effacer</button> <button type=\"submit\" disabled={edit.submitting()}>{edit.submitting() ? 'Enregistrement…' : 'Enregistrer'}</button> </div> </form> </main> } }"},{"url":"formulaires.html#tester-un-formulaire","page":"Formulaires","title":"Tester un formulaire","text":"On remplit les champs comme le ferait le navigateur, puis on joue le rôle du store avec un faux store : test('affiche l’erreur du serveur sous le bon champ', async () => { const account = fakeStore('account', { state: { userId: null } }); const { container } = await mount(SignupScreen, { stores: [account] }); const ui = within(container); await userEvent.type(ui.getByLabelText('E-mail'), 'ada@example.com'); await userEvent.type(ui.getByLabelText('Mot de passe'), 'longpassword'); await userEvent.click(ui.getByRole('button', { name: 'Créer mon compte' })); expect(account.sent).toEqual([{ name: 'register', args: [{ email: 'ada@example.com', password: 'longpassword' }] }]); const input = account.sent[0]!.args[0]; // le body envoyé : l'issue doit porter le même account.emit('register:failed', { input, reason: 'email-taken', error: null }); await flush(); expect(ui.getByText('Adresse déjà utilisée')).toBeTruthy(); }); L'issue émise doit porter le même input que la commande envoyée : c'est ainsi que le formulaire reconnaît la réponse à sa propre soumission."},{"url":"formulaires.html#ce-que-le-compilateur-verifie","page":"Formulaires","title":"Ce que le compilateur vérifie","text":"field vise un champ existant, qui n'est pas une liste ; la valeur d'un radio appartient à l'union déclarée. Chaque règle reçoit le bon type : age reçoit number | null , newsletter un boolean . submit.toInput produit bien l' input de la commande. failures répartit exactement les raisons de la commande entre fields et form , et fields ne vise que des champs existants. Une vérification vise une commande du store, et toInput et accept sont typés par elle. list(…).add(…) exige une ligne complète."},{"url":"formulaires.html#limites","page":"Formulaires","title":"Limites","text":"Les objets imbriqués ne sont pris en charge que sous forme de listes de lignes. Pour un sous-objet (une adresse), aplatis ses champs ( street , city ), puis reconstruis l'objet dans submit.toInput . Les erreurs du serveur ( failures.fields ) visent des champs de premier niveau, pas une ligne d'une liste. Les vérifications asynchrones passent par le store de soumission. Un champ fichier ne peut pas être pré-rempli."},{"url":"garanties.html","page":"Ce que le compilateur vérifie","title":"Ce que le compilateur vérifie","text":"La plupart des erreurs d'usage de Super sont détectées avant l'exécution : par TypeScript, ou par le plugin Vite. Cette page liste ce qui est vérifié, où, et ce qui ne l'est pas. Sauf la section sur les templates , chaque extrait ci-dessous vient des tests de types du dépôt ( packages/*/src/*.test-d.ts ) : chaque @ts-expect-error y fait échouer npm run typecheck si l'erreur attendue disparaît. Les extraits utilisent leur contrat d'essai basket : commandes add({ sku }) , clear() et save({ id }) (qui déclare Outcome<{ count: number }, 'empty' | 'offline'> ), événements emptied et saved: { id } , sélecteurs quantity(sku) , count() , entries() ."},{"url":"garanties.html#contrats-et-stores","page":"Ce que le compilateur vérifie","title":"Contrats et stores","text":"// @ts-expect-error une commande ne renvoie pas de donnée class Async extends SuperContract<{ state: {}; commands: { add(): Promise<number> } }> {} // @ts-expect-error deux paramètres : une commande n'a qu'un body class Bad extends SuperContract<{ state: {}; commands: { add(a: number, b: number): void } }> {} class Typo extends SuperContract<{ state: {}; command: { add(): void } }> { constructor() { // @ts-expect-error clé inconnue dans les types du contrat : command (attendu : state, commands, events) super({ name: 'typo' }); } } class BadName extends SuperStore<BasketContract> { constructor() { // @ts-expect-error aucun contrat 'panier' super({ contract: 'panier', initialState: { items: {} } }); } } // @ts-expect-error initialState ne respecte pas le state du contrat super({ contract: 'basket', initialState: { items: 'aucun' } }); // @ts-expect-error le premier paramètre d'un sélecteur est l'état du contrat abstract class WrongStore extends SuperStore<WrongState> {} // WrongState : count(s: { total: number }) // @ts-expect-error « pending » est réservé : Super le fournit avec les sélecteurs abstract class PendingStore extends SuperStore<Pending> {} // Pending déclare un sélecteur pending // @ts-expect-error clear et save manquent class Missing extends SuperStore<BasketContract> implements Commands<Missing> { constructor() { super(init); } add(_: { sku: string }) {} } class Wrong extends SuperStore<BasketContract> implements Commands<Wrong> { // @ts-expect-error paramètres différents de ceux du contrat add(_: { sku: 'mug' }) {} // @ts-expect-error clear est déclaré void clear() { return 42; } // @ts-expect-error le résultat déclaré est { count: number } async save(_: { id: string }) { return { total: 0 }; } // @ts-expect-error méthode publique hors contrat increment() {} } // Dans une méthode du store : // @ts-expect-error événement inconnu this.emit('nope'); // @ts-expect-error payload requis this.emit('saved'); // @ts-expect-error raison d'échec non déclarée this.fail('nope'); // @ts-expect-error commande inconnue void this.send('nope'); // @ts-expect-error dépendance manquante WithDeps.create(); // @ts-expect-error dépendance mal typée Store.create({ api: { fetchCart: () => 42 } }); // @ts-expect-error un store sans dépendance n'en reçoit pas NoDeps.create({ api: 1 }); Une commande déclarée avec une réponse directe, ou avec plusieurs paramètres. Un super({ contract }) qui nomme un contrat inconnu, ou un état initial non conforme. Avec implements Commands<Self> : une commande sans méthode, une méthode aux paramètres différents de ceux du contrat, une méthode qui renvoie autre chose que le résultat déclaré (ou qui l'oublie), une méthode publique hors contrat. Un événement inconnu, un payload mal typé ou oublié ; une raison d'échec inconnue du contrat ; une commande inconnue dans this.send . Des dépendances manquantes ou mal typées à la création."},{"url":"garanties.html#lire-et-envoyer","page":"Ce que le compilateur vérifie","title":"Lire et envoyer","text":"Sur le handle d'un store (tests, racine de composition, autres stores) : const basket = Ok.create(); // @ts-expect-error l'instance ne sort pas : pas de méthode add sur le handle basket.add({ sku: 'mug' }); // @ts-expect-error body mal typé basket.send('add', { sku: 42 }); // @ts-expect-error paramètre du sélecteur requis basket.selectors.quantity(); // @ts-expect-error commande inconnue void shop.send('remove'); // @ts-expect-error body manquant void shop.send('add'); // @ts-expect-error argument en trop void shop.send('load', 1); // @ts-expect-error événement inconnu shop.on('removed', () => {}); // @ts-expect-error commande inconnue cart.on('remove:done', () => {}); // @ts-expect-error champ absent du body cart.pending('add', { id: 'a' }); Dans un composant, par la vue du contrat (extrait des tests de types, écrits en .ts : dans un .super , @contract basket; et @selector donnent les mêmes vérifications) : basket = this.contract('basket'); // @ts-expect-error aucun contrat 'panier' other = this.contract('panier'); // @ts-expect-error un sélecteur à paramètre se lit dans une fonction raw = this.selector(this.basket.selectors.quantity); // @ts-expect-error 0 ne vient pas d'un sélecteur : la condition se fait dans render shown = this.selector(() => (this.props.show ? this.basket.selectors.count() : 0)); // @ts-expect-error un calcul sur la valeur se fait dans render (ou dans un sélecteur du contrat) double = this.selector(() => this.basket.selectors.count() * 2); // @ts-expect-error un tableau dérivé n'est plus la valeur du sélecteur skus = this.selector(() => this.basket.selectors.entries().map(([sku]) => sku)); // @ts-expect-error aucun sélecteur constant = this.selector(() => 42); render() { // @ts-expect-error l'état brut n'est pas exposé this.basket.state(); // @ts-expect-error body mal typé this.basket.send('add', { sku: 1 }); // @ts-expect-error commande inconnue this.basket.send('nope'); // … }"},{"url":"garanties.html#composants","page":"Ce que le compilateur vérifie","title":"Composants","text":"Ces tests écrivent Dialog.create(…) : c'est ce que devient <Dialog … /> dans le TS virtuel d'un .super , d'où les mêmes erreurs dans un template (voir plus bas ). class Dialog extends SuperElement<{ props: { question: string }; emits: { answered: { confirmed: boolean }; closed: void } }> { static tag = 't-dialog'; render() { // @ts-expect-error événement non déclaré this.emit('nope'); // @ts-expect-error payload requis this.emit('answered'); // … } } // @ts-expect-error props requises Dialog.create(); // @ts-expect-error prop mal typée Dialog.create({ question: 42 }); // @ts-expect-error écouteur pour un événement que l'enfant n'émet pas Dialog.create({ question: 'ok ?' }, { on: { nope: () => {} } }); // @ts-expect-error `static tag` manquant NoTag.create(); // @ts-expect-error render est obligatoire class NoRender extends SuperElement { static tag = 'cmp-no-render'; }"},{"url":"garanties.html#formulaires","page":"Ce que le compilateur vérifie","title":"Formulaires","text":"// @ts-expect-error champ inconnu edit.field('nope'); // @ts-expect-error une liste ne se lie pas comme un champ simple edit.field('phones'); // @ts-expect-error valeur de radio hors de l'union edit.field('plan', 'gold'); // @ts-expect-error ligne incomplète phones.add({ label: 'travail' }); this.form({ … }) vérifie aussi que failures répartit exactement les raisons d'échec de la commande de soumission (une raison oubliée, présente deux fois ou inconnue du contrat ne compile pas, ni un champ inconnu dans fields ), que submit.toInput produit le body de la commande, et que le toInput d'une vérification asynchrone ( checks ) produit celui de la sienne."},{"url":"garanties.html#templates-super","page":"Ce que le compilateur vérifie","title":"Templates des fichiers .super","text":"Le template d'un composant .super est vérifié par npm run typecheck ( super-tsc ), et chaque erreur est rapportée à sa position dans le .super . L'extrait vient du projet d'essai de packages/lang : chaque ligne marquée ERREUR doit être signalée, et aucune autre ( packages/lang/src/check.test.ts ) ; il y en a 16. Greeting y est un composant aux props { name: string } , qui émet closed ; Panel déclare @prop heading: string; , @prop content: Children; et @prop footer?: Children; . export class ErrorsFixture extends SuperElement { @tag = 'lang-errors'; @ref input: HTMLInputElement; @state local = { user: null as { name: string } | null, status: 'idle' as Status, items: [] as Item[] }; render() { <main> <dvi>typo</dvi> {/* ERREUR balise inconnue */} <p>{this.local.get().user.name}</p> {/* ERREUR null possible */} const user = this.local.get().user; if (user) { <p>{user.name}</p> } for (const item of this.local.get().items; key item.idd) { {/* ERREUR clé */} <li>{item}</li> {/* ERREUR objet interpolé */} } <button on:clik={() => {}}>x</button> {/* ERREUR événement inconnu */} <input on:input={(e) => e.currentTarget.value.toFixed()} /> {/* ERREUR value est une chaîne */} <div ref={this.input}></div> {/* ERREUR référence sur le mauvais élément */} <input ref={this.input} /> const status = this.local.get().status; switch (status) { case 'idle': <p>idle</p> default: {assertNever(status)} {/* ERREUR switch non exhaustif */} } <Greeting nam=\"Ada\" on:closed={(e) => e.reason} /> {/* ERREUR prop inconnue */} <Greeting name={42} /> {/* ERREUR prop mal typée */} <Greeting name=\"Ada\" on:open={() => {}} /> {/* ERREUR événement inconnu du composant */} <p>for (more info) see below</p> {/* ERREUR texte ambigu */} <Greeting name=\"Ada\"><p>Greeting ne prend pas d’enfants</p></Greeting> {/* ERREUR enfants refusés */} <Panel heading=\"Sans enfants\" /> {/* ERREUR enfants obligatoires */} <Panel heading=\"x\"><p>a</p><:header>h</:header></Panel> {/* ERREUR emplacement inconnu */} </main> } } export class NativeName extends SuperElement { @tag = 'lang-native-name'; @prop title: string; // {/* ERREUR nom déjà pris par les éléments HTML */} render() { <p>{this.title}</p> } } Une balise sans tiret qui n'est pas une balise HTML connue. Une valeur peut-être null lue sans test ; le rétrécissement d'un if vaut pour les éléments qu'il contient. Une clé de boucle ( key ) qui n'existe pas sur l'élément parcouru. Un objet affiché par {…} (fini les [object Object] ). Un écouteur on: pour un événement que la balise n'a pas, et le type de l'événement reçu ( e.currentTarget est l' HTMLInputElement ). Une référence ref={…} posée sur un élément d'un autre type que le sien. Un switch non exhaustif, avec default: {assertNever(x)} . Sur un composant enfant : une prop inconnue, une prop mal typée, un on: pour un événement absent de ses emits . Des enfants pour un composant qui ne déclare pas content , des enfants obligatoires qui manquent, un emplacement <:nom> qui n'est pas une prop du composant. Un texte qui commence comme une instruction sans en être une, avec la correction proposée : {'for (more info) see below'} . Une prop qui porte le nom d'une propriété des éléments HTML ( @prop title , id , hidden …) : « « title » est déjà une propriété des éléments HTML : choisis un autre nom ». Le message de TypeScript est rapporté tel quel (« 'nam' does not exist in type 'Props'. Did you mean to write 'name'? »). Le parser refuse aussi, avec le message et souvent la correction ( packages/lang/src/parser.test.ts , packages/lang/src/compile.test.ts ) : la syntaxe de lit : @click , ?disabled , .value (« Syntaxe de lit : écris on:click={…} ») ; < et } dans le texte, avec la correction {'<'} , {'}'} ; une balise fermante qui ne correspond pas (« </i> ferme <b> ») ; return x; dans une méthode qui émet des éléments ( return; reste permis, comme return x; dans une fonction imbriquée) ; un élément hors d'une méthode de classe ; un bloc dont le } manque avant la balise fermante du parent ; un emplacement <:nom> hors d'un composant, avec des attributs, rempli deux fois, ou nommé content ."},{"url":"garanties.html#declarations-composant","page":"Ce que le compilateur vérifie","title":"Déclarations d'un composant","text":"Les déclarations @tag , @title , @prop et @emit sont lues par le parser, qui refuse ( parser.test.ts , « parse : déclarations d’un composant ») : un composant sans @tag (« Un composant déclare son tag : `@tag = 'mon-composant';` »), sauf une classe abstract ; static tag = '…'; dans un .super (« Dans un `.super`, le tag se déclare par `@tag = '…';` ») ; un tag qui n'est pas une chaîne écrite telle quelle, en minuscules, avec un tiret ; un générique SuperElement<…> écrit à la main (« Dans un `.super`, les props et les événements se déclarent dans la classe : `@prop nom: Type;` et `@emit nom: Type;` ») ; une déclaration en double (« `@tag` déclaré deux fois », « `@prop a` déclaré deux fois ») ; une prop sans type ( @prop label; ), une prop facultative avec une valeur par défaut ( @prop size?: number = 2; : « retire le ? »), un événement avec une valeur ; une déclaration hors d'un composant (« `@prop` ne s’écrit que dans un composant (`extends SuperElement`) »). Les types du composant en sont tirés ( virtual.test.ts ) : @prop question: string; devient une prop obligatoire, @prop tone: … = 'neutral'; et @prop size?: number; des props facultatives, @emit answered: { confirmed: boolean }; un événement. Ce sont eux que vérifient les balises qui utilisent le composant (prop inconnue, mal typée, on: inconnu, ci-dessus). Les déclarations de préparation ( @contract , @selector , @state , @form , @ref , @on ) sont lues elles aussi, et le parser refuse ( parser.test.ts , « parse : déclarations de préparation et écouteurs ») : un contrat déclaré deux fois, même sous un autre nom de champ (« Le contrat `cart` est déjà déclaré par `@contract cart` ») ; @contract router; (« Le router se lit par `this.router`, sans `@contract` ») ; un contrat qui n'est pas une chaîne écrite telle quelle ( @contract cart = name; ) ; un type sur @selector (« Pas de type sur `@selector` : il vient de la valeur ») ; un @ref sans type (« Une référence déclare le type de son élément : `@ref input: HTMLInputElement;` ») ; un @on mal écrit ( @on('cart') : « `@on` s’écrit `@on('contrat', 'événement')`, au-dessus d’une méthode ») ; l'ancienne forme dans un composant ( cart = this.contract('cart'); , this.selector(…) , this.state(…) , this.ref<T>() ), avec la ligne réécrite en correction ( @contract cart; , @state local = { open: false }; …) ; hors composant, la même ligne reste du TS ordinaire ; un écouteur posé dans le constructeur (« Dans un `.super`, un écouteur se déclare sur une méthode : `@on('cart', 'événement') onEvent(payload) { … }` »). Le TS virtuel en tire les champs qu'on écrivait à la main ( virtual.test.ts ) : @contract cart; devient readonly cart = this.contract('cart'); , @selector , @state et @ref les champs this.selector(…) , this.state(…) , this.ref<T>() , et @on('profile', 'save:done') onSaved(…) un écouteur this.contract('profile').on('save:done', …) : le paramètre de la méthode a donc le type du payload de l'événement, vérifié comme dans un écouteur écrit à la main. @on('router', 'navigated') devient this.router.on('navigated', …) ."},{"url":"garanties.html#titre-de-la-page","page":"Ce que le compilateur vérifie","title":"Titre de la page","text":"@title = …; et this.page.title = … sont vérifiés à l'exécution ( packages/dom/src/page.test.ts ) : un titre posé pendant render lève « `this.page.title` ne se pose pas pendant render » ; this.page.title ne se lit pas : « `this.page.title` se pose, il ne se lit pas » ; la pile est testée : le dernier composant monté qui pose un titre l'emporte, celui du dessous suit ses données sans s'afficher et revient au démontage ; un titre en fonction suit les valeurs qu'il lit, comme render . Le code compilé garde les numéros de ligne de la source, et sa source map ramène le JS final à la ligne et à la colonne du .super ( compile.test.ts ). Voir Templates et Outillage ."},{"url":"garanties.html#router","page":"Ce que le compilateur vérifie","title":"Router","text":"Avec defineRouter({ home: '/', item: { path: '/items/:id', params: params<{ id: number }>({ id: Number }) }, list: '/list?sort&tag[]' }) : // Dans un composant, par this.router : // @ts-expect-error le router se lit par this.router this.contract('router'); // @ts-expect-error paramètre `id` manquant this.router.href('item'); // @ts-expect-error `id` est un nombre this.router.href('item', { params: { id: '1' } }); // @ts-expect-error route inconnue this.router.href('nope'); // @ts-expect-error params requis this.router.send('navigate', { to: 'item' }); // @ts-expect-error route inconnue this.router.send('navigate', { to: 'nope' }); // @ts-expect-error aucune route n'a ce paramètre this.router.current.params.nope; // @ts-expect-error dans l'écran de `item`, `sort` est la query d'une autre route this.router.current.query.sort; // @ts-expect-error route inconnue this.router.at('nope'); // @ts-expect-error les sélecteurs du router sont devenus `current` this.router.selectors; // Hors composants, les mêmes vérifications sur Router.href(…) et router.send('navigate', …). // @ts-expect-error écran manquant declared.screens(() => ({ home: HomeScreen })); // @ts-expect-error un écran ne reçoit pas de props de route declared.screens(() => ({ home: HomeScreen, item: IdScreen })); // @ts-expect-error l'écran '!' doit accepter { error, path } declared.screens(() => ({ home: Screen, item: Screen, '!': IdScreen })); // @ts-expect-error '*' est réservé, ce n'est pas un nom de route defineRouter({ '*': '/x' }); // @ts-expect-error '!' n'est pas un nom de route defineRouter({ '!': '/oops' }); // @ts-expect-error .screens() pas encore appelé createRouter(declared, { mode: 'memory' }); // @ts-expect-error route inconnue declared.screens(() => ({ home: Screen, item: Screen, stats: redirect({ to: 'nope' }) })); // @ts-expect-error paramètre `id` manquant declared.screens(() => ({ home: Screen, item: Screen, stats: redirect({ to: 'item' }) })); // @ts-expect-error contrat inconnu declared.guards(({ read }) => ({ home: () => read('rt-nope') && true })); // @ts-expect-error cible de redirection inconnue declared.guards(() => ({ home: () => ({ to: 'nope' }) })); // @ts-expect-error guard pour une route inconnue declared.guards(() => ({ nope: () => true })); // @ts-expect-error les guards se déclarent avant les écrans : .screens() reste le dernier appel declared.screens(() => ({ home: Screen, item: Screen })).guards(() => ({})); Dans un écran ou après isValid() , les valeurs ont le type de la route : counterId = this.selector(this.router.current.params.id); // number | undefined render() { if (!this.counterId.isValid()) { <p>Introuvable</p> return; } this.counterId.value; // number } Les descriptions sont vérifiées contre le type écrit par l'app : // @ts-expect-error une clé obligatoire exige sa valeur par défaut query<{ page: number }>({ page: Number }); // @ts-expect-error une clé facultative n'a pas de défaut query<{ page?: number }>({ page: { type: Number, default: 1 } }); // @ts-expect-error mauvais type query<{ page?: number }>({ page: String }); // @ts-expect-error valeur hors de l'union query<{ sort?: 'a' | 'b' }>({ sort: { oneOf: ['a', 'c'] } }); // @ts-expect-error défaut hors de l'union query<{ sort: 'a' | 'b' }>({ sort: { oneOf: ['a', 'b'], default: 'c' } }); // @ts-expect-error une liste se décrit entre crochets query<{ tag: string[] }>({ tag: String }); // @ts-expect-error clé manquante query<{ a?: string; b?: string }>({ a: String }); // @ts-expect-error clé en trop query<{ a?: string }>({ a: String, b: String }); // @ts-expect-error un paramètre de chemin est toujours présent : pas de défaut params<{ id: number }>({ id: { type: Number, default: 1 } }); // @ts-expect-error `slug` n'est pas un paramètre du chemin defineRouter({ counter: { path: '/counters/:id', params: params<{ slug: string }>({ slug: String }) } }); // @ts-expect-error la query se décrit par query<T>, pas dans le chemin defineRouter({ counters: { path: '/counters?sort' } }); Pour la query, écrite dans le chemin ( list: '/list?sort&tag[]' ) ou décrite ( counters , comme dans Décrire les valeurs ) : // @ts-expect-error `page` n'est pas déclaré Router.href('list', { query: { page: '2' } }); // @ts-expect-error `tag` est une liste Router.href('list', { query: { tag: 'a' } }); // @ts-expect-error valeur hors de l'union (query décrite par { oneOf }) Router.href('counters', { query: { sort: 'nope' } }); // @ts-expect-error `id` reste requis Router.href('item', { query: {} }); // @ts-expect-error `/` n'a pas de query void router.send('navigate', { to: 'home', query: { sort: 'asc' } });"},{"url":"garanties.html#architecture","page":"Ce que le compilateur vérifie","title":"Architecture (plugin Vite)","text":"Ces règles ne sont pas des erreurs de type : le plugin refuse de charger le module, en dev, au build et en test. Pour un .super , elles s'appliquent à son code compilé. Les fichiers de test ( *.test.ts ) n'y sont pas soumis. Un module qui importe SuperContract ou SuperStore hors de src/@core/ . Un module qui importe SuperElement hors de src/@components/ . Un composant qui importe de @core/ autre chose qu'un type (un contrat, un store, une constante, ou import * as ) : il parle aux stores par @contract nom; ( this.contract('nom') dans un .ts ). Un module de @core/ qui importe une valeur de @super-ts/dom . Le plugin lit aussi les contrats et le router pour générer src/@core/contracts.d.ts . Il s'arrête avec une erreur sur : un contrat ( export class X extends SuperContract ) qui ne se nomme pas par super({ name: '…' }) ; deux contrats du même nom ; un contrat nommé 'router' quand l'app déclare un router ; deux export const … = defineRouter(…) dans le src . Voir Architecture ."},{"url":"garanties.html#a-l-execution","page":"Ce que le compilateur vérifie","title":"Erreurs à l'exécution","text":"Situation Message Store non fourni pour un composant [super] <counter-screen> : aucun store fourni pour le contrat \"counter\". Ajoute-le à createApp({ stores }) ou à mount(..., { stores }). Deux stores pour le même contrat [super] deux stores fournis pour le contrat \"counter\" Commande inconnue [super] commande inconnue \"x\" sur le store \"counter\" Commande après dispose() [super] store \"counter\" disposé : commande \"x\" refusée État lu ou modifié dans le constructeur d'un store [super] un store ne lit ni ne modifie son état dans son constructeur : utilise create() Méthode pending dans un contrat sans store déclaré (sinon refusée à la compilation) [super] \"pending\" est réservé : Super le fournit avec les sélecteurs Contrat introuvable (plugin Vite absent) [super] aucun contrat nommé \"counter\". … Tag absent ou sans tiret (composant .ts ; dans un .super , le parser le refuse avant) [super] CounterScreen : le tag (`@tag = '…'` dans un .super, `static tag` dans un .ts) est obligatoire et doit contenir un tiret (reçu counter) Même tag pour deux composants [super] le tag \"counter-screen\" est déjà utilisé par un autre composant connectedCallback ou disconnectedCallback surchargé [super] CounterScreen : ne surcharge pas connectedCallback, utilise mounted() / unmounted() contract , state , selector , ref ou form appelé pendant render [super] <counter-screen> : `selector` se déclare dans un champ ou le constructeur, pas pendant render this.page.title posé pendant render [super] <counter-screen> : `this.page.title` ne se pose pas pendant render this.page.title lu [super] <counter-screen> : `this.page.title` se pose, il ne se lit pas on appelé pendant render [super] <counter-screen> : `on` ne s'appelle pas pendant render Sélecteur lu avant le montage (dans le constructeur) [super] <counter-screen> : le contrat \"counter\" ne se lit qu'une fois le composant monté selector qui ne renvoie pas la valeur d'un sélecteur ( null ou undefined , que le compilateur ne voit pas) [super] <counter-screen> : selector() doit renvoyer la valeur d’un sélecteur, telle quelle. … Boucle de redirections [super] trop de redirections à partir de \"/a\" Guard qui lit un store non fourni [super] guard du router : aucun store fourni pour le contrat \"session\" Chemin qui ne commence pas par / [super] le chemin \"counters\" de la route \"x\" doit commencer par \"/\" href avec un paramètre manquant (typage contourné) [super] paramètre \"id\" manquant pour la route \"counter\" params qui ne décrit pas exactement les paramètres du chemin (typage contourné) [super] route \"counter\" : params doit décrire exactement les paramètres du chemin (id) Query écrite dans le chemin d'une route objet (typage contourné) [super] route \"counters\" : la query se décrit par query<T>({…}), pas dans le chemin Description qui n'est ni String , Number , Boolean , ni { oneOf } [super] clé \"x\" de la route \"a\" : attendu String, Number, Boolean ou { oneOf: [...] } Valeur de this.router.at(…) lue sur une autre route [super] <counter-history> : this.router.at('counter') lu alors que la route active est 'counters'"},{"url":"garanties.html#ce-qui-n-est-pas-verifie","page":"Ce que le compilateur vérifie","title":"Ce qui n'est pas vérifié","text":"Un store sans implements Commands<Self> : ni commande manquante, ni paramètres, ni résultat, ni méthode en trop. Une commande sans méthode n'est alors signalée qu'au send (« commande inconnue »). this.fail accepte les raisons de toutes les commandes du contrat, pas seulement celles de la commande en cours. Un événement déclaré que le store n'émet jamais. Un composant ne rattrape pas l'erreur de son propre constructeur : seul le renderError d'un ancêtre la reçoit. Un seul router est typé : celui que le plugin trouve dans le src . Une valeur de l'URL : elle vient de l'extérieur. Une valeur non conforme à la description est lue comme absente (query) ou undefined (paramètre), et isValid() le signale ; c'est à l'écran ou au guard d'en décider. Le lien entre un écran et sa route vient de .screens(…) , lu par le plugin Vite : un écran qu'il ne retrouve pas (classe sans @tag lisible, ou sans static tag dans un .ts , import qu'il ne résout pas) voit toutes les routes. La route qu'un composant .ts déclare à la main ( SuperElement<{ route: 'counter' }> ) n'est pas comparée à .screens(…) . Une liste oneOf incomplète : pour sort: 'label' | 'value' , { oneOf: ['label'] } compile. Une valeur en trop est refusée, mais une valeur oubliée ne l'est pas : elle ne sera jamais lue comme valide dans l'URL. Le type étant donné à part ( query<T> ), TypeScript ne peut pas vérifier que la liste couvre toute l'union. Un composant écrit par son tag ( <counter-screen> dans un template) au lieu de sa classe ( <CounterScreen /> ) : une balise avec tiret est un élément personnalisé quelconque, ni ses attributs ni ses événements ne sont vérifiés, et ce n'est pas supporté. Un import * as de @super-ts/dom ou @super-ts/core hors des dossiers imposés : la règle de placement ne voit que les imports nommés. Voir Limites ."},{"url":"index.html","page":"Super","title":"Super","text":"Un framework front minimaliste, typé de bout en bout, qui encadre trois choses : les stores, les composants et le routing. Tout le reste appartient à ton projet. Statut : draft exploratoire L'API peut encore bouger. Les paquets ne sont pas publiés sur npm : ils vivent dans le dépôt, sous packages/ ."},{"url":"index.html#en-un-coup-d-oeil","page":"Super","title":"En un coup d'œil","text":"Une fonctionnalité Super tient en trois fichiers : un contrat qui dit ce qu'on peut lire, demander et écouter ; un store qui l'implémente ; un composant qui affiche et envoie des commandes. Chacun est une classe. import { type Outcome, SuperContract } from '@super-ts/core'; export type CounterState = { counts: Readonly<Record<string, number>> }; export type CounterTypes = { state: CounterState; commands: { increment(input: { id: string }): Outcome<{ count: number }, 'storage'> }; }; export class CounterContract extends SuperContract<CounterTypes> { constructor() { super({ name: 'counter' }); } // Un sélecteur est une méthode : l'état d'abord, puis ses paramètres. count(s: CounterState, id: string) { return s.counts[id] ?? 0; } } import { type Commands, SuperStore } from '@super-ts/core'; import type { CounterRepository } from '../../ports/counter-repository'; import type { CounterContract } from './contract'; export class CounterStore extends SuperStore<CounterContract> implements Commands<CounterStore> { #repository: CounterRepository; constructor({ counterRepository }: { counterRepository: CounterRepository }) { super({ contract: 'counter', initialState: { counts: {} } }); this.#repository = counterRepository; } // Une commande du contrat = une méthode. L'attente vit dans le store. async increment({ id }: { id: string }) { const count = this.selectors.count(id) + 1; await this.#repository.save(id, count).catch(() => this.fail('storage')); this.set((s) => ({ counts: { ...s.counts, [id]: count } })); return { count }; // Super publie increment:done ; « en cours » est suivi tout seul } } import { SuperElement } from '@super-ts/dom'; export class CounterButton extends SuperElement { // Déclaré dans la classe : le tag, et la prop reçue du parent (<CounterButton counterId=\"cafes\" />). @tag = 'counter-button'; @prop counterId: string; // Préparé une fois : le store, demandé par le nom de son contrat, et la valeur lue. @contract counter; @selector count = () => this.counter.selectors.count(this.counterId); // À chaque rendu : on affiche, on envoie et on laisse filer. render() { <button on:click={() => this.counter.send('increment', { id: this.counterId })}>{this.count.value}</button> } } Le composant est un fichier .super : du TypeScript dont les méthodes écrivent leurs éléments directement, comme des instructions (voir Templates ). Il déclare dans sa classe son tag et ses props ( @tag , @prop ), le store qu'il lit et la valeur qu'il en tire ( @contract , @selector ), et lit une prop par son nom : this.counterId . Il n'importe rien de @core/ : il demande le store par le nom de son contrat, et le compilateur connaît ses sélecteurs et ses commandes. Il envoie une commande et laisse filer ; le store fait le travail asynchrone et met à jour son état ; Super suit la commande ( this.counter.selectors.pending('increment') ) et publie son issue ( increment:done , increment:failed ). Le composant se re-rend parce que la valeur qu'il lit a changé."},{"url":"index.html#principes","page":"Super","title":"Principes","text":"Deux dossiers imposés, le reste libre. Contrats et stores dans src/@core/ , composants dans src/@components/ . Le préfixe @ marque ce qui appartient à Super. Domaine, ports, adapters, routes et racine de composition s'organisent comme ton projet l'entend. Le contrat est la seule porte d'un store. Ses sélecteurs disent ce qu'on lit, ses commandes ce qu'on demande, ses événements ce qu'on écoute. Un composant demande le store par son nom ( @contract counter; ) et n'importe de @core/ que des types. La vue envoie et laisse filer. Une commande ne renvoie rien : il n'y a jamais d' await dans un composant. Le résultat revient par l'état ou par un événement. Props vers le bas, événements vers le haut. Un parent n'appelle jamais une méthode d'un enfant. Préparer, puis afficher. Les champs et le constructeur d'un composant préparent une fois (contrats, état local, lectures, écouteurs) ; render affiche à chaque rendu. Super refuse de préparer quoi que ce soit pendant le rendu. Le compilateur fait le travail. Une commande inconnue, un body manquant, une méthode de store hors contrat, un lien sans son paramètre, un écran aux mauvaises props ou une faute dans un template ne compilent pas. Le standard web d'abord. Un store est un EventTarget , un composant est un custom element. Les fichiers .super sont compilés vers lit-html, une dépendance assumée mais cachée : tu n'importes jamais lit."},{"url":"index.html#par-ou-commencer","page":"Super","title":"Par où commencer","text":"Démarrer Installer, lancer l'exemple, écrire ta première fonctionnalité. Exemples Compteurs, formulaire, boutique, erreurs, widget, kit d'interface : une app à lancer et à lire. Architecture Ce que Super impose, ce qui reste à toi. Commandes et événements Le trajet d'une action, du clic à l'écran. Composants Champs, constructeur et render, et comment choisir où mettre quoi. Templates La syntaxe des fichiers .super : éléments, conditions, boucles, enfants. Questions fréquentes Les questions qu'on se pose en découvrant Super. API Toutes les classes et fonctions, en une page."},{"url":"index.html#ce-que-super-ne-fait-pas","page":"Super","title":"Ce que Super ne fait pas, volontairement","text":"Pas de client HTTP, pas de conteneur d'injection : tu assembles tout dans ta racine de composition. Pas de couches imposées au-delà de @core/ et @components/ . Pas de shadow DOM : les composants rendent en light DOM, tes styles globaux s'appliquent."},{"url":"index.html#les-paquets","page":"Super","title":"Les paquets","text":"Paquet Contenu @super-ts/core SuperContract , SuperStore : contrats, sélecteurs, stores. Aucune dépendance au DOM. @super-ts/dom SuperElement : composants, rendu, createApp , router. @super-ts/testing mount , fakeStore , record , flush , cleanup . @super-ts/ui Le kit d'interface : champs reliés aux formulaires, CommandButton , RouteLink , toasts, fenêtres, menus, table. Voir Kit d'interface . @super-ts/vite Le plugin qui compile les .super , fait respecter l'architecture et génère le dictionnaire des contrats ( @core/contracts.d.ts ). @super-ts/lang Le langage des .super : parser, compilation vers lit, vérification des types ( super-tsc ). Voir Outillage . super-language-server Le serveur de langage des .super pour l'éditeur ( packages/lang-server ). @super-ts/lint La configuration Biome qui fixe l'ordre des imports."},{"url":"index.html#avec-un-assistant-ia","page":"Super","title":"Avec un assistant IA","text":"La doc existe aussi en markdown, au format llms.txt , pour la donner à un LLM ou à un agent de code. Ces fichiers sont générés à partir de ces pages à chaque npm run check , et npm run docs:check échoue s'ils ne sont plus à jour. llms.txt : l'index, une ligne par page. llms-full.txt : toute la doc en un fichier, code compris. llms-small.txt : la même, sans la FAQ, le catalogue des exemples ni les renvois vers l'app d'exemples, pour les petites fenêtres de contexte. Dans un projet, il suffit d'indiquer le chemin à l'agent, par exemple dans un AGENTS.md : « la doc de Super est dans docs/llms-full.txt »."},{"url":"limites.html","page":"Limites","title":"Limites","text":"Super est un draft. Voici ce qu'il fait mal ou vérifie mal aujourd'hui. Ce qu'il ne fait pas encore est dans Chantiers et questions ouvertes ."},{"url":"limites.html#limites-connues","page":"Limites","title":"Limites connues","text":""},{"url":"limites.html#typage","page":"Limites","title":"Typage","text":"Les paramètres d'une méthode de store s'annotent à la main : TypeScript n'infère pas les paramètres d'une méthode de classe. implements Commands<…> vérifie seulement qu'ils sont égaux à ceux du contrat. this.fail accepte toutes les raisons déclarées par le contrat, pas seulement celles de la commande en cours."},{"url":"limites.html#plugin","page":"Limites","title":"Plugin d'architecture","text":"Il lit le code comme du texte : il voit les imports nommés (y compris renommés), pas un import * as dom from '@super-ts/dom' hors des dossiers imposés. Il reconnaît un contrat à sa déclaration export class X extends SuperContract , suivie de super({ name: '…' }) avec un nom écrit en toutes lettres. Rien n'empêche un composant d'importer un store exporté par un module user-land."},{"url":"limites.html#composants-limites","page":"Limites","title":"Composants","text":"Un composant ne rattrape pas l'erreur de son propre constructeur : seul le renderError d'un ancêtre le peut. @selector n'accepte que la valeur d'un sélecteur, telle quelle : une condition ou un calcul va dans render , ou dans un nouveau sélecteur du contrat. Une prop ou un champ ne peut pas porter le nom d'une propriété des éléments HTML ( id , title , hidden , slot …) : c'est une erreur de type. Un paramètre de route id se lit donc dans un champ nommé autrement ( counterId = this.router.current.params.id; ), et une prop title devient heading . C'est aussi pour ça que le contenu écrit entre les balises remplit une prop content et non children , propriété native des éléments. page est un nom réservé dans un composant : c'est this.page , qui porte le titre de la page. Un titre suivi ( @title = () => … ) n'est recalculé qu'au rendu du composant qui le pose. Ce qu'il lit est suivi comme les lectures de render : une valeur lue par le titre seul re-rend donc tout le composant quand elle change, et une valeur que Super ne suit pas (un champ ordinaire, l'heure) ne le met à jour qu'au prochain rendu. Un composant enfant s'écrit par sa classe ( <CounterScreen /> ) : une balise <counter-screen> écrite par son tag n'est pas supportée. Le remplacement à chaud recharge la page quand un composant change de champs, ou a des membres #privés , méthodes comprises (voir Remplacement à chaud )."},{"url":"limites.html#fichiers-super-limites","page":"Limites","title":"Fichiers .super","text":"La syntaxe est en version 0 ( packages/lang/SPEC.md ). Ses limites assumées : Pas de directive sur un composant ( {form.field('x')} dans sa balise) : un composant reçoit des props, des on: , des enfants et des emplacements nommés. Sur une balise native, on: n'accepte que les événements de cette balise : écouter sur un <div> un événement personnalisé remonté d'un enfant n'est pas permis. Une signature d'appel générique dans un type littéral ( { <T>(x: T): T } ) est prise pour un élément : sors-la dans un type ou une interface d'un fichier .ts . @prop , @emit et les déclarations de préparation ( @contract , @selector , @state , @form , @ref , @on ) sont du TS valide (des champs et des méthodes décorés), mais @tag = … et @title = … ne le sont pas : seuls nos outils les connaissent (le formateur des .super , la grammaire Tree-sitter, le serveur de langage). Un éditeur sans eux les affiche en erreur. Le nom d'événement de @on est une chaîne écrite telle quelle : pas de gabarit ( @on('counter', `${change}:done`) ) ni de boucle sur une liste d'événements. Écouter plusieurs événements demande une méthode par événement, qui peuvent appeler une même méthode privée (l'écran du compteur a onIncremented , onDecremented , onReset … qui appellent #done ). Pas de type sur @contract , @selector , @state ni @form : il vient de la valeur. Pour l'élargir, on écrit as dans la valeur ( @state local = { message: null as string | null }; ). @ref est l'inverse : un type, sans valeur. L'ancienne forme ( cart = this.contract('cart'); , this.selector(…) , this.state(…) , this.form(…) , this.ref<T>() , .on(…) dans le constructeur) est refusée dans un .super . Un composant écrit en .ts garde ces méthodes, qui restent la seule écriture possible hors des .super . Et côté outillage (voir Outillage ) : Biome ne lit pas les .super : leur TS est formaté par Biome à travers le formateur des .super , mais l'ordre de leurs imports n'est pas contrôlé. Dans Zed, l'extension des .super ( editors/zed ) s'installe en extension de développement, et sa grammaire ( editors/tree-sitter-super ) est compilée depuis un dépôt git local, désigné par un chemin absolu dans extension.toml tant que la grammaire n'est pas publiée. Le serveur de langage tourne sur TypeScript 6, parce que Volar ne supporte pas encore TypeScript 7. La vérification en ligne de commande ( npm run typecheck ), elle, utilise le TypeScript 7 du dépôt."},{"url":"limites.html#rendu","page":"Limites","title":"Rendu","text":"Le suivi des sélecteurs s'arrête au premier niveau de l'état : un sélecteur qui lit une liste est recalculé dès qu'un élément change. Un sélecteur qui construit de gros objets par élément paie alors un parcours complet de son résultat. Le cache des sélecteurs garde un résultat par jeu d'arguments primitifs (un sku , un id ) pendant toute la vie du store. Le gel de l'état ne descend que dans les tableaux et les objets simples : le contenu d'une Map , d'un Set ou d'une instance reste modifiable, et une telle mutation échappe au suivi. Les erreurs du code que Super ne voit pas passer ( setTimeout , écouteur posé à la main sur window ) partent seulement dans la console."},{"url":"limites.html#router-limites","page":"Limites","title":"Router","text":"Les guards sont synchrones, et il n'y a pas de guard de sortie (« modifications non enregistrées »). Pas de chemin de base (application servie sous /app/ ). Les types décrits se limitent à String , Number , Boolean , { oneOf } et leurs listes : pas de date, d'objet, ni de conversion sur mesure. Une liste { oneOf } qui oublie une valeur de l'union compile : seule une valeur en trop est refusée. La valeur oubliée n'est jamais valide dans l'URL. Pas de raccourci pour changer une seule clé de query : une navigation redonne toute la query ( { ...valeursActuelles, sort: 'value' } ). Un seul router typé par app : le plugin refuse deux déclarations defineRouter ."},{"url":"limites.html#kit-limites","page":"Limites","title":"Kit d'interface","text":"Pas de composant de mise en page ( Stack , Grid , Card ) : l'agencement reste le CSS de l'app. fieldOf s'écrit dans le rendu du composant qui possède le formulaire : un champ du kit placé dans un sous-composant ne suivrait plus le formulaire. Les éléments flottants (menu, popover, info-bulle, liste du combobox) n'utilisent pas l'API popover du navigateur : un ancêtre en overflow: hidden peut les couper. Quelques textes en français n'ont pas encore de prop pour les changer (« Vérification… », la pagination de la table). Voir Limites du kit ."},{"url":"limites.html#distribution","page":"Limites","title":"Distribution","text":"Les paquets ne sont pas publiés : ils sont résolus par alias depuis packages/*/src . Ce qui manque encore, les suites mises de côté et les questions en discussion sont dans Chantiers et questions ouvertes ."},{"url":"lire-un-store.html","page":"Lire un store","title":"Lire un store","text":"@contract nom; donne au composant la vue du store fourni par l'application. @selector choisit ce qu'il en lit : le composant ne se re-rend que si cette valeur change."},{"url":"lire-un-store.html#use","page":"Lire un store","title":"@contract et @selector","text":"/** Une ligne de la liste d'accueil : ne se re-rend que si la valeur de son compteur change. */ export class CounterListItem extends SuperElement { @tag = 'counter-list-item'; @prop counterId: string; @prop label: string; @contract counter; @selector count = () => this.counter.selectors.count(this.counterId); render() { <a href={this.router.href('counter', { params: { id: this.counterId } })}>{this.label}</a> <span class=\"counter-list-value\">{this.count.value}</span> } } @contract counter; se déclare dans le corps de la classe, une fois par store utilisé, et se lit par this.counter . Le nom est celui du contrat, vérifié par le compilateur : @contract compteur; ne compile pas. Pour un autre nom de champ : @contract shop = 'catalog'; . @selector count = …; se déclare aussi dans le corps de la classe, après le @contract qu'il lit. Sa valeur est la lecture d' un sélecteur ; il se lit par .value dans render , avec le type du sélecteur. Pas de type à écrire : il vient de la valeur. Toutes ces déclarations sont décrites dans Composants . Un composant écrit dans un .ts garde les méthodes : counter = this.contract('counter') , count = this.selector(…) . Les sélecteurs sont ceux du contrat, avec l'état déjà fourni, plus pending(…) pour savoir si une commande est en cours (voir pending ). Le composant n'importe pas le contrat : il le nomme. Seuls des types peuvent venir de @core/ ( import type )."},{"url":"lire-un-store.html#un-selecteur-tel-quel","page":"Lire un store","title":"Un sélecteur, tel quel","text":"La valeur d'un @selector est la valeur d'un sélecteur telle quelle . Deux écritures, selon que le sélecteur prend un paramètre ou non : @contract counter; @selector catalog = this.counter.selectors.catalog; // sans paramètre : passé tel quel @selector isLoading = () => this.counter.selectors.pending('load'); // avec paramètre : une fonction @selector loadErrorMessage = this.counter.selectors.loadErrorMessage; Une condition, un calcul ou un mélange de deux sélecteurs ne vont pas dans un @selector . Ils vont dans render , ou dans un nouveau sélecteur du contrat s'ils ont un sens métier : // ✗ ne compile pas : la fonction ne renvoie pas la valeur d'un sélecteur @selector canDecrement = () => this.counter.selectors.canDecrement(this.counterId) && !this.counter.selectors.pending(); // ✓ deux lectures, combinées dans render @selector canDecrement = () => this.counter.selectors.canDecrement(this.counterId); @selector busy = () => this.counter.selectors.pending(); render() { <button disabled={!this.canDecrement.value || this.busy.value}>−</button> } La règle est vérifiée à la compilation : une valeur de sélecteur porte une marque de type que @selector exige. null et undefined ne peuvent pas porter de marque : pour eux, Super vérifie à l'exécution, et lève une erreur qui explique quoi faire. La raison : un @selector qui calcule pourrait ne dépendre d'aucun store et rester figé, ou mélanger le store avec autre chose sans que Super le sache."},{"url":"lire-un-store.html#ce-que-renvoie-contract","page":"Lire un store","title":"Ce que donne @contract","text":"Membre Rôle selectors Les sélecteurs du contrat, plus pending , lus sur l'état courant à chaque appel. À passer à @selector , ou à lire directement dans render . send(nom, body?) Envoie une commande et laisse filer. Renvoie void ; l'issue revient par les sélecteurs, ou par nom:done / nom:failed . on(nom, écouteur) Écoute un événement du store, ou l'issue d'une commande. Dans un .super , il s'écrit sur une méthode, @on('counter', 'increment:done') , qui est appelée tant que le composant est monté : pas de signal à passer (voir Écouter l'issue ). Dans un .ts , il se déclare dans le constructeur ; il est interdit pendant render . href(route, { params, query }?) Pour le router seulement : construit un lien typé, sans abonner le composant (voir plus bas ). Le composant ne reçoit pas le store lui-même : pas d'état brut, pas de subscribe , pas de dispose , pas d' emit . Ces capacités restent à celui qui a créé le store."},{"url":"lire-un-store.html#quand-le-composant-se-re-rend","page":"Lire un store","title":"Quand le composant se re-rend","text":"À chaque changement d'état du store, Super recalcule les @selector lus au dernier rendu et compare chaque valeur avec celle affichée. Si rien n'a changé, le composant ne se re-rend pas. Exemple : l'écran de « Cafés » lit count('cafes') . Incrémenter « Pompes » change l'état du store, mais pas la valeur lue par l'écran : il ne se re-rend pas."},{"url":"lire-un-store.html#ce-qui-compte-comme-un-changement","page":"Lire un store","title":"Ce qui compte comme un changement","text":"La valeur lue est comparée en profondeur à la précédente. Peu importe qu'un sélecteur la reconstruise : seul son contenu compte, et Super garde l'ancienne référence tant qu'il est égal (partage structurel). Les tableaux et objets simples sont comparés élément par élément ; une Date , une Map ou une instance de classe, par référence. Lecture Re-rendu quand… @selector count = () => this.counter.selectors.count(this.counterId) le nombre change. @selector busy = () => this.counter.selectors.pending() une commande commence ou se termine. @selector lines = this.cart.selectors.lines une ligne change. Les lignes inchangées gardent leur référence. @selector catalog = this.counter.selectors.catalog jamais, si le catalogue ne change pas. La valeur de .value est la même référence tant que son contenu ne change pas : la passer en props à un enfant ne le re-rend pas inutilement. Un enfant ne se re-rend que si l'une de ses props change. Pour une liste : un composant par ligne Sur la liste des compteurs, chaque ligne est un petit composant ( CounterListItem , plus haut) qui lit sa propre valeur. Quand un compteur change, seule sa ligne se re-rend : la liste ne bouge pas, et le DOM des autres lignes n'est pas recalculé."},{"url":"lire-un-store.html#lire-les-props-dans-la-lecture","page":"Lire un store","title":"Lire les props dans la lecture","text":"La fonction d'un @selector peut lire les props ( this.counterId ). Elle est recalculée à chaque rendu, donc à chaque changement de props : si l'écran passe de « Cafés » à « Pompes », la lecture suit, sans mise à jour manquée. C'est aussi pour ça qu'un sélecteur à paramètre s'écrit dans une fonction : les props sont lisibles quand la déclaration s'initialise, mais une valeur lue à ce moment-là resterait celle de la création."},{"url":"lire-un-store.html#sans-fonction-de-lecture","page":"Lire un store","title":"Lire un sélecteur directement dans render","text":"Un sélecteur appelé directement dans render ( {this.counter.selectors.count('cafes')} ) abonne aussi le composant, aussi finement qu'un @selector : Super retient chaque lecture et sa valeur, et à chaque changement du store, il refait ces lectures. Le composant ne se re-rend que si l'une d'elles donne une autre valeur (comparée en profondeur : un tableau neuf au même contenu ne compte pas). La lecture est retenue chez le composant qui rend , même si la vue du contrat vient d'un autre : un enfant qui reçoit en prop la vue de son parent et la lit dans son propre render s'abonne lui-même, et se re-rend seul. C'est ce que fait le CommandButton du kit, qui lit pending sur le contrat de l'écran qui l'a préparé. @selector reste utile pour lire une valeur hors de render par .value , pour la nommer une fois et la réutiliser, et pour isValid() sur une valeur de route. Seul ce qui est lu compte : ce que render affiche sans passer par un sélecteur (une variable de module, Date.now() ) ne déclenche aucun rendu."},{"url":"lire-un-store.html#n-afficher-rien-d-un-store","page":"Lire un store","title":"N'afficher rien d'un store","text":"Un composant qui envoie des commandes ou écoute des événements, mais n'affiche rien du store, déclare le contrat sans @selector : il ne se re-rend jamais pour ce store. @contract counter; protected override mounted() { this.counter.send('load'); }"},{"url":"lire-un-store.html#le-router","page":"Lire un store","title":"Le router","text":"Le router se lit par this.router , sans le déclarer : une vue toujours disponible. La route active se lit par this.router.current : name() (le nom de la route active), path() , params.<clé>() , query.<clé>() . Chacune se passe telle quelle à @selector , comme un sélecteur sans paramètre. @selector route = this.router.current.name; // 'examples' | 'counters' | 'counter' | … | null this.router.href('counter', { params: { id: 'cafes' } }) construit un lien, avec la route et ses paramètres vérifiés. Il ne lit pas la route active : un composant qui ne fait qu'afficher des liens ne se re-rend pas à chaque navigation. Voir Router ."},{"url":"lire-un-store.html#l-etat-brut-reste-cache","page":"Lire un store","title":"L'état brut reste caché","text":"Un composant ne lit l'état d'un store que par les sélecteurs de son contrat : // @ts-expect-error `counts` n'est pas un sélecteur du contrat this.counter.selectors.counts; // @ts-expect-error la vue d'un contrat n'a pas d'état this.counter.state(); Ce n'est pas qu'une question de types : à l'exécution, la vue ne passe que les sélecteurs, jamais l'objet d'état. Les seuls moyens de contourner sont volontaires : un sélecteur qui renverrait tout l'état, un store exporté depuis un module user-land, ou un as any ."},{"url":"lire-un-store.html#plusieurs-stores","page":"Lire un store","title":"Plusieurs stores, ou plusieurs lectures","text":"Déclare autant de @contract et de @selector que nécessaire. Chaque @selector est comparé seul : le composant se re-rend si l'un d'eux change. @contract cart; @selector catalog = this.cart.selectors.catalog; @selector lines = this.cart.selectors.lines; @selector total = this.cart.selectors.total; @selector isEmpty = this.cart.selectors.isEmpty;"},{"url":"lire-un-store.html#store-non-fourni","page":"Lire un store","title":"Quand le store n'est pas fourni","text":"Super résout les contrats au montage. Si aucune application (ou aucun test) n'a fourni de store pour ce contrat, le composant ne s'affiche pas (son renderError , s'il en a un, prend la place) et l'erreur est signalée (phase setup , voir Gérer les erreurs ) : [super] <counter-screen> : aucun store fourni pour le contrat \"counter\". Ajoute-le à createApp({ stores }) ou à mount(..., { stores })."},{"url":"outillage.html","page":"Outillage des .super","title":"Outillage des .super","text":"Un fichier .super n'est pas du TypeScript que tsc ou ton éditeur savent lire seuls. Trois outils s'en chargent : la vérification en ligne de commande, le plugin Vite qui le compile, et un serveur de langage pour l'éditeur. Tous partent du même principe : un TS virtuel ."},{"url":"outillage.html#ts-virtuel","page":"Outillage des .super","title":"Le principe : un TS virtuel","text":"Chaque .super est traduit en un TypeScript équivalent pour le compilateur : le code du fichier est recopié tel quel, chaque élément devient une suite d'appels typés, et une table de correspondance relie chaque position du TS virtuel à sa position dans le .super . Le compilateur vérifie ce TS virtuel, et les erreurs sont rapportées à la bonne ligne et à la bonne colonne du .super . Les instructions sont recopiées telles quelles ( if , for , switch , déclarations) : le rétrécissement de types de TypeScript s'applique au template. Un composant enfant devient l'appel de sa méthode create , dont le typage vérifie déjà props et événements. Le TS virtuel est aussi écrit sur disque , dans .super/virtual/ à côté du tsconfig (ignoré par git), avec, dans .super/types/ , une déclaration ( .d.ts ) des exports du fichier et sa source map vers le .super . Les tsconfig déclarent ces dossiers ( rootDirs , paths ) : un .ts qui importe un composant .super , comme routes.ts , en voit les types par la déclaration. Le serveur TypeScript de l'éditeur suit sa source map : « aller à la définition » ouvre le .super , dans n'importe quel éditeur."},{"url":"outillage.html#verifier-les-types","page":"Outillage des .super","title":"Vérifier les types : super-tsc","text":"npm run typecheck # ou, pour un projet précis : node packages/lang/src/cli.ts examples/demo/tsconfig.json super-tsc écrit le TS virtuel de chaque .super couvert par le tsconfig (son include et son exclude ), lance le tsc du projet (TypeScript 7), puis rapporte chaque erreur dans le .super . Les erreurs de syntaxe des .super (un texte ambigu, une balise non fermée) sont rapportées aussi. Les .ts du projet sont vérifiés dans la même passe. src/@components/shop/index.super(29,48): error TS2339: Property 'prix' does not exist on type 'Product'. src/@components/shop/index.super(42,10): error SUPER: Texte lu comme `for`, qui n’est pas valide (…). Si c’est du texte, entoure-le d’accolades : {'for (more info) see below'} Ce qui est vérifié est détaillé dans Ce que le compilateur vérifie ."},{"url":"outillage.html#vite","page":"Outillage des .super","title":"Compiler : le plugin Vite","text":"superPlugin compile chaque .super en code lit-html, en dev comme au build et dans les tests (Vitest passe par les mêmes plugins). Un import sans extension trouve un .super : @components/shop donne shop/index.super . Les règles d'architecture du plugin s'appliquent au code compilé, et le remplacement à chaud fonctionne comme pour un composant .ts . Une erreur de syntaxe d'un .super arrête le chargement du module, avec sa position : overlay en dev, échec du build ou du test. En dev , le plugin réécrit aussi le TS virtuel sur disque à chaque modification."},{"url":"outillage.html#source-maps","page":"Outillage des .super","title":"Source maps","text":"Le code compilé garde les numéros de ligne du .super , et le plugin fournit une source map jusqu'à la colonne : une trace d'erreur dans le navigateur ou un point d'arrêt du débogueur pointent la source."},{"url":"outillage.html#editeur","page":"Outillage des .super","title":"Dans l'éditeur : le serveur de langage","text":"packages/lang-server est un serveur de langage (LSP) construit sur Volar. Il sert les .super , et seulement eux. Les erreurs de TypeScript et de syntaxe, pendant la frappe, avec la correction rapide « Entourer d'accolades » pour un texte ambigu. La réécriture des anciennes formes : une ligne écrite avec une méthode ( cart = this.contract('cart'); , lines = this.selector(this.cart.selectors.lines); , local = this.state({ … }); , input = this.ref<HTMLInputElement>(); ) est une erreur dans un .super , avec la correction rapide « Écrire @contract » (ou @selector , @state …) qui la remplace par @contract cart; . Un écouteur posé dans le constructeur n'a pas de correction automatique : il devient à la main une méthode @on('cart', 'événement') . La complétion dans les expressions, y compris pendant la frappe ( if (this. , une clé de boucle, une déclaration pas encore terminée). La complétion dans les balises : après < , les composants (ceux du projet pas encore importés ajoutent leur import) et les balises HTML ; après </ , la balise à fermer ; dans une balise, ses attributs, ref et ses événements, ou les props (obligatoires d'abord) et les événements d'un composant. La complétion des déclarations : après @ dans le corps d'un composant (hors de ses méthodes), tag , title , prop , emit , puis contract , selector , state , ref , form et on , avec un gabarit ( @tag = 'mon-composant'; , @prop nom: string; , @contract nom; …). @t propose tag et title , @em propose emit ; un @tag ou un @title déjà écrit n'est plus proposé. Après @contract , les contrats de l'app que le composant ne déclare pas encore sont proposés ( @contract cart; , ou errorLog = 'error-log'; pour un nom qui n'est pas un identifiant) ; dans @contract x = '…' , les noms de contrats aussi ; dans @on('…', '…') , les contrats puis les événements du contrat choisi ( router s'écrit à la main). Le survol et l'aller à la définition ; le survol de @tag , @title , @prop , @emit et des déclarations de préparation ( @contract , @on …) affiche leur documentation (forme, valeurs permises, exemple). Le formatage du fichier (voir Formater ). Le TS virtuel écrit sur disque à chaque frappe : un .ts ouvert à côté voit tout de suite une nouvelle prop. TypeScript 6 dans l'éditeur, TypeScript 7 en ligne de commande Volar ne sait pas encore piloter TypeScript 7. Le serveur de langage a donc son propre paquet ( packages/lang-server , avec ses dépendances) et tourne sur TypeScript 6, tandis que super-tsc utilise le TypeScript 7 du projet. Les deux donnent les mêmes erreurs sur ce que fait la démo."},{"url":"outillage.html#formater","page":"Outillage des .super","title":"Formater","text":"npm run format # Biome pour les .ts, le formateur des .super pour les .super npm run lint # vérifie les deux (lancé aussi par npm run check) Le TS d'un .super est formaté par Biome, avec la configuration du dépôt : chaque élément de premier niveau y est remplacé par une instruction de substitution, que Biome place et indente comme les autres. Le formateur des .super imprime ensuite les templates à ces emplacements : Une balise sur une ligne si elle tient dans la largeur (140 colonnes), sinon un attribut par ligne et les enfants indentés. Un composant qui reçoit des enfants, et un emplacement <:nom> , toujours sur plusieurs lignes, même s'ils tiennent : ce qui va dans quel emplacement se lit d'un coup d'œil. Du texte suivi remplit les lignes, avec ses éléments en ligne ( <code> , <strong> ) ; une liste d'éléments sans texte garde un élément par ligne. Les instructions ( if , for , switch , déclarations) et leurs blocs sont indentés, les lignes vides entre enfants sont gardées (une au plus). Les déclarations d'un composant ( @tag = …; , @title = …; , @prop , @emit ) sont gardées et indentées comme les autres membres de la classe, bien que @tag et @title ne soient pas du TS valide. Le rendu ne change jamais : une ligne n'est coupée que là où il y a déjà un blanc, ou au bord d'un élément, d'un bloc ou d'une instruction, où les blancs ne rendent rien (voir les espaces ). Les tests le vérifient sur chaque .super du dépôt. Un fichier qui a des erreurs de syntaxe n'est pas formaté. Dans l'éditeur, le serveur de langage formate le fichier (formatage à l'enregistrement dans Zed, voir ci-dessous)."},{"url":"outillage.html#zed","page":"Outillage des .super","title":"Zed","text":"L'extension de editors/zed déclare le langage « Super » pour les fichiers .super et lance le serveur : celui du paquet super-language-server s'il est installé dans le projet, sinon packages/lang-server , avec le Node du PATH. Comme les .super ont leur propre langage, vtsls, le serveur TypeScript habituel de Zed, ne les voit pas. Installer : Rust par rustup, puis zed: install dev extension sur le dossier editors/zed (voir son README). La compilation se suit dans zed: open log . Coloration : la grammaire Tree-sitter des .super ( editors/tree-sitter-super ), celle de TSX étendue aux instructions écrites entre les balises : if , for … ; key , switch et les déclarations y sont colorés comme du code, pas comme du texte. Elle connaît aussi @tag = …; et @title = …; dans le corps d'une classe (règle super_declaration ), que TSX refuserait. Commentaires : entre des balises, cmd+/ écrit {/* … */} . Formatage : par le serveur, à l'enregistrement ; jamais par Prettier. Aller à la définition depuis un .ts : vtsls suit la source map de la déclaration du composant et ouvre le .super (voir le principe ). Après une mise à jour du serveur, relance-le depuis un .super ouvert : editor: restart language server . Après une modification de l'extension elle-même : Rebuild dans le panneau des extensions. Après une mise à jour de la grammaire (comme l'ajout de @tag et @title ), réinstalle l'extension : zed: install dev extension sur editors/zed . Les limites de ce montage sont listées dans Limites ."},{"url":"outillage.html#les-paquets","page":"Outillage des .super","title":"Les paquets","text":"Paquet Contenu packages/lang Parser, TS virtuel, compilateur, source maps, formateur, super-tsc , et la spécification ( SPEC.md ). packages/lang-server Serveur de langage. packages/vite Le plugin qui compile les .super ."},{"url":"parents-enfants.html","page":"Parents et enfants","title":"Parents et enfants","text":"Props vers le bas, événements vers le haut. Un parent ne pilote jamais un enfant en appelant ses méthodes : il lui passe des props, et l'enfant répond par des événements."},{"url":"parents-enfants.html#utiliser-un-sous-composant","page":"Parents et enfants","title":"Utiliser un sous-composant","text":"Dans un template, un enfant se place en balise, au nom de sa classe : une balise qui commence par une majuscule est un composant, importé comme n'importe quelle classe ( import { CounterControls } from './counter-controls' ). <CounterControls count={count} canDecrement={this.canDecrement.value && !busy} canIncrement={!busy} on:increment={() => this.run('increment')} on:decrement={() => this.run('decrement')} /> Les attributs sont les props. Le compilateur les vérifie contre les @prop de l'enfant : une prop requise manquante, une prop en trop ou une valeur mal typée est une erreur. Une valeur fixe s'écrit entre guillemets ( question=\"Vider le panier ?\" , une chaîne), une valeur calculée entre accolades. on:nom branche un événement de l'enfant sur une fonction du parent. Le nom et le payload sont vérifiés contre les @emit de l'enfant. La balise est l'équivalent de CounterControls.create({ count, … }, { on: { increment, … } }) , l'appel qui sert hors template (voir Créer un élément hors template ). L'élément enfant est créé une fois par emplacement, puis ses props sont mises à jour à chaque rendu du parent. Il garde son état local. S'il reçoit des props égales (comparées clé par clé), il ne se re-rend pas. Un composant peut aussi recevoir des éléments entre ses balises, s'il les déclare (voir Composer : des enfants )."},{"url":"parents-enfants.html#declarer-les-props","page":"Parents et enfants","title":"Déclarer les props","text":"Une prop se déclare dans le corps de la classe par @prop , avec son type, et se lit par this.nom . Le tag, les props et les événements s'écrivent au même endroit, sans générique (le détail de chaque déclaration est dans Composants : les déclarations ) : export class CounterListItem extends SuperElement { @tag = 'counter-list-item'; @prop counterId: string; @prop label: string; render() { <a href={this.router.href('counter', { params: { id: this.counterId } })}>{this.label}</a> // … } } Une prop prend l'une de ces trois formes : @prop question: string; // obligatoire @prop note?: string; // facultative : string | undefined @prop tone: 'neutral' | 'danger' = 'neutral'; // facultative, avec une valeur par défaut Une prop obligatoire manquante dans la balise du parent est une erreur de compilation. Une prop facultative ( ? ) vaut undefined quand le parent ne la passe pas. ? et une valeur par défaut ne vont pas ensemble : c'est une erreur. La valeur par défaut rend la prop facultative ; elle est calculée une fois par instance (un [] par défaut n'est pas partagé entre deux éléments). Un composant dont toutes les props sont facultatives se place sans attribut ( <RouterOutlet /> ). this.counterId est en lecture seule, et toujours à jour : un changement de prop re-rend l'enfant. this.props existe toujours (toutes les props, en lecture seule), mais on écrit this.nom . Les props sont lisibles dès la construction (pour initialiser un @state , par exemple). Une copie faite à ce moment-là ne suit pas les changements suivants : lis this.nom dans render ou dans la fonction d'un @selector pour une valeur toujours à jour."},{"url":"parents-enfants.html#noms-de-props-refuses","page":"Parents et enfants","title":"Les noms déjà pris par les éléments HTML","text":"Un composant est un élément HTML : this.id , this.title , this.hidden ou this.slot existent déjà. Une prop ne peut donc pas porter l'un de ces noms, et le compilateur le dit : @prop title: string; // ✗ « title » est déjà une propriété des éléments HTML : choisis un autre nom Dans l'app d'exemples, title est devenu heading ( Card , KitPage ) et id est devenu counterId ( CounterListItem ). Un paramètre de route id se lit de même dans un champ nommé autrement : counterId = this.router.current.params.id; . Le nom page est lui aussi réservé (c'est this.page ). Le contenu écrit entre les balises remplit pour la même raison une prop content ( children est natif), voir Composer : des enfants ."},{"url":"parents-enfants.html#emit-et-on","page":"Parents et enfants","title":"emit chez l'enfant, on chez le parent","text":"Les deux côtés emploient chacun leur vocabulaire. on: est le préfixe qui sert, côté parent, à écouter ; l'enfant ne le voit jamais. Côté enfant ( CounterControls ) Côté parent ( CounterScreen ) Déclarer @emit increment: void; et @emit decrement: void; , dans le corps de la classe rien Agir this.emit('increment') : « j'annonce qu'on a cliqué » on:increment={…} : « quand tu annonces ça, je fais ceci » L'enfant parle, le parent écoute. L'enfant ne sait pas qui l'écoute, ni même si quelqu'un l'écoute. C'est le même principe qu'un <button> HTML : il émet click , et c'est la page qui écrit on:click={…} , avec le même préfixe. Ailleurs, c'est $emit / @increment en Vue, dispatch / on:increment en Svelte."},{"url":"parents-enfants.html#declarer-les-evenements","page":"Parents et enfants","title":"Déclarer les événements d'un composant","text":"export class ItemPicker extends SuperElement { @tag = 'item-picker'; @emit picked: { id: string }; @emit closed: void; render() { <button on:click={() => this.emit('picked', { id: 'a' })}>Choisir A</button> <button on:click={() => this.emit('closed')}>Fermer</button> } } @emit nom: T; déclare un événement et le type de ce qu'il transporte ( void s'il ne transporte rien). Il n'a pas de valeur : @emit closed: void = … est une erreur. Un événement void s'émet sans argument. Le compilateur refuse un nom inconnu, un payload mal typé, ou un payload oublié."},{"url":"parents-enfants.html#le-trajet-complet","page":"Parents et enfants","title":"Le trajet complet d'un clic sur « + »","text":"CounterControls émet increment . CounterScreen reçoit l'événement et appelle this.run('increment') . run envoie this.counter.send('increment', { id: 'cafes' }) au store. Le store sauvegarde et met à jour son état ; Super publie increment:done . L'écran se re-rend ; la nouvelle valeur redescend dans CounterControls par la prop count . CounterControls ne connaît ni le store, ni l' id , ni la commande : il reste réutilisable. C'est l'écran qui décide de ce que signifie « incrémenter »."},{"url":"parents-enfants.html#un-dialogue","page":"Parents et enfants","title":"Un dialogue : le parent le rend, il répond par un événement","text":"Dans l' exemple Boutique : shared/confirm-dialog.super , shop/index.super . « Vider le panier ? » est rendu par le parent et répond par un événement. Même un dialogue de confirmation suit cette règle. Le parent l'ouvre en le rendant, avec sa question en prop ; le dialogue émet la réponse. Monté, il est ouvert : pas de prop nullable qui voudrait dire « fermé ». Personne n'attend rien, il n'y a pas d' await . export class ConfirmDialog extends SuperElement { @tag = 'confirm-dialog'; @prop question: string; @emit answered: { confirmed: boolean }; render() { <div class=\"backdrop\"> <div role=\"dialog\" aria-modal=\"true\" aria-label=\"Confirmation\"> <p>{this.question}</p> <div class=\"actions\"> <button type=\"button\" on:click={() => this.emit('answered', { confirmed: false })}>Annuler</button> <button type=\"button\" class=\"danger\" on:click={() => this.emit('answered', { confirmed: true })}>Confirmer</button> </div> </div> </div> } } @contract cart; // Le dialogue ouvert (aucun : null), et un message ponctuel. @state local = { dialog: null as 'confirm-clear' | null, message: null as string | null }; // Le dialogue répond par un événement : le parent décide de la suite. onClearAnswered = ({ confirmed }: { confirmed: boolean }) => { this.local.set({ dialog: null }); // ferme le dialogue if (confirmed) this.cart.send('clear'); }; render() { <main class=\"screen\"> {/* … */} <button type=\"button\" on:click={() => this.local.set({ dialog: 'confirm-clear' })}>Vider le panier</button> {/* … */} if (this.local.get().dialog === 'confirm-clear') { <ConfirmDialog question=\"Vider le panier ?\" on:answered={this.onClearAnswered} /> } </main> } Clic sur « Vider le panier » : le parent met dialog: 'confirm-clear' dans son état local. Le parent se re-rend ; la condition est vraie, le dialogue est monté avec sa question et s'affiche. Clic sur « Confirmer » : le dialogue émet answered { confirmed: true } . onClearAnswered remet dialog à null (le dialogue est démonté) et envoie la commande. Ouvrir et fermer un dialogue, c'est changer une valeur dans l'état du parent. Avec plusieurs dialogues, garde un seul champ ( dialog: 'confirm-clear' | 'confirm-delete' | null ) et une condition par dialogue : chacun a sa question et son handler, et deux modales ne peuvent pas être ouvertes en même temps. Le même motif vaut pour un drawer ou un menu."},{"url":"parents-enfants.html#handlers-en-champ-fleche","page":"Parents et enfants","title":"Un handler passé à un enfant : un champ fléché","text":"onClearAnswered est un champ qui contient une fonction fléchée, pas une méthode. Une fonction fléchée garde le this du composant ; une méthode passée telle quelle ( on:answered={this.onAnswered} avec onAnswered() { … } ) le perdrait, et this.local serait undefined au moment de l'appel. Même règle pour une action passée à on:click sans fonction autour. onAnswered = ({ confirmed }: { confirmed: boolean }) => { … }; // ✓ this lié onAnswered({ confirmed }: { confirmed: boolean }) { … } // ✗ this perdu une fois passé à on:answered"},{"url":"parents-enfants.html#les-listes","page":"Parents et enfants","title":"Les listes","text":"Pour une liste d'enfants, utilise une boucle for avec une clé, écrite après key : un élément déplacé garde son DOM et son état local. Sans clé, le rendu suit la position (voir Listes ). <ul class=\"counter-list\"> for (const c of shown; key c.id) { <li><CounterListItem counterId={c.id} label={c.label} /></li> } </ul>"},{"url":"parents-enfants.html#composer","page":"Parents et enfants","title":"Composer : des enfants","text":"Une carte, une modale, des onglets : des composants de mise en page, dont le contenu vient du parent. Le composant déclare ce qu'il accepte par des props de type Children , et le place où il veut : import { type Children, SuperElement } from '@super-ts/dom'; /** Une carte : un titre, un contenu, et des actions facultatives. */ export class Card extends SuperElement { @tag = 'composition-card'; @prop heading: string; @prop content: Children; @prop actions?: Children; render() {"},{"url":"parents-enfants.html#this-heading","page":"Parents et enfants","title":"{this.heading}","text":"{this.content} if (this.actions) { {this.actions} } } } content reçoit le contenu écrit entre les balises. C'est une prop comme les autres : @prop content: Children; , lue par this.content . Elle ne s'appelle pas children parce que this.children est la propriété native des éléments HTML (la liste de leurs éléments enfants). Un emplacement nommé est une autre prop de type Children , ici actions , lue par this.actions . Facultatif, il s'écrit avec ? ( @prop footer?: Children; ) ; un composant en déclare autant qu'il veut. Le parent remplit content par les éléments écrits entre les balises, et actions par un emplacement nommé, ou par une méthode : // Un emplacement, écrit là où la carte est utilisée. <Card heading={this.label.value}> <p>Valeur : {this.count.value}</p> <:actions> <button on:click={() => this.run('reset')}>Remettre à zéro</button> </:actions> </Card> // Ou une méthode, pratique dans une boucle (la variable passe en paramètre). #actions(c: Counter) { <button on:click={() => this.rename(c.id)}>Renommer</button> } // … for (const c of this.counters.value; key c.id) { <Card heading={c.label} actions={this.#actions(c)}> <p>{c.count}</p> </Card> } Les enfants appartiennent au parent : le clic sur « Remettre à zéro » appelle une méthode du parent, et this.count est lu par le parent. Les enfants suivent son rendu ; la carte les garde quand elle se re-rend seule. Le compilateur vérifie le contrat : des enfants pour un composant qui ne déclare pas content , des enfants obligatoires qui manquent, un emplacement qui n'est pas une prop du composant sont des erreurs. La syntaxe complète est dans Templates : des enfants et des emplacements nommés . L'exemple Composition de l'app d'exemples montre les deux façons côte à côte."},{"url":"parents-enfants.html#ce-qui-n-existe-pas","page":"Parents et enfants","title":"Ce qui n'existe pas, volontairement","text":"Pas de référence vers un enfant pour appeler ses méthodes : un enfant n'expose pas d'API. Dans un template, <CounterControls … /> monte l'enfant, il ne donne pas une instance à garder. Pas de callback en prop pour remonter une information : rien ne l'empêche techniquement, mais on utilise un événement, déclaré par @emit et typé. L'enfant reste découplé, et le test peut écouter l'événement avec mount(…, { on }) . Pas d'accès d'un enfant aux stores de son parent par les props : un enfant qui a besoin d'un store déclare lui-même @contract nom; . Pas de tag écrit à la main : <counter-controls> en HTML brut n'est pas supporté. Un enfant passe toujours par sa classe, <CounterControls … /> (ou create hors template)."},{"url":"ports-adapters.html","page":"Ports et adapters","title":"Ports et adapters","text":"Les sources de données externes (localStorage, API HTTP, IndexedDB) ne sont pas un concept Super : ce sont de simples dépendances de tes stores. L' app d'exemples les organise en ports et adapters, un choix de projet : un localStorage pour les compteurs, un serveur simulé pour le formulaire, une vraie API HTTP (dummyjson.com) pour la table branchée du kit."},{"url":"ports-adapters.html#le-principe","page":"Ports et adapters","title":"Le principe","text":"Un port est une interface : ce dont le store a besoin, exprimé dans ses termes (« charger tous les compteurs », « enregistrer un compteur »). Un adapter est une implémentation de ce port pour une technologie donnée. Le store dépend du port, jamais d'un adapter. La racine de composition choisit l'adapter. Résultat : on change de stockage sans toucher au store, et on teste le store avec un adapter en mémoire."},{"url":"ports-adapters.html#le-port","page":"Ports et adapters","title":"Le port","text":"export interface CounterRepository { loadAll(): Promise<Record<string, number>>; save(id: string, count: number): Promise<void>; }"},{"url":"ports-adapters.html#les-adapters","page":"Ports et adapters","title":"Les adapters","text":"export function createLocalStorageCounterRepository({ storage = window.localStorage, key = 'super.counters', }: Options = {}): CounterRepository { function read(): Record<string, number> { const raw = storage.getItem(key); if (raw === null) return {}; // … parse et valide le JSON, lève une erreur s'il est invalide } return { async loadAll() { return read(); }, async save(id, count) { storage.setItem(key, JSON.stringify({ ...read(), [id]: count })); }, }; } export function createInMemoryCounterRepository( initial: Record<string, number> = {}, ): CounterRepository & { stored: Record<string, number> } { return { stored: { ...initial }, async loadAll() { return { ...this.stored }; }, async save(id, count) { this.stored = { ...this.stored, [id]: count }; }, }; } L'adapter en mémoire expose stored , pratique pour vérifier ce qui a été enregistré dans un test. Un adapter HTTP a la même forme, avec des fetch . Celui du catalogue de produits traduit la page ou la recherche demandée par le store dans les paramètres de l'API publique de test dummyjson.com, et sa réponse dans les types du domaine : export interface ProductCatalog { list(query: ProductQuery): Promise<ProductPage>; /** Les produits dont le nom ou la description contient `text`, au plus `limit`. */ search(text: string, limit: number): Promise<Product[]>; } export function createDummyJsonProductCatalog(fetchImpl: typeof fetch = fetch): ProductCatalog { const get = async (url: string): Promise<Raw> => { const response = await fetchImpl(url); if (!response.ok) throw new Error(`dummyjson : ${response.status}`); return (await response.json()) as Raw; }; return { async list({ page, pageSize, sort, order }: ProductQuery): Promise<ProductPage> { const params = new URLSearchParams({ limit: String(pageSize), skip: String((page - 1) * pageSize), select: SELECT, ...(sort ? { sortBy: sort, order } : {}), }); const raw = await get(`${API}?${params}`); return { products: toProducts(raw), total: raw.total }; }, async search(text, limit) { const params = new URLSearchParams({ q: text, limit: String(limit), select: SELECT }); return toProducts(await get(`${API}/search?${params}`)); }, }; } fetch est lui-même un paramètre : le test de l'adapter lui en donne un faux, et vérifie l'URL construite sans réseau. Les tests du store et de l'écran prennent l'autre adapter du port, createInMemoryProductCatalog , qui trie, pagine et cherche en mémoire comme le ferait le serveur."},{"url":"ports-adapters.html#les-brancher","page":"Ports et adapters","title":"Les brancher","text":"// Le store déclare sa dépendance par les paramètres de son constructeur. type Deps = { counterRepository: CounterRepository }; export class CounterStore extends SuperStore<CounterContract> implements Commands<CounterStore> { #repository: CounterRepository; constructor({ counterRepository }: Deps) { super({ contract: 'counter', initialState: { counts: {}, loadErrorMessage: null } }); this.#repository = counterRepository; } // … } // main.ts choisit l'adapter. CounterStore.create({ counterRepository: createLocalStorageCounterRepository() }); // Un test en choisit un autre. CounterStore.create({ counterRepository: createInMemoryCounterRepository({ cafes: 1 }) });"},{"url":"ports-adapters.html#ou-les-ranger","page":"Ports et adapters","title":"Où les ranger","text":"ports/ et adapters/ sont des dossiers user-land : Super ne les connaît pas. Tu peux les appeler autrement, ou mettre le port à côté du store, dans son dossier de @core/ . Une règle de bon sens : un composant n'importe jamais un adapter. Le plugin ne l'interdit pas (les adapters sont en user-land), mais un composant qui appellerait un adapter contournerait le store, et perdrait l'état partagé et les événements."},{"url":"ports-adapters.html#erreurs-des-adapters","page":"Ports et adapters","title":"Les erreurs des adapters","text":"Un adapter peut échouer (quota dépassé, réseau coupé). C'est au store de décider comment le publier : loadErrorMessage dans l'état pour un chargement (l'erreur doit rester visible), une raison d'échec pour une écriture. Voir Stores : les erreurs . await this.#repository.save(id, next).catch(() => this.fail('storage')); // increment:failed, raison 'storage'"},{"url":"router.html","page":"Router","title":"Router","text":"Le router est intégré à @super-ts/dom . Les routes sont nommées et typées : un lien sans son paramètre, une valeur du mauvais type ou une description de query fausse ne compilent pas. Et le router est un store comme un autre."},{"url":"router.html#declarer-les-routes","page":"Router","title":"Déclarer les routes","text":"Tout se déclare dans un fichier user-land, src/routes.ts , qui n'exporte qu'une chose : Router . import { defineRouter, query, redirect } from '@super-ts/dom'; import { CheckoutScreen } from '@components/checkout'; import { CompositionScreen } from '@components/composition'; import { CounterScreen } from '@components/counter'; import { CounterListScreen } from '@components/counter-list'; import { ErrorScreen } from '@components/error'; import { ErrorsScreen } from '@components/errors'; import { ExamplesScreen } from '@components/examples'; import { KitScreen } from '@components/kit'; import { KitDisplayScreen } from '@components/kit/display'; import { KitFormsScreen } from '@components/kit/forms'; import { KitPrimitivesScreen } from '@components/kit/primitives'; import { KitTableScreen } from '@components/kit/table'; import { KitThemeScreen } from '@components/kit/theme'; import { KitWindowsScreen } from '@components/kit/windows'; import { NotFoundScreen } from '@components/not-found'; import { ProfileScreen } from '@components/profile'; import { ShopScreen } from '@components/shop'; import { WidgetScreen } from '@components/widget'; import { PRODUCT_SORTS, type ProductSort } from './domain/catalog'; // La query de la liste des compteurs : son type, puis sa description pour lire l'URL. Une valeur // inconnue (`?sort=nimporte`) est remplacée par la valeur par défaut. type CountersQuery = { sort: 'original' | 'label' }; // Le tri et la page de la table branchée du kit : ils vivent dans l'URL. type KitTableQuery = { sort?: ProductSort; order: 'asc' | 'desc'; page: number; size: 5 | 10 | 20 | 50 }; // Le router de l'app : typé par ces routes (`this.router` dans un composant) et source des liens hors composants (`Router.href`). // `Router.href('counter')` sans `id`, ou `navigate({ to: 'compteur' })`, ne compilent pas. // Chaque écran lit sa route par `this.router.current`, typé par sa route (`/counters/:id` -> `params.id`). // `'*'` est l'écran affiché quand aucun chemin ne correspond, `'!'` celui d'un écran qui plante. export const Router = defineRouter({ examples: '/', // `?sort=label` trie la liste : changer de tri ne remonte pas l'écran. counters: { path: '/counters', query: query<CountersQuery>({ sort: { oneOf: ['original', 'label'], default: 'original' } }), }, counter: '/counters/:id', profile: '/profile', form: '/form', shop: '/shop', checkout: '/shop/checkout', errors: '/errors', widget: '/widget', composition: '/composition', kit: '/kit', 'kit-forms': '/kit/forms', 'kit-windows': '/kit/windows', 'kit-primitives': '/kit/primitives', 'kit-display': '/kit/display', 'kit-table': { path: '/kit/table', query: query<KitTableQuery>({ sort: { oneOf: PRODUCT_SORTS }, order: { oneOf: ['asc', 'desc'], default: 'asc' }, page: { type: Number, default: 1 }, size: { oneOf: [5, 10, 20, 50], default: 10 }, }), }, 'kit-theme': '/kit/theme', }) // Un guard lit les stores par leur contrat : on ne commande pas un panier vide. // Les guards viennent avant .screens(), qui doit rester le dernier appel. .guards(({ read }) => ({ checkout: () => !read('cart').isEmpty() || { to: 'shop' }, })) .screens(() => ({ examples: ExamplesScreen, counters: CounterListScreen, counter: CounterScreen, profile: ProfileScreen, form: redirect({ to: 'profile' }), // un raccourci : /form mène au formulaire shop: ShopScreen, checkout: CheckoutScreen, errors: ErrorsScreen, widget: WidgetScreen, composition: CompositionScreen, kit: KitScreen, 'kit-forms': KitFormsScreen, 'kit-windows': KitWindowsScreen, 'kit-primitives': KitPrimitivesScreen, 'kit-display': KitDisplayScreen, 'kit-table': KitTableScreen, 'kit-theme': KitThemeScreen, '*': NotFoundScreen, '!': ErrorScreen, })); L'objet Router a deux usages. Le plugin Vite le repère ( export const Router = defineRouter(…) ) et inscrit le router sous le nom 'router' dans le dictionnaire des contrats qu'il génère ( src/@core/contracts.d.ts ) : un composant le lit et le pilote par this.router , typé par les routes de l'app, sans importer routes.ts . Le plugin y relie aussi chaque écran à sa route (voir L'écran et sa route ). Et Router.href construit un lien dans le code qui n'est pas un composant (un test, un module user-land). Il n'y a rien d'autre à exporter, ni de déclaration à écrire à la main : un seul router est typé par app."},{"url":"router.html#definerouter","page":"Router","title":"defineRouter","text":"Une route se déclare de deux façons : Une chaîne , quand les valeurs sont du texte. Un segment :nom est un paramètre : '/counters/:id' donne { id: string } . Après ? , les clés de query lues par la route, [] marquant une liste : '/counters?sort&tag[]' donne { sort?: string; tag: string[] } . Voir Query . Un objet { path, params?, query? } , quand les valeurs ont un type : un nombre, un booléen, une liste fermée de valeurs. Le type est écrit par l'app, la description dit comment le lire dans l'URL. Voir Décrire les valeurs . type CounterParams = { id: number }; export const Router = defineRouter({ home: '/', counters: '/counters?sort&tag[]', // des chaînes counter: { path: '/counters/:id', params: params<CounterParams>({ id: Number }) }, // un nombre }) Chaque chemin doit commencer par / , sinon une erreur est levée. '*' et '!' sont réservés aux écrans « introuvable » et « erreur » : ce ne sont pas des noms de route possibles (erreur de compilation, et erreur à l'exécution)."},{"url":"router.html#decrire-les-valeurs","page":"Router","title":"Décrire les valeurs","text":"Dans la forme objet, l'app écrit le type de ses paramètres et de sa query, puis le décrit avec params<T>({…}) et query<T>({…}) , importés de @super-ts/dom . Le compilateur vérifie que la description correspond au type, clé par clé. À l'exécution, elle sert à lire et convertir les valeurs de l'URL. import { defineRouter, params, query } from '@super-ts/dom'; type CounterParams = { id: number }; type CountersQuery = { sort: 'label' | 'value'; page: number; tag: string[]; search?: string; archived?: boolean }; export const Router = defineRouter({ counter: { path: '/counters/:id', params: params<CounterParams>({ id: Number }) }, counters: { path: '/counters', query: query<CountersQuery>({ sort: { oneOf: ['label', 'value'], default: 'label' }, // obligatoire : une valeur par défaut page: { type: Number, default: 1 }, tag: [String], // une liste : [] si absente search: String, // facultative : pas de défaut archived: Boolean, }), }, }) Description Type Valeurs acceptées dans l'URL String string Toutes, décodées. Number number Un nombre décimal : 42 , -3 , 1.5 , 1e3 . abc est invalide. Boolean boolean true ou false , rien d'autre. { oneOf: ['label', 'value'] } 'label' | 'value' Une des valeurs listées. [String] , [Number] , [{ oneOf: […] }] une liste Chaque occurrence de la clé ( ?tag=a&tag=b ). Query seulement. String , Number et Boolean sont les constructeurs natifs de JavaScript : ils nomment le type et font la conversion. Une clé de query obligatoire a une valeur par défaut , prise quand la clé est absente ou invalide : { type: Number, default: 1 } , { oneOf: [...], default: 'label' } . Une clé facultative n'en a pas ( search?: string se décrit String ) : elle vaut undefined quand elle manque. Un paramètre de chemin n'a jamais de défaut : il est toujours présent dans l'URL qui correspond à la route. params décrit exactement les paramètres du chemin , ni plus ni moins. Sans params , les paramètres du chemin sont des chaînes. Une liste oneOf doit couvrir toute l'union : le compilateur refuse une valeur hors de l'union, mais pas une valeur oubliée. Avec { oneOf: ['label'] } pour 'label' | 'value' , ?sort=value serait toujours lu comme invalide. Voir ce qui n'est pas vérifié . Dans la forme objet, la query ne s'écrit pas dans le chemin : { path: '/counters?sort' } est refusé, elle se décrit par query . // @ts-expect-error une clé obligatoire exige sa valeur par défaut query<{ page: number }>({ page: Number }); // @ts-expect-error une clé facultative n'a pas de défaut query<{ page?: number }>({ page: { type: Number, default: 1 } }); // @ts-expect-error mauvais type query<{ page?: number }>({ page: String }); // @ts-expect-error valeur hors de l'union query<{ sort?: 'a' | 'b' }>({ sort: { oneOf: ['a', 'c'] } }); // @ts-expect-error une liste se décrit entre crochets query<{ tag: string[] }>({ tag: String }); // @ts-expect-error un paramètre de chemin est toujours présent : pas de défaut params<{ id: number }>({ id: { type: Number, default: 1 } }); // @ts-expect-error `slug` n'est pas un paramètre du chemin defineRouter({ counter: { path: '/counters/:id', params: params<{ slug: string }>({ slug: String }) } }); Ces erreurs sont aussi vérifiées à l'exécution, avec un message explicite : « route \"counter\" : params doit décrire exactement les paramètres du chemin (id) »."},{"url":"router.html#screens","page":"Router","title":".screens","text":"Associe un écran à chaque route. Un écran est une classe de composant ( SuperElement ) sans props obligatoire : il ne reçoit pas les valeurs de sa route en props, il les lit par this.router.current (voir Lire la route dans l'écran ). Le compilateur exige un écran par route. Deux clés facultatives s'ajoutent : '*' , l'écran affiché quand aucun chemin ne correspond, et '!' , l'écran affiché quand un écran plante sans être rattrapé (il est le seul à recevoir des props, { error, path } , voir Gérer les erreurs ). À la place d'un écran, une route peut recevoir une redirection . class HomeScreen extends SuperElement { /* … */ } class CounterScreen extends SuperElement { /* … */ } class NeedsCounter extends SuperElement { @tag = 'needs-counter'; @prop counterId: string; /* … */ } const declared = defineRouter({ home: '/', counter: '/counters/:id' }); declared.screens(() => ({ home: HomeScreen, counter: CounterScreen })); // ✓ // @ts-expect-error écran manquant pour `counter` declared.screens(() => ({ home: HomeScreen })); // @ts-expect-error l'écran attend une prop que le router ne fournit pas declared.screens(() => ({ home: HomeScreen, counter: NeedsCounter }));"},{"url":"router.html#lire-les-parametres","page":"Router","title":"Lire la route dans l'écran","text":"L'écran lit sa route par this.router.current : current.params.id() pour un paramètre du chemin, current.query.sort() pour une clé de query. Sur /counters/cafes , la route /counters/:id donne current.params.id() === 'cafes' . Les valeurs sont décodées ( /counters/caf%C3%A9 donne 'café' ), et converties si la route les décrit. /** Écran de la route `/counters/:id` : il lit `id` dans sa route. */ export class CounterScreen extends SuperElement { @tag = 'counter-screen'; // Suivi : renommer le compteur change aussi le titre de l'onglet. @title = () => this.label.value ?? 'Compteur introuvable'; // Le paramètre de la route, lu à l'appel : `this.counterId()`. counterId = this.router.current.params.id; // Ne lit que ce qui concerne le compteur affiché : les autres compteurs ne re-rendent pas l'écran. @contract counter; @selector label = () => this.counter.selectors.label(this.counterId()); @selector count = () => this.counter.selectors.count(this.counterId()); // … #back() { <a class=\"back-link\" href={this.router.href('counters')}>← Tous les compteurs</a> } render() { const label = this.label.value; if (label === null) { <main class=\"screen\">{this.#back()}<h1>Compteur introuvable</h1><p>Aucun compteur « {this.counterId()} ».</p></main> return; } // … } } Le champ ne s'appelle pas id : id est une propriété native des éléments HTML, et un champ ou une prop ne peut pas en reprendre le nom. Le paramètre id se garde donc dans counterId ( counterId = this.router.current.params.id; ). Il en va de même pour title , hidden ou slot . Chaque valeur est une fonction , qui lit la route active à l'appel. Elle se garde dans un champ ( counterId ci-dessus), se déstructure ( const { id } = this.router.current.params ), ou se donne telle quelle à un @selector , comme un sélecteur sans paramètre : @selector sort = this.router.current.query.sort; , puis this.sort.value . Lue pendant render , directement ou par un @selector , elle abonne le composant au router : il se re-rend quand la valeur change. Valeur de route ou sélection : gardée telle quelle ( counterId = this.router.current.params.id ), la valeur se lit en l'appelant, this.counterId() , comme un sélecteur ; donnée à un @selector ( @selector counterId = this.router.current.params.id; ), elle devient une sélection, qui se lit par this.counterId.value et this.counterId.isValid() . Dans la fonction d'un autre @selector , on appelle la valeur de route ( this.counter.selectors.count(this.counterId()) ) : une sélection lue là ne l'abonnerait pas au router. Elle est typée par la route de l'écran : params.id existe sur l'écran de /counters/:id , params.nope ne compile pas. Voir L'écran et sa route . current.name() et current.path() donnent le nom de la route active et le chemin tel que navigué. En test , on monte l'écran seul avec un router en mode memory placé sur le bon chemin : voir Tester avec le router ."},{"url":"router.html#valeurs-invalides","page":"Router","title":"Une valeur invalide dans l'URL","text":"L'URL vient de l'extérieur : /counters/abc pour un id décrit Number , ?page=abc , ?sort=nimporte . Le router ne rejette pas la navigation pour autant : Une clé de query invalide est traitée comme absente : elle prend sa valeur par défaut, ou undefined . Dans une liste, seuls les éléments invalides sont retirés ( ?tag=1&tag=x donne [1] pour [Number] ). Un paramètre de chemin invalide ne mène pas à l'écran '*' : l'écran de la route est affiché, et la valeur vaut undefined . C'est à l'écran de décider quoi montrer. isValid() dit si l'URL contenait une valeur conforme. Il existe sur chaque valeur ( current.params.id.isValid() ) et sur la sélection qu'en fait @selector ( this.counterId.isValid() ). Après ce test, la valeur est du type décrit : number , et non plus number | undefined . ({ id: Number }) }\"> class CounterScreen extends SuperElement { @tag = 'counter-screen'; @selector counterId = this.router.current.params.id; // number | undefined render() { if (!this.counterId.isValid()) { <p>Ce compteur n’existe pas.</p> return; } const id = this.counterId.value; // number // … } } Une clé absente est valide : elle prend son défaut (ou undefined ), comme prévu par la description. isValid() n'est faux que si l'URL portait une valeur non conforme, ou si la route active ne déclare pas cette clé. Pour une liste , isValid() est faux dès qu'un élément a été retiré. Le composant se re-rend si la valeur change, ou si seule sa validité change (de ?page=1 à ?page=abc , la valeur reste 1 mais devient invalide). Un paramètre string est toujours valide , comme toute valeur d'une route déclarée par une chaîne. Pour rediriger plutôt qu'afficher un message, deux endroits conviennent : le guard de la route ( ({ params }) => params.id.isValid() || { to: 'counters' } ), et l'écran n'est jamais rendu ; ou mounted() , avec this.router.send('navigate', …) , et l'écran se rend une fois avant de partir. Naviguer depuis render n'est pas dans l'esprit du framework : render décrit l'écran, il ne déclenche rien."},{"url":"router.html#l-ecran-et-sa-route","page":"Router","title":"L'écran et sa route","text":"Dans un écran, this.router.current est typé par sa propre route , sans rien écrire à la main. Le plugin Vite lit .screens(…) dans routes.ts , retrouve le tag de chaque écran, et génère le lien dans src/@core/contracts.d.ts : declare module '@super-ts/dom' { interface ScreenRoutes { 'counter-list-screen': 'counters'; 'counter-screen': 'counter'; // … } } Le compilateur .super ajoute la route au type de chaque composant, d'après son tag : CounterScreen voit params.id , et current.name() y vaut 'counter' | null . Un écran utilisé sur deux routes voit leur union : chaque clé de l'une ou l'autre, undefined là où une route ne l'a pas. Un composant qui n'est pas un écran voit l'union de toutes les routes de l'app, de la même façon : current.params.id() vaut number | undefined si seule la route counter a un id numérique. Une clé qu'aucune route ne déclare ne compile pas. Un composant écrit en .ts , qui garde static tag et le générique, déclare sa route lui-même : SuperElement<{ route: 'counter' }> , ou SuperElement<{ props: P; route: 'counter' }> . Les écrans '*' et '!' n'ont pas de route propre : ils voient toutes les routes."},{"url":"router.html#hors-de-l-ecran","page":"Router","title":"Hors de l'écran : current et at","text":"Un en-tête ou un fil d'Ariane lit la route active de la même façon, par this.router.current , typé par l'union de toutes les routes : @selector route = this.router.current.name; pour savoir où l'on est. Un composant qui n'est affiché que sur une route précise, sans en être l'écran (un enfant de l'écran, par exemple), lit cette route par this.router.at('counter') : ses params et sa query , typés par elle seule, au lieu de l'union. /** Affiché dans l'écran du compteur : sa route est toujours `counter`. */ class CounterHistory extends SuperElement { @tag = 'counter-history'; route = this.router.at('counter'); render() { const id = this.route.params.id(); // typé par la route `counter` // … } } at se déclare n'importe où, mais lire une de ses valeurs alors que la route active est une autre lève une erreur : « this.router.at('counter') lu alors que la route active est 'counters' ». Un composant affiché sur plusieurs routes lit donc current , et vérifie current.name() ."},{"url":"router.html#ecran-et-props-en-plus","page":"Router","title":"Un écran qui a besoin d'autres props","text":"Le router n'a rien à donner à un écran : .screens() refuse un composant qui a une prop obligatoire. Une prop facultative compile, mais vaut toujours undefined quand l'écran est affiché par sa route. On sépare alors l'écran, qui lit la route, du composant qu'il affiche, dont les props sont libres et qui se réutilise ailleurs : // Composant réutilisable : ses props ne dépendent d'aucune route. export class CounterList extends SuperElement { @tag = 'counter-list'; @prop sort: 'original' | 'label'; @prop heading: string; // pas `title` : c'est une propriété des éléments HTML @prop compact: boolean = false; render() { /* … */ } } // Écran de la route `counters` : il lit sa query et complète le reste. export class CounterListScreen extends SuperElement { @tag = 'counter-list-screen'; @selector sort = this.router.current.query.sort; render() { <CounterList sort={this.sort.value} heading=\"Mes compteurs\" /> } } // Ailleurs, dans le render d'un autre composant, le même composant avec d'autres props. <CounterList sort=\"label\" heading=\"Favoris\" compact={true} /> Ce que l'écran ajoute vient d'une constante (l'intitulé ci-dessus), d'un store déclaré par @contract (préférences, utilisateur), ou de la route elle-même : si la valeur doit pouvoir figurer dans l'URL, déclare-la dans la query. Pourquoi les chemins et les écrans sont déclarés à part Les écrans lisent le router par this.router , typé d'après Router , et Router contient les écrans. Le compilateur ne peut typer Router sans lire les écrans que parce que les routes sont posées à part, dans defineRouter(...) , et que .screens(...) est le dernier appel de la déclaration : le type du router ne dépend pas des écrans. C'est pourquoi les guards, qui ne dépendent que des routes, viennent avant. Une forme fusionnée, du genre defineRouter(() => ({ screens: { home: { path, component } } })) , ne peut pas être typée : le type du router dépendrait des écrans, qui dépendent du router, et tout retomberait en any . Pourquoi les écrans sont donnés par une fonction routes.ts importe les écrans ; si un module chargé par un écran importe à son tour routes.ts (pour Router.href , hors composant), les deux modules s'importent mutuellement. Si un écran est chargé en premier (dans un test, par exemple), routes.ts s'évalue avant que l'écran soit initialisé. Avec la fonction, les écrans ne sont lus qu'à la création du router, par createRouter , une fois tout chargé."},{"url":"router.html#query","page":"Router","title":"Query","text":"Une route ne lit que les clés de query qu'elle déclare. Dans une chaîne, elles suivent ? , séparées par & , et une clé suivie de [] est une liste ; les valeurs sont des chaînes. Avec query<T>({…}) , elles sont typées et converties (voir Décrire les valeurs ). L'écran les lit par this.router.current.query : /** Écran de la route `counters` : la liste des compteurs, triée par nom si `?sort=label`. */ export class CounterListScreen extends SuperElement { @tag = 'counter-list-screen'; @title = 'Mes compteurs'; // … // La query de la route, typée par sa description : 'original' | 'label'. @selector sort = this.router.current.query.sort; render() { const byLabel = this.sort.value === 'label'; // … <nav class=\"counter-sort\" aria-label=\"Tri\"> <a href={this.router.href('counters')} aria-current={byLabel ? null : 'page'}>Ordre d’origine</a> <a href={this.router.href('counters', { query: { sort: 'label' } })} aria-current={byLabel ? 'page' : null}>Par nom</a> </nav> // … } } Une clé simple peut manquer : elle vaut sa valeur par défaut, ou undefined . Répétée dans l'URL, seule la première valeur compte. Une liste vaut toujours un tableau : ?tag=a&tag=b donne ['a', 'b'] , et [] si la clé est absente. Une valeur invalide est traitée comme absente ( ?sort=nimporte donne le défaut 'original' ) : voir Une valeur invalide dans l'URL . Les clés non déclarées sont ignorées : sur /counters?sort=label&utm_source=mail , current.query n'a pas de utm_source . L'URL n'est pas réécrite pour autant : current.path() vaut toujours '/counters?sort=label&utm_source=mail' , et la barre d'adresse la garde. Paramètres et query se lisent séparément : un paramètre et une clé de query peuvent porter le même nom ( '/items/:id?id' ). Une clé vide ou en double lève une erreur. Changer seulement la query ne remonte pas l'écran : son état local est conservé, et il se re-rend s'il lit une valeur qui a changé. Voir RouterOutlet . Pour construire un lien ou naviguer, paramètres et query se donnent séparément, avec leurs valeurs typées : this.router.href('counters', { query: { sort: 'label', tag: ['a', 'b'] } }) // '/counters?sort=label&tag=a&tag=b' this.router.href('counter', { params: { id: 42 }, query: { tab: 'historique' } }) // '/counters/42?tab=historique' this.router.send('navigate', { to: 'counters', query: { tag: ['a'] } }); this.router.href('counters', { query: { page: '2' } }) // ✗ ne compile pas : `page` n'est pas déclaré this.router.href('counters', { query: { sort: 'nope' } }) // ✗ ne compile pas : valeur hors de l'union Les valeurs s'écrivent dans l'URL par String(valeur) : 2 donne page=2 , false donne archived=false . Une liste répète la clé. Une clé à undefined ou une liste vide sont omises . La query est facultative , même pour une clé obligatoire : absente de l'URL, elle reprend son défaut à la lecture. Une navigation donne toute la query : les clés qu'elle ne donne pas disparaissent de l'URL. Pour changer une seule clé, on redonne les autres : const { sort, tag } = this.router.current.query; this.router.send('navigate', { to: 'counters', query: { sort: sort(), tag: [...tag(), 'nouveau'] } });"},{"url":"router.html#redirections","page":"Router","title":"Redirections","text":"Une route peut renvoyer vers une autre, en déclarant redirect(…) à la place de son écran. C'est utile pour une page prévue mais pas encore construite, un ancien chemin qu'on garde pour les liens existants, ou un chemin qui n'a pas d'écran propre (dans l' app d'exemples , /form renvoie vers /profile : voir routes.ts ). export const Router = defineRouter({ home: '/', stats: '/stats', // page prévue, pas encore construite item: '/items/:id', legacy: '/old/items/:id', // ancien chemin }).screens(() => ({ home: HomeScreen, stats: redirect({ to: 'home' }), // temporaire : remplacé par StatsScreen le jour venu item: ItemScreen, legacy: redirect({ to: 'item', params: { id: 'archive' } }), })); Les liens restent justes : this.router.href('stats') donne /stats dès aujourd'hui. Le jour où la page existe, on remplace redirect(…) par l'écran, sans toucher aux liens. La cible est typée comme un navigate ( { to, params, query } ) : une route inconnue ou un paramètre manquant ne compilent pas. L'historique reste propre : le chemin redirigé n'y entre jamais. Une navigation vers /stats ajoute / à l'historique, et un chemin initial redirigé remplace l'entrée courante. Le bouton retour ne ramène pas sur une page qui renvoie aussitôt ailleurs. Les redirections s'enchaînent (une redirection vers une route elle-même redirigée), jusqu'à 10 de suite. Au-delà, une boucle est supposée et une erreur est levée : « trop de redirections à partir de \"/a\" »."},{"url":"router.html#guards","page":"Router","title":"Guards","text":"Un guard décide, avant d'afficher une route, si on y va ou si on est redirigé ailleurs, selon l'état de l'app ou l'URL : « est-on connecté ? », « cet identifiant est-il valide ? ». Il se déclare un par route, avant les écrans : import { defineRouter, params } from '@super-ts/dom'; export const Router = defineRouter({ home: '/', account: '/account', login: '/login', counters: '/counters', counter: { path: '/counters/:id', params: params<{ id: number }>({ id: Number }) }, }) .guards(({ read }) => ({ account: () => read('session').isLoggedIn() || { to: 'login' }, counter: ({ params }) => params.id.isValid() || { to: 'counters' }, })) .screens(() => ({ home: HomeScreen, account: AccountScreen, login: LoginScreen, counters: CounterListScreen, counter: CounterScreen })); Un guard renvoie true pour laisser passer, ou une cible ( { to, params, query } ) pour rediriger. La cible est typée comme un navigate . Il reçoit sa route comme this.router.at(…) la donne : { params, query } , typés par la route, chaque valeur à appeler ( params.id() ) et munie de isValid() . Il lit les stores par le nom de leur contrat , avec read('session') , comme un composant avec @contract session; : il reçoit les sélecteurs du contrat (et pending ), lus au moment de la navigation. Un nom de contrat inconnu ne compile pas. Les stores viennent de l'application qui reçoit le router : routes.ts ne connaît aucune instance. Il ne fait que lire : il ne peut pas envoyer de commande. Décider d'une navigation ne déclenche pas d'effet de bord. Il se déclare avant .screens(…) , qui doit rester le dernier appel. Après les écrans, guards n'existe pas : ça ne compile pas. Placé après, il obligerait le compilateur à lire les écrans pour typer le router, et les écrans lisent le router : tout retomberait en any . Il est synchrone . Une vérification asynchrone (« la session est-elle encore valide ? ») se fait dans le store ; le guard lit son résultat. Les routes sans guard passent toujours. L'app d'exemples protège la commande de la boutique : /shop/checkout renvoie vers /shop tant que le panier est vide. Voir routes.ts et l' exemple Boutique . .guards(({ read }) => ({ checkout: () => !read('cart').isEmpty() || { to: 'shop' }, })) .screens(() => ({ /* … */ checkout: CheckoutScreen }));"},{"url":"router.html#quand-les-guards-s-appliquent","page":"Router","title":"Quand les guards s'appliquent","text":"À toutes les navigations : navigate , visit , les liens interceptés, le bouton retour du navigateur. Au chemin courant, au moment où le router rejoint l'application ( createApp ou mount ) : c'est elle qui fournit les stores. Avant ce moment, ils ne sont pas évalués. Une redirection décidée par un guard suit les mêmes règles qu'une redirection déclarée : le chemin refusé n'entre pas dans l'historique. Un guard qui redirige vers la page courante annule simplement la navigation. Un store lu par un guard doit être fourni Si un guard lit un contrat que l'application ne fournit pas, une erreur est levée : « guard du router : aucun store fourni pour le contrat \"session\" ». En test, passe le store (vrai ou faux) à mount(…, { stores, router }) . const session = fakeStore('session', { state: { user: null } }); const router = createRouter(Router, { mode: 'memory' }); await mount(RouterOutlet, { stores: [session], router }); await router.send('navigate', { to: 'account' }); expect(router.state().name).toBe('login'); session.setState({ user: 'ada' }); await router.send('navigate', { to: 'account' }); expect(router.state().name).toBe('account');"},{"url":"router.html#liens","page":"Router","title":"Liens : this.router.href","text":"// href=\"/counters/cafes\" <a href={this.router.href('counter', { params: { id: c.id } })}>{c.label}</a> // href=\"/\" <a href={this.router.href('examples')}>Exemples</a> this.router.href(nom, { params, query }) construit le chemin et encode les valeurs ( 'a b' devient 'a%20b' ). params est obligatoire si le chemin a des paramètres, query toujours facultative. Il n'abonne pas le composant : il ne lit pas la route active, et un changement de route ne re-rend pas un composant qui ne fait que construire des liens. Les valeurs sont typées par la route : { params: { id: '42' } } ne compile pas si id est décrit Number . La query suit les règles de Query . this.router.href('counter') sans id , ou this.router.href('compteur', …) , ne compilent pas. Une route sans paramètre ni query refuse toute valeur. Hors composant (un test, un module user-land), Router.href , importé de routes.ts , fait la même chose : Router.href('counter', { params: { id: 'cafes' } }) ."},{"url":"router.html#interception-des-liens","page":"Router","title":"L'interception des liens","text":"L'application intercepte les clics sur les liens internes ( href commençant par / ) et les transforme en navigation, sans rechargement. Le navigateur garde la main dans ces cas : lien externe ( https://… , //… ) ou relatif ( ../x ) ; attribut target autre que _self ( target=\"_blank\" ) ; attribut download ou data-native ; clic avec Cmd, Ctrl, Shift ou Alt, ou autre bouton que le gauche ; événement déjà annulé par un autre écouteur. // Le navigateur charge vraiment l'URL. <a href=\"/export.csv\" data-native>Télécharger</a>"},{"url":"router.html#afficher-l-ecran","page":"Router","title":"Afficher l'écran : RouterOutlet","text":"RouterOutlet affiche l'écran de la route active, qui lit ses valeurs par this.router.current . C'est un composant comme un autre : on l'écrit <RouterOutlet /> dans une mise en page commune, après l'avoir importé de @super-ts/dom . import { RouterOutlet, SuperElement } from '@super-ts/dom'; import { RouteLink } from '@super-ts/ui'; import './index.css'; /** Mise en page commune : la navigation entre les exemples, puis l'écran de la route active. */ export class AppShell extends SuperElement { @tag = 'app-shell'; @contract counter; protected override mounted() { this.counter.send('load'); } render() { // Chaque lien se marque lui-même `aria-current=\"page\"` sur la page affichée ; `activeFor` // étend une section à ses autres routes (la liste des compteurs et un compteur). <header class=\"app-header\"> <nav aria-label=\"Exemples\"> <RouteLink to={{ to: 'examples' }}> Exemples </RouteLink> <RouteLink to={{ to: 'counters' }} activeFor={['counter']}> Compteurs </RouteLink> <RouteLink to={{ to: 'profile' }}> Formulaire </RouteLink> <RouteLink to={{ to: 'shop' }} activeFor={['checkout']}> Boutique </RouteLink> <RouteLink to={{ to: 'errors' }}> Erreurs </RouteLink> <RouteLink to={{ to: 'widget' }}> Widget </RouteLink> <RouteLink to={{ to: 'composition' }}> Composition </RouteLink> <RouteLink to={{ to: 'kit' }}> Kit </RouteLink> </nav> </header> <RouterOutlet /> } } Les liens de la coquille sont des RouteLink , du kit d'interface : la cible s'écrit comme pour navigate , et chaque lien pose lui-même aria-current=\"page\" quand il mène à la page affichée. activeFor garde « Compteurs » actif sur un compteur, et « Boutique » sur la commande. Sans le kit, la coquille lirait le nom de la route active par this.router.current.name (elle se re-rendrait quand la route change) et construirait ses liens par this.router.href (qui, lui, n'abonne pas). aria-current vaudrait 'page' sur le lien de la route active et null sur les autres : un attribut calculé à null est retiré (voir Attributs ). @selector route = this.router.current.name; render() { const name = this.route.value; const current = (active: boolean) => (active ? 'page' : null); // `null` retire l'attribut <nav aria-label=\"Exemples\"> <a href={this.router.href('counters')} aria-current={current(name === 'counters' || name === 'counter')}>Compteurs</a> // … </nav> } Chaque changement de chemin monte une nouvelle instance de l'écran : passer de /counters/cafes à /counters/pompes construit un nouvel écran, et son état local repart de zéro. Un changement de query ou de hash seul ( /counters vers /counters?sort=label ) garde l'écran monté : un filtre ou une page de plus ne fait pas perdre l'état local, et l'écran se re-rend s'il lit une valeur qui a changé. Les rendus en attente passent parents d'abord . Quand l'outlet remplace un écran, l'ancien ne se re-rend donc pas avec une route qui n'est plus la sienne : il est retiré avant."},{"url":"router.html#creer-le-router","page":"Router","title":"Créer le router","text":"import { createApp, createRouter } from '@super-ts/dom'; import { AppShell } from '@components/app-shell'; import { Router } from './routes'; // Le titre de l'onglet : celui que pose l'écran affiché (`@title`), suivi du nom de l'app. const router = createRouter(Router, { title: { default: 'Super · exemples', suffix: ' · Super' } }); createApp({ root, stores: [counter, profile, cart, checkout, errorLog, catalog], router }).mount(AppShell.create()); Option Rôle mode 'browser' (défaut) synchronise l'URL avec l'historique du navigateur. 'memory' garde l'historique en mémoire, pour les tests. initialPath Chemin de départ en mode memory (défaut '/' ). title { default, suffix } : le titre de la page quand aucun composant n'en pose, et le texte ajouté au titre posé. Voir Le titre de la page . createRouter n'accepte qu'un router dont les écrans sont déclarés : lui passer defineRouter({ … }) sans .screens(...) ne compile pas. Il renvoie le handle du router, à passer à createApp({ router }) , ou à mount(…, { router }) en test. Ce handle se lit comme celui d'un store : router.state() donne l'état complet , et router.send('navigate', …) navigue."},{"url":"router.html#titre-de-la-page","page":"Router","title":"Le titre de la page","text":"Le titre de l'onglet suit l'écran affiché. Le router en fixe le cadre, par l'option title de createRouter (et non de defineRouter , dont les clés sont des routes) ; l'écran pose son propre titre par @title . // Le titre de l'onglet : celui que pose l'écran affiché (`@title`), suivi du nom de l'app. const router = createRouter(Router, { title: { default: 'Super · exemples', suffix: ' · Super' } }); default est le titre quand aucun composant n'en pose (la page d'accueil des exemples, par exemple). Sans default , c'est le titre d'origine du document qui revient. suffix est ajouté au titre posé : l'écran de la boutique pose « Boutique », l'onglet affiche « Boutique · Super ». Dans l'écran, @title reçoit une chaîne (un titre fixe) ou une fonction (un titre suivi ), recalculée après chaque rendu avec les mêmes lectures que render : export class ShopScreen extends SuperElement { @tag = 'shop-screen'; // Suivi : le titre de l'onglet change avec le panier, comme le rendu. @title = () => { const count = this.cart.selectors.count(); return count > 0 ? `Boutique (${count} au panier)` : 'Boutique'; }; @contract cart; // … } Le titre est posé au montage et retiré au démontage : en changeant de route, l'ancien écran rend la main et le nouveau pose le sien. Tout composant peut poser un titre , pas seulement un écran : les titres forment une pile, le dernier composant monté qui en pose un l'emporte, et à son démontage le titre précédent revient. Dans la démo, KitPage donne leur titre à toutes les pages du kit ( @title = () => this.heading; ). Ailleurs que dans la déclaration ( mounted , un gestionnaire), this.page.title = … fait la même chose. Le détail (pile, titre impératif, règles) est dans Composants : le titre de la page ."},{"url":"router.html#le-router-est-un-store","page":"Router","title":"Le router dans un composant","text":"Un composant lit et pilote le router par this.router , sans rien déclarer : la route active ( current ), une route précise ( at ), la navigation ( send ) et les liens ( href ) ; ses événements s'écoutent par une méthode @on('router', 'navigated') . Rien à importer de routes.ts : la vue est typée par les routes de l'app. Elle se lit partout, render compris, et un composant qui ne la lit pas se monte sans router. @contract router est refusé : le router se lit par this.router . Voir Composants : les déclarations de préparation . @selector route = this.router.current.name; // 'examples' | 'counters' | … | null @selector sort = this.router.current.query.sort; @on('router', 'navigated') onNavigated({ from, to }) { /* … */ } this.router.send('navigate', { to: 'counter', params: { id: 'cafes' } }); // typé par les routes this.router.send('navigate', { to: 'counters', query: { sort: 'label' } }); this.router.send('navigate', { to: 'examples' }); this.router.send('visit', '/counters/cafes'); // chemin brut this.router.send('back'); this.router.href('counter', { params: { id: 'cafes' } }); // un lien, sans abonnement"},{"url":"router.html#l-etat-du-router","page":"Router","title":"La route active et l'état du router","text":"Un composant lit la route active par this.router.current . Chaque valeur s'appelle, ou se donne à un @selector : Valeur Contenu current.name() Le nom de la route active ( 'examples' | 'counters' | 'counter' | … , 'form' étant redirigée), ou null si aucune ne correspond. current.path() Le chemin courant, tel que navigué (query et hash compris). current.params.<clé>() Un paramètre du chemin, décodé et converti : 'café' pour /counters/caf%C3%A9 . undefined s'il est invalide, ou si la route active ne l'a pas. current.query.<clé>() Une clé de query déclarée par la route active, convertie : sa valeur, son défaut, undefined , ou [] pour une liste. ….isValid() Sur un paramètre ou une clé de query : l'URL ne portait pas de valeur non conforme, et la route active déclare cette clé. Le handle renvoyé par createRouter (dans main.ts ou un test) donne l'état complet par router.state() : path , name , params et query (convertis), invalid (les clés dont l'URL portait une valeur invalide : { params: ['id'], query: [] } ), et deux champs que seul RouterOutlet utilise : screen , l'écran à afficher (l'écran '*' si aucune route ne correspond ; jamais une redirection, elles sont suivies avant), et errorScreen , l'écran '!' . Un composant n'a pas accès à ces deux-là."},{"url":"router.html#les-commandes-du-router","page":"Router","title":"Les commandes du router","text":"Commande Effet navigate({ to, params, query }) Navigation typée par nom de route. params porte les paramètres du chemin, obligatoire si le chemin en a ; query , facultative, la query déclarée. visit(chemin) Navigation par chemin brut (c'est ce qu'utilisent les liens interceptés). back() Revient à l'entrée précédente de l'historique. Chaque navigation émet navigated { from, to } . Naviguer vers le chemin courant (recliquer sur le lien de la page affichée) n'ajoute rien à l'historique et ne remonte pas l'écran, mais émet quand même navigated , avec from === to : c'est ce qui permet de quitter l'écran '!' en recliquant sur le lien de la page en erreur."},{"url":"router.html#resolution-des-chemins","page":"Router","title":"Résolution des chemins","text":"Le slash final est ignoré : /counters/cafes/ correspond à counter . La query et le hash sont ignorés pour trouver la route, mais conservés dans path . Les clés de query déclarées sont lues dans query . Seule la forme du chemin compte pour trouver la route : /counters/abc correspond à counter même si id est décrit Number , avec un id invalide. Un chemin sans correspondance donne une route null et l'écran '*' (rien n'est affiché s'il n'est pas déclaré). Les redirections déclarées et celles des guards sont suivies avant d'afficher : path et la route active sont ceux de la destination finale."},{"url":"router.html#tester-avec-le-router","page":"Router","title":"Tester avec le router","text":"Un composant qui lit this.router a besoin d'un router. En test, crée-le en mode memory , sur le chemin voulu : l'écran y lit sa route, sans props. import { Router } from '../../routes'; const router = createRouter(Router, { mode: 'memory', initialPath: '/counters/cafes' }); const { container } = await mount(CounterScreen, { stores: [counter], router }); await userEvent.click(within(container).getByRole('link', { name: '← Tous les compteurs' })); expect(router.state().name).toBe('counters');"},{"url":"selecteurs.html","page":"Sélecteurs","title":"Sélecteurs","text":"Les sélecteurs sont les lectures autorisées de l'état. Ce sont les méthodes du contrat, utilisées telles quelles par les composants, le store et les tests. Tu les écris avec l'état en premier paramètre, et Super le fournit à l'appel : tu écris count(s, id) dans le contrat, puis selectors.count(id) partout ailleurs."},{"url":"selecteurs.html#declarer-des-selecteurs","page":"Sélecteurs","title":"Déclarer des sélecteurs","text":"// Les seules lectures autorisées de l'état. Un composant lit par là (plus `pending`, fourni par Super). export class CounterContract extends SuperContract<CounterTypes> { constructor() { super({ name: 'counter' }); } catalog(_s: CounterState) { return COUNTERS; } find(_s: CounterState, id: string) { return COUNTERS.find((counter) => counter.id === id) ?? null; } count(s: CounterState, id: string) { return s.counts[id] ?? 0; } label(_s: CounterState, id: string) { return COUNTERS.find((counter) => counter.id === id)?.label ?? null; } loadErrorMessage(s: CounterState) { return s.loadErrorMessage; } canDecrement(s: CounterState, id: string) { return (s.counts[id] ?? 0) > MIN_COUNT; } } Chaque sélecteur reçoit l'état en premier paramètre . Annote-le ( s: CounterState ) : TypeScript n'infère pas les paramètres d'une méthode. Il peut prendre d'autres paramètres après l'état : count(s, id: string) s'utilise en selectors.count('cafes') . Il peut ignorer l'état : catalog renvoie une donnée statique. C'est utile pour que les composants n'aient rien d'autre à demander que le contrat. Il doit être pur : pas d'effet de bord, pas d'appel réseau, seulement une lecture. pending est réservé : Super l'ajoute aux sélecteurs, pour savoir si une commande est en cours ( selectors.pending('load') ). Une méthode pending dans le contrat ne compile pas (erreur à la déclaration du store). Un sélecteur ne lit que l'état ; les commandes en cours n'en font pas partie."},{"url":"selecteurs.html#un-selecteur-sans-parametre","page":"Sélecteurs","title":"Un sélecteur sans paramètre","text":"Un sélecteur ne prend un paramètre que si la réponse en dépend. canDecrement a besoin de l' id (il faut savoir si ce compteur est au-dessus de 0). loadErrorMessage n'en a pas besoin : la réponse ne dépend que de l'état global. Côté composant, la différence se voit : un sélecteur sans paramètre se passe tel quel à @selector loadErrorMessage = this.counter.selectors.loadErrorMessage; , un sélecteur à paramètre s'appelle dans une fonction (voir Dans un composant )."},{"url":"selecteurs.html#pourquoi-des-selecteurs","page":"Sélecteurs","title":"Pourquoi des sélecteurs","text":"Une seule définition. « Un compteur absent vaut 0 » est écrit une fois. Le store, les composants et les tests appliquent la même règle ; la changer dans le contrat la change partout. Une porte fermée. Un composant ne voit jamais l'état brut : this.counter n'a pas de state() , et this.counter.selectors.counts ne compile pas, counts n'étant pas un sélecteur. La vue ne peut pas réinventer une règle de lecture dans son coin. Moins de bruit. L'état est fourni par Super : pas de s à trimballer."},{"url":"selecteurs.html#les-utiliser","page":"Sélecteurs","title":"Les utiliser","text":"Où Comment Exemple Composant La vue du contrat, en général dans un @selector (voir les déclarations ) @selector count = () => this.counter.selectors.count(this.counterId); Store L'outil protégé this.selectors this.selectors.count(id) + 1 Test, autre store, main.ts Le handle du store store.selectors.count('cafes')"},{"url":"selecteurs.html#dans-un-composant","page":"Sélecteurs","title":"Dans un composant","text":"// Le paramètre de la route, lu à l'appel : `this.counterId()`. counterId = this.router.current.params.id; // Ne lit que ce qui concerne le compteur affiché : les autres compteurs ne re-rendent pas l'écran. @contract counter; @selector label = () => this.counter.selectors.label(this.counterId()); @selector count = () => this.counter.selectors.count(this.counterId()); @selector canDecrement = () => this.counter.selectors.canDecrement(this.counterId()); // Un chargement ou une écriture en cours : on attend avant d'en relancer une. @selector busy = () => this.counter.selectors.pending(); Un @selector lit la valeur d'un sélecteur telle quelle ; la condition ou le calcul se font dans render , ou dans un nouveau sélecteur du contrat. Voir Lire un store pour les règles de re-rendu."},{"url":"selecteurs.html#dans-le-store","page":"Sélecteurs","title":"Dans le store","text":"increment({ id }: { id: string }) { return this.#write(id, this.selectors.count(id) + 1); } decrement({ id }: { id: string }) { if (this.selectors.find(id) && this.selectors.count(id) <= MIN_COUNT) this.fail('below-min'); return this.#write(id, this.selectors.count(id) - 1); } Chaque appel relit l'état courant : juste après un this.set , this.selectors.count(id) renvoie déjà la nouvelle valeur."},{"url":"selecteurs.html#dans-un-test","page":"Sélecteurs","title":"Dans un test","text":"const store = CounterStore.create({ counterRepository }); await store.send('load'); await store.send('increment', { id: 'cafes' }); expect(store.selectors.count('cafes')).toBe(2); Pourquoi sur le handle, et pas sur le contrat ? Un contrat n'a pas d'état : il décrit un store, il n'en est pas un. Il peut exister plusieurs stores pour le même contrat. Les sélecteurs se lisent donc sur un store précis : son handle ( store.selectors ), sa vue dans un composant ( this.counter.selectors ), ou this.selectors dans le store lui-même. Chacun fournit l'état de ce store, et son cache."},{"url":"selecteurs.html#quoi-mettre-dans-un-selecteur","page":"Sélecteurs","title":"Quoi mettre dans un sélecteur","text":"Oui : toute lecture qu'un composant ou le store fait plus d'une fois, ou qui contient une règle (« vaut 0 si absent », « possible si rien n'est en cours »). Oui : les données dont les composants ont besoin et qu'ils ne peuvent pas importer de @core/ (catalogue, libellés). Oui : une valeur que l'écran affiche après une condition ou un calcul, quand ce calcul mérite un nom. @selector n'accepte qu'un sélecteur tel quel ; un sélecteur de plus garde le composant simple. Non : un sélecteur qui renvoie tout l'état ( all(s: CounterState) { return s; } ). Ça rouvre la porte que les sélecteurs ferment. Oui : les dérivations (lignes d'un panier, total, liste filtrée). Leur place est dans le contrat plutôt que dans les composants : elles sont partagées, testables sans DOM, et Super stabilise leur résultat (voir ci-dessous)."},{"url":"selecteurs.html#deriver-dans-un-selecteur","page":"Sélecteurs","title":"Dériver dans un sélecteur","text":"Un sélecteur peut filtrer, trier ou construire de nouveaux objets sans précaution particulière. Chaque store garde un cache de ses sélecteurs, et Super évite les recalculs et les re-rendus inutiles en deux temps. Recalculer ou non : Super note les champs de premier niveau de l'état que le sélecteur lit. Au changement d'état suivant, si aucun de ces champs n'a changé de référence, le résultat précédent est renvoyé sans recalcul. Garder la référence : après un recalcul, le résultat est comparé en profondeur au précédent. S'il est égal, c'est l'ancienne référence qui est renvoyée. Sinon, les parties inchangées (une ligne qui n'a pas bougé) gardent la leur. Exemple : une messagerie dont l'état contient les messages et la réponse en cours de saisie. type InboxState = { messages: Message[]; folder: 'inbox' | 'archive'; draft: string }; export class InboxContract extends SuperContract<{ state: InboxState }> { constructor() { super({ name: 'inbox' }); } visible(s: InboxState) { return s.messages.filter((m) => m.folder === s.folder).sort((a, b) => b.date - a.date); } } visible lit messages et folder . Une frappe dans draft crée un nouvel état, mais ne déclenche ni filtre, ni tri, ni re-rendu. Un message reçu déclenche le recalcul ; la liste se re-rend, et seule la ligne du nouveau message est nouvelle. Ce qu'il faut savoir : Le suivi s'arrête au premier niveau : un sélecteur qui renvoie s.messages[3].subject est recalculé dès qu'un message change. Le recalcul est sans conséquence, la comparaison du résultat évite le re-rendu. Un sélecteur qui parcourt l'état entier ( Object.keys(s) , { ...s } ) dépend de tout : il est recalculé à chaque changement. La comparaison ne descend que dans les tableaux et les objets simples : une Date , une Map ou une instance de classe se compare par référence. Un sélecteur ne lit que son état et ses arguments : ce qu'il lirait ailleurs (une variable de module, Date.now() ) n'est pas suivi."},{"url":"selecteurs.html#un-contrat-sans-selecteurs","page":"Sélecteurs","title":"Un contrat sans sélecteurs","text":"Les sélecteurs sont facultatifs, mais ce sont les seules lectures qu'un composant a. Sans eux, un composant peut envoyer des commandes au store et écouter ses événements, rien de plus : il ne voit jamais l'état brut. Le handle complet, lui, garde state() pour les tests, la racine de composition et les autres stores. Le router suit la même règle : les composants lisent la route active par this.router.current ( name() , path() , params , query ), jamais son état brut (voir Router )."},{"url":"stores.html","page":"Stores","title":"Stores","text":"Un store implémente un contrat. Il garde l'état, traite les commandes, attend ce qu'il doit attendre (un adapter, le réseau), puis met à jour son état et annonce ce qui s'est passé."},{"url":"stores.html#definir-un-store","page":"Stores","title":"Définir un store","text":"import { type Commands, SuperStore } from '@super-ts/core'; import { MIN_COUNT } from '../../domain/counter'; import type { CounterRepository } from '../../ports/counter-repository'; import type { CounterContract } from './contract'; /** Les dépendances sont ce que tu veux : Super ne les inspecte jamais. */ type Deps = { counterRepository: CounterRepository }; const message = (error: unknown) => (error instanceof Error ? error.message : String(error)); // Pas de drapeau « en cours » ni d'événement à émettre : Super suit chaque commande et publie son // issue. Le handler fait son travail, échoue avec `this.fail(raison)`, ou retourne son résultat. export class CounterStore extends SuperStore<CounterContract> implements Commands<CounterStore> { #repository: CounterRepository; constructor({ counterRepository }: Deps) { super({ contract: 'counter', initialState: { counts: {}, loadErrorMessage: null } }); this.#repository = counterRepository; } // L'erreur de chargement reste dans l'état : elle doit rester visible, même pour un écran monté plus tard. async load() { this.set({ loadErrorMessage: null }); try { this.set({ counts: await this.#repository.loadAll() }); } catch (error) { this.set({ loadErrorMessage: message(error) }); } } increment({ id }: { id: string }) { return this.#write(id, this.selectors.count(id) + 1); } decrement({ id }: { id: string }) { if (this.selectors.find(id) && this.selectors.count(id) <= MIN_COUNT) this.fail('below-min'); return this.#write(id, this.selectors.count(id) - 1); } reset({ id }: { id: string }) { return this.#write(id, MIN_COUNT); } /** Le code commun aux trois écritures : une méthode privée, pas une commande. */ async #write(id: string, next: number) { if (!this.selectors.find(id)) this.fail('unknown'); await this.#repository.save(id, next).catch(() => this.fail('storage')); this.set((s) => ({ counts: { ...s.counts, [id]: next } })); return { count: next }; } } Un store vit dans src/@core/<nom>/store.ts , à côté de son contrat. Il étend SuperStore<CounterContract> : la classe du contrat ne s'importe que comme type, le lien à l'exécution passe par le nom donné à super({ contract: 'counter' }) ."},{"url":"stores.html#le-constructeur","page":"Stores","title":"Le constructeur : contrat, état initial, dépendances","text":"Le constructeur reçoit les dépendances et appelle super avec deux choses : contract : le nom du contrat implémenté, celui de son super({ name }) . Un nom inconnu, ou celui d'un autre contrat, ne compile pas. initialState : l'état de départ, conforme au state du contrat. Il est copié à chaque create() : deux instances ne partagent jamais leur état. Le constructeur range ses dépendances dans des champs #privés et peut écouter les stores reçus (voir plus bas ). Il ne lit ni ne modifie l'état : this.get() , this.set() ou this.send() y lèvent une erreur. L'état n'existe qu'une fois le store créé."},{"url":"stores.html#les-commandes","page":"Stores","title":"Les commandes : une méthode par commande","text":"Chaque commande du contrat est une méthode publique du store, du même nom. implements Commands<CounterStore> fait vérifier le tout par le compilateur : Une méthode pour chaque commande : en oublier une ne compile pas. Les paramètres du contrat, exactement : increment({ id }: { id: string }) . Annote-les à la main, TypeScript n'infère pas les paramètres d'une méthode de classe. Un paramètre plus étroit ( { id: 'cafes' } ) ne compile pas. Synchrone ou asynchrone : une méthode peut être async . C'est dans le store, et seulement là, qu'on attend un adapter. Elle retourne le résultat déclaré par l' Outcome de sa commande (rien pour une commande void ), ou échoue avec this.fail(raison) . Super publie l'issue ( increment:done , increment:failed ) et suit la commande en cours : pas de drapeau à gérer. Voir Déclarer l'issue . Aucune autre méthode publique : le code partagé entre commandes s'écrit en méthode #privée , comme #write . Une méthode publique hors contrat ne compile pas. Sans implements Commands<Self> , rien de cela n'est vérifié : Super prendrait toute méthode publique pour une commande. Garde-le sur chaque store."},{"url":"stores.html#les-outils","page":"Stores","title":"Les outils","text":"Le store hérite d'outils protected , utilisables dans ses méthodes. Ces noms sont réservés. Outil Rôle this.get() L'état courant, gelé en profondeur : une mutation en place ( this.get().items.push(x) ) lève une erreur. On le remplace avec set . this.selectors Les sélecteurs du contrat, état fourni : this.selectors.count(id) . Chaque appel relit l'état courant. Plus this.selectors.pending(…) pour les commandes en cours. this.set(patch) Fusionne le patch dans l'état (un niveau). Les champs que le patch ne touche pas gardent leur référence : c'est ce qui permet à Super de savoir ce qui a changé. Accepte un objet ou une fonction (état) => patch . L'état est mis à jour tout de suite ; les abonnés sont prévenus une seule fois à la fin de la tâche, même après plusieurs set . this.emit(nom, payload?) Annonce un événement déclaré dans events (pas l'issue d'une commande : Super la publie). Le payload est typé ; un événement void s'émet sans argument. this.send(nom, body?) Envoie une commande de ce même store, suivie par Super comme une autre (en cours, :done , :failed ). Pour partager du code sans ce suivi, appelle une méthode #privée . this.fail(raison) Fait échouer la commande en cours avec une raison déclarée. Ne revient pas. Le compilateur accepte les raisons de toutes les commandes du contrat, pas seulement celles de la commande en cours. this.signal AbortSignal avorté par dispose() . Inutile pour les stores reçus en dépendance (voir plus bas) ; il sert aux écouteurs posés hors de Super, comme un window.addEventListener('online', …, { signal: this.signal }) . this.set({ loadErrorMessage: null }); // objet partiel this.set((s) => ({ counts: { ...s.counts, [id]: next } })); // fonction de l'état courant"},{"url":"stores.html#les-dependances","page":"Stores","title":"Les dépendances","text":"Les dépendances sont les paramètres du constructeur . create(…) prend exactement ces arguments, avec leurs types. CounterStore.create({ counterRepository: createLocalStorageCounterRepository() }); // ok // @ts-expect-error dépendance manquante CounterStore.create(); Un store sans dépendance a un constructeur sans paramètre et se crée avec create() , comme CartStore.create() ."},{"url":"stores.html#creer-une-instance","page":"Stores","title":"Créer une instance : le handle","text":"Déclarer la classe ne crée rien. C'est CounterStore.create(deps) qui fabrique une instance, en général dans main.ts ou dans un test. Il renvoie un handle , jamais l'instance : les méthodes du store ne s'appellent pas directement, elles se déclenchent par send . const counter = CounterStore.create({ counterRepository }); counter.state(); // Readonly<CounterState> counter.selectors.count('cafes'); // les sélecteurs du contrat await counter.send('increment', { id: 'cafes' }); // Promise<void> : résolue si la commande réussit const off = counter.on('increment:done', ({ input, result }) => {}); counter.pending('increment'); // une commande est-elle en cours ? const unsubscribe = counter.subscribe((state) => {}); counter.dispose(); // les send suivants sont rejetés Membre Rôle state() L'état courant, figé. selectors Les sélecteurs du contrat, lus sur l'état courant, plus pending(…) . send(nom, body?) Envoie une commande. La promesse ne porte aucune donnée : elle se résout si la commande réussit, et se rejette si elle échoue (avec une CommandFailure qui porte la raison pour un échec déclaré), si la commande est inconnue ou si le store est disposé. on(nom, écouteur, { signal }?) Écoute un événement déclaré, ou le cycle de vie d'une commande ( increment:done , increment:failed ). Retourne la fonction de désabonnement. pending(commande?, body?) Une commande est-elle en cours ? Toutes, une commande, ou une commande pour un body. subscribe(écouteur, { signal }?) Écoute chaque changement d'état (regroupés par tâche). dispose() Retire les écouteurs internes ; les send suivants sont rejetés. contract Le contrat lu par Super (son nom), utile au fournisseur de createApp . Le handle complet n'est pas pour les composants Les composants reçoivent une vue réduite par @contract counter; : selectors , send() (qui renvoie void ) et on() , jamais l'état brut ; ils écoutent ses événements par une méthode @on('counter', 'increment:done') . Le handle complet sert aux tests, à la racine de composition et aux autres stores. Son type se déduit du nom du contrat : StoreOfContract<'counter'> ."},{"url":"stores.html#subscribe","page":"Stores","title":"subscribe : être prévenu de chaque changement d'état","text":"Dans l' exemple Boutique : main.ts , adapters/saved-cart.ts . Le panier est enregistré dans le localStorage à chaque changement, et survit au rechargement de la page. subscribe appelle ta fonction après chaque changement d'état, avec le nouvel état (plusieurs set dans la même tâche ne donnent qu'un appel). Il renvoie une fonction qui arrête l'écoute. const savedCart = createSavedCart(); // adapters/saved-cart.ts const cart = CartStore.create({ quantities: savedCart.load() }); // le panier d'avant le rechargement // subscribe : le panier est enregistré à chaque changement, et survit au rechargement de la page. // Le store ne sait rien du stockage : c'est la racine de composition qui le branche. cart.subscribe((state) => savedCart.save(state.quantities)); C'est l'usage type de subscribe : synchroniser l'état avec un système extérieur (un stockage, un outil d'analytics, un autre onglet), hors de tout composant, sans que le store le sache. CartStore reçoit seulement ses quantités de départ ( { quantities } ) et ignore où elles sont gardées ; changer de stockage ne touche que main.ts et l'adapter. Le compteur fait autrement, et à raison : son store parle à un port, CounterRepository (voir Les dépendances ), parce que la persistance fait partie de son métier. Le chargement est asynchrone, une écriture peut échouer, et l'écran doit l'afficher : ces cas passent par les commandes et l'état du store. Quand le stockage n'est qu'un reflet de l'état, sans erreur à remonter ni donnée à attendre, subscribe suffit. Dans un composant, tu n'en as pas besoin : @selector fait la même chose en plus fin (seulement quand la valeur lue change) et se désabonne tout seul au démontage. subscribe sert au code hors composants : main.ts , un outil de journalisation pendant le développement, un test qui compte les changements."},{"url":"stores.html#dispose","page":"Stores","title":"dispose : mettre fin à la vie du store","text":"Dans l' exemple Widget : timer-widget.ts . Fermer le minuteur libère son application et son store. dispose retire les écouteurs internes du store et avorte son signal : s'il écoutait un autre store, cette écoute s'arrête. Les commandes envoyées ensuite sont rejetées. counter.dispose(); await counter.send('increment', { id: 'cafes' }); // rejeté : « store \"counter\" disposé : commande \"increment\" refusée » Dans une app classique, les stores vivent aussi longtemps que la page : tu n'appelles jamais dispose . Il sert aux stores qui vivent moins longtemps : un widget créé avec sa propre application puis retiré de la page, un store créé pour une session et libéré à sa fin, ou un test qui vérifie qu'un store libéré refuse les commandes. export function mountTimerWidget(root: HTMLElement): () => void { const timer = TimerStore.create(); const app = createApp({ root, stores: [timer] }); app.mount(TimerWidget.create()); return () => { app.dispose(); // retire l'application et vide la racine timer.dispose(); // libère le store }; }"},{"url":"stores.html#un-store-qui-depend-d-un-autre","page":"Stores","title":"Un store qui dépend d'un autre store","text":"Dans l' exemple Boutique : checkout/store.ts , checkout/store.test.ts . Le store de commande reçoit le panier, le lit, lui envoie clear et écoute ses événements. Un store peut recevoir un autre store en dépendance, écouter ses événements ou lui envoyer des commandes. Le type de la dépendance se déduit du nom du contrat : StoreOfContract<'cart'> . Rien à nettoyer : Super lie les on et subscribe des stores reçus en dépendance à la durée de vie du store qui les reçoit. L'écoute s'arrête d'elle-même à son dispose() . import { type Commands, type StoreOfContract, SuperStore } from '@super-ts/core'; import type { OrderClient } from '../../ports/order-client'; import type { CheckoutContract } from './contract'; type Deps = { cart: StoreOfContract<'cart'>; orderClient: OrderClient }; export class CheckoutStore extends SuperStore<CheckoutContract> implements Commands<CheckoutStore> { #cart: Deps['cart']; #orderClient: OrderClient; constructor({ cart, orderClient }: Deps) { super({ contract: 'checkout', initialState: { lastOrder: null } }); this.#cart = cart; this.#orderClient = orderClient; // Un nouvel achat commence : la confirmation de la commande précédente n'a plus lieu d'être. cart.on('add:done', () => this.set({ lastOrder: null })); } // … } // main.ts const cart = CartStore.create(); const checkout = CheckoutStore.create({ cart, orderClient: createFakeOrderClient() }); L'écoute se pose dans le constructeur, mais son écouteur ne s'exécute qu'après create : il peut alors appeler this.set ."},{"url":"stores.html#envoyer-une-commande-a-un-autre-store","page":"Stores","title":"Envoyer une commande à un autre store","text":"Un store peut aussi envoyer des commandes au store qu'il reçoit, et attendre la fin du traitement : on est dans un store, c'est le seul endroit où l'on attend. async placeOrder({ address }: { address: string }) { const cart = this.#cart.selectors; // l'état du panier, lu par ses sélecteurs if (cart.isEmpty()) return this.fail('empty-cart'); const lines = cart.lines().map((line) => ({ sku: line.product.sku, quantity: line.quantity })); const total = cart.total(); const result = await this.#orderClient.place({ address, lines, total }).catch(() => this.fail('network')); if (!result.ok) return this.fail(result.reason); await this.#cart.send('clear'); // une commande envoyée à l'autre store, attendue jusqu'à la fin const order = { orderId: result.orderId, total }; this.set({ lastOrder: order }); return order; } Pas de donnée en retour : la promesse de send dit seulement « c'est fini » (et se rejette si la commande échoue). Pour connaître le résultat, lis l'autre store ensuite, ou écoute ses événements. Lire l'autre store : this.#cart.selectors passe par ses sélecteurs. this.selectors ne couvre que le store lui-même. Un seul sens : le panier est créé avant et passé à la création. Deux stores ne peuvent pas dépendre l'un de l'autre ; si le panier doit réagir au checkout, il écoute un événement du checkout au lieu de le recevoir en dépendance. Au premier niveau des dépendances Super reconnaît les stores passés directement dans l'objet de dépendances, premier argument du constructeur ( { cart } ). Un store rangé plus profond ( { stores: { cart } } ) n'est pas lié : garde les stores au premier niveau."},{"url":"stores.html#les-erreurs","page":"Stores","title":"Les erreurs","text":"Un composant envoie ses commandes sans attendre : c'est donc le store qui décide comment une erreur se publie. Un refus prévu (compteur inconnu, déjà à 0, stockage plein) : this.fail(raison) , avec une raison déclarée dans l' Outcome . Le composant écoute :failed et affiche le message de son choix. Une erreur qui doit rester visible , même pour un écran monté plus tard : dans l'état, comme loadErrorMessage . Une exception inattendue : rien à faire. La commande échoue avec la raison 'error' , pending redevient faux, et l'exception part dans la console. Situation Effet Commande absente du store send se rejette : « commande inconnue \"x\" sur le store \"counter\" ». Store disposé send se rejette : « store \"counter\" disposé : commande \"x\" refusée ». Méthode qui appelle this.fail('storage') :failed avec reason: 'storage' ; la promesse de send se rejette avec une CommandFailure . Méthode qui lève une exception :failed avec reason: 'error' et l'exception ; la promesse de send se rejette avec elle. this.get() , this.set() ou this.send() dans le constructeur Erreur à create : l'état n'existe qu'une fois le store créé."},{"url":"templates.html","page":"Templates : les fichiers .super","title":"Templates : les fichiers .super","text":"Un composant s'écrit dans un fichier .super : du TypeScript dont les méthodes contiennent des éléments HTML écrits comme des instructions. Le contrôle de flux est celui de TypeScript ( if , for , switch ), et tout le template est vérifié par le compilateur : props, événements, attributs, références."},{"url":"templates.html#fichiers-super","page":"Templates : les fichiers .super","title":"Un fichier .super","text":"import { SuperElement } from '@super-ts/dom'; import './counter-list-item.css'; /** Une ligne de la liste d'accueil : ne se re-rend que si la valeur de son compteur change. */ export class CounterListItem extends SuperElement { @tag = 'counter-list-item'; @prop counterId: string; @prop label: string; @contract counter; @selector count = () => this.counter.selectors.count(this.counterId); render() { <a href={this.router.href('counter', { params: { id: this.counterId } })}>{this.label}</a> <span class=\"counter-list-value\">{this.count.value}</span> } } Le composant se déclare dans sa classe : @tag pour son tag, @prop pour ses props (lues par this.label ), @emit pour ses événements, sans générique. Voir Composants : les déclarations . Ce qu'il prépare une fois se déclare aussi : @contract pour un store, @selector pour une lecture (lue par this.count.value ), et de même @state , @form , @ref et les écouteurs @on('contrat', 'événement') . Voir Composants : les déclarations de préparation . Tout le reste est du TypeScript : imports, types, champs, méthodes. Seuls les éléments et ces déclarations sont nouveaux. On l'importe sans extension , comme un .ts : import { ConfirmDialog } from '../shared/confirm-dialog' , ou @components/shop pour shop/index.super . Un module sans template reste un .ts : contrats, stores, domaine, routes, tests. Le plugin Vite compile le fichier, npm run typecheck le vérifie et l'éditeur le comprend : voir Outillage des .super ."},{"url":"templates.html#elements","page":"Templates : les fichiers .super","title":"Des éléments écrits comme des instructions","text":"Un élément s'écrit là où TypeScript attend une instruction, dans une méthode de la classe, et il est émis à cet endroit. render() ne renvoie rien : il émet. Plusieurs éléments à la suite sont permis, sans racine commune. render() { const label = this.label.value; if (label === null) { <p>Compteur introuvable</p> return; } <h1>{label}</h1> <p>Valeur : {this.count.value}</p> } Pas d'élément dans une expression : const x = <p /> ou () => <p /> sont refusés. Pour réutiliser un morceau, écris une méthode (voir Fragments ). return; arrête le rendu en gardant ce qui est déjà émis. return x; est refusé dans une méthode qui émet des éléments : elle renvoie ce qu'elle émet. Un élément sans enfant se ferme par /> ( <div /> ), sauf les éléments vides du HTML ( <br> , <input> , <img> …)."},{"url":"templates.html#texte","page":"Templates : les fichiers .super","title":"Le texte","text":"Le texte s'écrit tel quel entre les balises. Un enfant est lu comme une instruction seulement s'il commence par une forme réservée : Début de l'enfant Lu comme if ( , for ( , switch ( Une instruction de contrôle const ou let , un nom ou une déstructuration, puis = Une déclaration Tout le reste ( Total : , if you need help , let me know ) Du texte Un texte qui commence par une forme réservée sans en être une est une erreur, jamais une devinette. L'éditeur propose la correction : l'entourer d'accolades. <p>for (more info) see below</p> // erreur : texte lu comme une boucle for <p>{'for (more info) see below'}</p> // correct < , { et } ne s'écrivent pas dans le texte : {'<'} , {'{'} , {'}'} . Entre les balises, // est du texte : un commentaire s'écrit {/* … */} ."},{"url":"templates.html#espaces","page":"Templates : les fichiers .super","title":"Les espaces","text":"Ils suivent les règles du HTML, comme un template HTML écrit à la main : Chaque suite de blancs compte pour une espace , retours à la ligne compris : contenant puis <code>offline</code> à la ligne suivante s'affiche « contenant offline ». Les blancs au début et à la fin d'un élément ou d'un bloc ne rendent rien : <button> , un retour à la ligne, − , un retour à la ligne, </button> donne un bouton « − ». Deux éléments de la méthode séparés seulement par des blancs sont séparés par une espace ; s'il y a du code entre eux, non."},{"url":"templates.html#interpolations","page":"Templates : les fichiers .super","title":"Interpolations","text":"{expression} affiche une chaîne, un nombre ou un booléen. null et undefined n'affichent rien. Un objet est refusé par le compilateur, ce qui évite les [object Object] . <p role=\"status\">Commande n° {lastOrder.orderId}, {formatPrice(lastOrder.total)}.</p> <p>{count} article{count > 1 ? 's' : ''}</p> Tout est échappé {'<b>Ada</b>'} affiche le texte « <b>Ada</b> », sans créer de balise. Une donnée saisie par un utilisateur ne peut pas injecter de HTML."},{"url":"templates.html#attributs","page":"Templates : les fichiers .super","title":"Attributs","text":"Écriture Effet class=\"screen\" Attribut fixe. href={url} Attribut calculé. null ou undefined le retirent. disabled={busy} Attribut booléen du HTML ( disabled , hidden , checked …) : présent si vrai. disabled Attribut booléen toujours présent. prop:value={v} Propriété DOM plutôt qu'attribut ( el.value = v ). on:click={handler} Écouteur d'événement (voir Événements ). ref={this.input} Référence vers l'élément (voir Références ). {order.field('address')} dans la balise Directive d'élément : form.bind() , form.field(…) (voir Formulaires ). render() { const name = this.route.value; // `null` retire l'attribut. const current = (active: boolean) => (active ? 'page' : null); <header class=\"app-header\"> <nav aria-label=\"Exemples\"> <a href={this.router.href('examples')} aria-current={current(name === 'examples')}>Exemples</a> <a href={this.router.href('counters')} aria-current={current(name === 'counters' || name === 'counter')}>Compteurs</a> {/* … */} </nav> </header> <RouterOutlet /> } Une valeur d'attribut est une chaîne, un nombre, un booléen, null ou undefined . Une balise sans tiret doit exister en HTML ou en SVG : <dvi> est une erreur. Une balise avec tiret est un élément personnalisé. La syntaxe de lit est refusée , avec la forme à utiliser : @click → on:click , ?disabled → disabled , .value → prop:value ."},{"url":"templates.html#evenements","page":"Templates : les fichiers .super","title":"Événements","text":"on:événement={gestionnaire} pose un écouteur. Sur une balise HTML, le nom doit être un événement de cette balise ( on:clik est une erreur) et le gestionnaire reçoit l'événement typé, avec currentTarget du type de l'élément. <input on:input={(event) => this.local.set({ draft: event.currentTarget.value })} /> <button type=\"button\" on:click={() => this.run('reset')}>Remettre à zéro</button> Sur un composant enfant, on: s'abonne à ses événements, déclarés par @emit (voir Composants enfants ). Une erreur levée dans un gestionnaire est signalée à onError (voir Gérer les erreurs )."},{"url":"templates.html#afficher-ou-non","page":"Templates : les fichiers .super","title":"Afficher ou non : if","text":"Un if dans le template est le if de TypeScript, avec son rétrécissement de types : après if (user) , user n'est plus null . if (this.isLoading.value) { <p>Chargement…</p> } if (loadErrorMessage) { <div role=\"alert\"> <p>Impossible de charger les compteurs : {loadErrorMessage}</p> <button type=\"button\" on:click={() => this.counter.send('load')}>Réessayer</button> </div> } else if et else s'écrivent comme en TypeScript. Le corps d'un bloc suit les mêmes règles que les enfants d'un élément."},{"url":"templates.html#listes","page":"Templates : les fichiers .super","title":"Listes : for","text":"Seul for…of est accepté. key , après un ; dans les parenthèses, identifie chaque élément : quand l'ordre change, les éléments sont déplacés plutôt que recréés, et les composants enfants gardent leur état local. <ul class=\"counter-list\"> for (const c of shown; key c.id) { <li><CounterListItem counterId={c.id} label={c.label} /></li> } </ul> Sans key , le rendu est positionnel : il suffit pour une liste qui ne change jamais d'ordre. Une boucle à une seule clé recrée une zone quand la clé change : for (const _round of [round]; key _round) { … } dans l' écran des erreurs ."},{"url":"templates.html#switch","page":"Templates : les fichiers .super","title":"Choisir : switch","text":"Chaque case s'arrête au case ou au default suivant : pas de cascade, et break est inutile. Sur une union, un default qui appelle une fonction attendant never rend le choix exhaustif : TypeScript signale un cas oublié. switch (status) { case 'idle': <p>Au repos</p> case 'busy': <p>Occupé</p> case 'done': <p>Fini</p> default: {assertNever(status)} }"},{"url":"templates.html#declarations","page":"Templates : les fichiers .super","title":"Déclarations dans le template","text":"Une déclaration const ou let peut s'écrire au milieu des enfants, terminée par ; . Elle est visible des enfants qui la suivent, dans le même élément ou le même bloc. for (const l of this.lines.value; key l.product.sku) { const { product, quantity } = l; <li>{product.label} × {quantity}</li> }"},{"url":"templates.html#enfants","page":"Templates : les fichiers .super","title":"Composants enfants","text":"Une balise qui commence par une majuscule est un composant, une classe SuperElement en portée : <CounterControls count={count} canDecrement={this.canDecrement.value && !busy} canIncrement={!busy} on:increment={() => this.run('increment')} on:decrement={() => this.run('decrement')} /> Les attributs sont ses props , vérifiés contre ses @prop : une prop manquante, en trop ou mal typée est une erreur. on:x s'abonne à ses @emit , avec le type de la donnée émise. Pas de directive sur un composant : {…} dans la balise se place sur un élément HTML. Voir Parents et enfants ."},{"url":"templates.html#content","page":"Templates : les fichiers .super","title":"Des enfants : content","text":"Un composant qui accepte des enfants le déclare par une prop content du type Children de @super-ts/dom , et les place où il veut par une interpolation : {this.content} . import { type Children, SuperElement } from '@super-ts/dom'; export class Modal extends SuperElement { @tag = 'ui-modal'; @prop heading: string; @prop content: Children; @prop footer?: Children; @emit closed: void; render() {"},{"url":"templates.html#this-heading","page":"Templates : les fichiers .super","title":"{this.heading}","text":"{this.content} if (this.footer) { {this.footer} } } } Les enfants écrits entre ses balises remplissent content : <Modal heading=\"Supprimer le compteur ?\" on:closed={this.cancel}> <p>« {this.label.value} » sera définitivement supprimé.</p> </Modal>"},{"url":"templates.html#emplacements","page":"Templates : les fichiers .super","title":"Des emplacements nommés","text":"Un emplacement nommé (le pied de la modale) est une autre prop de type Children , déclarée comme les autres ( @prop footer?: Children; ) et lue par this.footer . Elle se remplit de deux façons, au choix. Par un emplacement <:nom> , écrit entre les balises du composant, là où il est utilisé : <Modal heading=\"Supprimer le compteur ?\" on:closed={this.cancel}> <p>« {this.label.value} » sera définitivement supprimé.</p> <:footer> <button on:click={this.cancel}>Annuler</button> <button class=\"danger\" on:click={this.confirm}>Supprimer</button> </:footer> </Modal> Par une méthode qui émet des éléments : une telle méthode renvoie Children (voir Fragments ). #footer() { <button on:click={this.cancel}>Annuler</button> <button class=\"danger\" on:click={this.confirm}>Supprimer</button> } render() { <Modal heading=\"Supprimer le compteur ?\" footer={this.#footer()} on:closed={this.cancel}> <p>« {this.label.value} » sera définitivement supprimé.</p> </Modal> } La méthode sert surtout pour une liste d'emplacements, comme des onglets dont les panneaux sont une prop panels: Children[] : <Tabs labels={['Profil', 'Sécurité']} panels={[this.#profile(), this.#security()]} /> . Tout est vérifié contre les @prop du composant : des enfants pour un composant qui n'en déclare pas, des enfants ou un emplacement obligatoires qui manquent, un emplacement inconnu. Les enfants restent ceux du parent : leurs écouteurs, leurs lectures de store et leur état sont ceux du parent, et ils suivent son rendu. Le composant qui les reçoit les garde quand il se re-rend seul. Un emplacement <:nom> se place directement dans un composant, sans attribut, une seule fois par nom. <:content> n'existe pas : les enfants directs remplissent déjà content . Dans l'éditeur , <: dans un composant propose ses emplacements. Un exemple complet : l'écran Composition de l'app d'exemples."},{"url":"templates.html#references","page":"Templates : les fichiers .super","title":"Références","text":"ref={…} relie un élément à une référence déclarée par @ref nom: T; . Le type de l'élément est vérifié : une référence HTMLInputElement posée sur un <div> est une erreur. @ref widgetSlot: HTMLElement; // … <div class=\"widget-slot\" ref={this.widgetSlot}></div>"},{"url":"templates.html#fragments","page":"Templates : les fichiers .super","title":"Fragments réutilisables","text":"Tout n'a pas besoin d'être un composant. Une méthode qui émet des éléments se réutilise dans render par une interpolation de son appel. Elle renvoie ce qu'elle émet, de type Children : return x; y est refusé, et son appel peut aussi remplir un emplacement nommé d'un composant. #back() { <a class=\"back-link\" href={this.router.href('counters')}>← Tous les compteurs</a> } render() { const label = this.label.value; if (label === null) { <main class=\"screen\">{this.#back()}<h1>Compteur introuvable</h1><p>Aucun compteur « {this.counterId()} ».</p></main> return; } // … } Crée un composant quand il te faut un état local, un store, des événements ou un re-rendu indépendant (comme une ligne de liste)."},{"url":"templates.html#ne-rien-rendre","page":"Templates : les fichiers .super","title":"Ne rien rendre","text":"Une méthode qui n'émet aucun élément ne rend rien : render() {} est un composant vide, et un if sans else ne rend rien quand sa condition est fausse."},{"url":"templates.html#dom-et-styles","page":"Templates : les fichiers .super","title":"DOM et styles","text":"Le DOM est patché, pas remplacé : le focus et la saisie en cours survivent à un re-rendu. Light DOM : pas de shadow DOM. Tes styles globaux s'appliquent aux composants, et tu peux cibler leur tag en CSS ( counter-list-item { display: contents; } ). Un élément racine n'est pas nécessaire : render peut émettre plusieurs éléments de premier niveau."},{"url":"templates.html#styles-d-un-composant","page":"Templates : les fichiers .super","title":"Styles d'un composant","text":"Super n'a pas de système de styles : un composant est un élément du DOM comme un autre. L' app d'exemples suit une convention simple, que tu peux reprendre : une feuille par composant , posée à côté de lui ( index.css pour un écran, counter-controls.css pour un sous-composant), importée par le composant, et dont les règles sont imbriquées sous son tag. app-shell { .app-header { padding: 1rem 1.5rem; border-bottom: 1px solid color-mix(in srgb, currentColor 15%, transparent); } .app-header nav { display: flex; flex-wrap: wrap; gap: 0.5rem 1.5rem; } .app-header a { font-weight: 600; text-decoration: none; opacity: 0.6; } .app-header a[aria-current='page'] { opacity: 1; } } import { RouterOutlet, SuperElement } from '@super-ts/dom'; import { RouteLink } from '@super-ts/ui'; import './index.css'; import './styles.css'; // références globales d'abord : les feuilles des composants passent après Le tag sert de portée : imbriquer sous app-shell évite qu'une classe .app-header touche le reste de la page, sans shadow DOM. Le composant charge ce dont il a besoin : Vite inclut la feuille dès que le composant est importé, et la retire s'il ne l'est plus. Les styles globaux d'abord : main.ts importe styles.css (variables, typographie, éléments de base) avant tout composant, pour que les feuilles des composants passent après."},{"url":"templates.html#html","page":"Templates : les fichiers .super","title":"Et html, nothing, repeat ?","text":"@super-ts/dom exporte toujours html , nothing et repeat , les briques de lit-html sur lesquelles le compilateur s'appuie. Un composant écrit en .ts dont render renvoie un html`…` fonctionne encore, mais son template n'est pas vérifié par le compilateur. Écris tes composants en .super ."},{"url":"tests.html","page":"Tester","title":"Tester","text":"Chaque brique se teste à son niveau : le store sans DOM, l'adapter seul, le composant avec un faux store, l'app entière avec un router en mémoire. Et les garanties de typage ont leurs propres tests."},{"url":"tests.html#la-configuration","page":"Tester","title":"La configuration","text":"Les tests tournent sous Vitest avec happy-dom, un DOM simulé. Ils vivent à côté du code qu'ils testent ( @core/counter/store.test.ts à côté de @core/counter/store.ts , @components/counter/index.test.ts à côté de l'écran, index.super ). Un test reste un fichier .ts , même pour un composant écrit en .super . Vitest reprend les plugins de vite.config.ts : le plugin Super y compile les .super comme en dev, et import { CounterControls } from './counter-controls' trouve counter-controls.super . export default defineConfig({ resolve: { alias }, plugins, // le plugin Super compile aussi les .super des tests test: { environment: 'happy-dom', execArgv: ['--no-experimental-webstorage'], // Node 25+ : voir plus bas globals: true, setupFiles: ['./vitest.setup.ts'], }, }); import { cleanup } from '@super-ts/testing'; import { afterEach } from 'vitest'; // Démonte tout ce que `mount()` a monté pendant le test. afterEach(() => cleanup()); Node 25 et plus Node expose un localStorage natif qui masque celui de happy-dom (« localStorage.clear is not a function »). L'option execArgv: ['--no-experimental-webstorage'] le désactive dans les workers de test."},{"url":"tests.html#tester-un-store","page":"Tester","title":"Tester un store","text":"Un store se teste sans DOM, avec un adapter en mémoire. XStore.create(deps) renvoie le handle, comme dans main.ts ; await send(…) attend la fin de la commande, puis on vérifie l'état, les sélecteurs et les événements. import { record } from '@super-ts/testing'; import { createInMemoryCounterRepository } from '../../adapters/in-memory-counter-repository'; import { CounterStore } from './store'; test('increment persiste, met à jour l’état, et Super publie increment:done avec le résultat', async () => { const counterRepository = createInMemoryCounterRepository({ cafes: 1 }); const store = CounterStore.create({ counterRepository }); const done = record(store, 'increment:done'); await store.send('load'); await store.send('increment', { id: 'cafes' }); expect(store.selectors.count('cafes')).toBe(2); expect(counterRepository.stored).toEqual({ cafes: 2 }); expect(done.calls).toEqual([{ input: { id: 'cafes' }, result: { count: 2 } }]); }); store.selectors.x(…) lit l'état courant par les sélecteurs du contrat ; store.state() donne l'état brut, figé. store.pending(…) dit si une commande est en cours : toutes ( pending() ), une commande ( pending('load') ), ou une commande pour un body ( pending('increment', { id: 'cafes' }) ). record(store, événement) enregistre les payloads, y compris ceux du cycle de vie ( 'increment:done' ) : calls (tous), last (le dernier), stop() (arrête l'écoute). Un échec se vérifie de deux façons : la promesse de send , rejetée avec une CommandFailure qui porte la raison, et l'événement :failed . Un faux adapter écrit sur place suffit : test('un échec de sauvegarde donne la raison storage et conserve la valeur', async () => { const store = CounterStore.create({ counterRepository: { loadAll: async () => ({ cafes: 3 }), save: async () => Promise.reject(new Error('quota dépassé')) }, }); const failed = record(store, 'increment:failed'); await store.send('load'); await store.send('increment', { id: 'cafes' }).catch(() => {}); expect(failed.last).toEqual({ input: { id: 'cafes' }, reason: 'storage', error: null }); expect(store.state().counts).toEqual({ cafes: 3 }); expect(store.pending()).toBe(false); // plus rien en cours, même après un échec }); Un store qui dépend d'un autre se teste avec le vrai : on crée le panier, puis la commande qui le reçoit en dépendance, exactement comme dans main.ts . function setup() { const cart = CartStore.create(); const orderClient = createFakeOrderClient({ delay: 0 }); const checkout = CheckoutStore.create({ cart, orderClient }); return { cart, orderClient, checkout }; } test('passe la commande avec le contenu du panier, puis vide le panier', async () => { const { cart, orderClient, checkout } = setup(); await cart.send('add', { sku: 'tshirt' }); await checkout.send('placeOrder', { address: '12 rue des Lilas' }); expect(orderClient.orders).toEqual([{ address: '12 rue des Lilas', lines: [{ sku: 'tshirt', quantity: 1 }], total: 2500 }]); expect(cart.selectors.isEmpty()).toBe(true); expect(checkout.state().lastOrder).toEqual({ orderId: 'C0001', total: 2500 }); });"},{"url":"tests.html#tester-un-adapter","page":"Tester","title":"Tester un adapter","text":"L'adapter localStorage se teste contre le localStorage de happy-dom, ou contre n'importe quel objet compatible grâce à son option storage . Rien de Super ici : c'est du user-land. test('relit ce qui a été sauvegardé, sous la clé choisie, sans écraser les autres compteurs', async () => { const repository = createLocalStorageCounterRepository({ key: 'test.counters' }); await repository.save('cafes', 7); await repository.save('pompes', 2); expect(JSON.parse(localStorage.getItem('test.counters')!)).toEqual({ cafes: 7, pompes: 2 }); await expect(createLocalStorageCounterRepository({ key: 'test.counters' }).loadAll()).resolves.toEqual({ cafes: 7, pompes: 2 }); });"},{"url":"tests.html#tester-un-composant","page":"Tester","title":"Tester un composant seul","text":"Un composant de présentation, sans store, se monte avec ses props ; ses événements s'écoutent par on , typé par ses emits . Le composant est un .super , le test un .ts qui l'importe sans extension. import { mount } from '@super-ts/testing'; import { within } from '@testing-library/dom'; import userEvent from '@testing-library/user-event'; import { CounterControls } from './counter-controls'; test('affiche la valeur et émet increment / decrement', async () => { const increment = vi.fn(); const decrement = vi.fn(); const { container } = await mount(CounterControls, { props: { count: 4, canDecrement: true, canIncrement: true }, on: { increment, decrement }, }); const ui = within(container); await userEvent.click(ui.getByRole('button', { name: 'Incrémenter' })); await userEvent.click(ui.getByRole('button', { name: 'Décrémenter' })); expect(ui.getByLabelText('Valeur du compteur').textContent).toBe('4'); expect(increment).toHaveBeenCalledOnce(); expect(decrement).toHaveBeenCalledOnce(); });"},{"url":"tests.html#mount","page":"Tester","title":"mount","text":"mount(Classe, options) prend la classe exportée par le .super (pas un élément déjà créé), le monte dans document.body sous une application de test, attend le premier rendu et retourne : Option Rôle props Les props du composant, typées par sa classe. stores Les stores à fournir (vrais ou faux), trouvés par le nom de leur contrat comme avec createApp . router Un router, en général createRouter(Router, { mode: 'memory', initialPath }) . Un écran monté seul y lit sa route : initialPath: '/counters/cafes' lui donne id === 'cafes' . on Des écouteurs pour les événements du composant, typés par ses emits . onError Reçoit les erreurs des composants montés, comme createApp({ onError }) . Voir Tester les erreurs . Retour Rôle container Le conteneur, à passer à within() de testing-library. element L'instance montée, typée par sa classe. setProps(props) Change les props et attend le rendu. unmount() Démonte (fait automatiquement par cleanup )."},{"url":"tests.html#flush","page":"Tester","title":"flush","text":"Les notifications de store et les rendus sont regroupés à la fin de la tâche. Après une action qui change un store sans passer par testing-library (un emit de faux store, un send sur un vrai), await flush() laisse passer les rendus en attente. Les findBy* de testing-library attendent d'eux-mêmes."},{"url":"tests.html#faux-store","page":"Tester","title":"Tester un écran avec un faux store","text":"fakeStore('nom', { state, commands? }) crée un store pour le contrat de ce nom, sans implémentation. L'écran le trouve comme il trouverait le vrai, par @contract counter : c'est ce que permet la règle « un composant ne connaît que le contrat ». L'état donné est typé par le contrat, et les sélecteurs du contrat le lisent normalement. import { createRouter } from '@super-ts/dom'; import { type FakeCommands, fakeStore, flush, mount } from '@super-ts/testing'; import type { CounterState } from '@core/counter/contract'; import { Router } from '../../routes'; import { CounterScreen } from '.'; const idle: CounterState = { counts: { cafes: 2 }, loadErrorMessage: null }; type CounterCommands = FakeCommands<'counter'>; async function setup(id: string, commands: CounterCommands = {}) { const counter = fakeStore('counter', { state: idle, commands }); // L'écran contient des liens : il lui faut un router (ici en mémoire). const router = createRouter(Router, { mode: 'memory', initialPath: `/counters/${id}` }); const { container } = await mount(CounterScreen, { stores: [counter], router }); return { counter, router, ui: within(container) }; } test('envoie les commandes avec l’id du compteur', async () => { const { counter, ui } = await setup('cafes'); await userEvent.click(ui.getByRole('button', { name: 'Incrémenter' })); expect(counter.sent).toEqual([{ name: 'increment', args: [{ id: 'cafes' }] }]); }); test('affiche le message de la raison d’échec, pour son compteur seulement', async () => { const { counter, ui } = await setup('cafes'); // Le test joue le rôle du store en émettant l'issue. counter.emit('decrement:failed', { input: { id: 'pompes' }, reason: 'storage', error: null }); counter.emit('decrement:failed', { input: { id: 'cafes' }, reason: 'below-min', error: null }); await flush(); expect(ui.getByText('Le compteur est déjà à zéro.')).toBeTruthy(); expect(ui.queryByText('Impossible d’enregistrer : le stockage est indisponible.')).toBeNull(); }); Membre du faux store Rôle sent Les commandes reçues, dans l'ordre : { name, args } . setState(patch) Change l'état, comme le ferait le store. emit(nom, payload) Émet un événement du contrat, ou l'issue d'une commande ( 'decrement:failed' ), comme le feraient le store et Super. selectors , state() , on … Le reste du handle d'un store, comme un vrai. commands (option) Des implémentations pour certaines commandes. Les autres sont enregistrées et se terminent sans publier d'issue : c'est au test d'émettre :done ou :failed , avec des valeurs conformes au contrat. FakeCommands<'counter'> type ces implémentations par le nom du contrat. Chacune reçoit le body, puis { fail } , et retourne le résultat déclaré par l' Outcome : Super publie alors l'issue comme pour un vrai store. const counter = fakeStore('counter', { state: idle, commands: { increment: () => ({ count: 3 }), // publie increment:done avec { count: 3 } decrement: (_input, { fail }) => fail('storage'), // publie decrement:failed avec la raison storage }, });"},{"url":"tests.html#tester-l-app-entiere","page":"Tester","title":"Tester l'application entière","text":"L'app s'assemble comme dans main.ts : vrais stores, adapters sans latence, router en mémoire. mount reçoit la coquille, AppShell , qui affiche l'écran de la route. async function startApp(initialPath = '/') { const counter = CounterStore.create({ counterRepository: createLocalStorageCounterRepository() }); const profileClient = createFakeProfileClient({ delay: 0 }); const profile = ProfileStore.create({ profileClient }); const cart = CartStore.create(); const orderClient = createFakeOrderClient({ delay: 0 }); const checkout = CheckoutStore.create({ cart, orderClient }); const errorLog = ErrorLogStore.create(); const router = createRouter(Router, { mode: 'memory', initialPath }); const { container } = await mount(AppShell, { stores: [counter, profile, cart, checkout, errorLog], router, onError: (error, { tag, phase, caughtBy }) => errorLog.send('record', { message: error.message, tag, phase, caughtBy }), }); await flush(); // laisse `load` se terminer return { router, profileClient, orderClient, cart, ui: within(container) }; } test('parcours complet des compteurs : liste, détail, incrément, retour', async () => { const { router, ui } = await startApp('/counters'); await userEvent.click(ui.getByRole('link', { name: 'Cafés' })); expect(router.state()).toMatchObject({ path: '/counters/cafes', name: 'counter', params: { id: 'cafes' } }); expect(ui.getByRole('heading', { name: 'Cafés' })).toBeTruthy(); await userEvent.click(ui.getByRole('button', { name: 'Incrémenter' })); await userEvent.click(ui.getByRole('button', { name: 'Incrémenter' })); expect(await ui.findByText('Incrémenté : 2')).toBeTruthy(); await userEvent.click(ui.getByRole('link', { name: '← Tous les compteurs' })); expect(ui.getByRole('link', { name: 'Cafés' }).parentElement!.textContent).toContain('2'); expect(JSON.parse(localStorage.getItem('super.counters')!)).toEqual({ cafes: 2 }); });"},{"url":"tests.html#tests-de-types","page":"Tester","title":"Tests de types : les fichiers *.test-d.ts","text":"Une partie de ce que promet Super, ce sont des erreurs de compilation : une route inconnue, un paramètre manquant, un écran aux mauvaises props. Un test Vitest ne peut pas constater qu'une ligne est refusée par le compilateur. Les fichiers *.test-d.ts servent à ça. import { expectTypeOf, test } from 'vitest'; test('Router.href est typé par les chemins', () => { expectTypeOf(Router.href('home')).toBeString(); // @ts-expect-error paramètre `id` requis Router.href('counter'); }); Le « d » vient de .d.ts : ces fichiers testent le typage, pas le comportement. C'est la convention de Vitest. Ils ne sont jamais exécutés . C'est npm run typecheck ( super-tsc , qui lance tsc ) qui les compile. Chaque // @ts-expect-error affirme « cette ligne doit être refusée ». Si un changement la rend acceptable, la compilation échoue (« Unused '@ts-expect-error' directive »). npm run check lance le typecheck puis les tests : ces fichiers sont vérifiés à chaque passage. Le template d'un .super n'a pas besoin de tests de types : npm run typecheck le vérifie directement (props d'un enfant, attributs, événements, interpolations). Les types qu'un test voit d'un composant .super (ses props pour mount , ses emits pour on ) viennent du TS virtuel, par la déclaration que super-tsc écrit dans .super/types/ (voir Outillage )."},{"url":"tests.html#qui-teste-quoi","page":"Tester","title":"Qui teste quoi","text":"Ce qui est testé Où Le fonctionnement de Super (router, sélecteurs, re-rendus, typage des contrats…) Les tests des paquets, dans packages/ . Ton app n'a pas à les refaire. Le comportement de ton app (règles du store, affichage des écrans, parcours) Les tests de ton app, à côté de ton code."},{"url":"ui.html","page":"Kit d'interface","title":"Kit d'interface","text":"@super-ts/ui rassemble les composants qu'une app finit toujours par écrire : champs reliés à un formulaire, bouton qui envoie une commande, lien de navigation, messages, fenêtres, menus, table. Ils ont une apparence sobre réglée par des variables CSS, sont accessibles au clavier et aux lecteurs d'écran, et se branchent directement sur les contrats, les formulaires et le router de Super."},{"url":"ui.html#ce-que-le-kit-apporte","page":"Kit d'interface","title":"Ce que le kit apporte","text":"Le kit se range en quatre familles : Les composants propres à Super , qui connaissent ses concepts : Field , Select , Checkbox , RadioGroup reliés à un formulaire @form , CommandButton relié à une commande, RouteLink relié au router, Toasts pour signaler les issues des commandes, ErrorPanel pour un renderError ou l'écran '!' . Les primitives accessibles , longues à écrire correctement : Dialog , Modal , ConfirmDialog , Menu , Tabs , Disclosure , Tooltip , Popover , Combobox . L'affichage : Button , Badge , Spinner , Skeleton , EmptyState . Les données : Table , statique ou branchée sur un store. Ce sont des composants Super comme les tiens ( SuperElement , props, événements, emplacements), écrits en .ts : une app les importe sans rien configurer de plus. Ils rendent dans le DOM normal, sans shadow DOM : les styles de l'app les atteignent, et les tests les trouvent par leur rôle et leur libellé. Le kit ne fournit aucun composant de mise en page : pas de Stack , de Grid ni de Card . La mise en page reste le CSS de l'app, là où elle est le plus simple à lire et à changer."},{"url":"ui.html#importer","page":"Kit d'interface","title":"Importer le kit","text":"import { SuperElement } from '@super-ts/dom'; import { Button, Checkbox, CommandButton, commandOf, createToasts, Field, fieldOf, RadioGroup, Select, Toasts } from '@super-ts/ui'; Importer le kit charge sa feuille de styles : il n'y a pas de CSS à ajouter à la main. @super-ts/ui dépend de @super-ts/dom , et de rien d'autre. Dans ce dépôt, il est résolu par alias comme les autres paquets ( packages/ui/src , déclaré dans vite.config.ts et dans les paths du tsconfig.json ) : voir Distribution . Un composant du kit s'écrit par sa classe, comme tout composant enfant : <Button> , pas <super-button> ."},{"url":"ui.html#theme","page":"Kit d'interface","title":"Le thème et les styles","text":""},{"url":"ui.html#variables","page":"Kit d'interface","title":"Les variables --super-*","text":"Toute l'apparence du kit passe par ces variables, déclarées sur :root . Chaque couleur a une valeur claire et une valeur sombre (voir Clair et sombre ) : Variable Défaut (clair, sombre) Rôle --super-font system-ui, … La police de tous les composants. --super-text #1f2328 , #e6edf3 Le texte courant. --super-muted #59636e , #9ea7b3 Le texte secondaire : aides des champs, légendes, messages vides. --super-surface #ffffff , #161b22 Le fond des fenêtres, menus, champs, toasts, boutons secondaires. --super-subtle #f4f5f7 , #222933 Les fonds discrets : survol, en-têtes de table, squelettes. --super-border #d0d5dd , #3d444d Les bordures. --super-accent #2f6fde , #5a9bff La couleur d'action : bouton principal, liens, onglet actif, anneau de focus. --super-accent-contrast #ffffff , #0d1117 Le texte posé sur --super-accent . --super-danger #c0362c , #ff7b72 Les actions destructrices, les erreurs, le ton danger . --super-danger-contrast #ffffff , #0d1117 Le texte posé sur --super-danger . --super-success #1a7f37 , #56d364 Le ton success (badges, toasts). --super-warning #9a6700 , #e3b341 Le ton warning . --super-info #0969da , #79c0ff Le ton info . --super-radius 6px L'arrondi des coins. --super-space 0.5rem L'unité d'espacement : marges internes et écarts en sont des multiples. --super-shadow 0 8px 24px … L'ombre des éléments flottants : fenêtres, menus, toasts. --super-focus un anneau de --super-accent L'anneau de focus au clavier ( box-shadow ). --super-backdrop rgb(0 0 0 / 0.55) Le fond derrière une fenêtre modale."},{"url":"ui.html#couche-super-ui","page":"Kit d'interface","title":"Une couche CSS de spécificité nulle","text":"Toutes les règles du kit sont dans la couche @layer super-ui , et leurs sélecteurs sont enveloppés dans :where(…) , qui ramène leur spécificité à zéro. Une règle de l'app passe donc toujours devant, sans !important ni sélecteur alourdi : une règle hors couche l'emporte sur toute règle d'une couche."},{"url":"ui.html#clair-sombre","page":"Kit d'interface","title":"Clair et sombre","text":"Chaque couleur du kit est déclarée par light-dark(clair, sombre) . Le navigateur choisit la valeur selon le color-scheme de l'élément, hérité de ses ancêtres : Sans color-scheme , le kit reste clair, quel que soit le thème du système. Avec color-scheme: light dark sur :root , l'app suit le thème du système, et le kit avec elle. C'est ce que fait l'app d'exemples dans son src/styles.css . Une zone peut forcer le sien : color-scheme: dark sur un élément passe en sombre tous les composants du kit qu'il contient, même dans une page claire. /* Forcer le thème sombre dans une zone, quel que soit celui du système. */ .kit-dark-zone { color-scheme: dark; padding: 1rem; border-radius: 0.75rem; background: #0d1117; color: #e6edf3; } color-scheme règle les couleurs du kit et celles du navigateur (barres de défilement, champs natifs), pas le fond ni le texte de la zone elle-même : c'est à l'app de les poser, comme ici. Une surcharge de couleur s'écrit de préférence elle aussi avec light-dark(…) , pour rester lisible dans les deux thèmes. Pour les navigateurs qui ne connaissent pas encore light-dark() , rien à faire : le minifieur CSS de Vite (Lightning CSS) la compile au build en une forme de repli qu'ils comprennent."},{"url":"ui.html#surcharger","page":"Kit d'interface","title":"Surcharger le thème","text":"Les variables se règlent à la portée voulue, du plus large au plus précis. Les exemples qui suivent sont ceux de la page « Thème » du kit dans l'app d'exemples (voir Exemples ), qui affiche chacun à côté de son effet. Pour toute l'app, quelques variables sur :root , dans une feuille chargée par main.ts : /* Le thème du kit pour toute la démo : quelques variables sur :root suffisent. */ :root { --super-accent: light-dark(#4f46e5, #a5b4fc); --super-radius: 8px; --super-font: inherit; } Pour une zone de l'app, les mêmes variables sur un élément qui l'entoure : /* Une zone : tous les composants du kit qu'elle contient. */ .kit-ocean { --super-accent: light-dark(#0e7490, #67e8f9); --super-radius: 999px; } Pour une seule instance, chaque composant accepte une prop class , ajoutée à l'élément racine qu'il rend (le <button> d'un Button , le <dialog> d'un Dialog , le <div> d'un champ) : <Button class=\"kit-violet\"> Avec class=\"kit-violet\" </Button> /* Un seul composant : la classe passée en prop arrive sur son élément. */ .kit-violet { --super-accent: light-dark(#7c3aed, #c4b5fd); } --super-space règle tous les espacements d'un coup : sur une table, il la rend plus dense ( <Table class=\"kit-compact\" …> ) : /* Une table plus dense : l'espacement du kit vient d'une seule variable. */ .kit-compact { --super-space: 0.25rem; font-size: 0.9rem; } Au-delà des variables, une règle ordinaire de l'app sur une classe du kit : /* Au-delà des variables : une règle ordinaire passe devant le kit, sans !important. */ .kit-caps .super-button { text-transform: uppercase; letter-spacing: 0.06em; } Les classes du kit commencent toutes par super- ( .super-button , .super-field , .super-window , .super-table …), et les variantes passent par des attributs : [data-variant=\"danger\"] pour un bouton, [data-tone=\"success\"] pour un badge ou un toast."},{"url":"ui.html#champs","page":"Kit d'interface","title":"Les champs de formulaire","text":"Field , Select , Checkbox et RadioGroup se relient à un champ de @form (voir Formulaires ) par fieldOf(formulaire, 'nom') . Chacun s'occupe de ce qu'on répète d'un champ à l'autre : le libellé, relié au contrôle ( <label for> , ou la légende d'un <fieldset> pour RadioGroup ) ; l'aide ( hint ), affichée sous le champ ; l'erreur de la règle ou du serveur, affichée sous le champ quand le formulaire la montre ; « Vérification… » pendant une vérification asynchrone ; aria-invalid quand il y a une erreur, et aria-describedby vers l'aide et l'erreur. export class KitFormsScreen extends SuperElement { @tag = 'kit-forms-screen'; @contract counter; @contract profile; notices = createToasts(); @selector cafes = () => this.counter.selectors.count('cafes'); @form edit = { initial: { name: '', email: '', country: 'FR', newsletter: false, plan: 'free' as 'free' | 'pro' | 'team' }, rules: { name: (v) => v.trim() !== '' || 'Nom obligatoire', email: (v) => /.+@.+\\..+/.test(v) || 'Adresse invalide', }, // … checks, submit, failures }; render() { const { edit } = this;"},{"url":"ui.html#champs","page":"Kit d'interface","title":"Champs","text":"{edit.formError()} Enregistrer // … } } fieldOf est vérifié par le compilateur, comme edit.field('…') : un nom absent du formulaire ne compile pas, et le type de la valeur doit convenir au composant. Un champ booléen ne peut pas aller dans un <Field> , un champ texte ne peut pas aller dans une <Checkbox> . Composant Valeur du champ Props propres Field string , number ou null type ( text par défaut, email , password , number , url , tel , search , date , time , datetime-local , color , range ), multiline et rows pour une zone de texte, placeholder , autocomplete . Select string , ou une liste avec multiple options ( { value, label }[] ), multiple . Checkbox boolean , ou une liste avec value value : la case est alors l'une d'un groupe, dont le champ est une liste. RadioGroup string options : un bouton radio par option. Tous reçoivent field , label , et facultativement hint et class . fieldOf s'écrit dans le rendu du composant qui possède le formulaire C'est ce composant qui se re-rend quand une valeur, une erreur ou une vérification change, et le champ du kit avec lui. Le formulaire ne se passe donc pas à un sous-composant qui appellerait fieldOf de son côté : les champs y resteraient figés. Le render() de l'écran, comme ci-dessus, ou une méthode de rendu de la même classe convient."},{"url":"ui.html#commandbutton","page":"Kit d'interface","title":"Envoyer une commande : CommandButton","text":"CommandButton envoie une commande au clic, et reste désactivé tant qu'elle est en cours, avec aria-busy=\"true\" . La commande se prépare par commandOf(vue, 'commande', entrée) : le contrat, le nom de la commande et son entrée sont vérifiés par le compilateur. @contract counter; // … <CommandButton command={commandOf(this.counter, 'reset', { id: 'cafes' })} pendingLabel=\"Remise à zéro…\"> Remettre les cafés à zéro </CommandButton> « En cours » vient de pending sur cette commande et cette entrée (voir pending ) : un autre bouton qui remet un autre compteur à zéro n'est pas désactivé. pendingLabel remplace le contenu pendant l'envoi ; sans lui, le contenu reste affiché. variant ( primary par défaut, secondary , danger ) et disabled fonctionnent comme sur Button . L'issue revient comme pour tout envoi : par les sélecteurs, ou par nom:done et nom:failed écoutés par @on (voir Écouter l'issue ). Le bouton n'affiche aucune issue lui-même. Le bouton lit le contrat du composant qui l'a préparé, pendant son propre rendu : c'est lui, et lui seul, qui se re-rend quand la commande commence ou se termine (voir Lire un sélecteur directement dans render )."},{"url":"ui.html#commandof","page":"Kit d'interface","title":"Préparer une commande : commandOf","text":"commandOf réunit la vue du contrat, le nom de la commande et son entrée. Chaque argument est typé par le précédent, ce qui donne la vérification et la complétion dans l'éditeur au fil de la frappe : Argument Son type vient de L'éditeur propose this.counter la vue déclarée par @contract counter; les contrats du composant 'reset' les commandes de ce contrat load , increment , decrement , reset { id: 'cafes' } l'entrée de cette commande id commandOf(this.counter, 'rest', { id: 'cafes' }); // commande inconnue commandOf(this.counter, 'reset', { identifiant: 'x' }); // entrée qui n'est pas celle de reset commandOf(this.counter, 'reset'); // entrée manquante commandOf(this.counter, 'load', { id: 'cafes' }); // load ne prend pas d'entrée Une commande sans entrée s'écrit sans troisième argument : commandOf(this.counter, 'load') . commandOf n'envoie rien : il prépare. L'envoi a lieu au clic du bouton, par la vue du contrat, donc vers le store du composant qui l'a préparé. La même entrée sert à pending : le bouton n'est désactivé que pour cette commande avec cette entrée. fieldOf(this.edit, 'email') suit le même principe pour les champs : le formulaire fixe les noms proposés, et le type de la valeur suit jusqu'au composant (voir les champs )."},{"url":"ui.html#routelink","page":"Kit d'interface","title":"Liens de navigation : RouteLink","text":"RouteLink est un lien vers une route, qui se marque lui-même aria-current=\"page\" quand il mène à la page affichée. Sa cible to s'écrit et se vérifie comme celle de navigate . <nav aria-label=\"Exemples\"> <RouteLink to={{ to: 'examples' }}> Exemples </RouteLink> <RouteLink to={{ to: 'counters' }} activeFor={['counter']}> Compteurs </RouteLink> <RouteLink to={{ to: 'shop' }} activeFor={['checkout']}> Boutique </RouteLink> // … </nav> Actif : le chemin du lien est celui de la page affichée, sans tenir compte de la query ni d'une barre oblique finale. /counters?sort=label garde le lien « Compteurs » actif. activeFor ajoute des noms de route pour lesquels le lien est aussi actif : une section, sa liste et son détail. exact compare aussi la query : utile pour des liens qui ne diffèrent que par elle (un tri, un filtre). Le clic est géré par le router, comme pour tout lien interne (voir L'interception des liens ). Params et query se donnent comme pour navigate : to={{ to: 'counter', params: { id } }} ."},{"url":"ui.html#toasts","page":"Kit d'interface","title":"Signaler une issue : Toasts","text":"Une file de messages se crée par createToasts() dans le composant qui veut signaler quelque chose, et s'affiche par <Toasts of={…} /> . Le composant y pousse les issues des commandes qu'il écoute : export class KitPrimitivesScreen extends SuperElement { @tag = 'kit-primitives-screen'; notices = createToasts(); // … #action = ({ id }: { id: string }) => { if (id === 'hello') this.notices.show('Bonjour !'); if (id === 'oops') this.notices.show('Quelque chose s’est mal passé.', { tone: 'error', duration: 0 }); }; render() { <KitPage heading=\"Primitives\" intro=\"…\"> // … <Menu label=\"Actions\" items={ACTIONS} on:select={this.#action} /> // … <Toasts of={this.notices} /> </KitPage> } } Les issues des commandes se changent en messages dans les méthodes qui les écoutent, déclarées par @on : // Les issues des commandes deviennent des messages. @on('profile', 'save:done') onSaved() { this.notices.show('Profil enregistré.', { tone: 'success' }); } @on('counter', 'reset:done') onReset() { this.notices.show('Cafés remis à zéro.'); } show(message, { tone, duration }) : tone vaut info (défaut), success ou error ; duration est en millisecondes, 5000 par défaut, et 0 garde le message jusqu'à sa fermeture. show renvoie un identifiant, à passer à dismiss(id) pour le retirer plus tôt. Chaque message a sa croix de fermeture. Un message error est annoncé tout de suite par les lecteurs d'écran ( role=\"alert\" ), les autres poliment ( role=\"status\" ). La zone est fixée en bas à droite de l'écran ; .super-toasts se replace par une règle de l'app."},{"url":"ui.html#errorpanel","page":"Kit d'interface","title":"Afficher une erreur : ErrorPanel","text":"ErrorPanel présente une erreur : un titre, le message, et le détail technique (le chemin et la pile) replié sous « Détails ». Il s'utilise dans un renderError (voir Le renderError d'un composant ), ou tel quel comme écran '!' du router, qui lui passe error et path : .screens(() => ({ // … '!': ErrorPanel, })); // Dans un composant : un bouton « Réessayer » qui émet retry override renderError(error: Error) { <ErrorPanel error={error} canRetry on:retry={() => this.counter.send('load')} /> } Props : error , path , title (« Une erreur est survenue » par défaut), canRetry qui affiche le bouton émettant retry , retryLabel . Le panneau a le rôle alert ."},{"url":"ui.html#fenetres","page":"Kit d'interface","title":"Les fenêtres : Dialog, Modal, ConfirmDialog","text":"Comme tout composant Super, une fenêtre montée est ouverte : c'est le parent qui décide de la rendre ou non, souvent selon son état local. La fenêtre ne se ferme pas d'elle-même : elle le demande au parent par un événement, qui retire la fenêtre de son rendu (voir Un dialogue ). @state local = { window: null as 'dialog' | 'modal' | 'confirm' | null }; #close = () => this.local.set({ window: null }); render() { const open = this.local.get().window; <KitPage heading=\"Fenêtres\" intro=\"…\"> // … les boutons qui ouvrent if (open === 'dialog') { <Dialog title=\"Renommer\" on:close={this.#close}> <p>Un dialogue a un contenu et des actions.</p> <:actions> <Button variant=\"secondary\" on:press={this.#close}> Annuler </Button> <Button on:press={this.#close}> Enregistrer </Button> </:actions> </Dialog> } if (open === 'modal') { <Modal title=\"À propos\" closeOn={{ backdrop: true }} on:close={this.#close}> <p>Une modale n’a pas d’actions : Échap, la croix ou un clic sur le fond la ferment.</p> </Modal> } if (open === 'confirm') { <ConfirmDialog question=\"Supprimer tous les compteurs ?\" confirmLabel=\"Supprimer\" danger on:answered={({ confirmed }) => { this.#close(); if (confirmed) this.notices.show('C’était pour de faux.', { tone: 'error' }); }} /> } <Toasts of={this.notices} /> </KitPage> } Fenêtre Contenu Événement Dialog title , les enfants, et des actions en pied dans l'emplacement <:actions> . close { reason } Modal La même mécanique, sans actions : title et les enfants. close { reason } ConfirmDialog question , title (« Confirmation » par défaut), confirmLabel , cancelLabel , danger pour un bouton de confirmation rouge. answered { confirmed } : true pour la confirmation, false pour l'annulation, Échap, la croix ou le fond. reason dit ce qui a demandé la fermeture : 'escape' , 'backdrop' (un clic sur le fond) ou 'button' (la croix). closeOn règle chaque moyen de fermer : { escape, backdrop, button } . Par défaut, Échap et la croix, pas le clic sur le fond, qu'on fait trop souvent par mégarde. { button: false } retire la croix. Un vrai <dialog> ouvert en modal : le reste de la page devient inerte (ni clic, ni focus, ni lecteur d'écran), et le fond est assombri par --super-backdrop . À l'ouverture, le focus entre dans la fenêtre (sur l'élément autofocus , sinon le premier élément focusable) ; à la fermeture, il revient à l'élément qui l'avait. Le défilement de la page est bloqué tant que la fenêtre est ouverte. Le titre nomme la fenêtre pour les lecteurs d'écran ( aria-labelledby ) ; closeLabel nomme la croix (« Fermer » par défaut)."},{"url":"ui.html#primitives","page":"Kit d'interface","title":"Les primitives accessibles","text":"Chacune suit le motif ARIA attendu (rôles, états, clavier). Celles qui gardent un état d'affichage (ouvert, onglet choisi) le gardent elles-mêmes, et préviennent le parent par un événement."},{"url":"ui.html#menu","page":"Kit d'interface","title":"Menu","text":"const ACTIONS = [ { id: 'hello', label: 'Dire bonjour' }, { id: 'archive', label: 'Archiver', disabled: true }, { id: 'oops', label: 'Signaler une erreur' }, ]; <Menu label=\"Actions\" items={ACTIONS} on:select={this.#action} /> Un bouton ouvre la liste d'actions. Clavier : flèches haut et bas, Début, Fin, Entrée ou Espace pour choisir, Échap pour fermer et revenir au bouton. Les entrées désactivées sont sautées. Un clic hors du menu le ferme. Le choix est émis par select { id } ."},{"url":"ui.html#tabs","page":"Kit d'interface","title":"Tabs","text":"const TABS = [ { id: 'profile', label: 'Profil' }, { id: 'security', label: 'Sécurité' }, ]; #profile() { Le panneau du profil. } #security() { Le panneau de la sécurité. Les flèches gauche et droite passent d’un onglet à l’autre. } // … dans render()"},{"url":"ui.html#tabs","page":"Kit d'interface","title":"Tabs","text":"panels est une liste d'emplacements ( Children[] ), un par onglet et dans le même ordre, remplis par des méthodes de rendu (voir Emplacements nommés ). Clavier : flèches gauche et droite, Début, Fin ; les onglets désactivés sont sautés. Sans selected , les onglets gardent leur choix (le premier au départ). Avec selected , c'est le parent qui le tient, prévenu par change { id } : utile pour mettre l'onglet dans la query de la route."},{"url":"ui.html#disclosure","page":"Kit d'interface","title":"Disclosure","text":"<Disclosure summary=\"Pourquoi ce compteur ?\"> <p>Un contenu repliable, sur les balises details et summary.</p> </Disclosure> Un contenu repliable, sur <details> et <summary> : le navigateur en fait déjà un élément accessible. open l'ouvre au premier affichage ; toggle { open } prévient à chaque ouverture et fermeture."},{"url":"ui.html#tooltip","page":"Kit d'interface","title":"Tooltip","text":"<Tooltip text=\"Une info-bulle, au survol et au focus\"> <Button variant=\"ghost\"> Survole-moi </Button> </Tooltip> L'info-bulle s'affiche au survol et au focus, et Échap la masque. Le premier élément focusable du contenu est relié à elle par aria-describedby : un lecteur d'écran lit le texte avec le bouton."},{"url":"ui.html#popover","page":"Kit d'interface","title":"Popover","text":"<Popover label=\"Filtres\"> <p>Un contenu flottant, non modal.</p> </Popover> Un contenu flottant derrière un bouton, non modal : le reste de la page reste utilisable. Échap le ferme et rend le focus au bouton ; un clic hors du contenu le ferme aussi. toggle { open } prévient le parent ; title nomme le contenu (défaut : label )."},{"url":"ui.html#combobox","page":"Kit d'interface","title":"Combobox","text":"Une saisie avec suggestions, en deux modes. À valeurs en dur : le combobox filtre lui-même ses options sur la saisie, sans tenir compte des accents ni de la casse (« peche » trouve « Pêche »). // Des valeurs écrites en dur : le combobox les filtre lui-même, sans accents ni casse. const FRUITS = ['Abricot', 'Ananas', 'Banane', 'Cerise', 'Citron', 'Fraise', 'Framboise', 'Mangue', 'Myrtille', 'Pêche', 'Poire', 'Pomme'].map( (fruit) => ({ value: fruit.toLowerCase(), label: fruit }), ); // … <Combobox label=\"Fruit\" options={FRUITS} placeholder=\"Tape « peche »…\" on:select={({ label }) => this.notices.show(`Fruit choisi : ${label}`)} /> Branché sur une API : le parent cherche, le combobox affiche. filter={false} lui fait afficher les options telles quelles, loading affiche « Chargement… », et le parent réagit à search { text } , émis à chaque saisie. Dans la page « Primitives » du kit, les suggestions viennent de l'API publique de test dummyjson.com, par le store du catalogue : // Les suggestions viennent du store du catalogue, qui cherche dans l'API dummyjson.com. @contract catalog; @selector suggestions = this.catalog.selectors.suggestions; @selector searching = () => this.catalog.selectors.pending('search'); // … <Combobox label=\"Produit\" options={this.suggestions.value.map((p) => ({ value: String(p.id), label: p.title }))} filter={false} loading={this.searching.value} placeholder=\"Tape « apple »…\" on:search={({ text }) => this.catalog.send('search', { text })} on:select={({ label }) => this.notices.show(`Produit choisi : ${label}`)} /> Le combobox émet une recherche par frappe ; c'est au store de ne pas inonder le serveur. Celui du catalogue attend la fin de la frappe, n'envoie que la dernière demande, et ignore une réponse dépassée : /** * Une recherche par frappe : on attend un court instant, et seule la dernière demande part au * serveur. Une réponse dépassée par une frappe plus récente est ignorée. */ async search({ text }: { text: string }) { const request = ++this.#latestSearch; if (text.trim() === '') return this.set({ suggestions: [] }); await wait(this.#searchDelay); if (request !== this.#latestSearch) return; const found = await this.#catalog.search(text.trim(), SUGGESTIONS).catch(() => this.fail('network')); if (request === this.#latestSearch) this.set({ suggestions: found }); } Le choix est émis par select { value, label } , et le libellé choisi reste dans la saisie. value donne la valeur choisie au départ. Clavier : flèches pour parcourir, Entrée pour choisir, Échap pour fermer la liste. L'option parcourue est annoncée par aria-activedescendant : le focus reste dans la saisie. Sans option à montrer, la liste affiche emptyLabel (« Aucun résultat » par défaut). Rien de tapé et rien à proposer : la liste reste fermée, le focus n'ouvre pas une liste vide."},{"url":"ui.html#affichage","page":"Kit d'interface","title":"L'affichage","text":"Neutre Actif En attente // …"},{"url":"ui.html#skeleton","page":"Kit d'interface","title":"Skeleton","text":"// … Ajoute un compteur en favori pour le retrouver ici. Parcourir Composant Props Remarques Button variant ( primary par défaut, secondary , danger , ghost ), type ( button par défaut, submit , reset ), disabled , label . Émet press au clic. label nomme un bouton dont le contenu n'est pas un texte (une icône). Avec type=\"submit\" , il soumet le formulaire qui l'entoure. Badge tone ( neutral par défaut, info , success , warning , danger ). Une étiquette courte : un statut, un compte. Spinner size ( small , medium par défaut, large ), label . Rôle status : annoncé par les lecteurs d'écran avec label (« Chargement… » par défaut). Skeleton lines (1 par défaut), width , height . La silhouette d'un contenu qui charge. Décoratif : aria-hidden . EmptyState title , les enfants (l'explication), l'emplacement <:action> . Ce qu'on affiche quand il n'y a rien, et de quoi en sortir. Les animations du Spinner et du Skeleton s'arrêtent quand le système demande moins de mouvement ( prefers-reduced-motion )."},{"url":"ui.html#table","page":"Kit d'interface","title":"La table","text":"Les colonnes se déclarent par columns<Row>([…]) , typées par le type des lignes : value reçoit une ligne typée. type CounterRow = { id: string; label: string; count: number }; const COUNTER_COLUMNS = columns<CounterRow>([ { key: 'label', label: 'Compteur', sortable: true }, { key: 'count', label: 'Valeur', sortable: true, align: 'end' }, ]); const PRODUCT_COLUMNS = columns<Product>([ { key: 'title', label: 'Produit', sortable: true }, { key: 'brand', label: 'Marque', sortable: true, value: (p) => p.brand ?? 'Sans marque' }, { key: 'price', label: 'Prix', sortable: true, align: 'end', value: (p) => PRICE.format(p.price) }, { key: 'rating', label: 'Note', sortable: true, align: 'end' }, ]); Clé d'une colonne Rôle key , label Son identifiant (celui du tri) et son titre. value La valeur affichée et triée, calculée depuis la ligne. Par défaut, row[key] . sortable L'en-tête devient un bouton : un clic trie par ordre croissant, un second inverse. align 'end' aligne à droite, pour les nombres. La table a deux modes, selon qu'on lui donne total ou non."},{"url":"ui.html#table-statique","page":"Kit d'interface","title":"Statique : toutes les lignes","text":"const counters: CounterRow[] = this.counter.selectors .catalog() .map((c) => ({ id: c.id, label: c.label, count: this.counter.selectors.count(c.id) })); // … <Table columns={COUNTER_COLUMNS} rows={counters} rowKey={(row) => row.id} caption=\"Compteurs\" pageSize={2} /> Sans total , rows contient toutes les lignes : la table les trie et les pagine elle-même, et ne demande rien à personne. Sans pageSize , pas de pagination. Avec pageSizes ( [10, 20, 50] ), un choix « Lignes par page » s'ajoute à la pagination, et ramène à la première page."},{"url":"ui.html#table-defilement","page":"Kit d'interface","title":"Une table plus large que l'écran","text":"Par défaut, une table trop large pour la place disponible défile de gauche à droite dans sa propre zone : elle garde sa largeur naturelle, cellules sur une ligne, et ni la page ni la pagination ne bougent. Le titre ( caption ) reste au-dessus, visible pendant le défilement. La zone est atteignable au clavier ( tabindex=\"0\" ), pour défiler avec les flèches, et porte le nom de la table. scroll={false} retire ce comportement : la table prend la largeur de son conteneur, ses cellules reviennent à la ligne, et un éventuel débordement est laissé au CSS de l'app."},{"url":"ui.html#table-branchee","page":"Kit d'interface","title":"Branchée : une page à la fois","text":"Avec total (le nombre de lignes côté serveur), rows est la page courante, déjà triée. La table émet request { sort, page, pageSize } au montage, puis à chaque changement de tri, de page ou de taille de page, et le parent la relie à une commande qui charge la page demandée. Dans le cas le plus simple, la table garde elle-même son tri et sa page, et le parent n'a qu'à transmettre la demande ; un nouveau tri ramène alors à la première page. Pour qu'un lien, un rechargement ou le bouton précédent du navigateur retrouvent la même page, le parent peut piloter le tri, la page et leur taille par les props sort , page et pageSize , lus dans la query de la route. C'est ce que fait la page « Table » du kit dans l'app d'exemples, branchée sur l'API publique de test dummyjson.com (voir Exemples ). La query est décrite dans la route, et typée : // Le tri et la page de la table branchée du kit : ils vivent dans l'URL. type KitTableQuery = { sort?: ProductSort; order: 'asc' | 'desc'; page: number; size: 5 | 10 | 20 | 50 }; // … 'kit-table': { path: '/kit/table', query: query<KitTableQuery>({ sort: { oneOf: PRODUCT_SORTS }, order: { oneOf: ['asc', 'desc'], default: 'asc' }, page: { type: Number, default: 1 }, size: { oneOf: [5, 10, 20, 50], default: 10 }, }), }, L'écran lit cette query par des sélecteurs, la passe à la table, change l'URL quand la table annonce un tri ( sort ), une page ( page ) ou une taille de page ( pageSize ), et charge les données quand elle les demande ( request ) : export class KitTableScreen extends SuperElement { @tag = 'kit-table-screen'; @contract counter; @contract catalog; @selector products = this.catalog.selectors.products; @selector total = this.catalog.selectors.total; @selector loading = () => this.catalog.selectors.pending('load'); @selector loadError = this.catalog.selectors.loadErrorMessage; // La query de la route, typée par sa description dans routes.ts. @selector sort = this.router.current.query.sort; @selector order = this.router.current.query.order; @selector pageNumber = this.router.current.query.page; @selector size = this.router.current.query.size; /** Change le tri, la page ou leur taille : c'est l'URL qui change, et la table suit. */ #go(next: { sort: ProductSort | undefined; order: SortOrder; page: number; size: PageSize }) { const { sort, ...rest } = next; this.router.send('navigate', { to: 'kit-table', query: sort ? { sort, ...rest } : rest }); } #query(): ProductQuery { return { page: this.pageNumber.value, pageSize: this.size.value, sort: this.sort.value ?? null, order: this.order.value }; } #retry = () => this.catalog.send('load', this.#query()); render() { // … const sort = this.sort.value; const order = this.order.value; const size = this.size.value; <KitPage heading=\"Table\" intro=\"…\"> // … if (this.loadError.value) { <div role=\"alert\" class=\"kit-row\"> <p>{this.loadError.value}</p> <Button variant=\"secondary\" on:press={this.#retry}> Réessayer </Button> </div> } <Table columns={PRODUCT_COLUMNS} rows={this.products.value} rowKey={(product) => product.id} caption=\"Produits\" total={this.total.value} pageSize={size} pageSizes={PAGE_SIZES} sort={sort ? { key: sort, direction: order } : null} page={this.pageNumber.value} loading={this.loading.value} on:sort={({ key, direction }) => this.#go({ sort: isProductSort(key) ? key : undefined, order: direction, page: 1, size })} on:page={({ page }) => this.#go({ sort, order, page, size })} on:pageSize={({ pageSize }) => this.#go({ sort, order, page: 1, size: isPageSize(pageSize) ? pageSize : size })} on:request={() => this.catalog.send('load', this.#query())} /> </KitPage> } } L'URL est la seule source : trier ou paginer navigue ( /kit/table?sort=price&order=desc&page=3&size=20 ), la table suit ses props, puis émet request . L'écran y répond en relisant la query ( #query() ), sans se servir de l'argument de l'événement. Changer seulement la query ne remonte pas l'écran : la table reste montée, et redemande ses données quand ses props sort , page ou pageSize changent. Quand le parent pilote la page, c'est à lui de revenir à la première page sur un nouveau tri ou une nouvelle taille ( page: 1 dans on:sort et on:pageSize ci-dessus). La taille choisie dans la table cède à celle du parent : si le parent repasse une autre pageSize (un retour arrière dans l'historique), c'est elle qui s'affiche. sort vaut { key, direction: 'asc' | 'desc' } , ou null pour aucun tri. La clé reçue par on:sort est une chaîne : isProductSort la ramène au type du domaine. Une valeur inconnue dans l'URL ( ?sort=nimporte&page=abc&size=7 ) est remplacée par la valeur par défaut de la query : pas de tri, page 1, 10 lignes. request est émis après le rendu, jamais deux fois de suite pour la même demande. loading (ici pending('load') ) pose aria-busy sur la table, et affiche « Chargement… » tant qu'aucune ligne n'est arrivée. L'échec reste à l'écran : la table n'affiche pas d'erreur. Le store garde un message ( loadErrorMessage ), et l'écran l'affiche avec un bouton qui relance la même demande. Les réponses peuvent arriver dans le désordre : un tri puis un autre envoient deux load . Le store du catalogue ignore une réponse dépassée par une demande plus récente (voir Exemples ). Dans les deux modes, les en-têtes triables portent aria-sort et une place réservée à la flèche de tri (trier ne change aucune largeur), la pagination est une <nav> « Pagination » avec « Précédent », « Page 2 sur 5 » et « Suivant », caption nomme la table, et emptyLabel s'affiche quand il n'y a aucune ligne (« Aucune donnée » par défaut)."},{"url":"ui.html#textes","page":"Kit d'interface","title":"Les textes par défaut","text":"Les textes du kit sont en français par défaut. Ceux qu'une app voudra changer passent par des props : Prop Composants Défaut closeLabel Dialog , Modal , ConfirmDialog , Toasts « Fermer » confirmLabel , cancelLabel , title ConfirmDialog « Confirmer », « Annuler », « Confirmation » label Toasts , Spinner « Notifications », « Chargement… » emptyLabel Table , Combobox « Aucune donnée », « Aucun résultat » pageSizeLabel Table « Lignes par page » title , retryLabel ErrorPanel « Une erreur est survenue », « Réessayer » Quelques textes n'ont pas encore de prop : « Vérification… » sous un champ, « Chargement… » dans une table ou un combobox qui charge, la pagination de la table, et « Détails » dans ErrorPanel ."},{"url":"ui.html#tester","page":"Kit d'interface","title":"Tester un écran qui utilise le kit","text":"Rien de particulier : les composants du kit rendent dans le DOM de l'écran, et se trouvent par leur rôle et leur libellé, comme le reste (voir Tester ). Les tests des pages du kit montent le router sur le chemin de la page, avec des stores factices ou en mémoire : test('la modale s’ouvre et se ferme avec Échap', async () => { const { ui } = await setup('/kit/windows'); await userEvent.click(ui.getByRole('button', { name: 'Ouvrir une modale' })); await flush(); expect(ui.getByRole('heading', { name: 'À propos' })).toBeTruthy(); await userEvent.keyboard('{Escape}'); await flush(); expect(ui.queryByRole('heading', { name: 'À propos' })).toBeNull(); }); Un écran qui importe un fichier CSS en texte ( ?raw ), comme la page « Thème », le reçoit vide sous Vitest, qui ignore le CSS par défaut : test.css.include dans vitest.config.ts désigne les fichiers à lire."},{"url":"ui.html#limites","page":"Kit d'interface","title":"Limites","text":"Pas de composant de mise en page : ni Stack , ni Grid , ni Card . L'agencement reste le CSS de l'app. fieldOf s'écrit dans le rendu du composant qui possède le formulaire : passé à un sous-composant, le champ ne suivrait plus les changements du formulaire. Pas d'API popover du navigateur : les menus, popovers, info-bulles et listes du combobox sont positionnés en position: absolute sous leur déclencheur. Un ancêtre en overflow: hidden peut les couper, et ils ne se replacent pas au bord de l'écran. Les textes sont en français par défaut : la plupart se changent par une prop ( Les textes par défaut ), quelques-uns pas encore. La table trie sur une seule colonne à la fois, et n'a ni sélection de lignes, ni colonnes redimensionnables."}];
